class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  sealed trait Stat
  case object Default extends Stat
  case class VisitPoint(i: Int) extends Stat

  def solve(): Unit = {
    val N, M = ni()
    val (from, to) = na2(M, -1)
    val g = packWUGraph(N, from, to)
    val deg = map(N)(i => g(i).length)

    def junctions = deg.count(_ > 2)

    def removeCycle(): Unit = {
      val removed = Array.ofDim[Boolean](M)
      val s = deg.indexWhere(_ > 2)
      val t = deg.lastIndexWhere(_ > 2)
      debug(s"s:$s")
      debug(s"t:$t")

      val removes = ArrayBuffer[Int]()

      var v = s
      var stat: Stat = Default
      while(true) {
        debug(s"v:$v")
        var next = -1
        REP(g(v).length) { i =>
          val e = g(v)(i)
          if (next == -1 && !removed(e.id)) {
            next = e.to
            removed(e.id) = true
            removes += e.id
          }
        }
        assert(next != -1)
        v = next
        stat match {
          case Default =>
            if (v == s) {
              removes.foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
            if (v == t) stat = VisitPoint(removes.length)

          case VisitPoint(i) =>
            if (v == s) {
              removes.foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
            if (v == t) {
              removes.drop(i).foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
        }
      }
    }

    // オイラーパス　&& サイクルが１個と２このケースを除く
    val ok = deg.forall(_ % 2 == 0) &&
        // サイクルが交わる点が１こもないとサイクルは１こ
        junctions > 0 && {
      // サイクルが交わる点が２個で、かつサイクルを一つ取り除いた後に交わる点がなくなったらサイクルは２こ
      // それ以外は３個以上あるので合体して３個にできる
      junctions > 2 || {
        debug(deg)
        removeCycle()
        debug(deg)
        junctions > 0
      }
    }

    if (ok) out.println("Yes")
    else out.println("No")
  }

  case class Edge(to: Int, id: Int)
  type WUGraph = Array[Array[Edge]]
  /**
    * uwiのぱくり
    */
  def packWUGraph(n: Int, from: Array[Int], to: Array[Int]): WUGraph = {
    val g = new Array[Array[Edge]](n)
    val p = new Array[Int](n)
    val m = from.length
    REP(m)(i => p(from(i)) += 1)
    REP(m)(i => p(to(i)) += 1)
    REP(n)(i => g(i) = new Array(p(i)))
    REP(m) { i =>
      p(from(i)) -= 1
      g(from(i))(p(from(i))) = Edge(to(i), i)
      p(to(i)) -= 1
      g(to(i))(p(to(i))) = Edge(from(i), i)
    }
    g
  }

}

import scala.annotation.tailrec
import scala.collection.mutable
import scala.io.StdIn._
object Main extends App {

  val Array(n, m) = readLine.trim.split(' ').map(_.toInt)
  val nodes = Array.tabulate(n){_ ⇒ Nil: List[Edge]}
  for (i ← 0 until m){
    val Array(a, b) = readLine.trim.split(' ').map(_.toInt - 1)
    nodes(a) ::= Edge(i, b)
    nodes(b) ::= Edge(i, a)
  }
  println(
    if (dfs(nodes)) "Yes" else "No"
  )

  def dfs(nodes: Array[List[Edge]]): Boolean = {
    val searching = Array.tabulate(n){_ ⇒ false}
    val use = Array.tabulate(m){_ ⇒ false}
    @tailrec
    def sub(prev: Int, current: Int, path: List[Int]): Int= {
      if (searching(current)) {
        path.foreach(i ⇒ searching(i) = false)
        current
      }
      else {
        searching(current) = true
        nodes(current).dropWhile(e ⇒ e.to == prev || use(e.id)) match {
          case h::_ ⇒ sub(current, h.to, current::path)
          case Nil ⇒ -1
        }
      }
    }
    def remove(start: Int): Unit = {
      nodes(start).dropWhile(e ⇒ use(e.id)) match {
        case h::t ⇒
          use(h.id) = true
          nodes(start) = t
          sub(h.to)
          nodes(start) = nodes(start).dropWhile(e ⇒ use(e.id))
        case Nil ⇒ ???
      }
      @tailrec
      def sub(current: Int): Unit = {
        if (current != start){
          nodes(current).dropWhile(e ⇒ use(e.id)) match {
            case h::t ⇒
              use(h.id) = true
              nodes(current) = t
              sub(h.to)
            case Nil ⇒ ???
          }
        }
      }
    }
    var count = 0
    for (i ← 0 until n if count >= 0){
      var start = 0
      nodes(i) = nodes(i).dropWhile(e ⇒ use(e.id))
      while(nodes(i).nonEmpty && start != -1){
        start = sub(-1, i, Nil)
        if (start != -1){
          remove(start)
          count += 1
        }
      }
      if (nodes(i).nonEmpty){
        count = -1
      }
    }
    count >= 3
  }

  case class Edge(id: Int, to: Int)
  implicit class Extension[T](val value: T) extends AnyVal {
    @inline def let[A](@inline func: T ⇒ A): A = func(value)
    @inline def also(@inline func: T ⇒ Unit): T = {func(value); value}
  }
}

