import scala.io.StdIn._
object Main extends App {

  val Array(n, m) = readLine.trim.split(' ').map(_.toInt)
  val nodes = Array.tabulate(n){_ ⇒ Nil: List[Edge]}
  for (i ← 0 until m){
    val Array(a, b) = readLine.trim.split(' ').map(_.toInt - 1)
    nodes(a) ::= Edge(i, b)
    nodes(b) ::= Edge(i, a)
  }
  println(
    if (dfs(nodes)) "Yes" else "No"
  )

  def dfs(nodes: Array[List[Edge]]): Boolean = {
    val searching = Array.tabulate(n){_ ⇒ false}
    val use = Array.tabulate(m){_ ⇒ false}
    val unionFind = Array.tabulate(n){_ ⇒ new UnionFind}
    val isInCycle = Array.tabulate(m){_ ⇒ false}
    for (i ← nodes.indices; edge ← nodes(i) if !use(edge.id)){
      if (unionFind(edge.to).isSameUnion(unionFind(i))) {
        isInCycle(edge.id) = true
      }else {
        unionFind(edge.to).merge(unionFind(i))
        use(edge.id) = true
      }
    }
    use.indices.foreach(i ⇒ use(i) = false)
    @tailrec
    def sub(prev: Int, current: Int, path: List[Int]): Int= {
      if (searching(current)) {
        path.foreach(i ⇒ searching(i) = false)
        current
      }
      else {
        searching(current) = true
        nodes(current).dropWhile(e ⇒ e.to == prev || use(e.id)) match {
          case h::_ ⇒ sub(current, h.to, current::path)
          case Nil ⇒ -1
        }
      }
    }
    def remove(start: Int): Unit = {
      nodes(start).dropWhile(e ⇒ use(e.id)) match {
        case h::t ⇒
          use(h.id) = true
          nodes(start) = t
          sub(h.to)
          nodes(start) = nodes(start).dropWhile(e ⇒ use(e.id))
        case Nil ⇒ ???
      }
      @tailrec
      def sub(current: Int): Unit = {
        if (current != start){
          nodes(current).dropWhile(e ⇒ use(e.id)) match {
            case h::t ⇒
              use(h.id) = true
              nodes(current) = t
              sub(h.to)
            case Nil ⇒ ???
          }
        }
      }
    }
    var count = 0
    for (i ← 0 until n){
      var start = 0
      nodes(i) = nodes(i).dropWhile(e ⇒ use(e.id))
      while(nodes(i).nonEmpty && start != -1){
        start = sub(-1, i, Nil)
        if (start != -1){
          remove(start)
          count += 1
        }
      }
    }
    count >= 3 && isInCycle.indices.forall(i ⇒ isInCycle(i) || use(i))
  }

  class UnionFind{
    private var mParent = this
    private var mSize: Int = 1
    private def parent: UnionFind = {
      if (mParent != this){
        mParent = mParent.parent
      }
      mParent
    }
    def size: Int = parent.mSize
    def isTop: Boolean = mParent == this
    def isSameUnion(that: UnionFind): Boolean = {
      parent == that.parent
    }
    def merge(that: UnionFind): Unit = {
      if (!isSameUnion(that)){
        val p = parent
        val tp = that.parent
        if (p.mSize > tp.mSize){
          tp.mParent = p
          p.mSize += tp.mSize
        }else {
          p.mParent = tp
          tp.mSize += p.mSize
        }
      }
    }
  }
  case class Edge(id: Int, to: Int)
  implicit class Extension[T](val value: T) extends AnyVal {
    @inline def let[A](@inline func: T ⇒ A): A = func(value)
    @inline def also(@inline func: T ⇒ Unit): T = {func(value); value}
  }
}

