class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  sealed trait Stat
  case object Default extends Stat
  case class VisitPoint(i: Int) extends Stat

  def solve(): Unit = {
    val N, M = ni()
    val (from, to) = na2(M, -1)
    val g = packWUGraph(N, from, to)
    val deg = map(N)(i => g(i).length)

    def calcJunctions = deg.filter(_ > 2)

    def removeCycle(): Unit = {
      val removed = Array.ofDim[Boolean](M)
      val s = deg.indexWhere(_ > 2)
      val t = deg.lastIndexWhere(_ > 2)
      debug(s"s:$s")
      debug(s"t:$t")

      val removes = ArrayBuffer[Int]()

      var v = s
      var stat: Stat = Default
      while(true) {
        debug(s"v:$v")
        var next = -1
        REP(g(v).length) { i =>
          val e = g(v)(i)
          if (next == -1 && !removed(e.id)) {
            next = e.to
            removed(e.id) = true
            removes += e.id
          }
        }
        assert(next != -1)
        v = next
        stat match {
          case Default =>
            if (v == s) {
              removes.foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
            if (v == t) stat = VisitPoint(removes.length)

          case VisitPoint(i) =>
            if (v == s) {
              removes.foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
            if (v == t) {
              removes.drop(i).foreach { i =>
                deg(from(i)) -= 1
                deg(to(i)) -= 1
              }
              return
            }
        }
      }
    }

    val junctions = calcJunctions
    // オイラーパス　&& サイクルが１個と２このケースを除く
    val ok = deg.forall(_ % 2 == 0) &&
        // サイクルが交わる点が１こもないとサイクルは１こ
        junctions.nonEmpty && {

      // 交わる点が１個で、そこで３つ以上のサークルがくっついているようならOK。
      // 交わる点が２個で、かつサイクルを一つ取り除いた後に交わる点がなくなったらサイクルは２こ
      // それ以外は３個以上あるので合体して３個にできる
      junctions.length > 2 || junctions.length == 1 && junctions.head >= 6 || junctions.length == 2 && {
        debug(deg)
        removeCycle()
        debug(deg)
        calcJunctions.length > 0
      }
    }

    if (ok) out.println("Yes")
    else out.println("No")
  }

  case class Edge(to: Int, id: Int)
  type WUGraph = Array[Array[Edge]]
  /**
    * uwiのぱくり
    */
  def packWUGraph(n: Int, from: Array[Int], to: Array[Int]): WUGraph = {
    val g = new Array[Array[Edge]](n)
    val p = new Array[Int](n)
    val m = from.length
    REP(m)(i => p(from(i)) += 1)
    REP(m)(i => p(to(i)) += 1)
    REP(n)(i => g(i) = new Array(p(i)))
    REP(m) { i =>
      p(from(i)) -= 1
      g(from(i))(p(from(i))) = Edge(to(i), i)
      p(to(i)) -= 1
      g(to(i))(p(to(i))) = Edge(from(i), i)
    }
    g
  }

}

