set<int> es[114514];
bool used[114514];
int prv[114514];
int depth[114514];

void Erase(int u, int v) {
  rep(i, 2) {
    assert(es[u].count(v));
    es[u].erase(v);
    swap(u, v);
  }
}

bool check() {
  fill(used, used+N, false);
  fill(prv, prv+N, -1);

  queue<int> que;
  int root = -1;
  rep(v, N) {
    if (!es[v].empty()) {
      root = v;
      used[v] = 1;
      que.push(v);
      break;
    }
  }
  if (root == -1) return false;

  using Ans = pair<int, pii>;
  Ans ans(MOD, pii(-1, -1));
  while (!que.empty()) {
    int v = que.front(); que.pop();
    for (int u : es[v]) {
      if (!used[u]) {
        prv[u] = v;
        used[u] = true;
        depth[u] = depth[v]+1;
        que.push(u);
      } else if (prv[v] != u) {
        MN(ans, Ans(1+depth[v]+depth[u], pii(v, u)));
      }
    }
  }
  if (ans.X == MOD) return false;

  int p, q;
  tie(p, q) = ans.Y;
  assert(p != -1);
  Erase(p, q);
  //cout << p << ", " << q << endl;
  rep(i, 2) {
    while (p != root) {
      int np = prv[p];
      Erase(p, np);
      //cout << p << ", " << np << endl;
      p = np;
    }
    p = q;
  }
  return true;
}

