int f1, f2;

bool dfs(int v, int prev){
    if(v == f2){
        return false;
    }

    visited[v] = true;

    bool res = false;
    for(auto x : g[v]){
        if(prev != f1 && x == f1){
            return true;
        }
        if(!visited[x]){
            res |= dfs(x, v);
        }
    }

    return res;
}

