    rep(i, n){
        if(deg[i].first % 2 == 1){
            return false;
        }
        deg[i].second = i;
    }

    SORT_INV(deg);
    if(deg[0].first >= 6 || deg[2].first >= 4){
        return true;
    }else if(deg[1].first < 4){
        return false;
    }

    f1 = deg[0].second;
    f2 = deg[1].second;
    visited.resize(n, false);

    return dfs(f1, -1);
}

