using Graph = vector<set<int>>;
int dfs(Graph& G, int u, vector<bool>& vis, int& cnt){
  if(vis[u]){
    ++cnt;
    return u;
  }

  vis[u] = true;
  while(!G[u].empty()){
    int to = *begin(G[u]);
    G[u].erase(to);
    G[to].erase(u);
    int r = dfs(G, to, vis, cnt);
    if(r != u){
      vis[u] = false;
      return r;
    }
  }
  vis[u] = false;

  return -1;
}

struct Timer{
  chrono::system_clock::time_point start;
  int mLim;
  Timer(){
	start = chrono::system_clock::now();
  }

  void SetLimit(int lim){
	mLim = lim;
  }

  // milli seconds
  bool TLE(int lim = -1) const{
	if(lim < 0) lim = mLim;
	auto crt = chrono::system_clock::now();
	return chrono::duration_cast<chrono::milliseconds>(crt - start).count() > lim;
  }
};


int main(){
  Timer timer;
  timer.SetLimit(1900);

  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N, M;
  cin >> N >> M;

  vector<PII> es(M);  
  REP(i,M){
    int u, v;
    cin >> u >> v;
    --u;
    --v;
    es[i] = MP(u, v);
  }

  Graph G(N);

  REP(i,M){
    int u = es[i].FF, v = es[i].SS;
    G[u].insert(v);
    G[v].insert(u);
  }

  REP(i,N){
    if(SZ(G[i]) % 2){
      cout << "No" << endl;
      return 0;
    }
  }

  VI perm(N);
  iota(ALL(perm), 0);
  std::mt19937 engine(0);

  while(!timer.TLE()){
    int cnt = 0;
    vector<bool> vis(N);
    REP(i,N){
      while(!G[i].empty()){
        dfs(G, i, vis, cnt);
      }
    }

    if(cnt >= 3){
      cout << "Yes" << endl;
      return 0;
    }

    shuffle(ALL(perm), engine);
    REP(i,N) G[i].clear();
    REP(i,M){
      int u = perm[es[i].FF], v = perm[es[i].SS];
      G[u].insert(v);
      G[v].insert(u);
    }
  }
  cout << "No" << endl;

  return 0;
}

