        g[a].adj.push_back(b);
        g[b].adj.push_back(a);
    }

    for(int i = 0;i < n;i++){
        if(g[i].adj.size() % 2 == 1){
            cout << "No\n";
            return 0;
        }
    }

    //if(m - n < 2) cout << "No\n";
    else cout << "Yes\n";
    return 0;
}

