using namespace std;
const string yes="Yes";
const string no="No";

int n,m;
vector<int> es[100010];

bool checked[100010];
queue<int> que;
int bfs(int s,int t){
  int paths=0;
  REP(i,n)checked[i]=false;
  que.push(s);
  checked[s]=true;
  while(!que.empty()){
    int index=que.front();
    que.pop();
    for(int e:es[index]){
      if(e==t){
	paths++;
	continue;
      }
      if(!checked[e]){
	que.push(e);
	checked[e]=true;
      }
    }
  }
  return paths;
}


string solve(){
  bool hasSix=false;
  int fourCount=0;
  REP(i,n){
    if(es[i].size()%2!=0) return no;
    if(es[i].size()==4) fourCount++;
    if(es[i].size()>=6) hasSix=true;
  }
  if(hasSix) return yes;
  if(fourCount>=3) return yes;
  if(fourCount<=1) return no;

  int s[2]={-1,-1};
  REP(i,n){
    if(es[i].size()==4){
      if(s[0]==-1)
	s[0]=i;
      else
	s[1]=i;
    }
  }
  int paths=bfs(s[0],s[1]);
  if(paths==2) return yes;
  return no;
}

