#define FOR(i,a,b) for (int i = (a); i < (b); i++)
#define RFOR(i,b,a) for (int i = (b) - 1; i >= (a); i--)
#define ITER(it,a) for (__typeof(a.begin()) it = a.begin(); it != a.end(); it++)
#define FILL(a,value) memset(a, value, sizeof(a))

#define SZ(a) (int)a.size()
#define ALL(a) a.begin(), a.end()
#define PB push_back
#define MP make_pair

typedef long long LL;
typedef vector<int> VI;
typedef pair<int, int> PII;

const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL) INF;

const int MAX = 100100;

multiset<int> g[MAX];
multiset<int> GG[MAX];
VI A[MAX];

int L[MAX];
int F[MAX];

bool no()
{
//	cout<<"No"<<endl;
	return 0;
}

bool yes()
{
	cout<<"Yes"<<endl;
	exit(0);
	return true;
}

int n;

bool try_once()
{
	FOR (i, 0, n)
	{
		g[i] = GG[i];
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i]) & 1) return no();
	}

	stack<int> st;
	VI a;

	st.push(0);

	while(SZ(st))
	{
		int x = st.top();
		if (SZ(g[x]) == 0)
		{
			a.PB(x);
			st.pop();
			continue;
		}

		int y;
		{
			int aa = rand() % SZ(A[x]);
			int val = A[x][aa];

			set<int>::iterator it = g[x].lower_bound(val);
			if (it == g[x].end()) it--;
			y = *it;
		}



		g[x].erase(g[x].find(y));
		g[y].erase(g[y].find(x));

		st.push(y);
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i])) throw -1;
	}

	a.pop_back();

//	FOR (i, 0, SZ(a))
//	{
//		cout<<a[i]<<' ';
//	}
//	cout<<endl;

	FOR (i, 0, n)
	{
		L[i] = -1;
	}

	int last = -1;
	int first = INF;

	FOR (i, 0, SZ(a))
	{
		int x = a[i];
		if (L[x] == -1)
		{
			L[x] = i;
			F[x] = i;
			continue;
		}

//		cout<<i<<": "<<x<<' '<<F[x]<<' '<<L[x]<<' '<<first<<' '<<last<<endl;

		if (F[x] <= last) return yes();
		if (L[x] >= first) return yes();

		last = max(last, L[x]);
		first = min(first, i);
		L[x] = i;
	}

	return no();
}

int main()
{
//	freopen("in.txt", "r", stdin);
	//ios::sync_with_stdio(false); cin.tie(0);

	int m;
	scanf("%d%d", &n, &m);
	FOR (i, 0, m)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		x--;
		y--;
		GG[x].insert(y);
		GG[y].insert(x);
		A[x].PB(y);
		A[y].PB(x);
	}

	FOR (i, 0, n)
	{
		sort(ALL(A[i]));
	}

	int time = clock();

	while(true)
	{
		if ((clock() - time) / (double)CLOCKS_PER_SEC > 1.9) break;
		try_once();
	}

	cout<<"No"<<endl;
}

