set<int> S[maxN];
bool judge() {
	int n = q.size();
	for(int i = 0; i < n; ++i) S[q[i]].insert(i);

	vector<bool> kl(n, false), kr(n, false);
	for(int i = 0; i < n; ++i) {
		auto p = S[q[i]].upper_bound(i);
		if(p != S[q[i]].end()) {
			kl[*p] = true;
		}
		if(i) kl[i] = (kl[i] || kl[i - 1]);
	}
	for(int i = n - 1; i >= 0; --i) {
		auto p = S[q[i]].find(i);
		if(p != S[q[i]].begin()) {
			--p;
			kr[*p] = true;
		}
		if(i < n - 1) kr[i] = (kr[i] || kr[i + 1]);
	}
	for(int i = 0; i < n; ++i) if(kl[i] && kr[i + 1]) {
//		printf("coin %d\n", i);
		return true;
	}

	vector<int> lst(n, 0);
	for(int i = 1; i < n; ++i) {
		lst[i] = *S[q[i]].rbegin();
		if(i) lst[i] = max(lst[i], lst[i - 1]);
	}
	for(int i = 1; i < n; ++i) {
		auto p = S[q[i]].upper_bound(i);
		if(p != S[q[i]].end()) {
			if(lst[i - 1] > *p) {
//				printf("split %d\n", i);
				return true;
			}
		}
	}

	return false;
}

