int getf(int x) {
	return (fa[x] == x) ? x : fa[x] = getf(fa[x]);
}

void merge(int x, int y) {
	x = getf(x); y = getf(y);
	if(x == y) {
		++ S[x];
		return;
	}
	fa[x] = y; S[y] = S[x] + 1 + S[y]; S2[y] = S2[x] + S2[y];
	return;
}

