vector<int> make_loop(int start, vector<vector<int>> &edges)
{
    set<int> visited;
    vector<int> path;
    visited.insert(start);
    path.push_back(start);
    int current_before = start;
    int current = start;
    // cout << "current: " << current << endl;
begin:
    for (auto neighber : edges[current])
    {
        if (visited.find(neighber) == visited.end()) // not visited
        {
            current_before = current;
            current = neighber;
            // cout << "current: " << current << endl;
            visited.insert(current);
            path.push_back(current);
            goto begin;
        }
    }
    for (auto neighber : edges[current])
    {
        if (neighber != current_before) // not before
        {
            path.push_back(neighber);
            auto pos = find(path.begin(), path.end(), neighber);
            return vector<int>(pos, path.end());
        }
    }
    throw 42;
}
void delete_edge(vector<vector<int>> &edges, int x, int y)
{
    auto posY = find(edges[x].begin(), edges[x].end(), y);
    edges[x].erase(posY);
    auto posX = find(edges[y].begin(), edges[y].end(), x);
    edges[y].erase(posX);
}
void delete_loop(vector<vector<int>> &edges, vector<int> &loop)
{
    for (int i = 0; i < loop.size() - 1; i++)
    {
        delete_edge(edges, loop[i], loop[i + 1]);
    }
}
int findDegree2(vector<vector<int>> &edges)
{
    for (int i = 0; i < edges.size(); i++)
    {
        if (edges[i].size() >= 2)
            return i;
    }
    return -1;
}
