}
bool solve(int N, int M, vector<vector<int>> &edges)
{
    for (auto edge : edges)
    {
        if (edge.size() % 2 == 1)
            return false;
    }
    int loopCount = 0;
    for (int i = 0; i < 3; i++)
    {
        // printvv(edges);
        int start = findDegree2(edges);
        // cout << "start:" << start << endl;
        if (start == -1)
            return false;
        vector<int> loop = make_loop(start, edges);
        // printv(loop, "loop:");
        delete_loop(edges, loop);
        // printvv(edges);
    }
    return true;
}
int main()
{
    int N, M;
