const int MAX = int ( 1e5 + 100 ) ;

struct Node {
	int a, b;
	bool f;
};

VI gr[MAX];
int n, m;
bool vis[MAX];
int start;
Node es[MAX];
bool dfs(int v, int par  ) {
	vis[v] = true;
	for (auto & g : gr[v]) {
		auto & e = es[g];
		if (!e.f) continue;
		int x;
		if (e.a == v) x = e.b;
		else x = e.a;
		if (x == par) continue;
		if (x == start) { 
			e.f = false;
			return true;
		}
		if (vis[x]) continue;
		if (dfs(x, v)) {
			e.f = false;
			return true;
		}
	}
	return false;
}
bool circle1() {
	memset(vis, false, sizeof(vis));
	VI zo(n);
	Rep(i, n) {
		zo[i] = i + 1;
	}
	random_shuffle(zo.begin(), zo.end());
	Loop(i, 1, n + 1) {
		bool f = false;
		for (auto x : gr[i]) {
			if (es[x].f) {
				f = true;
				break;
			}
		}
		if (!f) continue;
		start = i;
		f = dfs(i, -1);
		if (f) return true;
		else return false;
	}
	return false;
}



bool circle2() {
	memset(vis, false, sizeof(vis));
	Rep(i, m) {
		if (es[i].f == false) continue;
		start = es[i].a;
		bool f = dfs(start, -1);
		if (f) return true;
		else return false;
	}
	return false;
}
bool work1() {
