namespace Problem {
using namespace std;

class Solver2 {
 public:
  int n, m;
  vector<map<int, int>> t;
  Solver2(LL n, LL m) : n(n), m(m), t(n){};

  void solve() {
    for (int i = 0; i < m; ++i) {
      int a, b;
      cin >> a >> b;
      t[--a][--b] = 0;
      t[b][a] = 0;
    }
    bool ans = true;
    int ans2 = 0;
    int cnt6 = 0;
    vector<int> v4;
    for (int i = 0; i < n; ++i) {
      if (t[i].size() % 2) ans = false;
      ans2 += max(0, (int)t[i].size() - 2);
      if (t[i].size() >= 6) cnt6++;
      if (t[i].size() == 4) v4.push_back(i);
    }
    if (ans && ans2 >= 4) {
      if (ans2 >= 6 || cnt6) {
        cout << "Yes" << endl;
      } else {
        cout << (check(v4[0], v4[1]) ? "Yes" : "No") << endl;
      }
    } else {
      cout << "No" << endl;
    }
  }
  bool check(int s, int v) {
    int now = s;
    vector<int> res;
    while (1) {
      if (now == s || now == v) {
        res.push_back(now);
      }
      bool found = false;
      for (auto e : t[now]) {
        if (e.second == 0) {
          t[now][e.first] = 1;
          t[e.first][now] = 1;
          now = e.first;
          found = true;
          break;
        }
      }
      if (!found) break;
    }
    res.pop_back();
    for (int i = 0; i < res.size(); ++i) {
      rotate(res.begin(), res.begin() + 1, res.end());
      if (res[0]==res[1]) return true;
    }
    return false;
  }
};
