int N,M;
vector<int> g[100010];

int countCycles(){
    vector<int> deg(N,0);
    rep(i,N) deg[i]=g[i].size();

    int res=0;
    map<pair<int,int>,int> mp;
    vector<int> used(N,0);
    vector<int> pos(N,0);
    for(int i=0;i<N;i++){
        if(deg[i]==0) continue;

        stack<int> st;
        st.push(i);
        used[i]=1;
        while(1){
            int now=st.top();
            int nex=-1;
            for(;pos[now]<g[now].size();pos[now]++){
                int tar=g[now][pos[now]];
                if(mp.count(mkp(now,tar))) continue;

                nex=tar;
                pos[now]++;
                break;
            }

            if(nex==-1) break;
            if(used[nex]){
                deg[now]--;deg[nex]--;
                mp[mkp(now,nex)]=1;mp[mkp(nex,now)]=1;
                while(st.top()!=nex){
                    int tmp=st.top();
                    st.pop();
                    used[tmp]=0;
                }
                res++;
                continue;
            }else{
                st.push(nex);
                deg[now]--;deg[nex]--;
                used[nex]=1;
                mp[mkp(now,nex)]=1;mp[mkp(nex,now)]=1;
            }
        }
        used[i]=0;
    }
    return res;
}

