          cout<<"No"<<endl;
          return 0;
      }
  }

  rep(i,N) sort(g[i].begin(),g[i].end());

  int cycles=countCycles();
  if(cycles>=3) cout<<"Yes"<<endl;
  else cout<<"No"<<endl;

  return 0;
}

