int circles;
int last[125252];
bool pos[125252];

void f(vi c){
  int add = 0;
  for(int x : c){
    last[x] = -1;
  }
  REP(i,c.size()){
    int v = c[i];
    if(last[v] != -1){
      int to = last[v];
      add++;
      FOR(j,to,i)last[c[j]] = -1;
    }
    last[v] = i;
  }
  if(add==1 || circles+add>=3){
    circles += add;
    return;
  }
  // add == 2
  c.pop_back();
  REP(i,c.size())pos[i]=false;
  for(int x : c){
    last[x] = -1;
  }
  REP(i,c.size()){
    int v = c[i];
    if(last[v]!=-1){
      pos[last[v]] = true;
    }else{
      last[v] = i;
    }
  }
  queue<int> Q;
  REP(i,c.size()){
    int v = c[i];
    if(pos[i]){
      Q.push(v);
    }else if(last[v] != -1){
      if(Q.front() == v){
        Q.pop();
      }else{
        circles += 3;
        return;
      }
    }
  }
}

