    g[b].push_back(a);
  }
  // euler tour
  REP(i,n)if(g[i].size()%2 == 1){
    puts("No"); return 0;
  }
  REP(i,n)for(int x : g[i]){
    g2[i].insert(x);
  }
  // dfs
  while(true){
    vi c1;
    int start = -1;
    REP(i,n)if(g2[i].size()){
      start = i;break;
    }
    if(start==-1)break;
    int cur = start;
    c1.push_back(cur);
    do{
      int to = *g2[cur].begin();
      g2[cur].erase(to); g2[to].erase(cur);
      cur = to;
      c1.push_back(to);
    }while(cur != start);
    f(c1);
    if(circles >= 3){
      puts("Yes"); return 0;
    }
  }
  puts("No");
  return 0;
}

