		cout << "Yes\n";
	} else {
		cout << "No\n";
	}
}

bool cycle(int u, int v) {
	seen[u] = true;
	for (auto &i : g[u]) {
		if (i == v) {
			continue;
		} else if (seen[i]) {
			return true;
		} else if (cycle(i, v)) {
			return true;
		}
	}
	return false;
}

