bool vis[N];

void dfs(int u)
{
    vis[u]=1;
    for(int k=1;k<=17;k++)
        go[k][u]=go[k-1][go[k-1][u]];
    for(int v : g[u])
    {
        if(vis[v]) continue;
        go[0][v]=u;
        dep[v]=dep[u]+1;
        fa[v]=u;dfs(v);
    }
}

int lca(int x,int y)
{
    if(dep[x]<dep[y]) swap(x,y);
    for(int k=17;k>=0;k--)
        if(dep[go[k][x]]>=dep[y]) x=go[k][x];
    if(x==y) return x;
    for(int k=17;k>=0;k--)
        if(go[k][x]!=go[k][y]) x=go[k][x],y=go[k][y];
    return go[0][x];
}

void dfs2(int u)
{
    for(int v : g[u])
    {
        if(fa[v]!=u) continue;
        dfs2(v);
        val[u]+=val[v];
    }
}

