        for(int v : g[u])
        {
            if(u==fa[v]||v==fa[u]) continue;
            int x=lca(u,v);
            val[u]++;val[v]++;
            val[x]-=2;
        }
    dfs2(1);
    for(int i=2;i<=n;i++)
    {
        val[i]>>=1;
        if(!(val[i]&1)) return puts("No"),0;
    }
    puts("Yes");
    return 0;
}

