const int MAXN = 100010;
void bye() { std::cout << "No\n"; exit(0); }
int deg[MAXN], xs[MAXN], ys[MAXN];
int n, m, vis[MAXN], tc;
int head[MAXN], nxt[MAXN << 1], to[MAXN << 1];
void addedge(int b, int e, int tot) {
	nxt[++tot] = head[b]; to[head[b] = tot] = e;
	nxt[++tot] = head[e]; to[head[e] = tot] = b;
}
int dfs(int u, int fa = 0) {
	vis[u] = true;
	for (int i = head[u]; i; i = nxt[i])
		if (to[i] != fa) {
			if (vis[to[i]]) {
				xs[i >> 1] = 0;
				++tc;
				return true;
			}
			if (dfs(to[i], u)) {
				xs[i >> 1] = 0;
				++tc;
				return true;
			}
		}
	return false;
}
void reducecir() {
	memset(vis, 0, n + 1 << 2);
	memset(head, 0, n + 1 << 2);
	for (int i = 1; i <= m; ++i) if (xs[i])
		addedge(xs[i], ys[i], i * 2 - 1);
	for (int i = 1; i <= n; ++i) if (!vis[i] && dfs(i)) return ;
}

int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n >> m;
	for (int i = 1; i <= m; ++i) {
		std::cin >> xs[i] >> ys[i];
		++deg[xs[i]]; ++deg[ys[i]];
	}
	for (int i = 1; i <= n; ++i) if (deg[i] & 1) bye();
	static int tx[MAXN], ty[MAXN], rk[MAXN];
	memcpy(tx, xs, m + 1 << 2);
	memcpy(ty, ys, m + 1 << 2);
	for (int i = 1; i <= m; ++i) rk[i] = i;
	std::mt19937 rd(time(0) + (unsigned long) new char);
	while (clock() / (double) CLOCKS_PER_SEC < 1.5) {
		std::shuffle(rk + 1, rk + 1 + m, rd);
		for (int i = 1; i <= m; ++i)
			xs[i] = tx[rk[i]], ys[i] = ty[rk[i]];
		tc = 0;
		reducecir();
		if (tc < m) reducecir();
		if (tc < m) {
			std::cout << "Yes\n";
			return 0;
		}
	}
	bye();
	return 0;
}

