bool recur(
	int u, int p, int e,
	const vector<vector<int>>& g,
	vector<bool>& vis,
	vector<bool>& in_stack)
{
	in_stack[u] = true;
	vis[u] = true;
	for(const auto& v : g[u]){
		if(v == p || v == e){ continue; }
		if(in_stack[v]){ return true; }
		if(!vis[v]){ recur(v, u, e, g, vis, in_stack); }
	}
	in_stack[u] = false;
	return false;
}

