using namespace std;

int N, M;
const int K = 4;

struct Node {
  int n;
  int adj[K];
  int edge[K];

  void Add(int a, int e) {
    if (n < K) {
      adj[n] = a;
      edge[n] = e;
    }
    ++n;
  }

  int Next() const;
};

Node node[100020];
int color[100020];
bool visit[100020];

int Node::Next() const {
  for (int i = 0; i < n; ++i) {
    if (color[edge[i]] < 0) {
      return i;
    }
  }
  return -1;
}

int Solve() {
  memset(visit, 0, sizeof(visit));
  int cnt = 0;
  vector<int> up{0};
  int lv = 1;
  while (!up.empty()) {
    vector<int> st{up.back()};
    up.pop_back();
    while (true) {
      int p = st.back();
      if (visit[p]) {
	do {
	  if (node[st.back()].Next() >= 0) {
	    up.push_back(st.back());
	  }
	  visit[st.back()] = false;
	  st.pop_back();
	} while (st.back() != p);
	++cnt;
      }
      const Node& nd = node[p];
      int k = nd.Next();
      if (k < 0) {
	st.pop_back();
	assert(st.empty());
	break;
      }
      visit[p] = true;
      st.push_back(nd.adj[k]);
      color[nd.edge[k]] = lv;
    }
  }
  // cout << cnt << endl;
  return cnt >= 3;
}

int main() {
  while (cin >> N >> M) {
    memset(node, 0, sizeof(node));
    memset(color, -1, sizeof(color));
    for (int i = 0; i < M; ++i) {
      int a, b;
      cin >> a >> b;
      --a; --b;
      node[a].Add(b, i);
      node[b].Add(a, i);
    }
    bool odd = false;
    bool quick = false;
    for (int i = 0; i < N; ++i) {
      odd = odd || (node[i].n % 2 == 1);
      quick = quick || node[i].n > K;
    }
    if (!odd && (quick || Solve())) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }
}

