int N, M;
const int MAX_N = 100010;
const int MAX_M = 100010;
int a[MAX_M], b[MAX_M];

std::vector<int> Edge[MAX_M];
bool edge_used[MAX_M];
bool visited[MAX_N];
std::map<std::pair<int, int>, int> edge_map;

bool search_loop(int n, int from, std::vector<int>& path) {
    path.push_back(n);
    if (visited[n]) {
        return true;
    }
    visited[n] = true;
    for (int i = 0; i < Edge[n].size(); i++) {
        int e = Edge[n][i];
        assert(n == a[e] || n == b[e]);
        int next = (n == a[e]) ? b[e] : a[e];
        if (!edge_used[e] && next != from) {
            if (search_loop(next, n, path)) {
                return true;
            }
        }
    }
    visited[n] = false;
    path.pop_back();
    return false;
}

bool process_loop(int n) {
    std::vector<int> path;
    if (search_loop(n, -1, path)) {
        for (auto v : path) {
            visited[v] = false;
            //std::cout << v << " ";
        }
        //std::cout << std::endl;
        for (int i = path.size() - 1; 1 <= i; i--) {
            int min = std::min(path[i], path[i-1]);
            int max = std::max(path[i], path[i-1]);
            int e = edge_map[std::pair<int, int>({min, max})];
            edge_used[e] = true;
            if (path[i-1] == path.back()) {
                break;
            }
        }
        return true;
    }
    return false;
}

int main(int argc, char **argv) {
    std::cin >> N >> M;

    for (int i = 1; i <= M; i++) {
        std::cin >> a[i] >> b[i];
    }

    for (int i = 1; i <= M; i++) {
        edge_used[i] = false;
        int min = std::min(a[i], b[i]);
        int max = std::max(b[i], a[i]);
        edge_map[std::pair<int, int>({min, max})] = i;

        Edge[a[i]].push_back(i);
        Edge[b[i]].push_back(i);
    }

    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        while(process_loop(i)) {
            cnt++;
            //if (cnt == 3) { break; }
        }
        //if (cnt == 3) { break; }
    }

    //std::cout << cnt << std::endl;

    if (cnt < 3) {
        std::cout << "No" << std::endl;
        return 0;
    }

    for (int i = 1; i <= M; i++) {
        if (!edge_used[i]) {
            //std::cout << "edge_err:" << i << std::endl;
            std::cout << "No" << std::endl;
            return 0;
        }
    }

    std::cout << "Yes" << std::endl;
    return 0;

}

