int start = -1;
int goal = -1;

bool dfs(int s)
{
  for (auto x : V[s])
  {
    if (x != parent[s])
    {
      if (x == start)
      {
        return false;
      }
      else if (x == goal)
      {
        return true;
      }
      parent[x] = s;
      if (!dfs(x))
      {
        return false;
      }
    }
  }
  return true;
}

int main()
{
  cin >> N >> M;
  for (auto i = 0; i < M; i++)
  {
    int a, b;
