    a--;
    b--;
    V[a].push_back(b);
    V[b].push_back(a);
  }
  bool odd = false;
  bool six = false;
  int four = 0;
  for (auto i = 0; i < N; i++)
  {
    int s = V[i].size();
    if (s % 2 == 1)
    {
      odd = true;
      break;
    }
    if (s >= 6)
    {
      six = true;
      break;
    }
    if (s == 4)
    {
      four++;
    }
  }
  if (odd)
  {
    cout << "No" << endl;
  }
  else if (six)
  {
    cout << "Yes" << endl;
  }
  else if (four >= 3)
  {
    cout << "Yes" << endl;
  }
  else if (four == 2)
  {
    assert(false);
    for (auto i = 0; i < N; i++)
    {
      if ((int)V[i].size() == 4)
      {
        if (start == -1)
        {
          start = i;
        }
        else
        {
          goal = i;
          break;
        }
      }
    }
    fill(parent, parent + N, -1);
    if (!dfs(start))
    {
      cout << "Yes" << endl;
    }
    else
    {
      cout << "No" << endl;
    }
  }
  else
  {
    cout << "No" << endl;
  }
}

