		int now = st.top();
		int pre = -1;
		while (true) {
			int to = *g[now].begin();
			if (to == pre) to = *g[now].rbegin();
			if (to == pre) NO();
			if (set.count(to)) {
				int t = to;
				while (now != t) {
					g[now].erase(to);
					g[to].erase(now);
					to = now;
					now = st.top(); st.pop();
				}
				g[now].erase(to);
				g[to].erase(now);
				++cnt;
				break;
			}
			else {
				st.push(to);
				set.insert(to);
				pre = now;
				now = to;
			}
		}
	}
	if (cnt >= 3) YES();
	NO();

	return 0;
}

