	for(int i=1;i<=n;++i){
		if(S[i].size()&1)return puts("No"),0;
		if(maxd<S[i].size())
			maxd=S[i].size(),cnt=1;
		else if(maxd==S[i].size())
			++cnt;
	}
	if(maxd>=6)return puts("Yes"),0;
	if(maxd==4&&cnt>=3)return puts("Yes"),0;
	if(maxd==4&&cnt==2){
		int A=0,B=0;
		for(int i=1;i<=n;++i){
