using namespace std;
const int N=1e5+10;
struct Edge
{
	int v;bool flag;
	int rev;
}E[2*N];
int head[N],nxt[2*N],cc=0;
void Init(int n)
{
	for(int i=0;i<=n;i++)head[i]=-1;
	cc=0;
}
void add(int u,int v)
{
	nxt[cc]=head[u];head[u]=cc;
	E[cc++]={v,false,cc};
	nxt[cc]=head[v];head[v]=cc;
	E[cc++]={u,false,cc-2};
}
vector<int>cnt[10];
int V[N];
bool has=false,flag=false;
int tar;
void dfs(int idx,int sum)
{
	if(V[idx]>2&&sum){
		if(idx==tar)flag=true;
		return;
	}
	for(int k=head[idx];k!=-1;k=nxt[k]){
		Edge&e=E[k];
		if(e.flag)continue;
		E[e.rev].flag=e.flag=true;
		dfs(e.v,sum+1);
	}
}
int main()
{
	int n,m;scanf("%d%d",&n,&m);
	bool pass=true;
	Init(n);
	for(int i=0;i<m;i++){
		int u,v;scanf("%d%d",&u,&v);
		add(u,v);
		V[u]++,V[v]++;
	}for(int i=1;i<=n;i++){
		if(V[i]%2==1)pass=false;
		int u=V[i];
		if(u>6)u=6;
		cnt[u].push_back(i);
	}
	if(pass){
		if(!cnt[6].size()){
			if(cnt[4].size()<=1)pass=false;
			else {
				if(cnt[4].size()==2){
					tar=cnt[4][0];
					dfs(tar,0);
					pass=flag;
				}
			}
		}
	}if(pass)cout<<"Yes\n";
	else cout<<"No\n";
}

