bool solve() {
  int N = si(), M = si();
  vector<multiset<int>> G(N);
  vector<int> deg(N);
  REP(i, M) {
    int u = si() - 1, v = si() - 1;
    G[u].insert(v);
    G[v].insert(u);
    deg[u]++;
    deg[v]++;
  }
  REP(i, N) if (deg[i] % 2 == 1) return false;
  REP(i, N) if (deg[i] >= 6) return true;
  int c = count(ALL(deg), 4);
  if (c >= 3) return true;
  if (c == 1) return false;
  if (c == 0) return false;
  REP(i, N) if (deg[i] == 2) {
    int u = *G[i].begin();
    int v = *G[i].rbegin();
    G[u].erase(G[u].find(i));
    G[v].erase(G[v].find(i));
    G[i].clear();
    G[u].insert(v);
    G[v].insert(u);
  }
  REP(i, N) if (deg[i] == 4 && G[i].count(i)) return true;
  return false;
}

