bool dfs(int v) {
	mark[v] = true;
	for (int u: adj[v])
		if (!del[{u, v}]) {
			if (!mark[u]) {
				par[u] = v;
				if (dfs(u))
					return true;
			}
			else if (u != par[v]) {
				int x = v;
				par[u] = v;
				do {
					del[{x, par[x]}] = true;
					del[{par[x], x}] = true;
					x = par[x];
				} while (x != v);
				return true;
			}
		}
	return false;
}

void solve() {
