			exit(0);
		}
	for (int i = 0; i < 2; i++) {
		for (int v = 0; v < n; v++) {
			par[v] = -1;	
			if (!mark[v] && dfs(v))
				break;
		}
		memset(mark, false, sizeof mark);
	}
	for (int v = 0; v < n; v++)
		if (!mark[v]) {
			par[v] = -1;
			if (dfs(v)) {
				cout << "Yes";
				exit(0);
