void input() {
	cin >> n >> m;
	while(m--) {
		int u, v; cin >> u >> v; --u, --v;
		g[u].pb(v);
		g[v].pb(u);
	}
}

int f(int u) {
	int ret = dis[u] = nc++;
	for(int v : g[u]) {
		if(dis[v] == -1) par[v] = u, ret = max(ret, f(v));
		else if(par[u] != v && dis[v] < dis[u]) lis[v].pb(u);
	}
	return to[u] = ret;
}

int tot;
void rec(int u) {
	for(int v : g[u]) {
		if(par[v] == u) rec(v);
	}
	// 현재에서 먹을 수 있는 서킷
	int p = 0;
	for(int x : lis[u]) {
		// child 이동
		while(par[g[u][p]] != u || dis[x] > to[g[u][p]]) ++p;
		if(oc[dis[x]] == 0) {
			FOR(i, dis[g[u][p]], to[g[u][p]]+1) oc[i] = 1;
			++tot;
		}
	}
}

int solve() {
	memset(dis, -1, sizeof(dis));
	f(0);
	rec(0);
	cout << (tot >= 3 ? "Yes" : "No") << ENDL;
	return 0;
}

