bool rec(int from, int prev, int goal) {
	if (from == goal) return true;
	if (used[from]) return false;
	if (G[from].size() != 2) return false;
	used[from] = true;
	for (int to : G[from]) {
		if (to == prev) continue;
		if (rec(to, from, goal)) return true;
	}
	return false;
}

bool ok(int from) {
	for (int to : G[from]) {
		fill(used, used + N, false);
		if (rec(to, from, from)) return true;
	}
	return false;
}

