V<V<edge>> G;
V<bool> visited;
stack<int> st;

int dfs(int v, int s, int sum) {
   visited[v] = true;
   st.push(v);
   for (int i = 0; i < G[v].size(); i++) {
      edge& e = G[v][i];
      if (e.used) continue;
      edge& rev = G[e.to][e.rev];
      e.used = true; rev.used = true;

      if (e.to == s) return sum + 1;
      if (visited[e.to]) {
         ++sum;
         visited[e.to] = false;
         while (st.top() != e.to) {
            visited[st.top()] = false;
            st.pop();
         }
      }
      int res = dfs(e.to, s, sum);
      if (res > 0) return res;
   }
   return 0;
}

