    ins[u] = 1, stk[++top] = u;
    for (int i = fir[u], v; i; i = nxt[i]) {
        if (i / 2 == e) continue;
        v = to[i], fre[v] = i / 2;
        dfs(v, i / 2, cnt);
    }
    stk[top--] = ins[u] = 0;
}

void dfs2(int u, int &cnt) {
    if (ins[u]) return ;
    ins[u] = 1, ++cnt;
    for (int i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (ins[v] || ban[i / 2]) continue;
        dfs2(v, cnt);
