      ll nv = G[v][0] == pv ? G[v][1] : G[v][0];
      pv = v;
      v = nv;
    }
    return v;
  };
  bool ans = false;
  each(x, v) each(y, G[x]) {
    if (dfs(y, x) == x) {
      ans = true;
    }
  }
  cout << ans << endl;
}

