		++deg[u], ++deg[v];
	}
	for( int i = 1; i <= n; ++i )
		if( deg[i] & 1 ) {
			puts("No");
			return 0;
		}
	for( int i = 1; i <= n; ++i )
		if( !vis[i] )
			bfs(i);
	if( con.size() > 3 ) {
		puts("No");
		return 0;
	}
	int sum = 0;
	for( int tmp : con )
		sum += tmp;
	if( sum >= 3 ) puts("Yes");
	else {
		int cnt4 = 0;
		for( int i = 1; i <= n; ++i )
			if( deg[i] == 4 )
				++cnt4;
		if( cnt4 >= 3 ) {
			puts("Yes");
			return 0;
		}
		for( int i = 1; i <= n; ++i )
			cur[i] = G::head[i];
		euler(1);
		int ans = 0;
		memset(vis, 0, sizeof vis);
		for( auto it = eq.rbegin(); it != eq.rend(); ++it ) {
			int u = *it;
			if( vis[u] == 0 ) {
				vis[u] = 1;
				stk.push(u);
