class dinic {
  typedef long long ll;
  vector<int> level;
  vector<int> iter;

  void bfs(int s) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
      int v = q.front();q.pop();
      for (int i = 0; i < (int)g[v].size(); i++) {
        edge &e = g[v][i];
        if (e.cap > 0 && level[e.to] < 0) {
          level[e.to] = level[v] + 1;
          q.push(e.to);
        }
      }
    }
  }

  ll dfs(int v, int t, ll f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < (int)g[v].size(); i++) {
      edge &e = g[v][i];
      if (e.cap > 0 && level[v] < level[e.to]) {
        ll d = dfs(e.to, t, min(f,e.cap));
        if (d > 0) {
          e.cap -= d;
          g[e.to][e.rev].cap += d;
          return d;
        }
      }
    }
    return 0;
  }

public:
  struct edge { int to; ll cap; int rev; };
  vector<vector<edge>> g;
  const ll INF = 0x3f3f3f3f3f3f3f3f;

  dinic(int n) {
    g.resize(n); level.resize(n); iter.resize(n);
  }

  void add_edge(int u, int v, int cap) {
    g[u].push_back((edge){v,cap,(int)g[v].size()});
    g[v].push_back((edge){u,0,(int)g[u].size()-1});
  }

  ll max_flow(int s, int t) {
    ll flow = 0;
    while (true) {
      bfs(s);
      if (level[t] < 0) return flow;
      fill(iter.begin(), iter.end(), 0);
      ll f;
      while ((f = dfs(s,t,INF)) > 0) flow += f;
    }
  }
};


int main()
{
#ifdef FASTIO
  ios_base::sync_with_stdio(false); cin.tie(nullptr);
#endif

  cin >> n >> m;
  int a,b;
  dinic d(n);
  forn(i,m) {
    cin >> a >> b;
    a--,b--;
    d.add_edge(a, b, 1);
    d.add_edge(b, a, 1);
  }

  bool even = all_of(d.g.begin(),d.g.end(),[](vector<dinic::edge> v) { return v.size() % 4 == 0; });

  vi four;
  int six = 0;
  forn(i,n) {
    if (d.g[i].size() == 8) four.push_back(i);
    if (d.g[i].size() >= 12) six++;
  }

  bool ok;
  if (even && (four.size() >= 3 || six > 0)) ok = true;
  else if (!even || four.size() <= 1) ok = false;
  else {
    ll f = d.max_flow(four[0], four[1]);
    ok = f < 4;
  }

  if (ok)
    cout << "Yes\n";
  else
    cout << "No\n";

  return 0;
}

