        e[a-1]++; e[b-1]++;
        G.emplace_back(a-1, b-1);
    }
    int c = 0, p = 0;
    for (int i = 0; i < n; ++i) {
        if(e[i]%2){
            puts("No");
            return 0;
        }else if(e[i] >= 6){
            puts("Yes");
            return 0;
        }else if(e[i] == 4) c++, p = i;
    }
    if(c >= 3){
        puts("Yes");
        return 0;
    }else if(c <= 1){
        puts("No");
        return 0;
    }
    UnionFind uf(n);
    for (int i = 0; i < m; ++i) {
        if(G[i].first != p && G[i].second != p){
            uf.unite(G[i].first, G[i].second);
        }
    }
    int sz = -uf.uni[uf.root(p == 0 ? 1 : 0)];
    puts(sz == n-1 ? "No" : "Yes");
    return 0;
}

