struct Edge {
    int src, dst;
    int rev;
    bool use;
    Edge(int s, int d): src(s), dst(d) {}
    Edge(int s, int d, int r, bool u): src(s), dst(d), rev(r), use(u) {};
};
typedef vector<vector<Edge> > Graph;
Graph G;
void add_edge(int x, int y) {
    G[x].push_back(Edge(x, y, G[y].size(), false));
    G[y].push_back(Edge(y, x, G[x].size()-1, false));
}
vector<Edge> eularianCycle() { // [(0->x), (x->y), ..., (z->0)]
    int N = G.size(), cnt = 0;
    for (int i=0; i<N; i++) {
	cnt += G[i].size();
	if (G[i].size()%2) return vector<Edge>(); // odd degree vertex
    }
    vector<int> iter(N);
    vector<Edge> ret;
    stack<Edge> S;
    S.push(Edge(-1, 0));

    while (!S.empty()) {
	Edge e = S.top();
	if (iter[e.dst] < (int)G[e.dst].size()) {
	    Edge &f = G[e.dst][iter[e.dst]++];
	    if (!f.use) {
		f.use = G[f.dst][f.rev].use = true;
		S.push(f);
	    }
	} else {
	    S.pop();
	    ret.push_back(e);
	}
    }
    if ((int)ret.size() != (cnt>>1)+1) return vector<Edge>(); // not connected
