using namespace std;
typedef pair<int,int> pii;
const int N = 100010;
int _w;

int n, m, deg[N];

namespace G {
	int head[N], nxt[N*2], to[N*2], w[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v ) {
		to[eid] = v, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, nxt[eid] = head[v], head[v] = eid++;
	}
}

vector<int> con;
bool vis[N];

void bfs( int s ) {
	int cnt = 0, maxd = 0;
	queue<int> q;
	q.push(s), vis[s] = 1;
	while( !q.empty() ) {
		int u = q.front(); q.pop();
		++cnt, maxd = max(maxd, deg[u]);
		using namespace G;
		for( int i = head[u]; ~i; i = nxt[i] ) {
			int v = to[i];
			if( !vis[v] ) {
				vis[v] = 1;
				q.push(v);
			}
		}
	}
	if( cnt > 1 ) {
		con.push_back(maxd/2);
	}
}

vector<int> eq;
int cur[N];

void euler( int u ) {
	using namespace G;
	for( int &i = cur[u]; ~i; ) {
		int nowi = i;
		i = nxt[i];
		int v = to[nowi];
		if( w[nowi] ) continue;
		w[nowi] = w[nowi^1] = 1;
		euler(v);
	}
	eq.push_back(u);
}

stack<int> stk;

int main() {
	cin >> n >> m;
	G::init();
	for( int i = 0; i < m; ++i ) {
		int u, v;
		_w = scanf( "%d%d", &u, &v );
		G::link(u, v);
		++deg[u], ++deg[v];
	}
	for( int i = 1; i <= n; ++i )
		if( deg[i] & 1 ) {
			puts("No");
			return 0;
		}
	for( int i = 1; i <= n; ++i )
		if( !vis[i] )
			bfs(i);
	if( con.size() > 3 ) {
		puts("No");
		return 0;
	}
	int sum = 0;
	for( int tmp : con )
		sum += tmp;
	if( sum >= 3 ) puts("Yes");
	else {
		for( int i = 1; i <= n; ++i )
			cur[i] = G::head[i];
		euler(1);
		int ans = 0;
		memset(vis, 0, sizeof vis);
		for( int u : eq ) {
			if( vis[u] == 0 ) {
				vis[u] = 1;
				stk.push(u);
			} else {
				++ans;
				while(1) {
					int v = stk.top();
					stk.pop();
					if( v == u ) break;
				}
			}
		}
		puts( ans >= 3 ? "Yes" : "No" );
	}
	return 0;
}

