		if(at != 0 && ord[at] <= low[n] && !tmp) {
			ans.push_back(at);
			tmp = true;
			res++;
		}
		res += dfs(n);
		cnt++;
	}
	if(at == 0 && cnt > 1) {
		ans.push_back(0);
		res++;
	}
	return res;
}

