        if (unionSet(a, b)) {
            neigh[a].push_back(b);
            neigh[b].push_back(a);
        } else E.push_back(ii(a, b));
    }
    for (int i = 1; i <= n; i++)
        if (cnt[i] % 2) { printf("No\n"); return 0; }
        else if (cnt[i] >= 6) { printf("Yes\n"); return 0; }
        else if (cnt[i] >= 4) has++;
    Traverse(1);
    for (int j = 1; j < Maxm; j++)
        for (int i = 1; i <= n; i++)
            P[i][j] = P[P[i][j - 1]][j - 1];
    for (int i = 0; i < E.size(); i++) {
        int a = E[i].first, b = E[i].second;
        int lca = getLCA(a, b);
        int cur = V[a] + V[b] - V[lca] - V[P[lca][0]];
        if (cur < has) { printf("Yes\n"); return 0; }
    }
    printf("No\n");
