void addArc(Graph &g, int s, int d, Weight w = 1) {
    g[s].emplace_back(s, d, w);
}
void addEdge(Graph &g, int a, int b, Weight w = 1) {
    addArc(g, a, b, w);
    addArc(g, b, a, w);
}

bool dfs(Graph &g, int a, int b, int bef)
{
    if (a == b) return true;
    //std::cout << "dfs: " << a << std::endl;
    rep(i, g[a].size()) {
        if (g[a][i].w && g[a][i].d != bef) {
            g[a][i].w = 0;
            return dfs(g, g[a][i].d, b, a);
        }
    }
    return false;
}

string solve(Graph &g, int a, int b)
{
    //std::cout << "call" << std::endl;
    bool ret = true;
    ret &= dfs(g, a, b, -1);
    //cout << ret << endl;
    ret &= dfs(g, a, b, -1);
    //cout << ret << endl;
    ret &= dfs(g, a, b, -1);
    //cout << ret << endl;
    ret &= dfs(g, a, b, -1);
    //cout << ret << endl;
    if (ret) {
        return "No";
    } else {
        return "Yes";
    }
}

