template<typename T> int bins(const vector<T> &v, T key) {int imin=0,imax=v.size();while(imin<imax) {int imid=(imin+imax)>>1;if (v[imid]<key) imin=imid+1;else imax=imid;}return imin;}
class SplitGraph {
	vector<bool> seen;
	vi liveV; vpii liveE;
	void splitGraphDfs(const vvi &g, int x) {
		if (seen[x]) return;
		seen[x]=true;
		liveV.PB(x);
		for (auto &y:g[x]) {
			liveE.PB(MP(x,y));
			splitGraphDfs(g,y);
		}
	}
public:
	vvvi splitGraph(const vvi &g) {
		int n=g.size(); seen.clear(); seen.resize(n);
		vvvi vg;
		for (int x=0;x<n;x++) {
			if (!seen[x]) {
				splitGraphDfs(g, x);
				sort(liveV.begin(),liveV.end());
				vvi newg(liveV.size());
				for (auto &e:liveE) {
					int from=bins(liveV, e.fst),to=bins(liveV, e.snd);
					//printf("%d->%d\n",from,to);
					newg[from].PB(to);
				}
				liveV.clear(); liveE.clear();
				vg.PB(newg);
			}
		}
		return vg;
	}
};
SplitGraph SG;

bool done;
vector<bool> seen;
int special;
vi vloop;
bool findCyc(const vvi &g, int x, int p) {
	if (seen[x]) {
		special=x;
		return true;
	}
	seen[x]=true;
	for (auto &y:g[x]) {
		if (y==p) continue;
		if (findCyc(g,y,x)) {
			if (!done) vloop.PB(x);
			if (x==special) done=true;
			return true;
		}
	}
	return false;
}

bool solve(long long n, long long m, vector<long long> a, vector<long long> b){
	vvi ig(n);
	for (int i=0;i<m;i++) {
		int x=a[i]-1,y=b[i]-1;
		ig[x].PB(y); ig[y].PB(x);
	}
	vvvi sg=SG.splitGraph(ig);
	if (sg.size()>3) return false;
	int circuits=0;
	for (auto &g:sg) {
		if (g.size()<=1) return false;
		int above=0;
		for (auto &e:g) {
			if (e.size()%2!=0) return false;
		}
		vi vdeg(g.size());
		for (int x=0;x<(int)g.size();x++) vdeg[x]=g[x].size();
		seen.clear(); seen.resize(g.size()); vloop.clear(); done=false;
		findCyc(g,0,-1);
		for (auto &x:vloop) {
			//printf("%d ",x);
			vdeg[x]-=2;
		}
		//printf(" loop\n");
		int has=1;
		for (auto &deg:vdeg) {
			if (deg>=4) has=3;
			if (deg>=2) chkmax(has,2);
		}
		circuits+=has;
	}
	return circuits>=3;
}

