bool dfs( int cur, int prev, int goal, const vector<vector<int>>& edge )
{
	for( auto& next : edge[cur] )
	{
		if( next == prev ) continue;
		if( next == goal )
			return true;
		if( dfs( next, cur, goal, edge ) )
			return true;
	}
