using namespace std;

using ll = long long;

bool Solve() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> adj(n);
    vector<int> deg(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u - 1].push_back(v - 1);
        adj[v - 1].push_back(u - 1);
        ++deg[u - 1]; ++deg[v - 1];
    }

    int num_deg4 = 0, num_deg_gre6 = 0, s = -1, t = -1;
    for (int v = 0; v < n; ++v) {
        if (deg[v] & 1) return false;
        else if (deg[v] >= 6) ++num_deg_gre6;
        else if (deg[v] == 4) {
            ++num_deg4;
            if (s == -1) s = v;
            else t = v;
        }
    }
    if (3 <= num_deg4 || num_deg_gre6 != 0) return true;
    else if (num_deg4 <= 1) return false;

    for (int u : adj[s]) {
        int cur = u, prev = s;
        while (cur != s && cur != t) {
            for (auto v : adj[cur])
                if (v != prev) {
                    prev = cur;
                    cur = v;
                    break;
                }
        }
        if (cur == s) return true;
    }
    return false;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cout << (Solve() ? "Yes" : "No") << endl;

    return 0;
}

