	}
	if (mx >= 6)die("Yes");
	if (mx <= 2)die("No");
	int cnt = 0;
	REP(i, N) {
		if (deg[i] == 4)cnt++;
	}
	if (cnt >= 3)die("Yes");
	if (cnt <= 1)die("No");
	REP(i, N) {
		if (deg[i] == 4) {
			if (s == -1)s = i;
			else t = i;
		}
	}
	//pe(s + 1); print(t + 1);
	if (dfs(s, s))die("Yes");
	else die("No");
}

