#define N 100100
using namespace std;

int n, m, deg[N], stk[N], top, ins[N], ban[N], fre[N];
int tot = 1, fir[N], nxt[N << 1], to[N << 1];

inline void addE(int u, int v) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v;
}

void dfs(int u, int e, int &cnt) {
    if (cnt) return ;
    if (ins[u]) {
        for (int i = top; stk[i + 1] != u; --i)
            deg[stk[i]] -= 2, ++cnt, ban[fre[stk[i]]] = 1;
        return ;
    }
    ins[u] = 1, stk[++top] = u;
    for (int i = fir[u], v; i; i = nxt[i]) {
        if (i / 2 == e) continue;
        v = to[i], fre[v] = i / 2;
        dfs(v, i / 2, cnt);
    }
    stk[top--] = ins[u] = 0;
}

void dfs2(int u, int &cnt) {
    if (ins[u]) return ;
    ins[u] = 1, ++cnt;
    for (int i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (ins[v] || ban[i / 2]) continue;
        dfs2(v, cnt);
    }
}

