    for (int i = 1; i <= n; ++i)
        if (deg[i] & 1) return puts("No"), 0;

    int ok = 0;
    dfs(1, 0, ok);
    assert(ok);

    int cnt = 0;
    for (int i = 1; i <= n && !cnt; ++i)
        if (deg[i]) dfs2(i, cnt);
    for (int i = 1; i <= n; ++i)
        if (deg[i] == 2) -- cnt;

    puts(cnt ? "Yes" : "No");

    return 0;
}

