template <class Cost = int, class Cap = int>
struct Edge {
    int from, to, rev;
    Cost cost;
    Cap cap;
    Edge(int from = -1, int to = -1, Cost cost = 1, Cap cap = 0, int rev = -1)
        : from(from), to(to), cost(cost), cap(cap), rev(rev){};

    bool operator<(const Edge<Cost>& e) const { return this->cost < e.cost; }
    bool operator>(const Edge<Cost>& e) const { return this->cost > e.cost; }
};

template <class Cost = int, class Cap = int>
class Graph {
public:
    int size;
    std::vector<std::vector<Edge<Cost, Cap>>> path;

    explicit Graph(int N = 0) : size(N), path(size) {}
    void span(int u, int v, Cost cost = 1, Cap cap = 0) {
        path[u].push_back(Edge<Cost, Cap>(u, v, cost, cap));
    }
    std::vector<Edge<Cost, Cap>> operator[](int v) const { return path[v]; }
};

template <class Cost = int, class Cap = int>
class Lowlink {
private:
    Graph<Cost, Cap> graph;
    int cur;
    std::vector<int> order, low;

    void dfs(int v, int r) {
        order[v] = low[v] = cur++;
        int deg = 0;
        bool is_artic = false;

        for (auto e : graph[v]) {
            if (order[e.to] < 0) {
                ++deg;
                dfs(e.to, e.from);
                low[e.from] = std::min(low[e.from], low[e.to]);

                if (order[e.from] <= low[e.to]) is_artic = true;
                if (order[e.from] < low[e.to]) bridges.push_back(e);
            } else if (e.to != r) {
                // eは後退辺 1回だけ遡る
                low[e.from] = std::min(low[e.from], order[e.to]);
            }
        }

        if (r < 0) is_artic = (deg > 1);
        if (is_artic) artics.push_back(v);
    }

public:
    std::vector<int> artics;
    std::vector<Edge<Cost, Cap>> bridges;

    explicit Lowlink(const Graph<Cost, Cap>& graph)
        : graph(graph), order(graph.size, -1), low(graph.size, graph.size) {
        cur = 0;
        for (int v = 0; v < graph.size; ++v) {
            if (order[v] < 0) dfs(v, -1);
        }
    }
};

void fail() {
    std::cout << "No" << std::endl;
    exit(0);
}

void ok() {
    std::cout << "Yes" << std::endl;
    exit(0);
}

int main() {
    int N, M;
    std::cin >> N >> M;

    Graph<> graph(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u, --v;
        graph.span(u, v);
        graph.span(v, u);
    }

    for (int v = 0; v < N; ++v) {
        if (graph[v].size() % 2 != 0) fail();
    }

    for (int v = 0; v < N; ++v) {
        if (graph[v].size() >= 6) ok();
    }

    int cnt = 0;
    for (int v = 0; v < N; ++v) {
        if (graph[v].size() >= 4) ++cnt;
    }

    if (cnt <= 1) fail();
    if (cnt >= 3) ok();

    Lowlink<> lowlink(graph);
    std::cout << (lowlink.artics.empty() ? "No" : "Yes") << std::endl;
    return 0;
}

