bool dfs(vector<vector<Edge>> &edges, int start, int goal, int prev, vector<bool> &used) {

    if (goal == start) return true;

    for (Edge e : edges[start]) {
        int next = e.dst;
        int id = e.id;
        if (next == prev) continue;
        if (used[id]) continue;
        bool ok = dfs(edges, next, goal, start, used);
        if (ok) {
            used[id] = true;
            return true;
        }
    }
    return false;
}

