    }else{
      last[v] = i;
    }
  }
  queue<int> Q;
  REP(i,c.size()){
    int v = c[i];
    if(pos[i]){
      Q.push(v);
    }else if(pos[last[v]]){
      if(Q.front() == v){
        Q.pop();
      }else{
        circles += 3;
        return;
      }
    }
  }
  circles += add;
}

