VV<ll> edges;

ll dfs(ll now, ll pre, ll start, ll goal) {
    if(pre >= 0 && now == start) return 0;
    if(now == goal) return 1;
    ll cnt = 0;
    for(ll nxt : edges[now]) {
        if(nxt == pre) continue;
        cnt += dfs(nxt, now, start, goal);
    }
    return cnt;
}

bool solve() {
    ll N, M;
    cin >> N >> M;
    V<ll> cntv(N);
    edges.resize(N);
    for(ll i = 0; i < M; i++) {
        ll a, b;
        cin >> a >> b;
        a--;
        b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
        cntv[a]++;
        cntv[b]++;
    }
    ll cnt_over_6 = 0;
    V<ll> fours;
    for(ll i = 0; i < N; i++) {
        ll e = cntv[i];
        DEBUG(e);
        if(e == 4) fours.push_back(i);
        if(e >= 6) cnt_over_6++;
        if(e & 1) return false;
    }
    if(cnt_over_6 > 0) return true;
    if(fours.size() == 2) {
        ll f = fours[0], t = fours[1];
        ll cnt = dfs(f, -1, f, t);
        if(cnt != 4) return true;
    }
    if(fours.size() > 2) return true;
    return false;
}

int main() {
    cout << (solve() ? "Yes" : "No") << endl;
    return 0;
}

