const int N=1e6+10;

int gi() {
	int x=0,o=1;char ch=getchar();
	while((ch<'0'||ch>'9')&&ch!='-') ch=getchar();
	if(ch=='-') o=-1,ch=getchar();
	while(ch>='0'&&ch<='9') x=x*10+ch-'0',ch=getchar();
	return x*o;
}

int n,m;
vector<int> E[N];

void No() {
	puts("No");exit(0);
}

void Yes() {
	puts("Yes");exit(0);
}

namespace flow {

	struct edge {
		int to,w,nxt;
	} e[N<<1];

	int tot=1,h[N],dep[N],cur[N],s,t;

	void adde(int u,int v,int w) {
		e[++tot]=(edge){v,w,h[u]};h[u]=tot;
		e[++tot]=(edge){u,0,h[v]};h[v]=tot;
	}

	bool bfs() {
		memset(dep,0,sizeof(dep));
		queue<int> q;q.push(s);dep[s]=1;
		while(!q.empty()) {
			int u=q.front();q.pop();
			for(int i=h[u];i;i=e[i].nxt)
				if(e[i].w) {
					int v=e[i].to;
					if(!dep[v]) dep[v]=dep[u]+1,q.push(v);
				}
		}
		return dep[t];
	}

	int dfs(int u,int flow) {
		if(u==t) return flow;
		int ret=0;
		for(int &i=cur[u];i;i=e[i].nxt)
			if(e[i].w) {
				int v=e[i].to;
				if(dep[v]==dep[u]+1) {
					int d=dfs(v,min(flow,e[i].w));
					e[i].w-=d,e[i^1].w+=d,ret+=d,flow-=d;
					if(!flow) break;
				}
			}
		return ret;
	}

	int dinic(int _s,int _t) {
		s=_s,t=_t;
		int ret=0;
		while(bfs()) {
			memcpy(cur,h,sizeof(h));
			ret+=dfs(s,1e9);
		}
		return ret;
	}

}

int main() {
	n=gi(),m=gi();
	for(int i=1,u,v;i<=m;i++) u=gi(),v=gi(),E[u].push_back(v),E[v].push_back(u);
	for(int i=1;i<=n;i++) {
		if(E[i].size()&1) No();
	}
	for(int i=1;i<=n;i++) {
		if(E[i].size()>=6) Yes();
	}
	int cnt=0;
	for(int i=1;i<=n;i++) {
		if(E[i].size()>=4) ++cnt;
	}
	if(cnt>=3) Yes();
	if(cnt==2) {
		int A=0,B=0;
		for(int i=1;i<=n;i++)
			if(E[i].size()==4) {
				if(!A) A=i;
				else B=i;
			}
		for(int u=1;u<=n;u++)
			for(auto v:E[u]) flow::adde(u,v,1);
		if(flow::dinic(A,B)==2) Yes();
		No();
	}
	No();
	return 0;
}

