// Edge構造体を定義する無向グラフ
class GraphE {
public:
    using W_T = int;
    struct Edge {
        int u, v;
        W_T value;
        Edge(int from = 0, int to = 0, W_T value = 0) :u(from), v(to), value(value) {}
        inline int to(int _v) const { return _v == v ? u : v; }
    };
    size_t n;
    vector<vector<int>> vertex_to;
    vector<Edge> edges;

    GraphE(int n = 1) :n(n), vertex_to(n) { }

    inline size_t size() const noexcept { return n; }
    void resize(size_t _n) { vertex_to.resize(n = _n); }
    void connect(int from, int to, W_T val = 0) {
        vertex_to[(size_t)from].push_back((int)edges.size());
        vertex_to[(size_t)to].push_back((int)edges.size());
        edges.emplace_back(from, to, val);
    }
    void connect(vector<Edge>&& es) {
        edges = move(es);
        for (int i = 0; (size_t)i < edges.size(); ++i) {
            vertex_to[edges[i].u].push_back(i);
            vertex_to[edges[i].v].push_back(i);
        }
    }
};

// 

int N, M;

GraphE graph;
int paintedE[100010]; // edge
int paintedV[100010]; // vertex

// set<int> crossVtx;
int crossCnt = 0;

bool dfs(int idx, int last, int targetE, int targetV, int painter){
    // debug(idx);
    paintedV[idx] += 1;
    if (paintedV[idx] > 1) crossCnt += 1;

    for (auto ei : graph.vertex_to[idx]) {
        if (paintedE[ei] > 0) continue;
        const auto& e = graph.edges[ei];
        int to = e.to(idx);
        if (to == last) continue;
        // debug(ei);
        if (targetE == ei){
            if (last != -1 && targetV == idx) {
                // exit
                paintedE[ei] = painter;
                return true;
            }
            else continue;
        }
        paintedE[ei] = painter;
        return dfs(to, idx, targetE, targetV, painter);
    }
    return false;
}

