signed main() {
	INIT;

	VAR(int, n, m);
	VEC_ROW(int, m, a, b);

	std::vector<std::set<int>> g(n);
	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].insert(b[i]);
		g[b[i]].insert(a[i]);
	}

	REP(i, n) {
		if (g[i].size() % 2 == 1) NO();
	}

	int cnt = 0;
	while (cnt < 3) {
		std::stack<int> st;
		std::set<int> set;
		REP(i, n) if (g[i].size()) {
			st.push(i);
			set.insert(i);
			break;
		}
		if (st.empty()) break;
		int now = st.top();
		int pre = -1;
		while (true) {
			int to = *g[now].begin();
			if (to == pre) to = *g[now].rbegin();
			if (set.count(to)) {
				int t = to;
				while (now != t) {
					g[now].erase(to);
					g[to].erase(now);
					to = now;
					now = st.top(); st.pop();
				}
				g[now].erase(to);
				g[to].erase(now);
				++cnt;
				break;
			}
			else {
				st.push(to);
				set.insert(to);
				pre = now;
				now = to;
			}
		}
	}
	if (cnt >= 3) YES();
	NO();

	return 0;
}

