  }

  vec four;
  bool even = true;
  for (int i = 0; i < N; i++) {
    if (G[i].size() % 4 != 0) even = false;
  }

  int six = 0;
  for (int i = 0; i < N; i++) {
    if (G[i].size() == 8) four.pb(i);
    if (G[i].size() >= 12) six++;
  }

  bool ok;
  if (even && (four.size() >= 3 || six > 0))
    ok = true;
  else if (!even || four.size() <= 1)
    ok = false;
  else {
    int f = max_flow(four[0], four[1]);
    ok = f < 4;
  }

  if (ok)
    cout << "Yes" << endl;
  else
    cout << "No" << endl;

  return 0;
}

