void work(vector<int> & g)
{
    if (ans == 3) return;
    unordered_map<int, int>f;
    f.clear();
    for (int i = g.size() - 1; i > 0;  i --)
        if (!f[g[i]])f[g[i]] = i;
    for (int i = 1; i < g.size() - 1; i ++)
        if (f[g[i]] > i)
        {
            vector<int> gg;
            gg.clear();
            int x = f[g[i]];
            for (int j = i; j <= x; j ++)
                w[g[j]] = 0;
            tot = 1;
            ans ++;
            for (int j = i ; j < x; j ++)
                ins(g[j],g[j  + 1]);
            dfs(g[i], gg);
            work(gg);
            i = x;
            if (ans == 3) return;
        }
}
