using namespace std;
vector<int> make_loop(int start, int N, vector<vector<int>> &edges)
{
    set<int> visited;
    vector<int> path;
    visited.insert(start);
    path.push_back(start);
begin:
    int current = start;
    for (auto neighber : edges[current])
    {
        if (visited.find(neighber) == visited.end())
        {
            current = neighber;
            path.push_back(current);
            goto begin;
        }
        if (neighber == start)
        {
            path.push_back(start);
            return path;
        }
    }
}
void delete_edge(vector<vector<int>> &edges, int x, int y)
{
    auto posY = find(edges[x].begin(), edges[x].end(), y);
    edges[x].erase(posY);
    auto posX = find(edges[y].begin(), edges[y].end(), x);
    edges[y].erase(posX);
}
void delete_loop(vector<vector<int>> &edges, vector<int> &loop)
{
    for (int i = 0; i < loop.size(); i++)
    {
        delete_edge(edges, loop[i], loop[(i + 1) % loop.size()]);
    }
}
int findDegree2(vector<vector<int>> &edges)
{
    for (int i = 0; i < edges.size(); i++)
    {
        if (edges[i].size() >= 2)
            return i;
    }
    return -1;
}
bool solve(int N, int M, vector<vector<int>> &edges)
{
    for (auto edge : edges)
    {
        if (edge.size() % 2 == 1)
            return false;
    }
    int loopCount = 0;
    for (int i = 0; i < 3; i++)
    {
        int start = findDegree2(edges);
        if (start == -1)
            return false;
        vector<int> loop = make_loop(start, N, edges);
        delete_loop(edges, loop);
    }
    return true;
}
int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> edges(N);
    for (int i = 0; i < M; i++)
    {
        int a, b;
        cin >> a >> b;
        edges[a - 1].push_back(b - 1);
        edges[b - 1].push_back(a - 1);
    }
    cout << (solve(N, M, edges) ? "Yes" : "No") << endl;
}
