#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

pair< V<>, V< pair<int, int> > > lowlink(const VV<>& g, V<>& ord, V<>& low, int r = 0) {
  int n = g.size();
  ord.assign(n, -1); // pre-order
  low.assign(n, -1); // 後退辺を高々1回通って到達できる頂点のordのmin
  V<> articulation_points;
  V< pair<int, int> > bridges;
  int t = 0;
  auto dfs = [&](const auto& dfs, int v, int p) -> void {
    ord[v] = low[v] = t++;
    int d = 0;
    bool f = false;
    for (int w : g[v]) if (w != p) {
      if (ord[w] == -1) {
        dfs(dfs, w, v);
        low[v] = min(low[v], low[w]);
        f |= ord[v] <= low[w];
        if (ord[v] < low[w]) bridges.emplace_back(minmax(v, w));
        ++d;
      } else {
        low[v] = min(low[v], ord[w]);
      }
    }
    if (v == r and d >= 2 or v != r and f) {
      articulation_points.push_back(v);
    }
  };
  dfs(dfs, r, -1);
  sort(begin(articulation_points), end(articulation_points));
  sort(begin(bridges), end(bridges));
  return {articulation_points, bridges};
}

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n, m; cin >> n >> m;
  V<> d(n);
  VV<> g(n);
  for (int i = 0; i < m; ++i) {
    int a, b; cin >> a >> b, --a, --b;
    g[a].push_back(b);
    g[b].push_back(a);
    ++d[a], ++d[b];
  }
  if (m < 9) return cout << "No" << '\n', 0;
  for (int i = 0; i < n; ++i) if (d[i] & 1) {
    return cout << "No" << '\n', 0;
  }
  for (int i = 0; i < n; ++i) if (d[i] >= 6) {
    return cout << "Yes" << '\n', 0;
  }
  V<> ord, low;
  V<> as = lowlink(g, ord, low).first;
  sort(begin(as), end(as));
  int cnt = 0;
  for (int i = 0; i < n; ++i) {
    cnt += d[i] == 4;
  }
  if (cnt >= 3) return cout << "Yes" << '\n', 0;
  if (cnt < 2) return cout << "No" << '\n', 0;
  for (int i = 0; i < n; ++i) if (d[i] == 4) {
    if (binary_search(begin(as), end(as), i)) return cout << "Yes" << '\n', 0;
  }
  cout << "No" << '\n';
}

