#define INF (__INT32_MAX__ / 2)
#define MAX_NM 100000

using namespace std;
typedef vector<int>::iterator vecit;
typedef list<int>::iterator listit;

int n, m;
vector<int> adj_list[MAX_NM];

void cut_end(int node) {
    if(adj_list[node].size() == 1) {
        int adj = adj_list[node][0];
        adj_list[node].pop_back();

        for(vecit it = adj_list[adj].begin(); it != adj_list[adj].end(); it++)
            if(*it == node) {
                adj_list[adj].erase(it);
                break;
            }

        cut_end(adj);
    }
}

int find_enabled() {
    for(int i = 1; i <= n; ++i)
        if(adj_list[i].size() > 1)
            return i;
    return -1;
}

int visited[MAX_NM + 1];
bool find_circuit() {

    for(int i = 1; i <= n; ++i) {
        visited[i] = -INF;
        cut_end(i);
    }

    int now = 0;
    int cur = find_enabled();
    if(cur == -1) return false;

    list<int> circuit;
    circuit.push_back(cur);
    while(visited[cur] == -INF) {
        visited[cur] = ++now;
        int next;
        for(int i = 0; i < adj_list[cur].size(); ++i)
            if(visited[adj_list[cur][i]] < now - 1) {
                cur = adj_list[cur][i];
                circuit.push_back(cur);
                break;
            }
    }

    listit end = circuit.end();
    int base = *(--end);
    bool sw = false;
    for(listit it = circuit.begin(); it != circuit.end(); it++) {
        if(*it == base) sw = true;
        if(sw && adj_list[*it].size() == 2) {
            int adj1 = adj_list[*it][0], adj2 = adj_list[*it][1];

            for(vecit jt = adj_list[adj1].begin(); jt != adj_list[adj1].end(); jt++)
                if(*jt == *it) {
                    adj_list[adj1].erase(jt);
                    break;
                }
            for(vecit jt = adj_list[adj2].begin(); jt != adj_list[adj2].end(); jt++)
                if(*jt == *it) {
                    adj_list[adj2].erase(jt);
                    break;
                }

            adj_list[*it].clear();
        }
    }

    return true;
}

int main(int argc, char **argv) {
    scanf("%d %d", &n, &m);
    for(int i = 0; i < m; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj_list[a].push_back(b);
        adj_list[b].push_back(a);
    }

    bool res = true;
    res &= find_circuit();
    if(res)
        res &= find_circuit();
    if(res)
        res &= find_circuit();

    printf(res ? "Yes\n" : "No\n");
}

