bool rec(int v, int s, int& c) {
    if (v == s && c == M) return true;

    for (int i = 0; i < G[v].size(); ++i) {
        if (!G[v][i].used) {
            int u = G[v][i].to;
            G[v][i].used = true;
            G[u][G[v][i].rev].used = true;
            return rec(u, s, ++c);
        }
    }

    return false;
}

