vector<int> par;
int root(int x) {
	if (x == par[x]) return x;
	return par[x] = root(par[x]);
}
bool contain_cycle(int n, vector<int> a, vector<int> b) {
	par.resize(n);
	for (int i = 0; i < n; ++i) par[i] = i;
	for (int i = 0; i < a.size(); ++i) {
		if (root(a[i]) == root(b[i])) {
			return true;
		}
		par[root(a[i])] = root(b[i]);
	}
	return false;
}
