#define yy second
#define has(c,i) ((c).find(i) != end(c))
#define TR(X) ({ if(1) cerr << "TR: " << (#X) << " = " << (X) << endl; })

struct euler_tour {
	ll n;
	vvl adj;
	vl pos, indeg, path;

	euler_tour(vvl adj): n(sz(adj)), adj(adj), pos(n), indeg(n) {
		FOR(i,0,n) for (ll j: adj[i]) indeg[j]++;
	}

	void rec(ll i) {
		while (pos[i] < sz(adj[i])) rec(adj[i][ pos[i]++ ]);
		path.pb(i);
	}

	bool construct() {
		ll s = -1, t = -1;
		FOR(i,0,n) {
			ll in = indeg[i], out = sz(adj[i]);
			if (abs(in-out) > 1) return false;
			if (in < out) { if (s < 0) s = i; else return false; }
			if (in > out) { if (t < 0) t = i; else return false; }
		}
		if ((s < 0) != (t < 0)) return false;
		if (s < 0) FOR(i,0,n) if (sz(adj[i])) s = i;
		if (s < 0) return true;
		rec(s);
		reverse(all(path));
		return sz(path) == accumulate(all(indeg),0) + 1;
	}
};

bool solve() {
	ll n, m;
	cin >> n >> m;

	vvl adj(n);
	while (m--) {
		ll a, b;
		cin >> a >> b;
		a--, b--;
		adj[a].pb(b);
		adj[b].pb(a);
	}

	euler_tour E(adj);
	if (!E.construct()) return false;
	if (E.path[0] != E.path.back()) return false;

	map<ll,ll> deg_cnt;
	FOR(i,0,n) deg_cnt[min(6LL,sz(adj[i]))]++;

	if (deg_cnt[6] >= 1) return true;
	if (deg_cnt[4] <= 1) return false;
	if (deg_cnt[4] >= 3) return true;

	ll i = 0;
	while (sz(adj[i]) == 2) i++;

	for (ll j: adj[i]) {
		ll a = i, b = j;
		while (sz(adj[b]) == 2) {
			a ^= adj[b][0] ^ adj[b][1];
			swap(a,b);
		}
		if (b == i) return true;
	}
	return false;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cout << (solve() ? "Yes" : "No") << endl;
}

