#include <bits/stdc++.h>

using namespace std;

const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n, m;
vector<int> G[N], vec[N];
int f[N], g[N];

bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        G[u - 1].emplace_back(v - 1);
        G[v - 1].emplace_back(u - 1);
    }

    return true;
}

void solve() {
    for (int i = 0; i < n; ++i)
        if (G[i].size() % 2 != 0) {
            cout << "No\n";
            return ;
        }

    vector<int> S, path;
    S.emplace_back(0);
    set< pair<int, int> > used;

    for (; !S.empty(); ) {
        auto v = S.back();
        S.pop_back();

        for (const auto& to : G[v])
            if (!used.count(make_pair(min(v, to), max(v, to)))) {
                S.emplace_back(to);
                used.insert(make_pair(min(v, to), max(v, to)));
                break;
            }

        path.emplace_back(v);
    }

    auto len = path.size();
    path.insert(path.end(), path.begin() + 1, path.end());

    for (int i = 0; i < path.size(); ++i)
        vec[path[i]].emplace_back(i);

    int minr = MOD;
    f[path.size()] = MOD;

    for (int i = path.size() - 1; i >= 0; --i) {
        int v = path[i];

        if (i == vec[v].back()) {
            f[i] = f[i + 1];
            continue;
        }

        auto it = lower_bound(vec[v].begin(), vec[v].end(), minr);

        if (it != vec[v].end())
            f[i] = min(*it, f[i + 1]);
        else
            f[i] = f[i + 1];

        minr = min(minr, *upper_bound(vec[v].begin(), vec[v].end(), i));

        if (i < len && f[i + 1] < i + len) {
            cout << "Yes\n";
            return ;
        }
    }

    g[path.size()] = MOD;

    for (int i = path.size() - 1; i >= 0; --i) {
        int v = path[i];

        if (i == vec[v].back()) {
            f[i] = f[i + 1];
            g[i] = g[i + 1];
            continue;
        }

        int j = *upper_bound(vec[v].begin(), vec[v].end(), i);
        f[i] = min(f[i + 1], g[j]);
        g[i] = min(g[i + 1], j);

        if (i < len && f[i + 1] < i + len) {
            cout << "Yes\n";
            return ;
        }
    }

    cout << "No\n";
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

