bool judge(vvll g, ll N) {
	vll four;
	repn(i, N) {
		if (g[i].size() % 2 == 1) { return false; }
	}
	repn(i, N) {
		if (g[i].size() >= 6) { return true; }
		if (g[i].size() == 4) { four.push_back(i); }
	}

	if (four.size() <= 1) { return false; }
	if (four.size() >= 3) { return true; }

	ll u = four[0];
	ll v = four[1];

	rep(j, 4) {
		ll x = g[u][j];
		ll y = u;

		while (x != u && x != v) {
			ll t;
			if (g[x][0] != y) { t = g[x][0]; }
			else { t = g[x][1]; }

			y = x;
			x = t;
		}

		if (x == u) { return true; }
	}

	return false;
}

