  vector<vector<int>> G(N);
  for(int i = 0; i < M; ++i){
    int v, w;
    cin >> v >> w;
    --v,--w;
    G[v].push_back(w);
    G[w].push_back(v);
  }
  if(M < 6){
    cout << "No" << endl;
    return 0;
  }
  int t = 0;
  for(int i = 0; i < N; ++i){
    if(G[i].size()%2){
      cout << "No" << endl;
      return 0;
    }
  }
