    if(idx[v] < 0){
      idx[v] = i;
      continue;
    }
    V.emplace_back(i,idx[v]);
    idx[v] = i;
  }
  sort(V.begin(), V.end());
  segtree<int> seg(upd, fnd, INF);
  for(size_t i = 0; i < V.size(); ++i){
