bool isDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    if(deleted.find({a, b}) == deleted.end())
        return false;
    return true;
}

void addToDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    deleted.emplace(make_pair(a, b));
}

int cnt[MaxN];

void solve(int x)
{
    while(true)
    {
        while(!v[x].empty() && isDeleted(x, v[x].back()))
            v[x].pop_back();

        if(v[x].empty())
            break;

        int to = v[x].back();

        addToDeleted(x, to);
        v[x].pop_back();

        solve(to);

        ++cnt[x];
    }
}

