void add_edge(int a,int b)
{
	e[en].enext = v[a].estart;e[en].to = b;v[a].estart = en++;
}
int ea,eb,va;
void dfs(int i)
{
	v[i].vis = true;
	for(int j = v[i].estart;j != -1;j = e[j].enext) {
		int to = e[j].to;
		if(!v[to].vis) {
			v[to].vis = true;
			v[to].parent = i;
			v[to].depth = v[i].depth + 1;
			dfs(to);
		} else if(to != v[i].parent && v[to].depth < v[i].depth && va == -1) {
			for(int k = i;k != to;k = v[k].parent) {
