const int N = 1e5 + 10;
int n, m, rd[N];
int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1, x, y; i <= m; ++i) {
        scanf("%d%d", &x, &y);
        ++rd[x]; ++rd[y];
    }
    for (int i = 1; i <= n; ++i) if (rd[i] & 1) return puts("No"), 0;
    for (int i = 1; i <= n; ++i) if (rd[i] >= 6) return puts("Yes"), 0;
