#include <cstdio>
#include <vector>
#include <utility>
using namespace std;
vector<int> e[100010], ei[100010];
int d[100010], u[100010], n;
pair<int, int> st[100010];
int stn;
int dfs(int v, int k, int p = -1) {
	d[v] = 1;
	for (int i = 0; i < e[v].size(); i++) {
		int w = e[v][i];
		if (w == p) continue;
		if (u[ei[v][i]]) continue;
		if (d[w]) {
			u[ei[v][i]] |= k;
			do {
				u[st[--stn].second] |= k;
			} while (st[stn].first != w);
			return 1;
		} else {
			st[stn++] = make_pair(v, ei[v][i]);
			if (dfs(w, k, v)) return 1;
			--stn;
		}
	}
	return 0;
}
int go(int k) {
	for (int i = 0; i < n; i++) {
		if (!d[i] && dfs(i, 1 << k)) return 1;
	}
	return 0;
}
int cnt[4], col[100010];
void dfs2(int v, int p = -1) {
	d[v] = 1;
	for (int i = 0; i < e[v].size(); i++) {
		int w = e[v][i];
		if (w == p) continue;
		if (col[w]) {
			cnt[col[w]]++;
		} else if (!d[w]) {
			dfs2(w, p);
		}
	}
}
int go2(int k) {
	for (int v = 0; v < n; v++) {
		for (int j = 0; j < e[v].size(); j++) {
			if (u[ei[v][j]]) {
				col[j] |= u[ei[v][j]];
				col[e[v][j]] |= u[ei[v][j]];
			}
		}
	}
	for (int i = 0; i < n; i++) {
		d[i] = 0;
	}
	int c = 0, p[4] = {};
	for (int i = 0; i < n; i++) {
		if (col[i] || d[i]) continue;
		for (int j = 0; j < 4; j++) {
			cnt[j] = 0;
		}
		dfs2(i);
		if (cnt[1] + cnt[3] >= 2) p[1]++;
		if (cnt[2] + cnt[3] >= 2) p[2]++;
	}
	if (p[1] >= 1) c += p[1] - 1;
	if (p[2] >= 1) c += p[2] - 1;
	return 3 - k <= c;
}
int main() {
	int m;
	scanf("%d%d", &n, &m);
	for (int i = 0; i < m; i++) {
		int x, y;
		scanf("%d%d", &x, &y);
		--x; --y;
		e[x].push_back(y);
		ei[x].push_back(i);
		e[y].push_back(x);
		ei[y].push_back(i);
	}
	for (int i = 0; i < 3; i++) {
		for (int j = 0; j < n; j++) {
			d[j] = 0;
		}
		if (!go(i)) {
			if (i == 0 || !go2(i)) {
				puts("No");
				return 0;
			} else {
				break;
			}
		}
	}
	puts("Yes");
	return 0;
}

