int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N,M; cin >> N >> M;
    vector<vector<int>> G(N);
    vector<int> deg(N);
    rep(i,M) {
        int a,b; cin >> a >> b;
        --a; --b;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
        deg[a]++;
        deg[b]++;
    }

    int cnt2 = 0, cnt4 = 0;
    rep(i,N) {
        if (deg[i]&1) No();
        if (deg[i]==2) cnt2++;
        else if (deg[i]==4) cnt4++;
        else Yes(); 
    }
    if (cnt4 <= 1) No();
    if (cnt4 >= 3) Yes();
    int a = -1, b = -1;
    rep(i,N) {
        if (a==-1 and deg[i]==4) a = i;
        else if (b==-1 and deg[i]==4) b = i;
    }
    vector<bool> check(N);
    check[a] = check[b] = 1;
    auto dfs=[&](auto&& self, int v, int pv)->void {
        for (auto nv : G[v]) {
            if (nv==pv) continue;
            if (nv==a) Yes();
            if (check[nv]) continue;
            check[nv] = 1;
            self(self,nv,v);
        }
    };

    dfs(dfs,a,-1);
    No();
}

