	int to; bool tag;
	edge *nxt, *rev;
}edges[2*MAXN + 5], *adj[MAXN + 5], *ecnt = edges;
void addedge(int u, int v) {
	edge *p = (++ecnt), *q = (++ecnt);
	p->to = v, p->nxt = adj[u], adj[u] = p;
	q->to = u, q->nxt = adj[v], adj[v] = q;
	p->rev = q, q->rev = p;
}

int arr[MAXN + 5], cnt;
void dfs(int x) {
	for(;adj[x];) {
		edge *p = adj[x]; adj[x] = adj[x]->nxt;
		if( p->tag ) continue;
		p->rev->tag = true, dfs(p->to);
	}
	arr[++cnt] = x;
}

int nxt[MAXN + 5];

int deg[MAXN + 5];

