}

void unaddEdge(int from, int to, int cap = 1) {
    fg[from].eb(to, cap, fg[to].size());
    fg[to].eb(from, cap, fg[from].size() - 1);
}

void fbfs(int s) {
    memset(level, -1, sizeof(level));
    queue<int> que;
    level[s] = 0;
    que.push(s);
    while (!que.empty()) {
        int v = que.front();
        que.pop();
        for (int i = 0; i < fg[v].size(); i++) {
            fedge &e = fg[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                que.push(e.to);
            }
        }
    }
}

int fdfs(int v, int t, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < fg[v].size(); i++) {
        fedge &e = fg[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = fdfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                fg[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}
