template<int SZ> struct Dinic{//SZ = N+1
	typedef int F;struct EDGE{int to,rev;F flow,cap;};
	int lev[SZ],n,s,t;vector<EDGE> E;vector<int> G[SZ];
	vector<int>::iterator cur[SZ];
	void addedge(int u,int v,F cap,bool GH=false){int id=E.size();
		E.eb((EDGE){v,id+1,0,cap});G[u].eb(id);//GH:Undirected
		E.eb((EDGE){u,id,0,GH?cap:0});G[v].eb(id+1);}
	bool bfs(){
		for(int i=0;i<=n;i++)lev[i]=-1;queue<int> q;q.push(s);lev[s]=0;
		while(!q.empty()){int u=q.front();q.pop();
			for(int i:G[u]){auto &e=E[i];int v=e.to;
				if(lev[v]<0&&e.flow<e.cap)    q.push(v),lev[v]=lev[u]+1;}
		}return lev[t]>=0;}
	F dfs(int u,F flow){
		if(u==t)	return flow;
		for(;cur[u]!=G[u].end();cur[u]++){auto &e=E[*cur[u]];int v=e.to;
			if(e.flow<e.cap&&lev[u]+1==lev[v]){
				F df=dfs(v,min(flow,e.cap-e.flow));
				if(df>0){e.flow+=df;E[e.rev].flow-=df;return df;}
			}}return 0;}
	F maxflow(int n_,int s_,int t_){
		n=n_;s=s_;t=t_;F flow=0;
		while(bfs()){
			for(int i=0;i<=n;i++)	cur[i]=G[i].begin();
			while(F df=dfs(s,numeric_limits<F>::max()))	flow+=df;
		}return flow;}
};

