#define SIZE 200010

vector<int> g[SIZE];

int bfs(int start, int goal){
  bool visited[SIZE] = {};
  queue<int> que;

  for(int p : g[start])
    que.push(p);

  int res = 0;

  while(que.size()){
    int now = que.front(); que.pop();

    if (visited[now]) continue;

    if(now == start) continue;

    if(now == goal) {
      res++;
      continue;
    }

    visited[now] = true;

    for(int p : g[now]){
      que.push(p);
    }
  }

  return res <= 2;
}

