struct Dinic{
	const long long INF=1e18+9;

	struct edge {
		int to,rev;
		long long cap;
		edge(){}
		edge(int to,long long cap,int rev):to(to),cap(cap),rev(rev){}
	};

	int n;
	vector<vector<edge> > G;
	vector<map<int,int> > M;
	vector<int> level,iter;

	Dinic(){}
	Dinic(int sz):n(sz),G(n),M(n),level(n),iter(n){}

	void add_edge(int from,int to,long long cap){
		M[from][to]=G[from].size();
		M[to][from]=G[to].size();
		G[from].push_back(edge(to,cap,G[to].size()));
		// undirected
		G[to].push_back(edge(from,cap,G[from].size()-1));
		// directed
		// G[to].push_back(edge(from,0,G[from].size()-1));
	}

	void bfs(int s){
		fill(level.begin(),level.end(),-1);
		queue<int> que;
		level[s]=0;
		que.push(s);
		while(!que.empty()){
			int v=que.front();que.pop();
			for(int i=0;i<(int)G[v].size();i++){
				edge &e = G[v][i];
				if(e.cap>0&&level[e.to]<0){
					level[e.to]=level[v]+1;
					que.push(e.to);
				}
			}
		}
	}

	long long dfs(int v,int t,long long f){
		if(v==t) return f;
		for(int &i=iter[v];i<(int)G[v].size();i++){
			edge &e=G[v][i];
			if(e.cap>0&&level[v]<level[e.to]){
				long long d = dfs(e.to,t,min(f,e.cap));
				if(d>0){
					e.cap-=d;
					G[e.to][e.rev].cap+=d;
					return d;
				}
			}
		}
		return 0;
	}

	long long flow(int s,int t,long long lim){
		long long fl=0;
		for(;;){
			bfs(s);
			if(level[t]<0||lim==0) return fl;
			fill(iter.begin(),iter.end(),0);
			long long f;
			while((f=dfs(s,t,lim))>0){
				fl+=f;
				lim-=f;
			}
		}
	}

	long long flow(int s,int t){
		return flow(s,t,INF);
	}

	//cap==1 only
	bool back_edge(long long s,long long t,long long from, long long to){
		for(long long i=0;i<(long long)G[from].size();i++) {
			edge& e=G[from][i];
			if(e.to==to) {
				if(e.cap==0&&flow(from,to,1)==0) {
					flow(from,s,1);
					flow(t,to,1);
					return 1;
				}
			}
		}
		return 0;
	}
};

