	}
	int F[100010] = {}; 
	int S = -1; int G = -1; 	
	for(int i = 0; i < N; i++){
		F[i] = E[i].size(); 
		if(S == -1 && F[i] == 4) {S = i; continue;}
		if(S >= 0 && G == -1 && F[i] == 4) G = i; 
	}
	sort(F, F+N, greater<int>()); 
	bool possible = true; 
	for(int i = 0; i < N; i++){
		if(F[i] % 2) possible = false; 
	}
	if(F[0] == 2) possible = false; 
	if(N >= 2 && F[0] == 4 && F[1] == 2) possible = false; 
	if(N >= 3 && F[0] == 4 && F[1] == 4 && F[2] == 2){
		int a = E[S].at(0); int b = E[S].at(1); 
		int c = E[S].at(2); int d = E[S].at(3); 
