			if(A.at(A.size() - 1) == G){
				score ++; break; 
			}
			int p = E[A.at(A.size()-1)].at(0); 
			int q = E[A.at(A.size()-1)].at(1); 
			if(p != A.at(A.size()-2)) A.push_back(p); 
			else A.push_back(q);  
		}
		for(int i = 0; i < 114514; i++){
			if(B.at(B.size() - 1) == S) break; 
			if(B.at(B.size() - 1) == G){
				score ++; break; 
			}
			int p = E[B.at(B.size()-1)].at(0); 
			int q = E[B.at(B.size()-1)].at(1); 
			if(p != B.at(B.size()-2)) B.push_back(p); 
			else B.push_back(q);  
		}
		for(int i = 0; i < 114514; i++){
			if(C.at(C.size() - 1) == S) break; 
			if(C.at(C.size() - 1) == G){
				score ++; break; 
			}
			int p = E[C.at(C.size()-1)].at(0); 
			int q = E[C.at(C.size()-1)].at(1); 
			if(p != C.at(C.size()-2)) C.push_back(p); 
			else C.push_back(q);  
		}
		for(int i = 0; i < 114514; i++){
