        edge_used[i] = false;
        int min = std::min(a[i], b[i]);
        int max = std::max(b[i], a[i]);
        edge_map[std::pair<int, int>({min, max})] = i;

        Edge[a[i]].push_back(i);
        Edge[b[i]].push_back(i);
    }

    int cnt = 0;
    for (int i = 1; i <= N; i++) {
