    vector<int> dg(n, 0);

    vector<vector<int>> g(n);

    for(int i = 0; i < m; i += 1) {
        int a, b; cin >> a >> b;
        a -= 1, b -= 1;
        dg[a] += 1;
        dg[b] += 1;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    for(int i = 0; i < n; i += 1) {
        if(dg[i] % 2) {
            cout << "No\n";
            return 0;
        }
    }

    vector<int> fours;

    for(int i = 0; i < n; i += 1) {
        if(dg[i] >= 6) {
            cout << "Yes\n";
            return 0;
        } else if(dg[i] == 4) {
            fours.push_back(i);
        }
    }

    if(int(fours.size()) >= 3) {
        cout << "Yes\n";
        return 0;
    }

    if(int(fours.size()) < 2) {
        cout << "No\n";
        return 0;
    }

    int source = -1;
    for(int i = 0; i < n; i += 1)
        if(fours[0] != i) {
            source = i;
            break;
        }

    queue<int> q;
    q.push(source);
    vector<int> viz(n, 0);
    viz[source] = 1;

    while(not q.empty()) {
        int node = q.front();
        q.pop();

        for(auto v : g[node]) {
            if(v == fours[0])
                continue;
            if(not viz[v]) {
                viz[v] = 1;
                q.push(v);
            }
        }
    }

    if(accumulate(viz.begin(), viz.end(), 0) < n - 1) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
}

