const int maxn = 1e5;
int n, m, deg[maxn + 10], ans;
struct edge {
	int to, id;
};
vector<edge> g[maxn + 10];
bool vis[maxn + 10];
int cur[maxn + 10];
bool ban[maxn + 10];

int dfs(int p, int fae) {
	vis[p] = 1;	
	for (int &i = cur[p]; i < (int)g[p].size(); ++i) {
		edge e = g[p][i];
		if (e.id != fae && !ban[e.id]) {
			if (vis[e.to]) {
				ban[e.id] = 1; ban[fae] = 1;
				vis[p] = 0; ++i; return e.to;
			} else {
				int w = dfs(e.to, e.id);
				if (w == p) ++ans;
				else {
					vis[p] = 0; ban[fae] = 1; ++i;
					return w;
				}
			}
		}
	}
	assert(!fae);
	vis[p] = 0;
	return 0;
}

