		g[l].push_back((edge){r, i}); g[r].push_back((edge){l, i});
	}
	for (int i = 1; i <= n; ++i)
		if (deg[i] & 1) {
			printf("No"); return 0;
		}
	for (int i = 1; i <= n; ++i) dfs(i, 0);
	printf("%s", ans >= 3 ? "Yes" : "No");
}

