template<class T> inline bool MX(T &l,const T &r){return l<r?l=r,1:0;}
template<class T> inline bool MN(T &l,const T &r){return l>r?l=r,1:0;}

int N;
int M;
set<int> es[114514];
bool used[114514];
int prv[114514];
int depth[114514];

void Erase(int u, int v) {
  rep(i, 2) {
    assert(es[u].count(v));
    es[u].erase(v);
    swap(u, v);
  }
}

bool check() {
  fill(used, used+N, false);
  fill(prv, prv+N, -1);

  queue<int> que;
  int root = -1;
  rep(v, N) {
    if (!es[v].empty()) {
      root = v;
      used[v] = 1;
      que.push(v);
      break;
    }
  }
  if (root == -1) return false;

  using Ans = pair<int, pii>;
  Ans ans(MOD, pii(-1, -1));
  while (!que.empty()) {
    int v = que.front(); que.pop();
    for (int u : es[v]) {
      if (!used[u]) {
        prv[u] = v;
        used[u] = true;
        depth[u] = depth[v]+1;
        que.push(u);
      } else if (prv[v] != u) {
        MN(ans, Ans(1+depth[v]+depth[u], pii(v, u)));
      }
    }
  }
  if (ans.X == MOD) return false;

  int p, q;
  tie(p, q) = ans.Y;
  assert(p != -1);
  Erase(p, q);
  if (depth[p] < depth[q]) swap(p, q);
  while (depth[p] > depth[q]) {
    int np = prv[p];
    Erase(p, np);
    p = np;
  }

  while (p != q) {
    int np = prv[p];
    Erase(p, np);
    p = np;
    int nq = prv[q];
    Erase(q, nq);
    q = nq;
  }
  return true;
}

