const int MAXN = 200005;
vector<int> E[MAXN];
vector<int> findCycle(int n) {
	vector<int> vis(n + 1), par(n + 1), cycle;
	function<bool(int)> dfs = [&](int x) {
		vis[x] = 1;
		for (int y : E[x]) {
			if (!vis[y]) {
				par[y] = x;
				if (dfs(y)) return true;
			} else if (vis[y] == 1) {
				// Back-edge.
				for (;;) {
					cycle.push_back(x);
					if (x == y) break;
					x = par[x];
				}
				reverse(cycle.begin(), cycle.end());
				return true;
			}
		}
		vis[x] = 2;
		return false;
	};
	for (int i = 1; i <= n; ++i)
		if (!vis[i] && dfs(i)) break;
	return cycle;
}
set<pair<int, int>> badEdges;
bool used[MAXN];
int cnt;
void dfs(int x) {
	used[x] = true;
	++cnt;
	for (int y : E[x]) {
		if (badEdges.count({x, y})) continue;
		if (used[y]) continue;
		dfs(y);
	}
}
