		E[a].push_back(b);
		E[b].push_back(a);
		++deg[a];
		++deg[b];
	}
	bool all2 = true;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] & 1) no();
		else if (deg[i] != 2) all2 = false;
	}
	if (all2) no();
	auto cycle = findCycle(n);
	assert(!cycle.empty());
	int x = cycle[0];
	cycle.push_back(x);
	for (int i = 0; i + 1 < cycle.size(); ++i) {
		badEdges.insert({cycle[i], cycle[i + 1]});
		badEdges.insert({cycle[i + 1], cycle[i]});
		--deg[i];
		--deg[i + 1];
	}
	all2 = true;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] > 0 && deg[i] != 2) all2 = false;
	}
