struct BiconnectedComponent {
  vector<int> ord, low;
  vector<bool> used;
  vector<vector<int>> g;
  vector<vector<pair<int, int>>> bc;
  vector<pair<int, int>> tmp;
  int n, k = 0;
  BiconnectedComponent(const vector<vector<int>> &g) : g(g) {
    n = g.size();
    ord.resize(n, -1);
    low.resize(n, -1);
    used.resize(n, false);
  }
  void dfs(int u, int prev) {
    used[u] = true;
    ord[u] = k ++;
    low[u] = ord[u];
    int cnt = 0;
    for (auto v : g[u]) if (v != prev) {
      if (ord[v] < ord[u]) { 
        tmp.emplace_back(min(u, v), max(u, v));
      }
      if (!used[v]) {
        cnt ++;
        dfs(v, u);
        low[u] = min(low[u], low[v]);
        if (low[v] >= ord[u]) {
          bc.push_back({});
          while (true) {
            pair<int, int> e = tmp.back();
            bc.back().emplace_back(e);
            tmp.pop_back();
            if (min(u, v) == e.first && max(u, v) == e.second) {
              break;
            }
          }
        }
      } else {
        low[u] = min(low[u], ord[v]);
      }
    }
  }
};

bool solve() {
  int N = si(), M = si();
  vvi G(N);
  vector<int> deg(N);
  REP(i, M) {
    int u = si() - 1, v = si() - 1;
    G[u].push_back(v);
    G[v].push_back(u);
    deg[u]++;
    deg[v]++;
  }
  REP(i, N) if (deg[i] % 2 == 1) return false;
  REP(i, N) if (deg[i] >= 6) return true;
  BiconnectedComponent bc(G);
  bc.dfs(0, -1);
  if (bc.bc.size() >= 3) return true;
  if (bc.bc.size() == 1) {
    REP(i, N) if (deg[i] >= 4) return true;
    return false;
  }
  abort();
  int c = 0;
  REP(i, N) if (deg[i] >= 4) c++;
  return c >= 2;
}

int main() {
  cout << (solve() ? "Yes" : "No") << '\n';
}

