#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
typedef pair<int, int> pii;

const int MAX_N = 100 * 1000 + 5;
int n, m, par[MAX_N], h[MAX_N];
map<pair<int, int>, bool> del;
bool mark[MAX_N];
vector<int> adj[MAX_N];

void read_input() {
	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

pii dfs(int v, int cur_h = 0) {
	mark[v] = true;
	h[v] = cur_h;
	pii res = {-1, v};
	for (int u: adj[v])
		if (!del[{u, v}]) {
			if (!mark[u]) {
				par[u] = v;
				pii p = dfs(u, cur_h + 1);
				if (~p.F && (!~res.F || h[p.F] > h[res.F] || (h[p.F] == h[res.F] && h[p.S] < h[res.S])))
					res = p;
			}
			else if (u != par[v] && h[u] < h[v] && (!~res.F || h[u] >= h[res.F]))
				res = {u, v};
		}
	return res;
}

bool check(pii p) {
	int u = p.F, v = p.S;
	if (!~u)
		return false;
	int x = v;
	par[u] = v;
	do {
		del[{x, par[x]}] = true;
		del[{par[x], x}] = true;
		x = par[x];
	} while (x != v);
	return true;
}

void solve() {
	for (int i = 0; i < n; i++)
		if ((int) adj[i].size() % 2) {
			cout << "No";
			exit(0);
		}
	for (int i = 0; i < 2; i++) {
		for (int v = 0; v < n; v++) {
			par[v] = -1;	
			if (!mark[v] && check(dfs(v)))
				break;
		}
		memset(mark, false, sizeof mark);
	}
	for (int v = 0; v < n; v++)
		if (!mark[v]) {
			par[v] = -1;
			if (check(dfs(v))) {
				cout << "Yes";
				exit(0);
			}
		}
	cout << "No";
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	read_input();
	solve();
}

