    read(N, M);
    FOR(i, M) {
        int a, b;
        read(a, b);
        ec.addEdge(--a, --b);
        mf.addEdge(a, b, 1, 1);
    }
    writeln(ec.run(N) && (check1() || check2() || check3()) ? "Yes" : "No");
    return 0;
}

