class LowLink
{
    using Graph = std::vector<std::vector<int>>;
    using P = std::pair<int, int>;
    Graph G;
    std::vector<int> order;
    int next = 0;
    std::set<P> bridges;

    void add(int a, int b)
    {
        bridges.insert(P(std::min(a, b), std::max(a, b)));
    }
    int dfs(int cur, int pre)
    {
        int res = order[cur] = next++;
        for (const auto &to : G[cur])
        {
            if (to == pre)
                continue;
            if (order[to] >= 0)
                res = std::min(res, order[to]);
            else
            {
                int low = dfs(to, cur);
                if (low > order[cur])
                    add(cur, to);
                res = std::min(res, low);
            }
        }
        return res;
    }

  public:
    LowLink(int _v) : G(_v, std::vector<int>()), order(_v, -1) {}
    void addEdge(int s, int t)
    {
        G[s].push_back(t);
    }
    std::set<P> bridge()
    {
        // 連結であることを想定
        dfs(0, -1);
        // 非連結の場合
        // for(int i = 0;i < (int)order.size(); i++) if(order[i] == -1) dfs(i, -1);
        return bridges;
    }
};

