	while (!S.empty() && S.begin()->first == 2) {
		auto p = *S.begin();
		S.erase(S.begin());
		int u = a[p.second][0];
		int v = a[p.second][1];
		a[p.second].clear();
		m -= 1;
		if (u == v) {
			++num_cycles;
			continue;
		}
		S.erase({(int)a[u].size(), u});
		S.erase({(int)a[v].size(), v});
