}

struct edge {
	int to, nxt;
} graph[M << 1];
int n, m, head[N], deg[N], cnt = 0;
void addedge (int u, int v) {
	edge e = {v, head[u]};
	graph[head[u] = cnt++] = e;
}

bool check (int s, int u, int t) {
	int prv = s;
	while (u != s && u != t) {
		int v;
		for (int i = head[u]; ~i; i = graph[i].nxt) {
			if (graph[i].to != prv) v = graph[i].to;
		}
		prv = u, u = v;
	}
	return u == t;
}
int main () {
	read(n), read(m);
	for (int i = 1; i <= n; i++) head[i] = -1, deg[i] = 0;
	for (int i = 1; i <= m; i++) {
		int u, v;
		read(u), read(v);
		addedge(u, v), addedge(v, u);
		deg[u]++, deg[v]++;
	}

	int deg4 = 0, bigdeg = 0;
	bool flag = true;
	for (int i = 1; i <= n; i++) {
		if (deg[i] & 1) flag = false;
		if (deg[i] == 4) deg4++;
		else if (deg[i] > 4) bigdeg++;
	}

	if (!flag) printf("No\n");
	else {
		if (bigdeg) printf("Yes\n");
		else if (deg4 > 2) printf("Yes\n");
		else if (deg4 <= 1) printf("No\n");
		else {
			vector<int> vec;
			for (int i = 1; i <= n; i++) {
				if (deg[i] == 4) vec.push_back(i);
