        {
            return p1.second < p2.second;
        }
        return p1.first < p2.first;
    }
};

int main()
{
    int n, m;
    cin >> n >> m;
    set<pi, picomp> s;
    for (int i = 0; i < m; i++)
    {
        int a, b;
        cin >> a >> b;
        s.insert(make_pair(a, b));
        s.insert(make_pair(b, a));
    }
    int circuitnum = 0;
    while (s.size() > 0) {
        //int first = (*s.begin()).first;
        //int first = (*(++(s.end()))).first;
        int r = rand() % s.size();
        auto it = s.begin();
        advance(it, r);
        int first = (*it).first;
        int current = first;
        set<int> visited;
        vector<int> visited_ord;
        visited.insert(first);
        visited_ord.push_back(first);
        while (true) {
            auto it = s.lower_bound(make_pair(current, -1));
            if (it == s.end() || (*it).first != current) {
                //cout << "circut search failure" << endl;
                cout << "No" << endl;
                return 0;
            }
            int next = (*it).second;
            //printf("current=%d next=%d\n", current, next);
            s.erase(s.find(make_pair(current, next)));
            s.erase(s.find(make_pair(next, current)));
            if (visited.find(next) != visited.end()) {
                // circuit found
                circuitnum++;
                visited.clear();
                vector<int> visited_ord_new;
                for (auto n : visited_ord) {
                    visited.insert(n);
                    visited_ord_new.push_back(n);
                    if (n == next) {
                        break;
                    }
                }
                visited_ord = visited_ord_new;
            } else {
                visited.insert(next);
                visited_ord.push_back(next);
            }
            //cout << "current=" << current << " next=" << next << " circuitnum=" << circuitnum << " // " << visited_ord << endl;
            if (first == next) {
                //circuitnum++;
                break;
            }
            current = next;
        }
    }
    //cout << "circuit num=" << circuitnum << endl;
    if (circuitnum >= 3) {
        cout << "Yes" << endl;
    } else {
