set<int> cur;

set<int> hoge[2];

set<int> g[100005];

const int OK = 2000000;
const int NG = -1;

int dfs(int v, int from = -1){
  cur.insert(v);

  for(auto to : g[v]) if(to != from){
    int r = -1;
    if(cur.count(to) == 1) {
      r = to;
    }
    else {
      r = dfs(to, v);
    }
    if(r == OK){ return OK; }
    if(r > -1){
      hoge[0].insert(v);
      g[v].erase(to);
      g[to].erase(v);
      if(r == v) return OK;
      else return r;
    }
    if(r == NG) return NG;
  }
  return NG;
}

bool solve(){
  int n,m;
  cin>>n>>m;
  rep(i,m){
    int a,b;
    cin>>a>>b;
    a--;b--;
    g[a].insert(b);
    g[b].insert(a);
  }

  int cnt = 0;
  rep(i,n){
    while(g[i].size() > 0) {
      cur.clear();
      int r = dfs(i);
      if(r == OK) {
        cnt++;
        swap(hoge[0], hoge[1]);
      }
      else {
        assert(r == NG);
        return false;
      }
    }
  }

  if(cnt == 2) {
    int xx = 0;
    for(auto x : hoge[0]) if(hoge[1].count(x) ==1 ) xx++;
    if(xx>=3) cnt++;
  }

  return cnt >= 3;
}

