	fa[x]=f;
	for(int i=head[x];i;i=nex[i]){
		if(flag) return;
		if(e[i]==f) continue;
		if(!fa[e[i]]){
			if(flag) return;
			c[e[i]]=(i+1)/2;
			dfs(e[i],x);
