    vector<int> deg(N);
    vector< vector<int> > G(N);
    for(int i=0; i<M; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
        deg[u]++, deg[v]++;
    }

