int cnt[100005];


int main() {
	int n,m;
	scanf("%d%d", &n, &m);
	VVI g(n);
	REP(i, m) {
		int a, b;
		scanf("%d%d", &a, &b);
		a--, b--;
		cnt[a]++;
		cnt[b]++;
		g[a].PB(b);
		g[b].PB(a);
	}
	int x = 0;
	REP(i, n) {
		if (cnt[i] % 2) {
			printf("No\n");
			return 0;
		}
		x += (cnt[i] - 2) / 2;
	}
	REP(i, n) {
		for (auto to : g[i]) {
			if (to < i)continue;
			if (cnt[i] >= 4 && cnt[to] >= 4) {
				x--;
			}
		}
	}
	if (x >= 2)printf("Yes\n");
	else printf("No\n");
	return 0;
}

