int N, M;
set<int> pathes[100500];
int degree[100500];
vector<int> tour;
int start;
int num_circuit = 0;
int before[100500];

void bfs(int from) {
    if(pathes[from].empty()) return;
    tour.push_back(from);
    auto itr = pathes[from].begin();
    pathes[from].erase(*itr);
    auto itr2 = pathes[*itr].lower_bound(from);
    pathes[*itr].erase(itr2);
    bfs(*itr);
}

void solve() {
    //cout.precision(10);
    bool win = false;
    start = -1;
    for(int i = 1; i <= N; i++) {
        if(degree[i] % 2 != 0) {
            //cout << "No" << endl;
            num_circuit = -99;
            return;
        }
        if(degree[i] > 0) start = i;
        if(degree[i] >= 6) win = true;
    }
    if(win) {
        //cout << "Yes" << endl;
        //cerr << "a" << endl;
        num_circuit = 99;
        return;
    }
    //cerr << start << endl;
    if(start == -1) {
        //cout << "No" << endl;
        num_circuit = -99;
        return;
    }
    //start = 1;
    tour.clear();
    bfs(start);
    for(int i = 1; i <= N; i++) {
        before[i] = -1;
    }
    vector<l_l> circuit;
    //for(int i = 0; i < tour.size(); i++) cout << tour[i] << endl;
    //cout << endl;
    for(int i = 1; i < tour.size(); i++) {
        int val = tour[i];
        if(before[val] != -1) {
            circuit.push_back({before[val], i});
        }
        before[val] = i;
    }
    num_circuit++;
    if(circuit.size() == 0) {
        //cout << "No" << endl;
        return;
    }
    num_circuit++;
    ll RIGHT = 1e7;
    ll LEFT = -1e7;
    sort(circuit.begin(), circuit.end());
    /*
    for(int i = 0; i < circuit.size(); i++) {
        RIGHT = min((ll)RIGHT, circuit[i].second);
        if(circuit[i].second < circuit.back().first) {
            //cout << "Yes" << endl;
            //cerr << "b" << endl;
            num_circuit = 99;
            return;
        }
    }
    for(int i = 0; i < circuit.size(); i++) {
        if(RIGHT < circuit[i].first) {
            num_circuit = 99;
            return;
        }
    }
    */
    for(int i = 0; i < circuit.size(); i++) {
        RIGHT = min(RIGHT, circuit[i].second);
        LEFT = max(LEFT, circuit[i].first);
    }
    if(LEFT > RIGHT) {
        num_circuit = 99;
        return;
    }
    int r = -1;
    for(int i = 0; i < circuit.size(); i++) {
        if(circuit[i].second < r) {
            //cout << "Yes" << endl;
            num_circuit = 99;
            //cerr << "c" << endl;
            return;
        }
        r = max((ll)r, circuit[i].second);
    }
    //cout << "No" << endl;
    return;
}

int main() {
    cin >> N >> M;
    cin.tie(0);
    ios::sync_with_stdio(false);
    for(int i = 1; i <= M; i++) {
        int a, b;
        cin >> a >> b;
        pathes[a].insert(b);
        pathes[b].insert(a);
        degree[a]++;
        degree[b]++;
    }
    while(true) {
        for(int i = 1; i <= N; i++) degree[i] = pathes[i].size();
        //for(int i = 1; i <= N; i++) cerr << i << " " << degree[i] << endl;;
        solve();
        //cerr << num_circuit << endl;
        if(num_circuit >= 3) {
            cout << "Yes" << endl;
            return 0;
        }
        if(num_circuit < 0) {
            cout << "No" << endl;
            return 0;
        }
    }
}

#include <bits/stdc++.h>

const int MAXN = 100010;
void bye() { std::cout << "No\n"; exit(0); }
int deg[MAXN], xs[MAXN], ys[MAXN];
int n, m, vis[MAXN], tc;
int head[MAXN], nxt[MAXN << 1], to[MAXN << 1];
void addedge(int b, int e, int tot) {
	nxt[++tot] = head[b]; to[head[b] = tot] = e;
	nxt[++tot] = head[e]; to[head[e] = tot] = b;
}
int dfs(int u, int fa = 0) {
	vis[u] = true;
	for (int i = head[u]; i; i = nxt[i])
		if (to[i] != fa) {
			if (vis[to[i]]) {
				xs[i >> 1] = 0;
				++tc;
				return true;
			}
			if (dfs(to[i], u)) {
				xs[i >> 1] = 0;
				++tc;
				return true;
			}
		}
	return false;
}
void reducecir() {
	memset(vis, 0, n + 1 << 2);
	memset(head, 0, n + 1 << 2);
	for (int i = 1; i <= m; ++i) if (xs[i])
		addedge(xs[i], ys[i], i * 2 - 1);
	for (int i = 1; i <= n; ++i) if (!vis[i] && dfs(i)) return ;
}

int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n >> m;
	for (int i = 1; i <= m; ++i) {
		std::cin >> xs[i] >> ys[i];
		++deg[xs[i]]; ++deg[ys[i]];
	}
	for (int i = 1; i <= n; ++i) if (deg[i] & 1) bye();
	reducecir();
	if (tc < m) reducecir();
	if (tc == m) bye();
	std::cout << "Yes\n";
	return 0;
}

