			if (abs(in-out) > 1) return false;
			if (in < out) { if (s < 0) s = i; else return false; }
			if (in > out) { if (t < 0) t = i; else return false; }
		}
		if ((s < 0) != (t < 0)) return false;
		if (s < 0) FOR(i,0,n) if (sz(adj[i])) s = i;
		if (s < 0) return true;
		rec(s);
		reverse(all(path));
		return sz(path) == accumulate(all(indeg),0) + 1;
	}
};

bool solve() {
	ll n, m;
	cin >> n >> m;

	vvl adj(n);
	while (m--) {
		ll a, b;
		cin >> a >> b;
		a--, b--;
		adj[a].pb(b);
		adj[b].pb(a);
	}

	euler_tour E(adj);
	if (!E.construct()) return false;
	if (E.path[0] != E.path.back()) return false;

	map<ll,ll> deg_cnt;
	FOR(i,0,n) deg_cnt[min(6LL,sz(adj[i]))]++;

	if (deg_cnt[6] >= 1) return true;
	if (deg_cnt[4] >= 2) return true;
	return false;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cout << (solve() ? "Yes" : "No") << endl;
}

