inline void Tarjan(int k){
	dfn[k]=low[k]=++tim; int son=0;
	for(int x=Root[k];x;x=Next[x]){
		int v=Node[x]; if(!dfn[v]){
			++son; fa[v]=k; Tarjan(v);
			low[k]=min(low[k],low[v]);
