    cur.push_back(v);
    was[v] = 1;
    pas[v] = 1;

    int s = -1;
    for(int p : g[v]) {
      if(used[p]) continue;
      int u = (edges[p].u == v ? edges[p].v : edges[p].u);
      if(u == par) continue;
      if(was[u]) s = u;
    }

    if(~s) {
      reverse(cur.begin(), cur.end());
      while(cur.back() != s) cur.pop_back();
      range(i, 0, (int) cur.size()) to.insert(make_pair(cur[i], cur[(i + 1) % cur.size()]));
      return;
    }

    for(int p : g[v]) {
      if(used[p]) continue;
      int u = edges[p].u == v ? edges[p].v : edges[p].u;
      if(u == par) continue;
      if(!pas[u]) dfs(u, v);
      if(!to.empty()) return;
    }

    was[v] = 0;
    cur.pop_back();
  };
  dfs(0, -1);
  assert(to.size());
  int bug = 0;

  A:;
  bug += cur.size();
  cnt++;
  range(i, 0, m) {
    pair<int, int> s = make_pair(edges[i].u, edges[i].v);
    if(to.find(s) != to.end()) used[i] = 1;
    swap(s.first, s.second);
    if(to.find(s) != to.end()) used[i] = 1;
  }

  if(*min_element(used.begin(), used.end()) == 1) {
    cout << "No";
    return 0;
  }

  if(cnt == 2) {
    assert(bug < m);
    cout << "Yes";
    return 0;
  }

  range(i, 0, m) {
    if(!used[i]) {
      int u = edges[i].u;
      cur.clear(); to.clear();
      fill(was.begin(), was.end(), 0);
      fill(pas.begin(), pas.end(), 0);
      dfs(u, -1);
      goto A;
    }
  }
  return 0;
}

