int main() {
  uint64_t n, m;
  std::cin >> n >> m;
  std::vector<std::set<uint64_t>> e(n);

  for (uint64_t i = 0; i < m; i++) {
    uint64_t a, b;
    std::cin >> a >> b;
    e[a - 1].insert(b - 1);
    e[b - 1].insert(a - 1);
  }

  for (const auto &i : e) {
    if (i.size() % 2 != 0) {
      std::cout << "No" << std::endl;
      return 0;
    }
  }

  int count = 0;
  std::vector<uint64_t> v;
  v.reserve(n);

  while (std::any_of(e.cbegin(), e.cend(),
    [](const auto &i) {return !i.empty();})) {
    for (uint64_t i = 0; i < n; i++) {
      if (e[i].empty()) {
        continue;
      }
      const auto j = *e[i].cbegin();
      v.push_back(i);
      v.push_back(j);
      e[i].erase(j);
      e[j].erase(i);
    }

    while (!v.empty()) {
      const auto now = v.back();
      const auto next = *e[now].cbegin();
      e[now].erase(next);
      e[next].erase(now);
      const auto itr = std::find(v.cbegin(), v.cend(), next);
      if (itr != v.cend()) {
        count++;
        if (3 <= count) {
          std::cout << "Yes" << std::endl;
          return 0;
        }
        v.erase(itr, v.cend());
      } else {
        v.push_back(next);
      }
    }
  }

  std::cout << "No" << std::endl;
  return 0;
}

