bool isDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    if(deleted.find({a, b}) == deleted.end())
        return false;
    return true;
}

void addToDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    deleted.emplace(make_pair(a, b));
}

vector <int> s;

int lastPos[MaxN];

void addToS(int x)
{
    if(!lastPos[x])
    {
        s.push_back(x);
        lastPos[x] = s.size();
    }else
    {
        ++C;
        while(s.back() != x)
        {
            lastPos[s.back()] = 0;
            s.pop_back();
        }
    }
}

void solve(int x)
{
    int local = 0;

    while(true)
    {
        while(!v[x].empty() && isDeleted(x, v[x].back()))
            v[x].pop_back();

        if(v[x].empty())
            break;

        int to = v[x].back();

        addToDeleted(x, to);
        v[x].pop_back();

        solve(to);

        addToS(x);
    }
}

