#define MAX_N 200007

int N, M;
int head[MAX_N], to[MAX_N << 1], nxt[MAX_N << 1], cap = 1;
int d[MAX_N];
bool vis[MAX_N];

void addE(int u, int v) {
    nxt[++cap] = head[u];
    head[u] = cap;
    to[cap] = v;
}

bool dfs(int x, int s, int t) {
    vis[x] = true;
    for (int i = head[x]; i; i = nxt[i])
        if (to[i] != t && !vis[to[i]]) {
            if (to[i] == s) return true;
            if (dfs(to[i], s, t)) return true;
        }
    return false;
}

bool check() {
    int u = 0, v;
    Rep(i, N) if (d[i] == 4) !u ? u = i : v = i;
    return dfs(u, u, v);
}

void answ(int x) {
    puts(x ? "Yes" : "No");
    exit(0);
}

