    int u, v;
    Rep(i, M) {
        read(u), read(v);
        addE(u, v), addE(v, u);
        d[u]++, d[v]++;
    }
    Rep(i, N) if (d[i] & 1) answ(0);
    Rep(i, N) if (d[i] > 4) answ(1);
    int cnt = 0;
    Rep(i, N) if (d[i] == 4) cnt++;
    if (cnt > 2 || (cnt == 2 && check())) answ(1);
    answ(0);
    return 0;
}

