const int N = 1e5+5;
vector<int> graph[N];

int a[N],b[N];

int dfn[N],low[N];
int piv = 1,par[N];
void dfs(int x, int p){
    dfn[x] = low[x] = ++piv;
    par[x] = p;
    for(int i=0; i<graph[x].size(); i++){
        int id = graph[x][i];

        int w= a[id]^b[id]^x;
        if(w == p) continue;
        if(!dfn[w]){
            dfs(w, x);
            low[x] = min(low[x], low[w]);
        }
        else{
            low[x] = min(low[x], dfn[w]);
        }
    }
}

bool vis[N];
int cpiv = 1;
vector<int> Edge[N];

int sz[N],height[N];
void color(int x, int c){
    vis[x] = 1;
    if(c>0)
        ++sz[c];

    for(int i=0; i<graph[x].size(); i++){
        int id = graph[x][i];
        int w= a[id]^b[id]^x;
        if(vis[w]){
            if(height[w]<height[x]-1){
                Edge[c].push_back(id);
            }
            continue;
        }
        height[w]= height[x]+1;
        if(dfn[x] <= low[w]){
            ++cpiv;
            ++sz[cpiv];
            Edge[cpiv].push_back(id);
            color(w, cpiv);
        }
        else{
            Edge[c].push_back(id);
            color(w, c);
        }
    }
}

vector<int> adj[N];

int dp[N];
//자자 중대장은 너희에게 실망했다.
int pos;

int num[N];

vector<pair<int,int> > edgeList;

void dfs2(int node,int p) {
   num[node] = pos++;
   for(int i=0;i<adj[node].size();++i) {
      int ch = adj[node][i];
      if(ch==p) {
         continue;
      }
      if(num[ch]==0) {
         dfs2(ch,node);
      } else if(num[ch]<num[node]) {
         edgeList.push_back(make_pair(num[ch],num[node]));
      }
   }
}

int solveDp(int node,int n) {
   if(node>n) {
      return 0;
   }
   int &ret = dp[node];
   if(ret!=-1) {
      return ret;
   }
   ret = 0;
   int pos = lower_bound(edgeList.begin(),edgeList.end(), (make_pair(node,0)) ) - edgeList.begin();
   if(pos== edgeList.size()) {
      return 0;
   }
   if(edgeList[pos].first != node) {
      return solveDp(node+1,n);
   }
   int add = 1;
   ret = max(ret, 1 + solveDp(edgeList[pos].second+1,n));
   for(int x = 1;x<=2 && pos + x*2< edgeList.size() && edgeList[pos+x*2].first == node;++x) {
      int g = edgeList[pos+x*2].second;
      ret = max(ret, 1 + x + solveDp(g+1,n));
   }
   return ret;
}
