   for(int c= 1;c<=cpiv;++c) {
      if(sz[c]<3) {
         continue;
      }
      for(int j = 0;j<=sz[c];++j) {
         dp[j] = -1;
      }
      int root = -1;
      pos = 1;
      for(int j = 0;j<Edge[c].size();++j) {
         int id = Edge[c][j];
         root = a[id];
         num[a[id]] = num[b[id]] = 0;
         adj[a[id]].push_back(b[id]);
         adj[b[id]].push_back(a[id]);
      }
      dfs2(root,0);
      sort(edgeList.begin(),edgeList.end());
      ret += solveDp(1,sz[c]);
      if(ret>=3) {
         printf("Yes\n");
         return;
      }
      for(int j = 0;j<Edge[c].size();++j) {
         int id = Edge[c][j];
         adj[a[id]].clear();
         adj[b[id]].clear();
      }
      edgeList.clear();
   }
   printf("No\n");
}
