void erase(multimap<int, int>& mm, int i, int j)
{
	auto it = mm.find(i);
	while (it->second != j) {
		it++;
	}
	mm.erase(it);
}

bool count_sides(multimap<int, int>& rel)
{
	int count = 0;
	int prev  = 0;
	auto it = rel.begin();
	while (it != rel.end()) {
		if (prev != it->first) {
			if (count & 1) return false;
			prev = it->first;
			count = 0;
		}
		count++;
		it++;
	}
	if (count & 1) return false;

	return true;
}

bool search(multimap<int, int>& rel, int n)
{
	int  count  = 0;
	int  g_num  = 1;
	int  ind_c  = 1;
	bool is_ind = true;

	int p = rel.begin()->first;

	vector<int> nexts(n + 1);
	vector<int> prevs(n + 1);
	vector<int> gnums(n + 1);

	while (!rel.empty()) {
		auto it = rel.find(p);
		if (it == rel.end()) {
			prevs[p] = 0;

			p = rel.begin()->first;
			if (gnums[p] == 0) {
				g_num++;
				ind_c++;
				is_ind = true;
			}

			continue;
		}


		while (it->first == p && it->second == prevs[p]) it++;

		int n_p = it->second;

		nexts[p]   = n_p;

		if (gnums[n_p] != 0 && gnums[n_p] != gnums[p]) {
			is_ind = false;
			ind_c--;
		}

		gnums[p] = g_num;
		gnums[n_p] = g_num;

		if (nexts[n_p] != 0) {
			count++;

			int cur_p  = n_p;
			int cur_np = nexts[n_p];
			while (cur_np != n_p) {
				nexts[cur_p] = 0;
				prevs[cur_np] = 0;

				erase(rel, cur_p, cur_np);
				erase(rel, cur_np, cur_p);

				cur_p  = cur_np;
				cur_np = nexts[cur_p];
			}
			erase(rel, cur_p, cur_np);
			erase(rel, cur_np, cur_p);
			nexts[cur_p] = 0;

			p     = n_p;
		}
		else {
			prevs[n_p] = p;
			p     = n_p;
		}
	}

	if (count >= 3 && ind_c <= 3) return true;

	return false;
}

int main()
{
	int n, m; cin >> n >> m;

	multimap<int, int> rel;
	for (int i = 0; i < m; i++) {
		int a, b; cin >> a; cin >> b;

		rel.insert(make_pair(a, b));
		rel.insert(make_pair(b, a));
	}

	bool ok = count_sides(rel);

	if (ok) {
		ok = search(rel, n);
	}
	if (ok) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

