using namespace std;

struct edge { int64_t to, cap, rev;};

void add_edge(int from, int to, int64_t cap, vector<edge> G[]){
    G[from].push_back((edge){to, cap, G[to].size()});
    G[to].push_back((edge){from, 0, G[from].size()-1});
}

int64_t dfs_flow(int v, int t, int64_t f, vector<bool> &used, vector<edge> G[]){
    if(v==t) return f;
    used[v] = true;
    for(int i=0; i<G[v].size(); i++){
        edge &e = G[v][i];
        if(!used[e.to] && e.cap > 0){
            int64_t d = dfs_flow(e.to, t, min(f, e.cap), used, G);
            if(d>0){
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int64_t max_flow(int N, int s, int t, vector<edge> G[]){
    int64_t flow = 0;
    const int64_t INF = 1e18;
    vector<bool> used(N);
    while(true){
        fill(used.begin(), used.end(), false);
        int64_t f = dfs_flow(s, t, INF, used, G);
        if(f==0) return flow;
        flow += f;
    }
}

void fin(bool ok){
    cout << (ok ? "Yes" : "No") << endl;
    exit(0);
}

vector<int> edges[100000];
vector<edge> edges2[100000];

int main(){
    int N, M;
    cin >> N >> M;
    for(int i=0; i<M; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
        add_edge(a, b, 1, edges2);
        add_edge(b, a, 1, edges2);
    }

    vector<int> d4;
    for(int i=0; i<N; i++){
        int sz = edges[i].size();
        if(sz%2) fin(false);
        if(sz >= 6) fin(true);
        if(sz == 4) d4.push_back(i);
    }
    if(d4.size() >= 3) fin(true);
    if(d4.size() <= 1) fin(false);

    int path = max_flow(N, d4[0], d4[1], edges2);
    fin(path==2);
    return 0;
}

