vector<vector<int>> graph;
int DFS(int s, int t, int v, int previous_v){
    if(v == t) return 1;
    if(v == s) return 0;

    int flag = 0;
    for(int next_v : graph[v]){
        if(next_v == previous_v) continue;
        flag |= DFS(s, t, next_v, v);
    }
    return flag;
}

