namespace ff
{
    int n;
    vector<int> g[maxn];
    int d[maxn], ptr[maxn], it = 0;

    struct edge
    {
        int from, to, cap, flow;
        edge() {}
        edge(int _from, int _to, int _cap, int _flow) {
            from = _from;
            to = _to;
            cap = _cap;
            flow = _flow;
        }
    };

    vector< edge > e;

    void add_edge(int u, int v, int c) {
        e.push_back({u, v, c, 0});
        g[u].push_back(it++);
        e.push_back({v, u, 0, 0});
        g[v].push_back(it++);
    }

    bool bfs(int s, int t) {
        for (int i = 1; i <= n; ++i) {
            d[i] = INF;
        }
        d[s] = 0;
        vector<int> q;
        q.push_back(s);
        for (int it = 0; it < (int)q.size(); ++it) {
            int v = q[it];
            for (int num : g[v]) {
                int to = e[num].to, cap = e[num].cap, flow = e[num].flow;
                if (d[v] + 1 < d[to] && cap - flow) {
                    d[to] = d[v] + 1;
                    q.push_back(to);
                }
            }
        }
        return d[t] != INF;
    }

    int Flow = 0;

    int dfs(int v, int t, int c) {
        if (v == t) {
            Flow += c;
            return c;
        }
        for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
            int num = g[v][ptr[v]];
            int to = e[num].to, cap = e[num].cap, flow = e[num].flow;
            if (d[v] + 1 == d[to] && cap - flow) {
                int x = dfs(to, t, min(c, cap - flow));
                if (x) {
                    e[num].flow += x;
                    e[num ^ 1].flow -= x;
                    return x;
                }
            }
        }
        return 0;
    }

    int get_flow(int s, int t) {
        Flow = 0;
        while (bfs(s, t)) {
            for (int i = 1; i <= n; ++i) {
                ptr[i] = 0;
            }
            while (dfs(s, t, 1)) ;
        }
        return Flow;
    }
}

