      std::cout << "/" << crr << std::endl;
      ckd.at(crr) = true;
      for (auto const& nxt : graph.at(crr)) {
        if (nxt == x || nxt == p) continue;
        if (ckd.at(nxt)) yes();
        dfs(nxt, crr);
      }
      std::cout << "\\" << crr << std::endl;
    });
    for (size_t i = 0; i < n; i++) {
      if (i != x && !ckd.at(i)) dfs(i, i);
    }
  };
  std::for_each(fours.begin(), fours.end(), check);
  std::cout << "No" << std::endl;
  return 0;
}

