bool isDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    if(deleted.find({a, b}) == deleted.end())
        return false;
    return true;
}

void addToDeleted(int a, int b)
{
    if(a > b)
        swap(a, b);
    deleted.emplace(make_pair(a, b));
}

int cnt[MaxN];

vector <int> s;

int lastPos[MaxN];

void addToS(int x)
{
    if(!lastPos[x])
    {
        s.push_back(x);
        lastPos[x] = s.size();
    }else
    {
        ++C;
        while(s.back() != x)
        {
            lastPos[s.back()] = 0;
            s.pop_back();
        }
    }
}

