    auto itr2 = pathes[*itr].lower_bound(from);
    pathes[*itr].erase(itr2);
    bfs(*itr);
}

void solve() {
    //cout.precision(10);
    bool win = false;
    for(int i = 1; i <= N; i++) {
        if(degree[i] % 2 != 0) {
            //cout << "No" << endl;
            num_circuit = -99;
            return;
        }
        if(degree[i] > 2) start = i;
        if(degree[i] >= 6) win = true;
    }
    if(win) {
        //cout << "Yes" << endl;
        num_circuit = 99;
        return;
    }
    if(start == 0) {
        //cout << "No" << endl;
        num_circuit = -99;
        return;
    }
    bfs(start);
    for(int i = 1; i <= N; i++) {
        before[i] = -1;
    }
    vector<l_l> circuit;
    //for(int i = 0; i < tour.size(); i++) cout << tour[i] << endl;
    //cout << endl;
    for(int i = 1; i < tour.size(); i++) {
        int val = tour[i];
        if(before[val] != -1) {
            circuit.push_back({before[val], i});
        }
        before[val] = i;
    }
    num_circuit++;
    if(circuit.size() == 0) {
        //cout << "No" << endl;
        return;
    }
    num_circuit++;
    sort(circuit.begin(), circuit.end());
    for(int i = 0; i < circuit.size(); i++) {
        if(circuit[i].second < circuit[0].first) {
            //cout << "Yes" << endl;
            num_circuit = 99;
            return;
        }
    }
    int r = -1;
    for(int i = 0; i < circuit.size(); i++) {
        if(circuit[i].second < r) {
            //cout << "Yes" << endl;
            num_circuit = 99;
            return;
        }
        r = max((ll)r, circuit[i].second);
    }
    //cout << "No" << endl;
    return;
}

int main() {
    cin >> N >> M;
    cin.tie(0);
    ios::sync_with_stdio(false);
    for(int i = 1; i <= M; i++) {
        int a, b;
        cin >> a >> b;
        pathes[a].insert(b);
        pathes[b].insert(a);
        degree[a]++;
        degree[b]++;
    }
    while(true) {
        for(int i = 1; i <= N; i++) degree[i] = pathes[i].size();
        solve();
        if(num_circuit >= 3) {
            cout << "Yes" << endl;
            return 0;
        }
        if(num_circuit < 0) {
            cout << "No" << endl;
            return 0;
        }
    }
    solve();
}

