vector<int> par;
int root(int x) {
	if (x == par[x]) return x;
	return par[x] = root(par[x]);
}
bool contain_cycle(int n, vector<int> a, vector<int> b) {
	par.resize(n);
	for (int i = 0; i < n; ++i) par[i] = i;
	for (int i = 0; i < a.size(); ++i) {
		if (root(a[i]) == root(b[i])) {
			return true;
		}
		par[root(a[i])] = root(b[i]);
	}
	return false;
}
int main() {
	int N, M;
	cin >> N >> M;
	vector<int> A(M), B(M);
	vector<int> deg(N);
	for (int i = 0; i < M; ++i) {
		cin >> A[i] >> B[i];
		--A[i], --B[i];
		++deg[A[i]];
		++deg[B[i]];
	}
	int state = 1;
	for (int i = 0; i < N; ++i) {
		if (deg[i] % 2 == 1) {
			state = 0;
			break;
		}
	}
	int cnt4 = 0;
	if (state == 1) {
		for (int i = 0; i < N; ++i) {
			if (deg[i] == 4) state = 2, ++cnt4;
			if (deg[i] >= 6) {
				state = 3;
				break;
			}
		}
	}
	if (state <= 1) {
		cout << "No" << endl;
	}
	else if (state == 3) {
		cout << "Yes" << endl;
	}
	else if (cnt4 >= 3) {
		cout << "Yes" << endl;
	}
	else {
		int advantage = 0;
		for (int i = 0; i < N; ++i) {
			if (deg[i] == 4) {
				vector<int> a, b;
				for (int j = 0; j < M; ++j) {
					if ((deg[A[j]] != 4 || A[j] == i) && (deg[B[j]] != 4 || B[j] == i)) {
						a.push_back(A[j]);
						b.push_back(B[j]);
					}
				}
				if (contain_cycle(N, a, b)) {
					++advantage;
				}
			}
		}
		int total = advantage + (cnt4 - advantage) / 2 + 1;
		cout << (total >= 3 ? "Yes" : "No") << endl;
	}
	return 0;
}

