bool dfs(int n, int pre) {
	act[n] = true;
	for (auto nxt : G[n]) {
		if (nxt == pre)continue;
		if (nxt == s)return true;
		if (nxt == t)continue;
		if (act[nxt])continue;
		act[nxt] = true;
		if (dfs(nxt, n))return true;
	}
	act[n] = false;
	return false;
}
void solve() {
	int N, M; cin >> N >> M;
