		deg[u]++;
		deg[v]++;
		G[u].push_back(v);
		G[v].push_back(u);
	}
	int mx = 0;
	REP(i, N) {
		chmax(mx, deg[i]);
		if (deg[i] & 1)die("No");
	}
	if (mx >= 6)die("Yes");
	if (mx <= 2)die("No");
	int cnt = 0;
	REP(i, N) {
		if (deg[i] == 4)cnt++;
	}
	if (cnt >= 3)die("Yes");
	if (cnt <= 1)die("No");
	REP(i, N) {
		if (deg[i] == 2) {
			if (s == -1)s = i;
			else t = i;
		}
	}
	if (dfs(s, s))die("Yes");
	else die("No");
}

