using ll = long long;

void yes() { cout << "Yes" << endl; exit(0); }
void no() { cout << "No" << endl; exit(0); }

int N, M;
vector<int> graph[101010];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> M;
    for (int i = 0; i < M; ++i) {
        int a, b; cin >> a >> b;
        --a; --b;
        graph[a].emplace_back(b);
        graph[b].emplace_back(a);
    }

    int d6 = 0, d4 = 0;
    for (int i = 0; i < N; ++i) {
        int d = graph[i].size();
        if ((d & 1) != 0) no();
        else if (d >= 6) ++d6;
        else if (d >= 4) ++d4;
    }
    if (d6 > 0 || d4 >= 3) yes();
    if (d4 <= 1) no();

    // d6 == 0 && d4 == 2
    assert(d6 == 0 && d4 == 2);

    int u, w;
    {
        vector<int> t;
        for (int i = 0; i < N; ++i)
            if (graph[i].size() == 4) t.push_back(i);
        u = t[0]; w = t[1];
    }

    int num_path = 0;
    for (int v : graph[u]) {
        int c = v, p = u;
        while (c != u && c != w) {
            p = graph[c][0] + graph[c][1] - p;
            swap(p, c);
        }
        if (c == w) ++num_path;
    }

    if (num_path == 2) yes(); else no();

    return 0;
}

