      cout << "No" << endl;
    }
  }
  bool check(int s, int v) {
    int now = s;
    vector<int> res;
    vector<int> target = {s, s, v, v};
    while (1) {
      if (now == s || now == v) {
        res.push_back(now);
      }
      for (auto e : t[now]) {
        if (e.second == 0) {
          e.second = 1;
          t[e.first][now] = 1;
          now = e.first;
          break;
        }
      }
    }
    for (int i = 0; i < 4; ++i) {
      rotate(res.begin(), res.begin() + 1, res.end());
      if (res == target) return true;
    }
    return false;
  }
