void add_edge(int u,int v)
{
    e[++sum]={u,v,0,h[u]};h[u]=sum;
    e[++sum]={v,u,0,h[v]};h[v]=sum;
}

void dfs(int u)
{
    vis[u]=1;
    for(int t=h[u];~t;t=e[t].next)
    {
        if(e[t].del) continue;
        int v=e[t].v;
        if(vis[v]) continue;
        pre[v]=t;dfs(v);
    }
}

int main()
{
