void solve() {
// NMM(-A-B)
/* <foxy.memo-area> */
int N;int M;cin>>N;cin>>M;VI A(M);VI B(M);times(M,Ri_0){cin>>A[Ri_0];--A[Ri_0];
cin>>B[Ri_0];--B[Ri_0];}
/* </foxy.memo-area> */

  WI edges(N); times(M, i) { edges[A[i]].push_back(B[i]); edges[B[i]].push_back(A[i]); }

  VI w4;

  times(N, i) {
    if(edges[i].size() % 2 == 1) {
      cout << dict::No ln;
      return;
    }
    if(edges[i].size() >= 6) {
      cout << dict::Yes ln;
      return;
    }

    if(edges[i].size() == 4) w4.push_back(i);
  }

  if(w4.size() >= 3) {
    cout << dict::Yes ln;
    return;
  }
  if(w4.size() <= 1) {
    cout << dict::No ln;
    return;
  }

  // w4.size() == 2

  times(4, k) {
    int s = w4[0], t = edges[w4[0]][k];
    while(t != w4[0] && t != w4[1]) {
      // edges[t].size() == 2
      int u = edges[t][0] == s ? edges[t][1] : edges[t][0]; // u != s
      s = t; t = u;
    }
    if(t == w4[0]) {
      // found independent circuit
      cout << dict::Yes ln;
      return;
    }
  }

  cout << dict::No ln;
}

