void solve(){
	int n, m;
	scanf("%d%d", &n, &m);
	REP(i, 0, m) {
		int a, b;
		scanf("%d%d", &a, &b);
		g[a].insert(mp(b, 2 * i));
		g[b].insert(mp(a, 2 * i + 1));
	}
	int cnt4 = 0;
	REPN(i, 1, n) {
		if (SZ(g[i]) % 2 == 1) {
			printf("No\n");
			return;
		}
		if (SZ(g[i]) >= 4) {
			cnt4++;
		}
	}
	if (m <= n + 1) {
		printf("No\n");
		return;
	}
	/*if (m == n + 2 && cnt4 == 2) {
		printf("No\n");
		return;
	}*/
	REPN(i, 1, n) {
		if (SZ(g[i]) == 2) {
			st.insert(i);
		}
	}
	while(!st.empty()) {
		int a = *st.begin();
		st.erase(a);
		pii pp0 = *g[a].begin();
		g[a].erase(pp0);
		pii pp1 = *g[a].begin();
		g[a].erase(pp1);
		g[pp0._1].erase(mp(a, pp0._2 ^ 1));
		g[pp0._1].insert(mp(pp1._1, pp0._2 ^ 1));
		g[pp1._1].erase(mp(a, pp1._2 ^ 1));
		g[pp1._1].insert(mp(pp0._1, pp0._2));
	}
	REPN(i, 1, n) {
		if (SZ(g[i]) > 0) {
			vv.pb(i);
		}
	}
	if (SZ(vv) == 1 && SZ(g[vv[0]]) < 6) {
		printf("No\n");
		return;
	}
	if (SZ(vv) == 2 && SZ(g[vv[0]]) == 4 && SZ(g[vv[1]]) == 4) {
		int fl = 0;
		REP(i, 0, 2) {
			FA(it, g[vv[i]]) {
				if (it->_1 == vv[i]) {
					fl = 1;
				}
			}
		}
		if (!fl) {
			printf("No\n");
			return;
		}
	}
	printf("Yes\n");
}   

