//!=====================================!//
//!   88888888b dP                      !//
//!   88        88                      !//
//!  a88aaaa    88 .d8888b. dP  dP  dP  !//
//!   88        88 88'  '88 88  88  88  !//
//!   88        88 88.  .88 88.88b.88'  !//
//!   dP        dP '88888P' 8888P Y8P   !//
//!=====================================!//
template <typename T>
struct Flow
{
    Flow(const std::size_t v) : V(v), edge(v) {}
    void addEdge(const std::size_t from, const std::size_t to, const T cap) { edge[from].push_back({to, edge[to].size(), cap, false}), edge[to].push_back({from, edge[from].size() - 1, 0, true}); }
    struct Edge
    {
        std::size_t to, rev;
        T cap;
        const bool isrev;
    };
    const std::vector<Edge>& operator[](const std::size_t i) const { return edge[i]; }
    friend std::ostream& operator<<(std::ostream& os, const Flow& f)
    {
        os << "[\n";
        for (std::size_t i = 0; i < f.V; i++) {
            for (const auto& e : f.edge[i]) {
                if (not e.isrev) { os << i << "->" << e.to << ":"
                                      << e.cap << "\n"; }
            }
        }
        return (os << "]\n");
    }
    const std::size_t V;
    std::vector<std::vector<Edge>> edge;
};
//!============================================================================================================!//
//! 88888888b                      dP 88888888b       dP dP                                                    !//
//! 88                             88 88              88 88                                                    !//
//! 88aaaa .d8888b. 88d888b. .d888b88 88aaaa dP    dP 88 88  .dP  .d8888b. 88d888b. .d8888b. .d8888b. 88d888b. !//
//! 88     88'  '88 88'  '88 88'  '88 88     88    88 88 88888"   88ooood8 88'  '88 Y8ooooo. 88'  '88 88'  '88 !//
//! 88     88.  .88 88       88.  .88 88     88.  .88 88 88  '8b. 88.  ... 88             88 88.  .88 88    88 !//
//! dP     '88888P' dP       '88888P8 dP     '88888P' dP dP   'YP '88888P' dP       '88888P' '88888P' dP    dP !//
//!============================================================================================================!//
template <typename T>
T FordFulkerson(Flow<T>& flow, const std::size_t s, const std::size_t t)
{
    std::vector<bool> checked(flow.V);
    auto dfs = [&](auto&& self, const std::size_t pos, const T f) -> T {
        if (pos == t) { return f; }
        checked[pos] = true;
        for (auto& e : flow.edge[pos]) {
            if (e.cap == 0 or checked[e.to]) { continue; }
            const T d = self(self, e.to, std::min(f, e.cap));
            if (d <= 0) { continue; }
            e.cap -= d, flow.edge[e.to][e.rev].cap += d;
            return d;
        }
        return 0;
    };
    T f = 0;
    while (true) {
        std::fill(checked.begin(), checked.end(), false);
        const T df = dfs(dfs, s, std::numeric_limits<T>::max());
        if (df == 0) { break; }
        f += df;
    }
    return f;
}
