    for (int i = 0, a, b; i < M; i++) { std::cin >> a >> b, a--, b--, dim[a]++, dim[b]++, F.addEdge(a, b, 1), F.addEdge(b, a, 1); }
    bool s = false;
    std::vector<int> f;
    for (int i = 0; i < N; i++) {
        if (dim[i] % 2 == 1) {
            return std::cout << "No" << std::endl, 0;
        } else if (dim[i] >= 6) {
            s = true;
        } else if (dim[i] == 4) {
            f.push_back(i);
        }
    }
    if (s or f.size() > 2) { return std::cout << "Yes" << std::endl, 0; }
    if (f.size() <= 1) { return std::cout << "No" << std::endl, 0; }
    const int S = f.front(), T = f.back();
    std::cout << (FordFulkerson(F, S, T) == 2 ? "Yes" : "No") << std::endl;
