signed main() {
	INIT;

	VAR(int, n, m);
	VEC_ROW(int, m, a, b);

	std::vector<std::set<int>> g(n);
	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].insert(b[i]);
		g[b[i]].insert(a[i]);
	}

	REP(i, n) {
		if (g[i].size() % 2 == 1) NO();
	}

	int cnt = 0;
	while (cnt < 3) {
		std::stack<int> st;
		std::set<int> set;
		REP(i, n) if (g[i].size()) {
			st.push(i);
			set.insert(i);
			break;
		}
		if (st.empty()) break;
		int now = st.top();
		int pre = -1;
		while (true) {
			int to = *g[now].begin();
			if (to == pre) to = *g[now].rbegin();
			if (to == pre) NO();
			if (set.count(to)) {
				int t = to;
				while (now != t) {
					g[now].erase(to);
					g[to].erase(now);
					to = now;
					now = st.top(); st.pop();
				}
				g[now].erase(to);
				g[to].erase(now);
				++cnt;
				break;
			}
			else {
				st.push(to);
				set.insert(to);
				pre = now;
				now = to;
			}
		}
	}
	if (cnt >= 3) YES();
	assert(false);
	NO();

	return 0;
}

#include <bits/stdc++.h>

const int N = 100054, M = N * 2;

int V, E, Es = 0, R;
int to[M], first[N], next[M], deg[N];
bool used[N];

inline void addedge(int u, int v) {
	to[++Es] = v, next[Es] = first[u], first[u] = Es, ++deg[u];
	to[++Es] = u, next[Es] = first[v], first[v] = Es, ++deg[v];
}

inline bool dfs(int x, int px = 0) {
	int i, y; used[x] = true;
	for (i = first[x]; i; i = next[i]) if ((y = to[i]) != px) {
		if (!used[y] && dfs(y, x)) return true;
		if (y == R) return true;
	}
	return false;
}

int main() {
	int i, u, v, D, cnt;
	scanf("%d%d", &V, &E);
	for (i = 0; i < E; ++i) scanf("%d%d", &u, &v), addedge(u, v);
	for (i = 1; i <= V; ++i) if (deg[i] & 1) return puts("No"), 0;
	D = *std::max_element(deg + 1, deg + (V + 1));
	cnt = std::count(deg + 1, deg + (V + 1), D);
	if (D > 4 || (D == 4 && cnt > 2)) return puts("Yes"), 0;
	if (D < 4 || (D == 4 && cnt < 2)) return puts("No"), 0;
	u = std::find(deg + 1, deg + (V + 1), D) - deg;
	v = std::find(deg + (u + 1), deg + (V + 1), D) - deg;
	used[v] = true, R = u;
	puts(dfs(u) ? "Yes" : "No");
	return 0;
}

