ll start,X;
bool dfs(vector<vector<ll>> &g, ll v, ll p, vector<bool> &seen) {
	debug(v);
	seen[v] = true;
	for(ll nextv : g[v]){
		if(nextv==p)continue;
		if(nextv==start)return true;
		if(nextv==X)return false;
		if(seen[nextv]) continue;
		bool b=dfs(g, nextv, v, seen);
		return b;
	}
	return false;
}

