		ll a,b;
		cin>>a>>b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}
	ll t=0;
	ll t4=0;
	rep(i,N){
		if(g[i].size()%2==1){
			exit(1);
			p("No");return;
		}
		ll x=g[i].size();
		if(x>=6)t++;
		else if(x==4)t4++;

	}
	if(t>0){
		p("Yes");return;
	}
	if(t4>2){
		p("Yes");return;
	}
	if(t4<2){
		exit(1);
		p("No");return;
	}
	//何か他に条件がある
	if([&]{
		vector<ll> v;
		rep(i,N){
			if(g[i].size()==4)v.push_back(i);
		}
		start=v[0];
		X=v[1];
		vector<bool> seen(N,false);
		return dfs(g,v[0],-1,seen);
	}()){
		p("Yes");return;
	}

	exit(1);
	p("No");

}

