            for (int i = 0; i < 2; i++) {
                g[all[0]].erase(g[all[0]].find(v));
                g[v].erase(g[v].find(all[0]));
                deg[all[0]]--;
                deg[v]--;
            }
            g[v].clear();
            if (deg[all[0]] == 2) {
                q.push(v);
            }
        }
        else {
            for (int i = 0; i < 2; i++) {
                g[all[i]].erase(g[all[i]].find(v));
                deg[v]--;
                g[all[i]].insert(all[i ^ 1]);
            }
        }
        g[v].clear();
    }
    if (need <= 0) {
        cout << "Yes";
        return 0;
    }
    int cnt = 0;
    int ed = 0;
    for (int i = 1; i <= n; i++) {
        if (deg[i] != 0) {
            cnt++;
            ed += deg[i];
        }
    }
    if (ed / 4 >= need) {
        cout << "Yes";
        return 0;
    }
    bad();
    return 0;
}

