int rec(vector<targe_nodes> &target_nodes_info, int v, int w, int cur, int p)
{
    if (cur == w)
    {
        return 1;
    }
    else if (cur == v)
    {
        return 0;
    }
    int cnt = 0;
    int next = target_nodes_info[cur][0] + target_nodes_info[cur][1] - p;
    cnt = rec(target_nodes_info, v, w, next, cur);
    return cnt;
}

