namespace G {
	int head[N], nxt[N*2], to[N*2], w[N*2], eid;
	void init() {
		eid = 0;
		memset(head, -1, sizeof head);
	}
	void link( int u, int v ) {
		to[eid] = v, nxt[eid] = head[u], head[u] = eid++;
		to[eid] = u, nxt[eid] = head[v], head[v] = eid++;
	}
}

vector<int> con;
bool vis[N];

void bfs( int s ) {
	int cnt = 0, maxd = 0;
	queue<int> q;
	q.push(s), vis[s] = 1;
	while( !q.empty() ) {
		int u = q.front(); q.pop();
		++cnt, maxd = max(maxd, deg[u]);
		using namespace G;
		for( int i = head[u]; ~i; i = nxt[i] ) {
			int v = to[i];
			if( !vis[v] ) {
				vis[v] = 1;
				q.push(v);
			}
		}
	}
	if( cnt > 1 ) {
		con.push_back(maxd/2);
	}
}

vector<int> eq;
int cur[N];

void euler( int u ) {
	using namespace G;
	for( int &i = cur[u]; ~i; ) {
		int nowi = i;
		i = nxt[i];
		int v = to[nowi];
		if( w[nowi] ) continue;
		w[nowi] = w[nowi^1] = 1;
		euler(v);
	}
	eq.push_back(u);
}

