template<typename T> int bins(const vector<T> &v, T key) {int imin=0,imax=v.size();while(imin<imax) {int imid=(imin+imax)>>1;if (v[imid]<key) imin=imid+1;else imax=imid;}return imin;}
class SplitGraph {
	vector<bool> seen;
	vi liveV; vpii liveE;
	void dfs(const vvi &g, int x) {
		if (seen[x]) return;
		seen[x]=true;
		liveV.PB(x);
		for (auto &y:g[x]) {
			liveE.PB(MP(x,y));
			dfs(g,y);
		}
	}
public:
	vvvi splitGraph(const vvi &g) {
		int n=g.size(); seen.resize(n);
		vvvi vg;
		for (int x=0;x<n;x++) {
			if (!seen[x]) {
				dfs(g, x);
				sort(liveV.begin(),liveV.end());
				vvi newg(liveV.size());
				for (auto &e:liveE) {
					int from=bins(liveV, e.fst),to=bins(liveV, e.snd);
					newg[from].PB(to);
				}
				liveV.clear(); liveE.clear();
				vg.PB(newg);
			}
		}
		return vg;
	}
};
SplitGraph SG;
bool solve(long long n, long long m, vector<long long> a, vector<long long> b){
	vvi g(n);
	for (int i=0;i<m;i++) {
		int x=a[i]-1,y=b[i]-1;
		g[x].PB(y); g[y].PB(x);
	}
	vvvi sg=SG.splitGraph(g);
	if (sg.size()>3) return false;
	int circuits=0;
	for (auto &g:sg) {
		if (g.size()<=1) return false;
		int above=0;
		for (auto &e:g) {
			if (e.size()%2!=0) return false;
			if (e.size()>=4) above+=e.size()/2;
		}
		circuits+=1+above;
	}
	return circuits>=3;
}

