bool calc(unordered_map<int,unordered_map<int,bool> > &graph) {
	vector<int> below(n+1);
	vector<int> upper(n+1);
	for(int s = 1; s <= n; s++) {
		if(graph[s].size()>0) {
			//cout << "S=" << s << endl;
			queue<int> q;
			q.push(s);
			below[s] = -1;
			while(!q.empty()) {
				int q_size = q.size();
				//cout << "Q_SIZE=" << q_size << endl;
				for(int loop = 0; loop < q_size; loop++) {
					int now = q.front();q.pop();
					for(pair<int,bool> p : graph[now]) {
						int next = p.first;
						//cout << "(now,next)=" << now << "," << next << endl;
						//cout << next << "," << s << "," << below[now] << "," << below[now] << endl;
						if(((below[next]!=0))&&(below[now]!=next)) {
							int back_start = next;
							int back_end = now;
							int c = 0;
							while(back_end!=-1) {
								//return false;
								/*
								cout << "(" << back_start << "->" << back_end << ")" << endl;
								c++;
								if(c>5) return false;
								*/
								graph[back_start].erase(back_end);
								graph[back_end].erase(back_start);
								int temp = below[back_end];
								back_start = back_end;
								back_end = temp;
							}
							back_start = next;
							back_end = below[next];
							while(back_end!=-1) {
								//return false;
								/*
								cout << "(" << back_start << "->" << back_end << ")" << endl;
								c++;
								if(c>5) return false;
								*/
								graph[back_start].erase(back_end);
								graph[back_end].erase(back_start);
								int temp = below[back_end];
								back_start = back_end;
								back_end = temp;
							}
							return true;
						}
						else {
							if(below[next]==0) {
								below[next] = now;
								upper[now] = next;
								q.push(next);
							}
						}
					}
				}
			}
			break;
		}
	}
	return false;
}

