bool dfs(const vector<vector<int64_t>>& links, int64_t target, int64_t ng, int64_t current, int64_t parent) {
  for (auto v : links[current]) {    
    if (v == parent) {
      continue;
    }

    if (v == target) {
      return true;
    }

    if (v == ng) {
      return false;
    }

    auto tmp = dfs(links, target, ng, v, current);
    if (tmp) {
      return true;
    }
  }

  return false;
}

main() {
  int64_t n, m;
  cin >> n >> m;

  vector<vector<int64_t>> links(n);
  for (auto i : irange(0L, m)) {
    int64_t a, b;
    cin >> a >> b;
    --a;
    --b;
    links[a].emplace_back(b);
    links[b].emplace_back(a);
  }

  int64_t x = -1, y = -1;
  for (auto i : irange(0L, n)) {
    int64_t k = links[i].size();
    if (k % 2 == 1) {
      cout << "No" << endl;
      return 0;
    }

    if (k >= 6) {
      cout << "Yes" << endl;
      return 0;
    }

    if (k == 4) {
      if (x == -1) {
        x = i;
      } else if (y == -1) {
        y = i;
      } else {
        cout << "Yes" << endl;
        return 0;
      }
    }
  }

  if (y == -1) {
    cout << "No" << endl;
    return 0;
  }

  auto ret = dfs(links, x, y, x, -1);
  if (ret) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
}

