    tour.push_back(from);
    auto itr = pathes[from].begin();
    pathes[from].erase(*itr);
    auto itr2 = pathes[*itr].lower_bound(from);
    pathes[*itr].erase(itr2);
    bfs(*itr);
}

void solve() {
    //cout.precision(10);
    bool win = false;
    for(int i = 1; i <= N; i++) {
        if(degree[i] % 2 != 0) {
            //cout << "No" << endl;
            num_circuit = -99;
            return;
        }
        if(degree[i] > 2) start = i;
        if(degree[i] >= 6) win = true;
    }
    if(win) {
        //cout << "Yes" << endl;
        num_circuit = 99;
        return;
    }
    /*
