int main(){
    int n,m;
    scanf("%d%d",&n,&m);
    vector<int> adj[n];
    int a,b;
    for(int i=0;i<m;i++){
        scanf("%d%d",&a,&b); a--;b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    for(int i=0;i<n;i++){
        if((int)adj[i].size()%2==1){
            printf("No");
            return 0;
        }
    }
    vector<int> adj2[n];
    for(int i=0;i<n;i++){
        if((int)adj[i].size()>2){
            for(int j=0;j<(int)adj[i].size();j++){
                int x=adj[i][j],prev=i;
                while(adj[x].size()==2){
                    if(adj[x][0]==prev){
                        prev=x;
                        x=adj[x][1];
                    }else{
                        prev=x;
                        x=adj[x][0];
                    }
                }
                adj2[i].push_back(x);
                adj2[x].push_back(i);
            }
        }
    }
    int ans=0;
    for(int i=0;i<n;i++){
        for(int j=0;j<(int)adj2[i].size();j++){
            if(adj2[i][j]==i){
                ans+=2;
            }else{
                ans++;
            }
        }
    }
    if(ans%2==0&&ans>=6){
        printf("Yes");
    }else{
        printf("No");
    }
}

