struct union_find{
  vector<int> par,r;

  union_find(int n) : par(n),r(n){init(n);}

  void init(int n){
    for(int i = 0; i < n; i++) par[i] = i;
    for(int i = 0; i < n; i++) r[i] = 0;
  }

  int find(int x){
    if(par[x] == x) return x;
    else return find(par[x]);
  }

  void unite(int x,int y){
    x = find(x);
    y = find(y);
    if(x == y) return;
    if(r[x] < r[y]){
      par[x] = y;
    }else{
      par[y] = x;
      if(r[x] == r[y]) r[x]++;
    }
  }

  bool same(int x,int y){
    return find(x) == find(y);
  }
};

int main()
{
	int n,m;
	cin>>n>>m;
	vector<vector<int> > g(n,vector<int>());
	for(int i = 0; i < m; i++){
		int a,b;
		cin>>a>>b;
		a--;
		b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	int four=0,six=0;
	for(int i = 0; i < n; i++){
		if(g[i].size()%2!=0){
			// cout << i << endl;
			cout << "No"<<endl;
			return 0;
		}
		if(g[i].size()==4){
			four++;
		}
		if(g[i].size()>=6){
			six++;
		}
	}

	if(four>=3 || six>=1){
		cout << "Yes"<<endl;
	}else if(four<=1){
		cout << "No"<<endl;
	}else{
		int x=-1,y=-1;
		for(int i = 0; i < n; i++){
			if(g[i].size()==4){
				if(x<0)x=i;
				else y=i;
			}
		}
		bool flag=false;
		for(int i = 0; i < 4; i++){
			for(int j = i+1; j < 4; j++){
				union_find uf(n);
				for(int k = 0; k < n; k++){
					for(int l = 0; l < g[k].size(); l++){
						if(k!=x) uf.unite(k,g[k][l]);
						else if(l!=i&&l!=j) uf.unite(k,g[k][l]);
					}
				}
				if(!uf.same(x,y)) flag = true;
			}
		}
		cout<<(flag?"Yes":"No")<<endl;
	}

	return 0;
}

