const int N = 123456;

int n, m, degree[N];
vector<int> adj[N];
bool visit[N];

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout.tie(0);
  cin >> n >> m;
  for (int i = 1, x, y; i <= m; ++i) {
    cin >> x >> y;
    adj[x].push_back(y);
    adj[y].push_back(x);
    ++degree[x];
    ++degree[y];
  }
  for (int i = 1; i <= n; ++i) {
    if (degree[i] & 1) {
      cout << "No" << '\n';
      exit(0);
    }
  }
  for (int i = 1; i <= n; ++i) {
    if (degree[i] >= 6) {
      cout << "Yes" << '\n';
      exit(0);
    }
  }
  int total = 0;
  for (int i = 1; i <= n; ++i) {
    if (degree[i] >= 4) {
      ++total;
    }
  }
  if (total >= 3) {
    cout << "Yes" << '\n';
    exit(0);
  } else if (total == 2) {
    int foo = -1, bar = -1;
    for (int i = 1; i <= n; ++i) {
      if (degree[i] >= 4) {
        if (!~foo) {
          foo = i;
        } else {
          bar = i;
        }
      }
    }
    bool ok = false;
    function<void (int, int)> dfs = [&] (int x, int f) {
      if (f && x == foo) {
        ok = true;
      }
      if (x == foo || x == bar) {
        return;
      }
      if (visit[x]) {
        return;
      }
      visit[x] = true;
      for (auto y : adj[x]) {
        if (y != f || (y == f && (y == foo || y == bar))) {
          dfs(y, x);
        }
      }
    };
    dfs(foo, 0);
    if (ok) {
      cout << "Yes" << '\n';
      exit(0);
    }
  }
  cout << "No" << '\n';
  return 0;
}

