const int N=2e5;
int n,m;
int deg[N];
int id[N];
int head[N],nxt[N],to[N],tot;
void add(int u,int v){
	nxt[tot]=head[u];head[u]=tot;
	to[tot]=v;++tot;
}
int prv[N];
int que[N],lb,rb;
vector<int>no;
void bfs(int s){
	lb=rb=0;
	que[rb++]=s;
	memset(prv,~0,sizeof prv);
	prv[s]=0;
	for(;lb<rb;){
		int u=que[lb++];
		for(int e=head[u];~e;e=nxt[e]){
			bool ok=1;
			for(int i=0;i<no.size();++i)
				if(no[i]==e||(no[i]^1)==e)ok=0;
			if(!ok)continue;
			int v=to[e];
			if(!~prv[v]){
				prv[v]=e;
				que[rb++]=v;
			}
		}
	}
}
int main(){
	memset(head,~0,sizeof head);
	n=read(),m=read();
	for(int i=0;i<m;++i){
		int u=read()-1,v=read()-1;
		deg[u]++;deg[v]++;
		add(u,v);add(v,u);
	}
	for(int i=0;i<n;++i)id[i]=i;
	sort(id,id+n,[&](int a,int b){
		return deg[a]>deg[b];
	});
	for(int i=0;i<n;++i)if(deg[i]&1){
		puts("No");return 0;
	}
	if(deg[id[0]]>=6)puts("Yes");
	else if(deg[id[0]]>=4&&deg[id[1]]>=4&&deg[id[2]]>=4)puts("Yes");
	else if(deg[id[0]]>=4&&deg[id[1]]>=4){
		bfs(id[0]);no.PB(prv[id[1]]);
		bfs(id[0]);if(~prv[id[1]])no.PB(prv[id[1]]);else{puts("No");return 0;}
		bfs(id[0]);if(~prv[id[1]])puts("No");else puts("Yes");
	}
	else puts("No");
	return 0;
}

