int n,m,f=0,x,y,d[100005],fail[100005];
vector<int>v;
pair<int,int>e[100005];
int get(int x)
{
    return fail[x]==x?x:fail[x]=get(fail[x]);
}
int main()
{
    scanf("%d%d",&n,&m);
    for(int i=1;i<=m;i++)
    {
        scanf("%d%d",&x,&y);
        d[x]++;
        d[y]++;
        e[i]=make_pair(x,y);
    }
    bool flag=false;
    for(int i=1;i<=n;i++)
        if(d[i]%2)
        {flag=false;break;}
        else if(d[i]>=6) flag=true;
        else if(d[i]>=4)
        {
            f++;
            v.push_back(i);
            if(f>=3) flag=true;
        }
    if(f==2&&!flag)
    {
        for(int i=1;i<=n;i++)
            fail[i]=i;
        for(int i=1;i<=m;i++)
        {
            int x=e[i].first,y=e[i].second;
            if(x==v[0]||y==v[0]) continue;
            fail[get(x)]=fail[get(y)];
        }
        for(int i=1;i<=n;i++)
            f+=fail[i]==i;
        if(f>=4) flag=true;
    }
    printf(flag?"Yes":"No");
}

