void read_input() {
	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
}

bool dfs(int v, int cur_h = 0) {
	mark[v] = true;
	h[v] = cur_h;
	int w = -1;
	for (int u: adj[v])
		if (!del[{u, v}]) {
			if (!mark[u]) {
				par[u] = v;
				if (dfs(u, cur_h + 1))
					return true;
			}
			else if (u != par[v] && (w == -1 || h[u] > h[w]))
				w = u;
		}
	if (~w) {
		int x = v;
		par[w] = v;
		do {
			del[{x, par[x]}] = true;
			del[{par[x], x}] = true;
			x = par[x];
		} while (x != v);
		return true;

	}
	return false;
}

void solve() {
	for (int i = 0; i < n; i++)
		if ((int) adj[i].size() % 2) {
			cout << "No";
			exit(0);
		}
	for (int i = 0; i < 2; i++) {
		for (int v = 0; v < n; v++) {
			par[v] = -1;	
			if (!mark[v] && dfs(v))
				break;
		}
		memset(mark, false, sizeof mark);
	}
	for (int v = 0; v < n; v++)
		if (!mark[v]) {
			par[v] = -1;
			if (dfs(v)) {
				cout << "Yes";
				exit(0);
			}
		}
	cout << "No";
}

