void rmEdge(vector<vector<int>>& adj, int a, int b) {
  auto ia = find_if(adj[a].begin(), adj[a].end(), [b](int x) {return x == b;});
  adj[a].erase(ia);
  auto ib = find_if(adj[b].begin(), adj[b].end(), [a](int x) {return x == a;});
  adj[b].erase(ib);
}

