    });
    if (it == adj.end()) {
      cout << "No\n";
      return 0;
    }

    auto src = it - adj.begin();
    auto tgt = adj[src].back();
    rmEdge(adj, src, tgt);
    list<int> l;
    l.push_back(src);
    vector<bool> viz(n);
    vector<int> prec(n, -1);
    while (!l.empty()) {
      auto x = l.front();
      viz[x] = true;
      if (x == tgt) break;
      for (int a : adj[x]) {
        if (viz[a]) continue;
        prec[a] = x;
        l.push_back(a);
      }
      l.pop_front();
    }

    int cur = tgt;
    for (;;) {
      rmEdge(adj, cur, prec[cur]);
      if (prec[cur] == src) break;
      cur = prec[cur];
    }
  }

  if (any_of(adj.begin(), adj.end(), [](auto& v) {
    return v.size()%2 != 0;
