int count[1000010];
std::vector<int> V[100010];
std::vector<int> St;
int check[100010];
void func(int k, int prev)
{
	St.push_back(k);
	if(check[k]==1)
	{
		int i;
		for(i=0;i<St.size();i++) if(St[i]==k) break;
		for(;i<St.size()-1;i++)
		{
			int s = St[i], t = St[i+1];
			std::vector<int> ::iterator it;

			for(it = V[s].begin();it!=V[s].end();it++)
			{
				if((*it)==t)
				{
					V[s].erase(it);
					count[s]--;
					break;
				}
			}
			for(it = V[t].begin();it!=V[t].end();it++)
			{
				if((*it)==s)
				{
					V[t].erase(it);
					count[t]--;
					break;
				}
			}
		}
		return;
	}

	check[k] = 1;
	if(prev==V[k][0]) func(V[k][1],k);
	else func(V[k][0],k);
}

