using namespace std;
const int MaxN = (int)2e5;

int N, M;
set<int> G[MaxN];

list<int> tour;

void del_edge(int a,int b)
{
    G[a].erase(b);
    G[b].erase(a);
}

void get_tour(int start, list<int>::iterator it)
{
    int cur = start;
    list<int>::iterator init_it = it;
    while(true)
    {
        int nxt = *G[cur].begin();
        del_edge(cur, nxt);
        cur = nxt;
        auto x = tour.insert(it, cur);
        if(init_it == it)
            init_it = x;
        if(cur == start)
            break;
    }
    list<int>::iterator cur_it = init_it;
    while(cur_it != it)
    {
        if(G[*cur_it].empty())
        {
            cur_it++;
            continue;
        }
        list<int>::iterator next = cur_it;
        next++;
        get_tour(*cur_it, next);
        cur_it = next;
    }
}

int main()
{
    cin >> N >> M;
    for(int i = 0; i < M; i++)
    {
        int a, b;
