        if(G[i].size() == 4)
        {
            if(u == -1)
                u = i;
            else 
                v = i;
        }

    tour.push_back(0);
    get_tour(0, tour.end());
    int fu, su, fv, sv;

    list<int>::iterator it;

    for(fu = 0, it = tour.begin(); it != tour.end() && *it != u; it++, fu++);
