}edge[maxn * 2];
int point[maxn] = {0}, te = 1;
void add(int a, int b)
{
	te ++;
	edge[te].to = b;
	edge[te].next = point[a];
	point[a] = te;
}
bool flag[maxn * 2] = {0};
int du[maxn] = {0};
void dfs(int now, int st, int p)
{
	if(p && now == st)
		return ;
	du[now] --;
	//cout << now << " " << st << " " << p << endl;
	for(int e = point[now]; e; e = edge[e].next)
		if(!flag[e])
		{
			//cout << edge[e].to << endl;
			du[edge[e].to] --;
			flag[e] = flag[e ^ 1] = 1;
			dfs(edge[e].to, st, now);
			return ;
		}
}
int n, m;
int par[maxn];
int getr(int x)
{
	if(x == par[x])
		return x;
	return par[x] = getr(par[x]);
}
void link(int a, int b)
{
	int ra = getr(a), rb = getr(b);
	if(ra != rb)
		par[ra] = rb;
}
