int64_t dfs(const vector<vector<int64_t>>& links, int64_t target, int64_t ng, int64_t current, int64_t parent) {
  int64_t ret = 0;
  for (auto v : links[current]) {    
    if (v == parent) {
      continue;
    }

    if (v == target) {
      return 0;
    }

    if (v == ng) {
      return 1;
    }

    ret += dfs(links, target, ng, v, current);
  }

  return ret;
}

