set<int> E[100005];
int main() {
	int n, m;
	scanf("%d%d", &n, &m);
	vector<int> deg(n + 1);
	for (int i = 0; i < m; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		E[a].insert(b);
		E[b].insert(a);
		++deg[a];
		++deg[b];
	}
	for (int i = 1; i <= n; ++i) {
		if (deg[i] & 1) no();
	}
	int num4 = 0;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] >= 6) yes();
		else if (deg[i] == 4) ++num4;
	}
	if (num4 >= 3) yes();
	if (num4 == 2) {
		queue<int> Q;
		for (int i = 1; i <= n; ++i)
			if (deg[i] == 2) Q.push(i);
		bool loop = false;
		while (!Q.empty()) {
			int x = Q.front();
			Q.pop();
			int y = *E[x].begin();
			E[x].erase(y);
			int z = *E[x].begin();
			if (y == z) loop = true;
			E[y].erase(x);
			E[z].erase(x);
			E[y].insert(z);
			E[z].insert(x);
		}
		if (loop) yes();
	}
	no();
}

