int N, M;
vector<vector<int> > G;

int s, t;

vector<bool> seen;
bool rec(int v, int p = -1) {
    if (v == s && p != -1) return true;
    if (v != s) seen[v] = true;
    for (auto nv :  G[v]) {
        if (nv == p || nv == t || seen[nv]) continue;
        if (rec(nv, v)) return true;
    }
    return false;
}


bool solve() {
    cin >> N >> M;
    G.assign(N, vector<int>());
    for (int i = 0; i < M; ++i) {
        int a, b; cin >> a >> b; --a, --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    map<int,int> degs;
    for (int v = 0; v < N; ++v) degs[(int)G[v].size()]++;

    for (auto it : degs) if (it.first % 2 != 0) return false;
    if (degs[6] > 0) return true;
    if (degs[4] > 2) return true;
    if (degs[4] <= 1) return false;

    vector<int> four;
    for (int v = 0; v < N; ++v) {
        if (G[v].size() == 4) four.push_back(v);
    }
    s = four[0], t = four[1];
    seen.assign(N, 0);
    bool ok1 = rec(s);
    s = four[1], t = four[0];
    seen.assign(N, 0);
    bool ok2 = rec(s);

    if (ok1 && ok2) return true;
    else return false;
}

