        edges[a-1].push_back(b-1);
        edges[b-1].push_back(a-1);
    }

    BCC bcc;
    bcc.calculate(N, edges);

    int SZ = bcc.sz();
    if(SZ != 1) fail();

    int d4 = 0, d6 = 0;
    for(int i=0; i<N; i++){
