        G.add_edge(x, y);
    }

    for (int i = 0; i < N; ++i) {
        if (G.adj[i].size() % 2) {
            cout << "No" << endl;
            return 0;
        }
    }

    vector<int> C1, C2;
    G.find_euler_path();
    C1 = G.circuit;

    memset(seen, -1, sizeof(seen));
    bool ok = false;
    for (int i = 0; i < C1.size(); ++i) {
        int v = C1[i];
        if (seen[v] == -1 || (i - seen[v] + 1) == C1.size()) {
            seen[v] = i;
        } else {
            ok = true;
            C2.insert(C2.end(), C1.begin() + seen[v], C1.begin() + i + 1);
            C1.erase(C1.begin() + seen[v], C1.begin() + i);
            break;
        }
    }

    if (!ok) {
        cout << "No" << endl;
        return 0;
    }

    memset(seen, -1, sizeof(seen));
    ok = false;
    for (int i = 0; i < C1.size(); ++i) {
        int v = C1[i];
        if (seen[v] == -1 || (i - seen[v] + 1) == C1.size()) {
            seen[v] = i;
        } else {
            ok = true;
        }
    }

