using namespace std;

typedef pair <int, int> ii;

const int Maxn = 100005;
const int Maxm = 20;

int n, m;
int cnt[Maxn];
vector <int> neigh[Maxn];
int par[Maxn], siz[Maxn];
vector <ii> E;
int has;
int L[Maxn], P[Maxn][Maxm], V[Maxn];

int getPar(int x) { return par[x] == x? x: par[x] = getPar(par[x]); }

bool unionSet(int a, int b)
{
    a = getPar(a), b = getPar(b);
    if (a == b) return false;
    if (siz[a] < siz[b]) swap(a, b);
    siz[a] += siz[b]; par[b] = a;
    return true;
}

void Traverse(int v)
{
    V[v] += cnt[v] >= 4;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (P[v][0] == u) continue;
        L[u] = L[v] + 1; P[u][0] = v; V[u] = V[v];
        Traverse(u);
    }
}

int getLCA(int a, int b)
{
    if (L[a] < L[b]) swap(a, b);
    for (int i = Maxm - 1; i >= 0; i--)
        if (L[a] - (1 << i) >= L[b])
            a = P[a][i];
    if (a == b) return a;
    for (int i = Maxm - 1; i >= 0; i--)
        if (P[a][i] != P[b][i])
            a = P[a][i], b = P[b][i];
    return P[a][0];
}

int main()
{
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++)
        par[i] = i, siz[i] = 1;
    for (int i = 0; i < m; i++) {
        int a, b; scanf("%d %d", &a, &b);
        cnt[a]++; cnt[b]++;
        if (unionSet(a, b)) {
            neigh[a].push_back(b);
            neigh[b].push_back(a);
        } else E.push_back(ii(a, b));
    }
    for (int i = 1; i <= n; i++)
        if (cnt[i] % 2) { printf("No\n"); return 0; }
    for (int i = 1; i <= n; i++)
        if (cnt[i] >= 6) { printf("Yes\n"); return 0; }
        else if (cnt[i] >= 4) has++;
    Traverse(1);
    for (int j = 1; j < Maxm; j++)
        for (int i = 1; i <= n; i++)
            P[i][j] = P[P[i][j - 1]][j - 1];
    for (int i = 0; i < E.size(); i++) {
        int a = E[i].first, b = E[i].second;
        int lca = getLCA(a, b);
        int cur = V[a] + V[b] - V[lca] - V[P[lca][0]];
        if (cur < has) { printf("Yes\n"); return 0; }
    }
    printf("No\n");
    return 0;
}

