ll N, M;
vector<vector<ll>> es;
map<P, bool> visited;
vector<ll> dim;
vector<ll> hist;
vector<bool> visit;
void dfs(ll start, ll now) {
	visit[start] = true;
	for (auto &&e : es[now]) {
		P edge = P(min(now, e), max(now, e));
		if (visited[edge])
			continue;
		visited[edge] = true;
		hist.push_back(e);
		if (visit[e])
			return;
		visit[e] = true;
		dfs(start, e);
		return;
	}
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> M;
	es.assign(N, vector<ll>(0));
	dim.assign(N, 0);
	for (int i = 0;i < M;i++) {
		ll a, b;
		cin >> a >> b;
		a--; b--;
		es[a].push_back(b);
		es[b].push_back(a);
		dim[a]++;
		dim[b]++;
		visited[P(min(a, b), max(a, b))] = false;
	}
	bool ok = true;
	for (int i = 0;i < N;i++) {
		if (dim[i] % 2)
			ok = false;
	}
	if (ok) {
		for (int t = 0;t < 3;t++) {
			for (int i = 0;i < N;i++)
				if (dim[i] > 0) {
					hist.assign(0, 0);
					visit.assign(N, false);
					auto tmp = visited;
					dfs(i, i);
					visited = tmp;
					ll k;
					for (int i = (int)hist.size() - 2;i >= 0;i--) {
						if (hist[i] == hist.back()) {
							k = i;
							break;
						}
						dim[hist[i]] -= 2;
						visited[P(min(hist[i], hist[i + 1]), max(hist[i], hist[i + 1]))] = true;
					}
					dim[hist.back()] -= 2;
					visited[P(min(hist[k], hist[k + 1]), max(hist[k], hist[k + 1]))] = true;
					break;
				}
				else if (i == N - 1)
					ok = false;
		}
	}
	if (ok)
		cout << "Yes" << endl;
	else
		cout << "No" << endl;
	return 0;
}

