void kek(vector<vector<int>>& graph, set<pair<int, int>>& ban, vector<pair<int, int>>& order, int v) {
    while (not graph[v].empty()) {
        int u = graph[v].back();

        if (ban.count(make_pair(v, u)) or ban.count(make_pair(u, v))) {
            graph[v].pop_back();
