void solve() {
  int n, m; cin >> n >> m;
  vector<set<int>> g(n);
  rep(_,m) {
    int a, b; cin >> a >> b; --a, --b;
    g[a].emplace(b);
    g[b].emplace(a);
  }

  rep(i,n) {
    if (g[i].size() & 1) {
      cout << "No\n";
      return;
    }
  }

  vb finished(n, false);

  auto detection = [&]() -> bool {
    vb seen(n, false);
    stack<int> cycle;
    int cnt = 0;

    auto dfs = [&](auto dfs, int v, int p) -> bool {
      if (seen[v]) {
        int a, b = v;
        while (1) {
          a = b, b = cycle.top(); cycle.pop();
          g[a].erase(b);
          g[b].erase(a);
          if (finished[b]) ++cnt;
          else finished[b] = true;
          --m;
          if (b == v) break;
        }
        return true;
      }

      seen[v] = true;
      cycle.emplace(v);

      for (auto nv : g[v]) {
        if (nv != p) {
          if (dfs(dfs, nv, v)) return true;
        }
      }
      return false;
    };

    rep(i,n) {
      if (!g[i].empty()) {
        dfs(dfs, i, -1);
        return m > 0 || cnt > 2;
      }
    }
    return false;
  };

  CoutYN(detection() && detection());
}


