int DFS(int v, int ignoreVertex, const vector<vector<int>>& g, vector<bool>& used) {
  if (used[v]) return 0;
  used[v] = true;
  int result = 1;
  for (int to : g[v]) {
    if (to == ignoreVertex) continue;
    result += DFS(to, ignoreVertex, g, used);
  }
  return result;
}

