int N, M;
const int MAX_V = 101010;
//Ｏ(E*V^2)
//最大流アルゴリズム

struct edge {
  int to, cap, rev;
};

vector<edge> G[MAX_V];
int level[MAX_V]; // sからの距離
int iter[MAX_V];  //どこまで調べ終わったか

// fromからtoへ向かう容量capの辺をグラフに追加する。
void add_edge(int from, int to, int cap) {
  G[from].push_back((edge){to, cap, (int)G[to].size()});
}

// sからの最短距離をＢＦＳで計算する。
void bfs(int s) {
  memset(level, -1, sizeof(level));
  queue<int> que;
  que.push(s);
  level[s] = 0;
  while (!que.empty()) {
    int v = que.front();
    que.pop();
    for (int i = 0; i < G[v].size(); i++) {
      edge &e = G[v][i];
      if (e.cap > 0 && level[e.to] < 0) {
        level[e.to] = level[v] + 1;
        que.push(e.to);
      }
    }
  }
}

//増加パスをＤＦＳで探す。
int dfs(int v, int t, int f) {
  if (v == t)
    return f;
  for (int &i = iter[v]; i < G[v].size(); i++) {
    edge &e = G[v][i];
    if (e.cap > 0 && level[v] < level[e.to]) {
      int d = dfs(e.to, t, min(f, e.cap));
      if (d > 0) {
        e.cap -= d;
        G[e.to][e.rev].cap += d;
        return d;
      }
    }
  }
  return 0;
}

// sからtへの最大流を求める。
int max_flow(int s, int t) {
  int flow = 0;
  while (flow <= 6) {
    bfs(s);
    if (level[t] < 0)
      return flow;
    memset(iter, 0, sizeof(iter));
    int f;
    while ((f = dfs(s, t, INF)) > 0) {
      flow += f;
    }
  }
  return flow;
}

signed main() {
  cin >> N >> M;
  for (int i = 0; i < M; i++) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    add_edge(a, b, 1);
    add_edge(b, a, 1);
  }

  int c = 0, s, t;
  for (int i = 0; i < N; i++) {
    if (G[i].size() % 2) {
      cout << "No" << endl;
      return 0;
    }

    if (G[i].size() == 4) {
      if (c == 0) s = i;
      if (c == 1) t = i;
      c++;
    }

    if (G[i].size() >= 6 || c == 3) {
      cout << "Yes" << endl;
      return 0;
    }
  }

  if (c != 2) {
    cout << "No" << endl;
  } else {
    if (max_flow(s, t) == 2) {
      cout << "Yes" << endl;
    } else {
      cout << "No" << endl;
    }
  }

  return 0;
}

