void searchCC(LL v, vector<vector<LL>>& edge, vector<LL>& memo, vector<LL>& v_set){
    if(memo[v]) return;
    memo[v] = 1;
    v_set.push_back(v);
    for(LL e: edge[v]){
        searchCC(e, edge, memo, v_set);
    }
}

bool solve(LL n, LL m, vector<vector<LL>>& edge){
    vector<LL> memo(n);
    LL min_v = 0;
    LL max_v = 0;
    for(LL i = 0; i < n; ++i){
        if(memo[i]) continue;
        vector<LL> v_set;
        searchCC(i, edge, memo, v_set);
        LL cnt = 0;
        for(LL v: v_set){
            LL en = edge[v].size();
            //cerr << "en=" << en << endl;
            if(en % 2 == 1) return false;
            if(en == 4) ++cnt;
            if(en >= 6) cnt += 6;
        }
        //cerr << "cnt=" << cnt << endl;
        min_v += 1;
        max_v += 1 + (cnt+1)/2;
    }
    return (min_v <= 3) && (3 <= max_v);
}

