struct UnionFind{
    std::vector<int> data;
    UnionFind(int size):data(size,-1){}
    bool unite(int x,int y) {
        x=root(x);y=root(y);
        if(x!=y){
            if(data[y]<data[x])std::swap(x,y);
            data[x]+=data[y];data[y]=x;
        }
        return x!=y;
    }
    bool find(int x,int y) {
        return root(x)==root(y);
    }
    int root(int x) {
        return data[x]<0?x:data[x]=root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};


int main() {
	int n = ri();
	int m = ri();
	int a[m], b[m];
	std::set<int> hen[n];
	for (int i = 0; i < m; i++) a[i] = ri() - 1, b[i] = ri() - 1, hen[a[i]].insert(b[i]), hen[b[i]].insert(a[i]);

	for (int i = 0; i < n; i++) {
		if (hen[i].size() % 2) {
			std::cout << "No" << std::endl;
			return 0;
		}
	}

	UnionFind uni(n);
	std::set<int> label[n];
	int cnt = 0;
	int muda = 0;
	for (int i = 0; i < n; i++) {
		while (hen[i].size()) {
			int cur = i;
			std::set<int> list;
			do {
				assert(hen[cur].size());
				for (auto j : label[cur]) uni.unite(cnt, j);
				label[cur].insert(cnt);
				int next = *hen[cur].begin();
				if (list.count(next)) muda++;
				else list.insert(next);
				hen[cur].erase(next);
				hen[next].erase(cur);
				cur = next;
			} while (cur != i);
			cnt++;
		}
	}
	std::set<int> roots;
	for (int i = 0; i < cnt; i++) roots.insert(uni.root(i));

	if (cnt < 3) {
		std::cout << (cnt + muda >= 3 ? "Yes" : "No") << std::endl;
	} else std::cout << (roots.size() <= 3 ? "Yes" : "No") << std::endl;

	return 0;
}

