SplitGraph SG;

bool done;
vector<bool> seen;
int special;
vi vloop;
bool findCyc(const vvi &g, int x, int p) {
	if (seen[x]) {
		special=x;
		return true;
	}
	seen[x]=true;
	for (auto &y:g[x]) {
		if (y==p) continue;
		if (findCyc(g,y,x)) {
			if (!done) vloop.PB(x);
			if (x==special) done=true;
			return true;
		}
	}
	return false;
}

void dfs(const vector<set<int> > &g, int x) {
	if (seen[x]) return;
	seen[x]=true;
	for (auto &y:g[x]) dfs(g,y);
}

bool solve(long long n, long long m, vector<long long> a, vector<long long> b){
	vvi ig(n);
	for (int i=0;i<m;i++) {
		int x=a[i]-1,y=b[i]-1;
		ig[x].PB(y); ig[y].PB(x);
	}
	vvvi sg=SG.splitGraph(ig);
	if (sg.size()>3) return false;
	int circuits=0;
	for (auto &g:sg) {
		if (g.size()<=1) return false;
		int above=0;
		for (auto &e:g) {
			if (e.size()%2!=0) return false;
		}
		vector<set<int> > h(g.size());
		for (int x=0;x<g.size();x++) {
			for (auto &y:g[x]) {
				h[x].insert(y);
			}
		}
		seen.clear(); seen.resize(g.size()); vloop.clear(); done=false;
		findCyc(g,0,-1);
		for (int i=1;i<vloop.size();i++) {
			int x=vloop[i-1],y=vloop[i]; h[x].erase(y); h[y].erase(x);
		}
		h[vloop.front()].erase(vloop.back()); h[vloop.back()].erase(vloop.front());
		int has=1;
		for (auto &e:h) {
			int deg=e.size();
			if (deg>=4) has=3;
			if (deg>=2) chkmax(has,2);
		}
		for (int x=0;x<h.size();x++) {
			if (h[x].size()) {
				seen.clear(); seen.resize(h.size());
				dfs(h,x);
				for (int y=0;y<h.size();y++) {
					if (h[y].size()>0 && !seen[y]) {
						has=3;
					}
				}
				break;
			}
		}
		circuits+=has;
	}
	return circuits>=3;
}

