                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u]+w;
                    pre[v] = u;
                    if (w == 0) q.push_front(v);
                    else q.push_back(v);
                }
                if (v == start && pre[u] != start) {
                    best_use = min(best_use, dist[u]);
                }
            }
        }
        if (best_use == total_excess) return cout << "No", 0;
    }

    cout << "Yes";

    return 0;
}

