using Graph = vector<set<int>>;
int dfs(Graph& G, int u, vector<bool>& vis, int& cnt){
  if(vis[u]){
    ++cnt;
    return u;
  }

  vis[u] = true;
  while(!G[u].empty()){
    int to = *begin(G[u]);
    G[u].erase(to);
    G[to].erase(u);
    int r = dfs(G, to, vis, cnt);
    if(r != u){
      vis[u] = false;
      return r;
    }
  }
  vis[u] = false;

  assert(false);
  return -1;
}

