        {
            int u=q[hd++];
            for(int i=head[u];~i;i=G[i].nex) if(G[i].cap!=G[i].flow)
            {
                int v=G[i].to; 
                if(dis[v]==-1)
                {
                    dis[v]=dis[u]+1;
                    q[tl++]=v;
                }
            }
        }
        return dis[ed]!=-1;
    }
    int dfs(int u,int flow)
    {
        if(u==ed||flow==0) return flow;
        int rec=flow;
        for(int &i=cur[u];~i;i=G[i].nex)
        {
            int v=G[i].to;
            if(dis[v]==dis[u]+1)
            {
                int d=dfs(v,min(flow,G[i].cap-G[i].flow));
                G[i].flow+=d;
                G[i^1].flow-=d;
                if((flow-=d)==0) break;
            }
        }
        return rec-flow;
    }
    int maxflow()
    {
        int flow=0;
        while(bfs())
        {
            memcpy(cur,head,sizeof(head));
            flow+=dfs(st,inf);
        }
        return flow;
    }
}
