	rep(i, 1, n+1) {
		if(degrees[i]%2 == 1) {
			puts("No");
			return 0;
		}
		if(degrees[i] == 4)	cnt_four++;
	}
	LL maxDegree = *max_element(degrees+1, degrees+n+1);
	if(maxDegree >= 6)	puts("Yes");
	else if(maxDegree == 2)	puts("No");
	else if(cnt_four >= 3)	puts("Yes");
	else if(cnt_four == 2) {
		LL a = -1, b = -1;
		rep(i, 1, n+1) {
			if(degrees[i] == 4)	{
				if(a == -1)	a = i;
				else	b = i;
			}
		}
		LL cnt = 0;
		rep(it, adj[a].begin(), adj[a].end()) {
			if(dfs(*it, a, a, b))	cnt++;
		}
		if(cnt == 2)	puts("Yes");
		else	puts("No");
	}
	else puts("No");
}

