namespace UndirectedGraph
{

	void dfs(const int &u)
	{
		int &e = adj[u];
		while (e)
		{
			if (used[e])
				e = next[e];
			else
			{
				used[e] = used[e ^ 1] = true;
				dfs(go[e]);
			}
		}
	}

	inline bool solve()
	{
		n = getint(), m = getint();
		int mm = m;
		while (m--)
		{
			int u = getint(), v = getint();
			addEdge(u, v), addEdge(v, u);
			++deg[u], ++deg[v];
		}
		for (int u = 1; u <= n; ++u)
			if (deg[u] & 1)
				return false;
		for (int u = 1; u <= n; ++u)
			if (adj[u])
			{
				dfs(u);
				break;
			}
		for (int u = 1; u <= n; ++u)
			if (adj[u])
				return false;
		return mm - n >= 3;
	}
}

