struct edge_t {
  int other;
  int count;
  edge_t *rev;
};

vector<int> path;
void dfs(int v, vector<vector<edge_t*>> &adj) {
  while (!adj[v].empty()) {
    edge_t *last = adj[v].back();
    adj[v].pop_back();
    if (last->count == 0) {
      delete last;
      continue;
    }
    last->count = 0;
    last->rev->count = 0;

    dfs(last->other, adj);
    delete last;
  }
  path.push_back(v);
}

void answer_no() {
