  vector<vector<edge_t*>> adj(n);
  for (int i = 0; i < m; ++i) {
    int a, b;
    scanf("%d %d", &a, &b), --a, --b;
    adj[a].emplace_back(new edge_t);
    adj[b].emplace_back(new edge_t);
    edge_t *ab = adj[a].back();
    edge_t *ba = adj[b].back();
    ab->other = b;
    ab->rev = ba;
    ab->count = 1;
    ba->other = a;
    ba->rev = ab;
    ba->count = 1;
  }

  vector<int> fours;
  for (int i = 0; i < n; ++i) {
    if (adj[i].size() % 2 != 0)
      answer_no();
    //    if (adj[i].empty())
    //      answer_no();
    if (adj[i].size() >= 6)
      answer_yes();
    if (adj[i].size() == 4)
      fours.push_back(i);
  }

  if ((int)fours.size() <= 1)
    answer_no();
  if ((int)fours.size() >= 3)
    answer_yes();

  path.clear();
  dfs(0, adj);
  path.pop_back();

  vector<int> order;
  for (int i = 0; i < (int)path.size(); ++i) {
    if (path[i] == fours[0]) order.push_back(0);
    else if (path[i] == fours[1]) order.push_back(1);
  }
  assert((int)order.size() == 4);
  for (int i = 0; i + 1 < (int)order.size(); ++i)
    if (order[i] == order[i + 1])
      answer_yes();
  answer_no();

  return 0;
}

