typedef long long lint;

struct edge_t {
  int other;
  int count;
  edge_t *rev;
};

vector<int> path;
void dfs(int v, vector<vector<edge_t>> &adj) {
  while (!adj[v].empty()) {
    edge_t last = adj[v].back();
    adj[v].pop_back();
    if (last.count == 0) {
      continue;
    }
    last.count = 0;
    last.rev->count = 0;

    dfs(last.other, adj);
  }
  path.push_back(v);
}

void answer_no() {
  printf("No\n");
  exit(0);
}

void answer_yes() {
  printf("Yes\n");
  exit(0);
}

int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  vector<vector<edge_t>> adj(n);
  for (int i = 0; i < m; ++i) {
    int a, b;
    scanf("%d %d", &a, &b), --a, --b;
    adj[a].emplace_back(edge_t());
    adj[b].emplace_back(edge_t());
    edge_t &ab = adj[a].back();
    edge_t &ba = adj[b].back();
    ab.other = b;
    ab.rev = &ba;
    ab.count = 1;
    ba.other = a;
    ba.rev = &ab;
    ba.count = 1;
  }

  vector<int> fours;
  for (int i = 0; i < n; ++i) {
    if (adj[i].size() % 2 != 0)
      answer_no();
    if (adj[i].empty())
      answer_no();
    if (adj[i].size() >= 6)
      answer_yes();
    if (adj[i].size() == 4)
      fours.push_back(i);
  }

  if ((int)fours.size() <= 1)
    answer_no();
  if ((int)fours.size() >= 3)
    answer_yes();

  path.clear();
  dfs(0, adj);

  vector<int> pos0, pos1;
  for (int i = 0; i < n; ++i) {
    if (path[i] == fours[0])
      pos0.push_back(i);
    else if (path[i] == fours[1])
      pos1.push_back(i);
  }
  assert((int)pos0.size() == 2);
  assert((int)pos1.size() == 2);

  if (pos0[0] > pos0[1])
    swap(pos0[0], pos0[1]);
  if (pos1[0] > pos1[1])
    swap(pos1[0], pos1[1]);

  if (pos0[0] > pos1[0])
    swap(pos0, pos1);

  vector<int> &a = pos0;
  vector<int> &b = pos1;

  if (a[0] < b[0] && b[0] < a[1] && a[1] < b[1])
    answer_no();
  else
    answer_yes();

  return 0;
}

