		//始点終点をbgnとするような閉路が存在する
		if (next == bgn) {
			return true;
		}

		//まだ行ってないところであれば探索し、閉路が存在すればtrue
		if (flag[next] && dfs(bgn,cur,next,end)) {
			return true;
		}
	}
	//頂点bgnを始点終点とするような閉路は存在しない
	return false;
}

