typedef pair<int, int> Pair;

struct BCC{
    vector<Pair> bridge;
    vector<vector<int>> each_bcc;
    vector<int> cmp;
    stack<int> roots;
    stack<int> S;
    vector<bool> inS;
    vector<int> order;
    int k;

    void visit(int cur, int pre, const vector<int> G[]){
        order[cur] = ++k;
        S.push(cur);
        inS[cur] = true;
        roots.push(cur);

        for(auto to : G[cur]){
            if(order[to] == 0){
                visit(to, cur, G);
            }else if(to != pre && inS[to]){
                while(order[roots.top()] > order[to]) roots.pop();
            }
        }

        if(cur == roots.top()){
            if(pre != -1) bridge.push_back({pre, cur});
            vector<int> bcc;
            while(true){
                int node = S.top();
                S.pop();
                inS[node] = false;
                bcc.push_back(node);
                cmp[node] = each_bcc.size();
                if(node == cur) break;
            }
            each_bcc.push_back(bcc);
            roots.pop();
        }
    }

    void calculate(int N, const vector<int> edges[]){
        order.resize(N, 0);
        inS.resize(N, false);
        cmp.resize(N, 0);
        k = 0;
        for(int i=0; i<N; i++){
            if(order[i] == 0) visit(i, -1, edges);
        }
    }

    int sz(){
        return *max_element(cmp.begin(), cmp.end()) + 1;
    }

    int dump_graph(int N, const vector<int> edges[], vector<int> edges2[]){
        for(int i=0; i<N; i++){
            for(auto j : edges[i]){
                if(cmp[i] != cmp[j]){
                    edges2[cmp[i]].push_back(cmp[j]);
                }
            }
        }
        return *max_element(cmp.begin(), cmp.end()) + 1;  
    }
};

