vi vloop;
bool dfs(const vvi &g, int x, int p) {
	//printf("DFS:%d seen:%d\n",x,seen[x]?1:0);
	if (x==0) return true;
	if (seen[x]) return false;
	seen[x]=true;
	for (auto &y:g[x]) {
		if (y==p) continue;
		bool got=dfs(g,y,x);
		//printf("x:%d y:%d got:%d\n",x,y,got?1:0);
		if (got) {
			vloop.PB(x);
			return true;
		}
	}
	return false;
}

bool solve(long long n, long long m, vector<long long> a, vector<long long> b){
	vvi ig(n);
	for (int i=0;i<m;i++) {
		int x=a[i]-1,y=b[i]-1;
		ig[x].PB(y); ig[y].PB(x);
	}
	vvvi sg=SG.splitGraph(ig);
	if (sg.size()>3) return false;
	int circuits=0;
	for (auto &g:sg) {
		if (g.size()<=1) return false;
		int above=0;
		for (auto &e:g) {
			if (e.size()%2!=0) return false;
		}
		vi vdeg(g.size());
		for (int x=0;x<(int)g.size();x++) vdeg[x]=g[x].size();
		seen.clear(); seen.resize(g.size());
		vloop.clear(); vloop.PB(0);
		dfs(g,g[0][0],0);
		for (auto &x:vloop) {
			//printf("%d ",x);
			vdeg[x]-=2;
		}
		//printf(" loop\n");
		int has=1;
		for (auto &deg:vdeg) {
			if (deg>=4) has=3;
			if (deg>=2) chkmax(has,2);
		}
		circuits+=has;
	}
	return circuits>=3;
}

