bool check(int N, int M, std::vector<std::set<int>>edge)
{
	if (boost::count_if(edge, [](auto const& s) {return s.size() % 2 == 1; }) != 0)
	{
		return false;
	}
	else if (boost::count_if(edge, [](auto const& s) {return s.size() >= 6; }) != 0)
	{
		return true;
	}
	else if (boost::count_if(edge, [](auto const& s) {return s.size() == 4; }) >= 3)
	{
		return true;
	}
	else if (boost::count_if(edge, [](auto const& s) {return s.size() == 4; }) <= 1)
	{
		return false;
	}
	else
	{
		std::vector<int> four;
		for (auto i : boost::irange(0, N))
		{
			if (edge[i].size() == 4)
			{
				four.emplace_back(i);
			}
		}
		while (edge[four[0]].size() != 0)
		{
			int n = four[0];
			do
			{
				auto m = *edge[n].begin();
				edge[n].erase(m);
				edge[m].erase(n);
				n = m;
			} while (n != four[0] && n != four[1]);
			if (n == four[0])
			{
				return true;
			}
		}
	}
	return false;
}

