    }
    // all vertices are deg 2 or 4
    // try removing a vertex of deg 4, and seeing if there's a cycle
    for (int i=1; i<=n; i++) {
        if (cnt[i]==4) {
            memset(vis,0,sizeof vis);
            cycle=0;
            avoid=i;
            for (int j=1; j<=n; j++) {
                if (!vis[j] && j!=i) dfs(j,0);
            }
            if (cycle) return i;
        }
    }
    return 0;
}

