    repeat(i, N) {
        int d = graph.vertex_to[i].size();
        if (d % 2 != 0) bye("No");
        if (d == 4) d4 += 1;
        if (d >= 6) d6 += 1;
    }

    // ここまで：サーキットが1つ以上存在

    if (d4 >= 3 || d6 >= 1) bye("Yes");
    if (d4 == 0 && d6 == 0) bye("No");

    // d4 == 2 の時，分からない．

    GraphE::Edge e1 = graph.edges[0];

    // paint 1
    dfs(e1.v, -1, 0, e1.u, 1);
    if (crossCnt >= 2) bye("Yes");

    //debuga(paintedE, M);
    //debug(crossCnt);

    // RESET
    fill(paintedV, paintedV + N, 0);

    // paint 2
    bool ok = false;
    int eii = 0;
    while (paintedE[eii] > 0) ++eii;
    if (eii >= M) bye("No");
    // debug(eii)
    // debug(graph.edges[eii].u)
    ok = dfs(graph.edges[eii].v, -1, eii, graph.edges[eii].u, 2);
    // debuga(paintedE, M);
    if (!ok) bye("No");
    if (crossCnt >= 2) bye("Yes");

    // RESET
    fill(paintedV, paintedV + N, 0);

    // paint 3
    eii = 0;
    while (paintedE[eii] > 0) ++eii;
    if (eii >= M) bye("No");
    ok = dfs(graph.edges[eii].v, -1, eii, graph.edges[eii].u, 2);
    if (!ok) bye("No");
    bye("Yes");

    return 0;
}

