    for (int i = 1, u, v; i <= m; i++) scanf("%d%d", &u, &v), add(u, v), add(v, u);
    for (int i = 1; i <= n; i++) if (d[i] & 1)
    {
        puts("No");
        return 0;
    }
    dfs(1); 
    check() ? puts("Yes") : puts("No");
    return 0;
}

