class UnionFind
{
public:
    explicit UnionFind(int N)
    {
        m_par.reserve(N);
        for (int n = 0; n < N; ++n) {
            m_par.push_back(n);
        }
    }
    int Root(int n)
    {
        if (n == m_par[n]) return n;
        return m_par[n] = Root(m_par[n]);
    }
    void Unite(int n, int m)
    {
        if (Root(n) == Root(m)) return;
        m_par[Root(n)] = Root(m);
    }
    bool Same(int n, int m)
    {
        return Root(n) == Root(m);
    }
private:
    vi m_par;
};

int main(int argc, const char * argv[]) {
    ios_base::sync_with_stdio(false);
    int N, M;
    cin >> N >> M;
    vvi G(N);
    for (int m = 0; m < M; ++m) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    bool bAllEven = true;
    int i4 = 0, i6 = 0;
    for (int n = 0; n < N; ++n) {
        size_t m = G[n].size();
        if (m%2 != 0) {
            bAllEven = false;
            break;
        }
        if (m == 4) {
            ++i4;
        } else if (m >= 6) {
            ++i6;
        }
    }

    if (!bAllEven) {
        cout << "No" << endl;
        return 0;
    }

    if (i6 >= 1 || i4 >= 3) {
        cout << "Yes" << endl;
        return 0;
    } else if (i4 == 2) {
        UnionFind UF(N);
        int v = -1;
        for (int n = 0; n < N; ++n) {
            if (G[n].size() == 4) {
                v = n;
            } else if (G[n].size() == 2) {
                if (G[G[n][0]].size() != 4 || G[G[n][1]].size() != 4) {
                    UF.Unite(G[n][0], G[n][1]);
                }
            }
        }
        bool bSame = false;
        for (int i = 0; i < 4; ++i) {
            for (int j = i+1; j < 4; ++j) {
                if (UF.Same(G[v][i], G[v][j])) {
                    bSame = true;
                }
            }
        }
        if (bSame) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
    } else {
        cout << "No" << endl;
    }

    return 0;
}

