const int N = 1e5+7;
vector<pair<int, int>> edges;
vector<int> adj[N];

bool dfs(int u, int pe, int s, int t) {
    for (int e: adj[u]) {
        if (e == pe)    continue;
        int v = edges[e].first^edges[e].second^u;
        if (v == t) continue;
        if (v == s || dfs(v, e, s, t))    return true;
    }
    return false;
}

int main() {
