inline int getint()
{
	int x;
	scanf("%d", &x);
	return x;
}

int n, m;
int adj[MaxN];

int nE = 1;
int next[MaxNE], go[MaxNE];
bool used[MaxNE];

int tour_n;
int tour[MaxM];

inline void addEdge(const int &u, const int &v)
{
	next[++nE] = adj[u], go[adj[u] = nE] = v;
}

int deg[MaxN];

namespace UndirectedGraph
{
	inline int edgeId(const int &e)
	{
		int id = e >> 1;
		return e & 1 ? -id : id;
	}

	int cnt[MaxN];

	void dfs(const int &u)
	{
		int &e = adj[u];
		while (e)
		{
			if (used[e])
				e = next[e];
			else
			{
				used[e] = used[e ^ 1] = true;
				dfs(go[e]);
				tour[++tour_n] = e ^ 1;
			}
		}
	}

	inline bool solve()
	{
		n = getint(), m = getint();
		int mm = m;
		while (m--)
		{
			int u = getint(), v = getint();
			addEdge(u, v), addEdge(v, u);
			++deg[u], ++deg[v];
		}
		for (int u = 1; u <= n; ++u)
			if (deg[u] & 1)
				return false;
		for (int u = 1; u <= n; ++u)
			if (adj[u])
			{
				dfs(u);
				break;
			}
		for (int u = 1; u <= n; cnt[u] = -1, ++u)
			if (adj[u])
				return false;
		for (int i = tour_n; i; --i) {
		    int id = tour[i];
		    ++cnt[go[id]];
		}
		return mm - n >= 2;
	}
}

