        used[idx]=true;
        return true;
      }
      else{
        used[idx]=false;
      }
    }
  }
  return false;
}
bool dfs2(ll pos,ll st,bool f){
  //cout<<pos<<" "<<st<<" "<<(f?"O":"X")<<endl;
  if(f&&pos==st) return true;
  for(int i=0;i<node[pos].size();i++){
