    vector<ii> el;
    FOR(i, 0, m-1) {
        int a, b; cin >> a >> b;
        --a, --b;
        ++deg[a], ++deg[b];
        el.emplace_back(a, b);
    }

    string ans = "";
    int deg4 = 0, x = -1;
    FOR(i, 0, n-1) {
        if (deg[i]%2 == 1) { ans = "No"; break; }
        else if (deg[i] >= 6) { ans = "Yes"; break; }
        else if (deg[i] == 4) ++deg4, x = i;
    }

    if (ans == "") {
        if (deg4 >= 3) ans = "No";
        else if (deg4 == 2) {
            UnionFind UF(n);
            for (auto e : el) {
                if (e.fi != x and e.sc != x)
                    UF.unionset(e.fi, e.sc);
            }

            int cnt = 0;
            FOR(i,0,n-1) cnt += (i == UF.findset(i));
            if (UF.comp >= 3) ans = "Yes";
            else ans = "No";
        }
        else ans = "No";
    }
    cout << ans < '\n';
}

