using namespace std;

inline int nxt() {
	int x;
	scanf("%d", &x);
	return x;
}

const int N = 111;
int a[N][N];

int main() {
	mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

	int n = nxt(), m = nxt();
	vector<multiset<int>> a(n);
	for (int i = 0; i < m; ++i) {
		int u = nxt() - 1, v = nxt() - 1;
		a[u].insert(v);
		a[v].insert(u);
	}

	bool all_even = true;
	for (const auto& v : a) {
		all_even &= (v.size() % 2 == 0);
	}

	if (!all_even) {
		puts("No");
		return 0;
	}

	set<pair<int, int>> S;
	for (int i = 0; i < n; ++i) {
		S.insert({(int)a[i].size(), i});
	}
	int num_cycles = 0;
	while (!S.empty() && S.begin()->first == 2) {
		auto p = *S.begin();
		S.erase(S.begin());
		int u = *a[p.second].begin();
		int v = *a[p.second].rbegin();
		// cerr << u + 1 << " -- " << p.second + 1 << " -- " << v + 1 << " -> " << u + 1 << " -- " << v + 1 << "\n";
		// for (auto p : S) {
		// 	cerr << p.first << " " << p.second + 1 << "\n";
		// }
		a[p.second].clear();
		m -= 1;
		a[u].erase(a[u].find(p.second));
		a[v].erase(a[v].find(p.second));
		if (u == v) {
			--m;
			S.erase({(int)a[u].size() + 2, u});
			S.insert({(int)a[u].size(), u});
			++num_cycles;
			continue;
		}
		a[u].insert(v);
		a[v].insert(u);
	}

	num_cycles += m / 2;

	puts(num_cycles >= 3 ? "Yes" : "No");

	return 0;
}

