    if (is_1origin) x--, y--;
    g[x].eb(x, y, c);
    if (!is_directed) g[y].eb(y, x, c);
  }
  return g;
}

void solve() {
  inl(N, M);
  auto g = graph(N, M);
  ll rest = 0;
  each(x, g) {
    if (sz(x) & 1) die("No");
    rest += sz(x) - 2;
  }
  if (rest < 4) die("No");
  if (rest >= 6) die("Yes");

  int u = -1;
  rep(i, N) if (sz(g[i]) == 4) {
    u = i;
    break;
  }
  if (u == -1) die("Yes");
  each(x, g[u]) {
    if (sz(g[x]) == 4) die("No");
  }
  die("Yes");
}

