void bfs(int from) {
    if(pathes[from].empty()) return;
    tour.push_back(from);
    auto itr = pathes[from].begin();
    itr=pathes[from].erase(itr);
    auto itr2 = pathes[*itr].lower_bound(from);
    pathes[*itr].erase(itr2);
    degree[from]--;
    degree[*itr]--;
    bfs(*itr);
}

void solve() {
    //cout.precision(10);
    bool win = false;
    start = -1;
    for(int i = 1; i <= N; i++) {
        if(degree[i] % 2 != 0) {
            //cout << "No" << endl;
            num_circuit = -99;
            return;
        }
        if(degree[i] > 0) start = i;
        if(degree[i] >= 6) win = true;
