        //cout << "No" << endl;
        num_circuit = -99;
        return;
    }
    //start = 1;
    tour.clear();
    bfs(start);
    for(int i = 1; i <= N; i++) {
        before[i] = -1;
    }
    vector<l_l> circuit;
    //for(int i = 0; i < tour.size(); i++) cout << tour[i] << endl;
    //cout << endl;
    for(int i = 1; i < tour.size(); i++) {
        int val = tour[i];
        if(before[val] != -1) {
            circuit.push_back({before[val], i});
        }
        before[val] = i;
    }
    num_circuit++;
    if(circuit.size() == 0) {
        //cout << "No" << endl;
        return;
    }
    num_circuit++;
    ll RIGHT = 1e7;
    ll LEFT = -1e7;
    sort(circuit.begin(), circuit.end());
    /*
    for(int i = 0; i < circuit.size(); i++) {
        RIGHT = min((ll)RIGHT, circuit[i].second);
        if(circuit[i].second < circuit.back().first) {
            //cout << "Yes" << endl;
