#include <bits/stdc++.h>
using namespace std;

class Solution {
  int n, m;
  vector<vector<int>> g;
  vector<pair<int, int>> Es;
  vector<bool> used, passed;
  int greedy(int a) {
    if (passed[a]) return 0;
    passed[a] = 1;
    for (int id : g[a]) {
      if (not used[id]) {
        used[id] = 1;
        int u, v; tie(u, v) = Es[id];
        if (u == a) swap(u, v);
        return greedy(u) + 1;
      }
    }
    return 0;
  }
public:
  void run() {
    cin >> n >> m;
    g.resize(n);
    used.resize(m);
    passed.resize(n);
    Es.resize(m);
    for (int i = 0; i < m; ++i) {
      int a, b; cin >> a >> b;
      --a, --b;
      Es[i] = {a, b};
      g[b].emplace_back(i), g[a].emplace_back(i);
    }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
      if (g[i].size() % 2) {
        cout << "No\n";
        exit(0);
      }
      ans += g[i].size() / 2 - 1;
    }
    if (ans > 2) cout << "Yes\n", exit(0);
    for (int t = 0; t < 20; ++t) {
      passed.assign(n, 0);
      used.assign(m, 0);
      for (int i = 0; i < n; ++i) random_shuffle(g[i].begin(), g[i].end());
      int left = greedy(0);
      passed.assign(n, 0);
      for (int i = 0; i < n; ++i) {
        int add = greedy(i);
        if (add and left + add != m) {
          cout << "Yes\n";
          exit(0);
        }
      }
    }
    cout << "No\n";
  }
};


int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  Solution().run();
}

