	for(int i = 1; i <= m; ++i)
	{
		int u = read<int>(), v = read<int>();
		adj[u].emplace_back(v, i), ++deg[u];
		adj[v].emplace_back(u, i), ++deg[v];
	}
}

int vis[MAXN + 5], cut[MAXN + 5];

inline int dfs(int u, int id, int p)
{
	vis[u] = 1;
	int res = 0;
	for(auto it : adj[u]) if(it.snd != id)
	{
		int v = it.snd;
		if(v == p) return 1;
		if(!cut[v] && !vis[v]) res |= dfs(v, it.snd, p);
	}
	return res;
}

inline void solve()
{
	for(int i = 1; i <= n; ++i) if(deg[i] % 2 == 1) { puts("No"); return; }

	int mx = *max_element(deg + 1, deg + n + 1);
	if(mx >= 6) puts("Yes");
	else if(mx <= 2) puts("No");
	else
	{
		static vector<int> nds;

		for(int i = 1; i <= n; ++i) if(deg[i] == 4) nds.push_back(i);

		if(SZ(nds) > 2) { puts("Yes"); return; }
		else if(SZ(nds) == 1) { puts("No"); return; }
		{
			cut[nds[1]] = 1;
			puts(dfs(nds[0], 0, nds[0]) ? "Yes" : "No");
		}
	}
}

