int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N, M;
    cin >> N >> M;

    vvi adj(N);

    for (int i = 0, u, v; i < M; i++) {
        cin >> u >> v;
        adj[u-1].push_back(v-1);
        adj[v-1].push_back(u-1);
    }

    int two = 0, four = 0, six_plus = 0;
    vi fours;

    for (int i = 0; i < N; i++) {
        int v = adj[i].size();
        if (v&1) {
            cout << "No\n";
            return 0;
        }

        if (v == 2) two++;
        if (v == 4) { four++; fours.push_back(i); }
        else six_plus++;
    }

    if (six_plus > 0 || four > 2) { cout << "Yes\n"; return 0; }
    if (four < 2) { cout << "No\n"; return 0; }

    int root = fours.front(), paths = 0;
    for (int nbr : adj[root]) {
        int prv = root;
        while (adj[nbr].size() != 4) {
            int nxt = adj[nbr][0] + adj[nbr][1] - prv;
            prv = nbr;
            nbr = nxt;
        }
        if (nbr == fours.back()) paths++;
    }

    cout << (paths == 2 ? "Yes\n" : "No\n");

    return 0;
}

