using namespace std;

typedef long long ll;

const int MAX_N = 1e5 + 10;

int n, m;
bool inCycle[MAX_N];
vector <int> G[MAX_N];
int vis[MAX_N];
int path[MAX_N];
int nCycles = 0;
int H[MAX_N];

void dfs_buid (int u, int v, int h) {
  vector <int> pib;
  for (int v: G[u]) {
    if (H[v] == 0) {
      pib.push_back(v);
      H[v] = h + 1;
    }
  }
  for (int v: pib) dfs_buid(v, u, h + 1);
}

void dfs (int u, int p) {
  vis[u] = 1;
  for (int v: G[u]) {
    if (vis[v] == 2 or v == p) continue;
    if (vis[v] == 0) {
      path[v] = u;
      dfs(v, u);
    } else {
      nCycles++;
      int p = u;
      while (true) {
        inCycle[p] = true;
        if (p == v) break;
        p = path[p];
      }
    }
  }
  vis[u] = 2;
}

int main () {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> n >> m;
  for (int i = 1; i <= m; i++) {
    int u, v;
    cin >> u >> v;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  H[1] = 1;
  dfs_buid(1, -1, 1);
  for (int u = 1; u <= n; u++) sort(all(G[u]), [&] (int u, int v) { return H[u] < H[v]; });
  dfs(1, -1);
  bool ok = true;
  for (int u = 1; u <= n; u++) ok &= inCycle[u];
  if (ok and nCycles >= 3) cout << "Yes" << endl;
  else cout << "No" << endl;
  return (0);
}

