const int UnionFindTree_MAX_V = 100000;	//最大の頂点数
struct UnionFindTree{
	int par[UnionFindTree_MAX_V+10],r[UnionFindTree_MAX_V+10];
	void init(int n = UnionFindTree_MAX_V){
		for(int i = 0 ; i < n+10 ; i ++){
			par[i] = i;
			r[i] = 0;
		}
	}
	int find(int x){
		if(par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
	void unit(int x,int y){
		if(same(x,y))return;
		x = find(x);
		y = find(y);
		if(r[x] < r[y]){
			par[x] = y;
		}
		else {
			par[y] = x;
			if(r[x] == r[y]){
				r[x] ++;
			}
		}
	}
}uf;

