template<typename T> int bins(const vector<T> &v, T key) {int imin=0,imax=v.size();while(imin<imax) {int imid=(imin+imax)>>1;if (v[imid]<key) imin=imid+1;else imax=imid;}return imin;}
class SplitGraph {
	vector<bool> seen;
	vi liveV; vpii liveE;
	void splitGraphDfs(const vvi &g, int x) {
		if (seen[x]) return;
		seen[x]=true;
		liveV.PB(x);
		for (auto &y:g[x]) {
			liveE.PB(MP(x,y));
			splitGraphDfs(g,y);
		}
	}
public:
	vvvi splitGraph(const vvi &g) {
		int n=g.size(); seen.clear(); seen.resize(n);
		vvvi vg;
		for (int x=0;x<n;x++) {
			if (!seen[x]) {
				splitGraphDfs(g, x);
				sort(liveV.begin(),liveV.end());
				vvi newg(liveV.size());
				for (auto &e:liveE) {
					int from=bins(liveV, e.fst),to=bins(liveV, e.snd);
					//printf("%d->%d\n",from,to);
					newg[from].PB(to);
				}
				liveV.clear(); liveE.clear();
				vg.PB(newg);
			}
		}
		return vg;
	}
};
SplitGraph SG;

class ContractDegree2 {
	vector<bool> seen; vvi newg;
	void dfs(const vvi &g, int x, int big, int parent) {
		if (g[x].size()!=2 && big!=-1) newg[big].PB(x);
		if (seen[x]) return;
		seen[x]=true;
		//printf("x:%d big:%d parent:%d\n",x,big,parent);
		if (g[x].size()==2) {
			for (auto &y:g[x]) {
				if (y==parent) continue;
				dfs(g,y,big,x);
			}
		}
		else {
			for (auto &y:g[x]) {
				if (y==parent) continue;
				dfs(g,y,x,x);
			}
		}
	}
public:
	vvi contract(const vvi &g) {
		int n=g.size();
		seen.clear(); seen.resize(n); newg.clear(); newg.resize(n);
		for (int x=0;x<n;x++) {
			if (g[x].size()!=2) dfs(g,x,-1,-1);
		}
		return newg;
	}
};
ContractDegree2 CD2;

bool solve(long long n, long long m, vector<long long> a, vector<long long> b){
	vvi ig(n);
	for (int i=0;i<m;i++) {
		int x=a[i]-1,y=b[i]-1;
		ig[x].PB(y); ig[y].PB(x);
	}
	vvvi sg=SG.splitGraph(ig);
	if (sg.size()>3) return false;
	int circuits=0;
	for (auto &g:sg) {
		int n=g.size();
		if (n<=1) return false;
		int above=0;
		for (auto &e:g) {
			if (e.size()%2!=0) return false;
		}
		vvi h=CD2.contract(g);
		int selfloops=0;
		for (int x=0;x<n;x++) {
			for (auto &y:h[x]) {
				if (y==x) {
					selfloops++;
					//printf("selfloop:%d\n",x);
				}
			}
		}
		int extrapairs=0;
		for (int x=0;x<n;x++) {
			extrapairs+=((int)((int)g[x].size()/2))-1;
		}
		int dualloops = (extrapairs-selfloops)/2;
		//printf("extrapairs:%d selfloops:%d dualloops:%d\n",extrapairs,selfloops,dualloops);
		circuits+=1+selfloops+dualloops;
	}
	return circuits>=3;
}

