using namespace std;
using Int = long long;
bool solve(const vector<vector<int>> &G) {
    bool six = false;
    vector<int> four;
    for (int i = 0; i < G.size(); i++) {
        int t = G[i].size();
        if (t % 2) return false;
        if (t >= 6) six = true;
        if (t == 4) four.push_back(i);
    }
    if (six || four.size() >= 3) {
        return true;
    } else if (four.size() <= 1) {
        return false;
    } else {
        queue<pair<int, int>> Q;
        bool ans = false;
        Q.emplace(four[0], -1);
        while (!Q.empty()) {
            int node, prev;
            tie(node, prev) = Q.front();
            Q.pop();
            if (node == four[0] && prev != -1) {
                ans = true;
                break;
            }
            if (node == four[1]) {
                continue;
            }
            for (int next : G[node]) if (next != prev) {
                Q.emplace(next, node);
            }
        }
        return ans;
    }
}
int main() {
    int N, M; cin >> N >> M;
    vector<vector<int>> G(N);
    for (int i = 0; i < M; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    cout << (solve(G) ? "Yes" : "No") << '\n';
    return 0;
}

