void add_edge(int u,int v) {
  whe[u].push_back(ed[v].size());
  whe[v].push_back(ed[u].size());
  ed[u].push_back(v);
  ed[v].push_back(u);
}

void del_edge(int u) {
  int v = ed[u].back();
  int j = whe[u][ed[u].size() - 1];
  ed[u][ed[u].size() - 1] = -1;
  ed[v][j] = -1;
}

void dfs(int cur) {
  cnt[cur]++;
  while(ed[cur].empty() == false) {
    int j = ed[cur].back();
    if (j == -1) {
      ed[cur].pop_back();
      continue;
    }
    del_edge(cur);
    ed[cur].pop_back();
    dfs(j);
    break;
  }
}

