bool dfs(int source, int dest, int prev, int cur)
{
	int i;


	for (i = 0; i < graph[cur].size(); i++)
	{
		if (graph[cur][i] == prev)
		{
			continue;
		}

		if (graph[cur][i] == dest)
		{
			return false;
		}

		if (graph[cur][i] == source)
		{
			return true;
		}

		return dfs(source, dest, cur, graph[cur][i]);
	}
}

