const int MAX_N=1e6+1;
VI GG[MAX_N];
VI G[MAX_N];
int N,M;

int viz[MAX_N];
void dfs(int u) {
  if(viz[u]) return;
  viz[u]=true;
  FORR(v,G[u]) dfs(v);
}

void nope() {
  println("No");
  exit(0);
}
void yup() {
  println("Yes");
  exit(0);
}
void solve() {
  dfs(0);
  REP(i,N) if(!viz[i]) nope();
  REP(i,N) if(SZ(G[i])%2==1) nope();
  REP(i,N) if(SZ(G[i])>=6) yup();
  int cnt=0;
  REP(i,N) if(SZ(G[i])==4) {
    ++cnt;
  }
  if(cnt>2) yup();
  if(cnt<2) nope();
  VI us;
  REP(i,N) if(SZ(G[i])==4) us.push_back(i);
  assert(SZ(us)==2);
  int a=us.front(),b=us.back();
  REP(i,N) GG[i]=G[i];
  REP(i,N) G[i].clear();
  REP(u,N)FORR(v,GG[u]) if(u!=b&&v!=b) G[u].push_back(v);
  ZERO(viz);
  dfs(a);
  int cnt2=0;
  REP(i,N) cnt2+=viz[i];
  if(cnt2==N-1) nope();
  else yup();
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N>>M;
  REP(i,M) {
    int u,v; cin>>u>>v;
    --u,--v;
    G[u].push_back(v);
    G[v].push_back(u);
  }
  solve();

  return 0;
}

