#define N 200000 + 5

int n, m, sz, bcc, T[N], Deg[N], Head[N], Dfn[N], Low[N], Stack[N];
bool ok = true;

struct Edge
{
	int next, node;
}h[N << 1];

inline void addedge(int u, int v)
{
	static int tot = 1;
	h[++ tot].next = Head[u], Head[u] = tot;
	h[tot].node = v;
}

void dfs(int z)
{
	static int id = 0;
	Dfn[z] = Low[z] = ++ id;
	Stack[++ sz] = z;
	for (int i = Head[z]; i; i = h[i].next)
	{
		int d = h[i].node;
		if (!Dfn[d])
		{
			dfs(d);
			Low[z] = min(Low[z], Low[d]);
			if (Low[d] >= Dfn[z])
			{
				bcc ++;
				int j;
				do
				{
					j = Stack[sz --];
				} while (j != d);
			}
		}
		else Low[z] = min(Low[z], Dfn[d]);
	}
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1, u, v; i <= m; i ++)
	{
		scanf("%d%d", &u, &v);
		addedge(u, v), addedge(v, u);
		Deg[u] ++, Deg[v] ++;
	}
	for (int i = 1; ok && i <= n; i ++)
		ok = Deg[i] % 2 == 0;
	if (!ok) puts("No");
	else
	{
		ok = false;
		int cnt = 0;
		for (int i = 1; !ok && i <= n; i ++)
			ok = Deg[i] >= 6, cnt += Deg[i] >= 4;
		ok |= (cnt >= 3);
		if (!ok && cnt == 2)
			dfs(1), ok = bcc > 1;
		puts(ok ? "Yes" : "No");
	}
	return 0;
}

