const int MX = 100 * 1000 + 7;

int deg[MX];
vector<int> g[MX];
bool was[MX];
int timer = 1;
int tin[MX], fup[MX];

void dfs(int v, int p = -1) {
    was[v] = true;
    tin[v] = fup[v] = timer++;
    int c = 0;
    for (int to : g[v]) {
        if (to == p) {
            continue;
        }
        if (was[to]) {
            fup[v] = min(fup[v], tin[to]);
        } else {
            dfs(to, v);
            fup[v] = min(fup[v], fup[to]);
            if (fup[to] >= tin[v] && p != -1) {
                cout << "Yes\n";
                exit(0);
            }
            c++;
        }
    }
    if (p == -1 && c > 1) {
        cout << "Yes\n";
        exit(0);
    }
}

