void no() { printf("No\n"); exit(0); }
void yes() { printf("Yes\n"); exit(0); }

void er(int a, int b) { g[a].erase(b); g[b].erase(a); }

int go(int v, int p = 0){
	vis[v] = true;
	for (auto it = g[v].begin(); it != g[v].end(); ++it){
		if (*it == p)continue;
		if (vis[*it]){
			int an = *it;
			er(v, *it);
			return an;
		}
		int t = go(*it, v);
		if (t == 0)return 0;
		er(v, *it);
		if (t == v)t = 0;
		return t;
	}
}

