vi circuit(const Graph &G, int s, vb &ban) {
    vi ret;
    ret.push_back(s);
    int pos = s;
    while (true) {
        int ns = 0;
        for (auto e : G[pos]) {
            if (!ban[e.to]) {
                ns = e.to;
            }
        }
        ban[ns] = true;
        if (ns == pos)
            return ret;
        ret.push_back(ns);
        pos = ns;
    }
}

int main(void) {
    int N, M;
    cin >> N >> M;
    Graph G(N);
    vi dim(N, 0);
    rep(i, M) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(Edge{a, b, 1});
        G[b].push_back(Edge{b, a, 1});
        dim[a]++;
        dim[b]++;
    }
    rep(i, N) {
        if (dim[i] % 2 == 1) {
            cout << "No" << endl;
            assert(false);
            DEB cerr << __LINE__ << endl;
            return 0;
        }
    }
    vb used(N, false);
    vi c = circuit(G, 0, used);
    int num = 0;
    vi dim4;
    for (auto i : c) {
        if (dim[i] >= 6) {
            cout << "Yes" << endl;
            DEB cerr << __LINE__ << endl;
            return 0;
        } else if (dim[i] == 4) {
            num++;
            dim4.push_back(i);
        }
    }
    if (num >= 3) {
        cout << "Yes" << endl;
        DEB cerr << __LINE__ << endl;
        return 0;
    } else if (num == 0) {
        cout << "No" << endl;
        assert(false);
        DEB cerr << __LINE__ << endl;
        return 0;
    }

    rep(i, num) used[dim4[i]] = false;
    int start = 0;
    while (used[start]) {
        start++;
    }
    vi c2 = circuit(G, start, used);

    for (auto i : c2) {
        if (dim[i] >= 4) {
            cout << "Yes" << endl;
            DEB cerr << __LINE__ << endl;
            return 0;
        }
        bool all_used = true;
        rep(i, N) {
            if (!used[i]) {
                all_used = false;
                break;
            }
        }
        if (all_used) {
            cout << "No" << endl;
            assert(false);
            DEB cerr << __LINE__ << endl;
        } else {
            cout << "Yes" << endl;
            DEB cerr << __LINE__ << endl;
        }
    }

    return 0;
}

