bool visp[111111];
int dfs(int a, int fa){
	visp[a] = true;
	for(int i = fr[a]; i; i = ne[i]){
		if(to[i] == fa || vis[i]) continue;
		if(visp[to[i]]) {vis[i] = vis[i ^ 1] = true; visp[a] = false; return to[i];}
		else{
			int k = dfs(to[i], a);
			if(k != -1){
				vis[i] = vis[i ^ 1] = true;
				if(k != a) {visp[a] = false; return k;}
				else ans++;
			}
		}
	}
	visp[a] = false;
	return -1;
}

