int N, M;
vector <int> adj[100000];
int adj_cnt[100000];
int a, b;

int ans;

int main(void) {
	scanf("%d %d", &N, &M);
	for (int i = 0; i < M; i++) {
		scanf("%d %d", &a, &b);
		adj[a - 1].push_back(b - 1);
		adj[b - 1].push_back(a - 1);
	}
	int all_even = 1;
	for (int i = 0; i < N; i++) {
		adj_cnt[i] = adj[i].size();
		if (adj_cnt[i] % 2 == 1) {
			all_even = 0;
		}
	}
	if (all_even == 0) {
		printf("No\n");
	}

	/*出てる辺の個数が6以上の頂点があるか、4以上の頂点が3つ以上あればYes*/

	int four_cnt = 0;
	for (int i = 0; i < N; i++) {
		if (adj_cnt[i] >= 6) {
			printf("Yes\n");
			return 0;
		}
		if (adj_cnt[i] == 4) {
			four_cnt += 1;
		}
	}
	if (four_cnt >= 3) {
		printf("Yes\n");
		return 0;
	}

	/* 4以上の頂点が1つ以下ならNo */
	if (four_cnt <= 1) {
		printf("No\n");
		return 0;
	}

	int v;
	for (int i = 0; i < N; i++) {
		if (adj_cnt[i] == 4) {
			v = i;
			break;
		}
	}

	/*vからはじめて、もう一方の4の頂点を経由せずに自身に戻ってくるループがあるかを調べる。
	あればYes, なければNo*/
	int is_loop = 0;
	for (int i = 0; i < 4; i++) {
		int p = adj[v][i];
		int q = v;
		for (int j = 0; j < N; j++) {
			if (adj_cnt[p] == 4 && p != v) {
				break;
			}
			else if (p == v) {
				is_loop = 1;
				break;
			}
			if (adj[p][0] != q) {
				q = p;
				p = adj[p][0];
			}
			else {
				q = p;
				p = adj[p][1];
			}
		}
		if (is_loop == 1) {

			printf("Yes\n");
			return 0;
		}
	}
	printf("No\n");
}

