const int N = 1e5 +1;
int n, m, tot;
int a[N * 2][2], w[N], in[N];
int ans;
void ins(int x, int y)
{
    a[++tot][0] = y, a[tot][1] = w[x], w[x] = tot;
    a[++tot][0] = x, a[tot][1] = w[y], w[y] = tot;
}
void dfs(int x, vector<int>& d)
{
    for (int i = w[x]; i ;w[x] = i = a[i][1])
        if (a[i][0])
        {
            int y = a[i][0];
            a[i][0] = a[i ^ 1][0] = 0;
            w[x] = i;
            dfs(y, d);
            if (i > w[x]) i = w[x];
        }
    d.push_back(x);
}
void work(vector<int> & g)
{
    if (ans == 3) return;
    unordered_map<int, int>f;
    f.clear();
    for (int i = g.size() - 1; i > 0;  i --)
        if (!f[g[i]])f[g[i]] = i;
    for (int i = 1; i < g.size() - 1; i ++)
        if (f[g[i]] > i)
        {
            vector<int> gg;
            gg.clear();
            int x = f[g[i]];
            for (int j = i; j <= x; j ++)
                w[g[j]] = 0;
            tot = 1;
            ans ++;
            for (int j = i ; j < x; j ++)
                ins(g[j],g[j  + 1]);
            dfs(g[i], gg);
            work(gg);
            i = x;
            if (ans == 3) return;
