using namespace std;
int charge(int current, int next, int start, int end, int N, int M, vector<vector<int>> &edges)
{
    if(start == next || end == next) return next;
    for(auto nextnext: edges[next]){
        if(nextnext!=current){
            return charge(next, nextnext, start, end, N, M, edges);
        }
    }
}
bool nokori(int N, int M, vector<vector<int>> &edges)
{
    vector<int> points;
    for (int i = 0; i < N; i++)
    {
        if (edges[i].size() == 4)
        {
            points.push_back(i);
        }
    }
    int start = points[0];
    int end = points[1];
    vector<int> count(2);
    for(auto next :edges[start]){
        int ret=charge(start,next,start,end,N,M,edges);
        if(ret==start)count[0]++;
        else if(ret==end)count[1]++;
        else throw 42;
    }
    return count[0]==2;
}
bool solve(int N, int M, vector<vector<int>>& edges)
{
    for (auto edge : edges)
    {
        if (edge.size() % 2 == 1)
            return false;
    }
    for (auto edge : edges)
    {
        if (edge.size() >= 6)
            return true;
    }
    int count=0;
    for (auto edge : edges)
    {
        if (edge.size() == 4){
            count++;
        }
    }
    if(count>=3)return true;
    return nokori(N,M,edges);
}
int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> edges(N);
    for (int i = 0; i < M; i++)
    {
        int a, b;
        cin >> a >> b;
        edges[a - 1].push_back(b - 1);
        edges[b - 1].push_back(a - 1);
    }
    cout<<(solve(N,M,edges)?"Yes":"No")<<endl;
}
