}

void dfs(int u)
{
    vis[u]=1;
    for(int t=h[u];~t;t=e[t].next)
    {
        if(e[t].del) continue;
        int v=e[t].v;
        if(vis[v]) continue;
        pre[v]=t;dfs(v);
    }
}

