  bool check(int s, int v) {
    int now = s;
    vector<int> res;
    vector<int> target = {s, s, v, v};
    while (1) {
      if (now == s || now == v) {
        res.push_back(now);
      }
      bool found = false;
      for (auto e : t[now]) {
        if (e.second == 0) {
          t[now][e.first]= 1;
          t[e.first][now] = 1;
          now = e.first;
          found = true;
          break;
        }
      }
      if (!found) break;
    }
    res.erase(res[0]);
    for (int i = 0; i < 4; ++i) {
      rotate(res.begin(), res.begin() + 1, res.end());
      if (res == target) return true;
    }
    return false;
  }
};
