vector<int> euler;
void dfs(int a) {
	while(not G[a].empty()) {
		int v, i;
		tie(v, i) = G[a].back();
		G[a].pop_back();
		if(used[i]) continue;
		used[i] = true;
		dfs(v);
		euler.push_back(a);
	}
}


