const long long MOD = 1000000007;
const long long HIGHINF = (long long)1e18;
const int INF = (int)1e9;

const ll MAX_V = 100000;
struct edge {long long to, cap, rev; };  // 行き先、容量、逆辺

vector<edge> G[MAX_V];  // 隣接リスト
bool used[MAX_V];  // すでに訪問済みかのフラグ

// fromからtoへの容量capの辺をグラフに追加する
void add_edge(long long from, long long to, long long cap) {
    G[from].push_back((edge){to, cap, (ll)G[to].size()});
    G[to].push_back((edge){from, 0, (ll)(G[from].size()-1)});
}

// DFSで増加パスを探索
long long dfs(long long v, long long t, long long f) {
    if (v == t) return f;
    used[v] = true;
    for (int i=0; i<G[v].size(); i++) {
        edge &e = G[v][i];
        if (!used[e.to] && e.cap > 0) {
            long long d = dfs(e.to, t, min(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                G[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

// sからtへの最大流を求める
long long max_flow(long long s, long long t) {
    long long flow = 0;
    for (;;) {
        REP(i, MAX_V) used[i] = false;
        long long f = dfs(s, t, HIGHINF);
        if (f == 0) return flow;
        flow += f;
    }
}

