bool work(int x)
{
	if (bo[x])
	{
		int X=x;
		del(e[rev(la[x])].to,la[x]);
		del(x,rev(la[x])),x=e[rev(la[x])].to;
		while (x!=X) 
		{
			del(e[rev(la[x])].to,la[x]);
			del(x,rev(la[x])),x=e[rev(la[x])].to;
		}
		return 1;
	}
	bo[x]=1;
	for (int i=hd[x]; i; i=e[i].next)
		if (i!=rev(la[x])) 
		{
			la[e[i].to]=i;
			if (work(e[i].to)) return 1;
		}
	return 0;
