bool dfs(int x, int want, int ban) {
	u[x] = 1;
	for (int y : e[x]) {
		if (y == ban) continue;
		if (u[y]) continue;
		if (y == want) return true;
		if (dfs(y, want, ban)) return true;
	}
	return false;
}

void solve () {
	int cnt4 = 0;
	int cnt6 = 0;
	fi(0, n - 1) {
		if (deg[i] % 2 == 1) {
			printf("No\n");
			return;
		}
		if (deg[i] >= 4) cnt4++;
		if (deg[i] >= 6) cnt6++;
	}
	if (cnt4 >= 3 || cnt6 >= 1) {
		printf("Yes\n");
		return;
	}
	if (cnt4 == 2) {
		int x = -1;
		int y = -1;
		fi(0, n - 1) {
			if (deg[i] == 4) {
				x = i;
			}
			if (x > y) swap(x, y);
		}		
		memset(u, 0, sizeof(u));
		if (dfs(x, x, y)) {
			printf("Yes\n");
			return;
		} 
		if (dfs(y, y, x)) {
			printf("Yes\n");
			return;
		} 
	}
	printf("No\n");
}

