namespace dinic {
  const int maxn = 1e5, maxm = 1e6;
  typedef int FlowType;
  const FlowType inf_f = ~0U >> 1;

  void Init(int n);
  void AddEdge(int u, int v, FlowType cap);
  FlowType Solve(int s, int t);
  vector< pair<pii, FlowType> > Result(void);
}

namespace dinic {
  struct Edge {
    int v;
    FlowType cap, cap0;
  } edge[maxm << 1];

  int n, m, s, t;
  vector<int> g[maxn];

  void Init(int _n) {
    n = _n, m = 0;
    for (int i = 0; i < n; ++i) g[i].clear();
  }

  void AddEdge(int u, int v, FlowType c) {
    g[u].push_back(m);
    edge[m++] = (Edge){v, c, c};
    g[v].push_back(m);
    edge[m++] = (Edge){u, 0, 0};
  }

  int iter[maxn], dist[maxn];

  bool Bfs(void) {
    queue<int> que;
    que.push(s);
    FILL(dist, n, -1);
    dist[s] = 0;
    while (!que.empty()) {
      int u = que.front(); que.pop();
      for (int i = 0; i < g[u].size(); ++i) {
        Edge &e = edge[g[u][i]];
        if (e.cap && dist[e.v] == -1) {
          dist[e.v] = dist[u] + 1;
          que.push(e.v);
        }
      }
    }
    return dist[t] >= 0;
  }

  FlowType Dfs(int u, FlowType f) {
    if (u == t) return f;
    FlowType sum = 0;
    for (int &i = iter[u]; i < g[u].size(); ++i) {
      Edge &e = edge[g[u][i]], &rev = edge[g[u][i] ^ 1];
      if (e.cap && dist[e.v] == dist[u] + 1) {
        FlowType res = Dfs(e.v, min(f - sum, e.cap));
        e.cap -= res;
        rev.cap += res;
        if ((sum += res) == f) break;
      }
    }
    return sum;
  }

  FlowType Solve(int _s, int _t) {
    s = _s, t = _t;
    FlowType ans = 0;
    while (Bfs()) {
      FILL(iter, n, 0);
      ans += Dfs(s, inf_f);
    }
    return ans;
  }

  vector< pair<pii, FlowType> > Result(void) {
    vector< pair<pii, FlowType> > ans;
    for (int u = 0; u < n; ++u) {
      for (int i = 0; i < g[u].size(); ++i) {
        Edge &e = edge[g[u][i]];
        if (e.cap < e.cap0) {
          ans.push_back(make_pair(pii(u, e.v), e.cap0 - e.cap));
        }
      }
    }
    return ans;
  }
}

