    cout<<"No"<<endl;
    return 0;
  }

  for(int i=0;i<=max(n,m);i++) {
    used2[i]=false;
    used3[i]=used[i];
  }
  for(int i=1;i<=m;i++){
    if(!used3[i]){
      if(!dfs2(qr[i].first,qr[i].first,false)){
        cout<<"No"<<endl;
        return 0;
      }
      break;
    }
    if(i==m){
      cout<<"No"<<endl;
      return 0;
    }
  }

  for(int i=1;i<=m;i++){
    used[i]=used[i]|used3[i];
    used3[i]=false;
  }

  for(int i=1;i<=m;i++){
    if(!used[i]){
      cnt[qr[i].first]++;
      cnt[qr[i].second]++;
