void addedge(int u,int v){
	edge[++tote].to=v;
	edge[tote].next=head[u];
	head[u]=tote;
	return;
}
void dfs(int x,int last,int lim,int tar,int flag){
	if(x==tar&&flag==1){
		Flag=1;
		return ;
	}
	for(int i=head[x];i;i=edge[i].next){
		int v=edge[i].to;
		if(v==last) continue;
		if(v==lim) continue;
		dfs(v,x,lim,tar,1);
		if(Flag==1) return ;
	}
	return ;
}
