void dfs(int x)
{
	dep[x] = dep[fa[x]] + 1, wson[x] = 0, sz[x] = 1;
	for (int cur : linker[x])
	{
		if (!dep[cur])
		{
			son[x].push_back(cur);
			fa[cur] = x; dfs(cur);
			sz[x] += sz[cur];
			if (sz[cur] > sz[wson[x]])
				wson[x] = cur;
		}
	}
}
void dfs2(int x, int chain)
{
	top[x] = chain, dfn[x] = ++ ind, seq[ind] = x;
	if (wson[x])
	{
		dfs2(wson[x], chain);
		for (int cur : son[x])
			if (cur != wson[x]) dfs2(cur, cur);
	}
}
void modify(int x, int y)
{
	while (top[x] != top[y])
	{
		if (dep[top[x]] < dep[top[y]]) swap(x, y);
		add(dfn[top[x]], dfn[x]); x = fa[top[x]];
	}
	if (dep[x] > dep[y]) swap(x, y);
	add(dfn[x], dfn[y]);
}
inline bool cmp(const int &a, const int &b) {return dfn[a] < dfn[b];}
void dfs3(int x)
{
	for (int cur : linker[x])
	{
		if (dep[cur] > dep[x] && fa[cur] != x)
		{
			int which = upper_bound(son[x].begin(), son[x].end(), dfn[x], cmp) - son[x].begin() - 1;
			int ws = son[x][which];
			modify(ws, cur);
		}
	}
	for (int cur : son[x])
		dfs3(cur);
}
