void yes() {
  print("Yes");
  exit(0);
}

void no() {
  print("No");
  exit(0);
}

int main() {
  int n, m;
  scan(n, m);
  vi a(m), b(m);
  vi cnt(n, 0);
  rep (i, m) {
    scan(a[i], b[i]);
    --a[i]; --b[i];
    ++cnt[a[i]];
    ++cnt[b[i]];
  }
  if (m < n+2) {
    no();
  }
  rep (i, n) {
    if (cnt[i] % 2 != 0) {
      no();
    }
  }
  vector<set<int> > g(n);
  rep (i, m) {
    g[a[i]].insert(b[i]);
    g[b[i]].insert(a[i]);
  }
  int loop = 0;
  while (true) {
    int start = -1;
    rep (i, n) {
      if (cnt[i] > 0) {
        start = i;
        break;
      }
    }
    if (start == -1) { break; }
    vi pathv = {start};
    set<int> paths = {start};
    int prev = -1;
    debug(start);
    while (!pathv.empty()) {
      debug(loop);
      int u = pathv.back();
      for (int v : g[u]) {
        debug(pathv);
        debug3(prev, u, v);
        if (v == prev) { continue; }
        g[u].erase(v);
        g[v].erase(u);
        if (paths.find(v) != end(paths)) {
          loop += 1;
          if (loop == 3) {
            yes();
          }
          int sz = pathv.size();
          for (int i = sz-1; i >= 0; --i) {
            cnt[pathv[i]] -= 2;
            paths.erase(pathv[i]);
            if (pathv[i] == v) {
              break;
            }
          }
          for (int i = sz-1; i >= 0; --i) {
            if (pathv[i] == v) {
              int add = i;
              if (cnt[v] > 0) {
                ++add;
              }
              pathv.erase(begin(pathv) + add, end(pathv));
              break;
            }
          }
          sz = pathv.size();
          if (sz == 1) {
            prev = -1;
          } else if (sz > 1) {
            prev = pathv[sz-2];
          }
        } else {
          pathv.push_back(v);
          paths.insert(v);
          prev = u;
        }
        break;
      }
    }
  }
  no();

  return 0;
}

