bool solve(int n, int m) {
  vector<vector<int>> g(n);
  for (int i = 0; i < m; i++) {
    int a, b;
    scanf("%d%d", &a, &b);
    --a, --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  for (int i = 0; i < n; i++) {
    if (g[i].size() % 2) {
      return false;
    }
  }
  vector<int> big;
  for (int i = 0; i < n; i++) {
    if (g[i].size() >= 6) {
      return true;
    }
    if (g[i].size() == 4) {
      big.push_back(i);
    }
  }
  if (big.size() <= 1) return false;

  for (int i = 0; i < n; i++) {
    if (g[i].size() == 2) {
      int a = g[i][0];
      int b = g[i][1];
      *find(g[a].begin(), g[a].end(), i) = b;
      *find(g[a].begin(), g[a].end(), i) = a;
    }
  }

  for (int v : big) {
    if (find(g[v].begin(), g[v].end(), v) != g[v].end()) {
      return true;
    }
    if (big.size() > 2) {
      sort(g[v].begin(), g[v].end());
      if (unique(g[v].begin(), g[v].end()) != g[v].end()) {
        return true;
      }
    }
  }

  if (big.size() == 2) {
    return false;
  }

  vector<int> d(n, -1);
  vector<int> p(n, -1);
  queue<int> q;
  d[big[0]] = 0;
  q.push(big[0]);

  while (!q.empty()) {
    int v = q.front();
    q.pop();
    for (int to : g[v]) {
      if (d[to] == -1) {
        d[to] = d[v] + 1;
        q.push(to);
      } else if (to != p[v] && d[to] + d[v] + 1 < (int)big.size()) {
        return true;
      }
    }
  }

  return false;
}

