#include <bits/stdc++.h>
using namespace std;
const int N = 1e5+5;

int a[N],b[N];

vector<int> adj[N];

bool used[N];
bool vis[N];

int par[N];
bool dfs(int node,int last) {
   vis[node] = true;
   if(node==last) {
      return true;
   }
   for(int i=0;i<adj[node].size();++i) {
      int id = adj[node][i];
      int ch = a[id]^b[id]^node;
      if(used[id]) {
         continue;
      }
      if(vis[ch] ) {
         continue;
      }
      par[ch] = id;
      if(dfs(ch,last)){
         return true;
      }
   }
   return false;
}

void solve() {
   int n,m;
   scanf("%d%d",&n,&m);
   for(int i=0;i<m;++i) {
      scanf("%d%d",&a[i],&b[i]);
      adj[a[i]].push_back(i);
      adj[b[i]].push_back(i);
   }
   vector<int> four;
   int numberofSix = 0;
   for(int i=1;i<=n;++i) {
      if(adj[i].size()>=6) {
         ++numberofSix;
      } else if(adj[i].size()==4) {
         four.push_back(i);
      }
      if(adj[i].size()%2 != 0 ){
         printf("No\n");
         return;
      }
   }
   if(numberofSix || four.size()>=3) {
      printf("Yes\n");
      return;
   }

   if(four.size()==2) {
      bool lastVis = false;
      for(int i=0;i<3;++i) {
         memset(vis,0,sizeof(vis));
         int st = four[0], ed = four[1];
         lastVis = dfs(st,ed);
         while(ed!=st) {
            int id = par[ed];
            used[id] = true;
            int nn = a[id]^b[id]^ed;
            ed = nn;
         }
      }
      if(lastVis) {
         printf("No\n");
      } else {
         printf("Yes\n");
      }
   } else {
      printf("No\n");
   }
}
int main()
{
    //freopen("input.txt","r",stdin);
    solve();
}

