		std::cout << "No\n";
		return 0;
	} else {
		Max = std::max(Max, deg[i]);
		if (deg[i] == 4) { ++Cnt; if (A) B = i; else A = i; }
	}
	if (Max < 4) { std::cout << "No\n"; return 0; }
	if (Max > 4 || Cnt > 2) { std::cout << "Yes\n"; return 0; }
	dfs(A);
	return 0;
}

