typedef vector<int> vi;

int dfs(int u, int dest, const vector<vi> &adj, vector<bool> &vis)
{
	if(u == dest)
		return 1;
	vis[u] = true;
	int ret = 0;
	for(auto v: adj[u])
	{
		if(!vis[v])
			ret += dfs(v,dest,adj,vis);
	}
	return ret;
}

