int main() {
    int N, M;
    cin >> N >> M;
    vector<int> order(N, 0);
    vector<vector<int>> edge(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        order[a-1]++;
        order[b-1]++;
        edge[a-1].push_back(b-1);
        edge[b-1].push_back(a-1);
    }
    for (int i = 0; i < N; i++) {
        if (order[i] % 2 == 1) {
            cout << "No\n";
            return 0;
        }
    }
    vector<int> st;
    for (int i = 0; i < N; i++) {
        if (order[i] >= 6) {
            cout << "Yes\n";
            return 0;
        }
        if (order[i] == 4) {
            st.push_back(i);
        }
    }
    if ((int)st.size() >= 3) {
        cout << "Yes\n";
        return 0;
    }
    if ((int)st.size() <= 1) {
        cout << "No\n";
        return 0;
    }

    int start = st[0];
    int goal = st[1];
    queue<pair<int, int>> q;
    q.push({start, -1});
    int path = 0;
    while (!q.empty()) {
        int now = q.front().first;
        int par = q.front().second;
        q.pop();
        for (int nxt : edge[now]) {
            if (nxt == par) continue;
            if (nxt == start) continue;
            if (nxt == goal) {
                path++;
                continue;
            }
            q.push({nxt, now});
        }
    }
    if (path <= 2) {
        cout << "Yes\n";
    }else {
        cout << "No\n";
    }
    return 0;
}

