  // adj[a].emplace_back(ab);
  // adj[b].emplace_back(ba);
  // }
};

void eulerian_walk(l a, stack<Edge> &s, vb &visited, Graph &g) {
  for (auto e : g.adj[a]) {
    if (visited[e.id]) continue;
    visited[e.id] = true;
    eulerian_walk(e.to, s, visited, g);
    s.emplace(e);
  }
}

void solve(istream &in, ostream &out) {
  l n, m;
  in >> n >> m;
  Graph g(n);
  F(i, 0, m) {
    l a, b;
    in >> a >> b;
    a--;
    b--;
    g.add_undirected(a, b);
  }
  vb visited(g.e);
  stack<Edge> s;
  vl c(n);
  eulerian_walk(0, s, visited, g);
  F(i, 0, g.e) if (not visited[i]) {
    out << "No" << lf;
    return;
  }
  stack<l> in_path;
  l cycles = 0;
  c[0] = 1;
  in_path.emplace(0);
  while (not s.empty()) {
    Edge e = s.top(); s.pop();
    l a = e.to;
    // L(e.from, e.to);
    if (c[a]) {
      // L("cycle");
      cycles++;
      while (not in_path.empty()) {
        l x = in_path.top();
        in_path.pop();
        c[x]--;
        if (x == a) break;
      }
    }
    c[a]++;
  }
  // L(cycles);
  if (cycles >= 3) {
    out << "Yes" << lf;
  } else {
    out << "No" << lf;
  }
}

