int main(void)
{
	int N, M;	// N頂点M本
	int a, b;
	int count = 0;

	scanf("%d %d", N, M);

	// 入力された辺の情報をvectorに保存する
	// 保存の仕方は、頂点aに接続されている頂点の一覧を、sides[a]で参照できる
	vector<vector<int>> sides(N+1);

	for (int i = 0; i < M; i++) {
		scanf("%d %d", &a, &b);
		sides[a].push_back(b);
	}

	// オイラーグラフでなければ成り立たない。オイラーグラフの必要十分条件は、全ての点の次数が偶数であることである。
	for (int i = 1; i < sides.size(); i++) {
		if (sides[i].size() % 2 == 1) {
			printf("No\n");
			return 0;
		}
	}

	// 次数が6以上の辺があれば、3つのサーキットを作れる
	for (int i = 1; i < sides.size(); i++) {
		if (sides[i].size() >= 6) {
			printf("Yes\n");
			return 0;
		}
	}

	// 次数が4以上の辺が3つあれば、3つのサーキットを作れる
	count = 0;
	for (int i = 1; i < sides.size(); i++) {
		if (sides[i].size() >= 4) {
			count++;
		}
	}
	if (count >= 3) {
		printf("Yes\n");
		return 0;
	}

	printf("No\n");
	return 0;
}

