void dfs(int now, int last, int len){
	// cout << "path ";
	// for(int i = 0;i < len;++i){
	// 	cout << path[i] << ' ' ;
	// }

    // cout << '\n' << now << ' ' << last << '\n';
	if(cir.size() > 2)return;
	for(int i = 0;i < v[now].size();++i){
