const int maxN = 100000 + 233;
int n, m, deg[maxN];
set<int> G[maxN];

void initialize() {
	std::ios::sync_with_stdio(false);
	cin >> n >> m;
	for(int i = 1; i <= m; ++i) {
		int x, y; cin >> x >> y;
		G[x].insert(y); G[y].insert(x);
		deg[x]++; deg[y]++;
	}
}

bool vis[maxN];
int x = -1, y = -1;
bool DFS(int u, int d) {
	vis[u] = true;
	if(u == x && d > 0) return true;
	while(G[u].size()) {
		int v = *G[u].begin();
		G[u].erase(v); G[v].erase(u);
		if(DFS(v, d + 1)) return true;
	}
	return false;
}

bool solve() {
	for(int u = 1; u <= n; ++u) if(deg[u] % 2 == 1) return false;
	vector<int> d(deg + 1, deg + n + 1);
	std::sort(d.begin(), d.end()); std::reverse(d.begin(), d.end());
	while(d.size() && d.back() == 2) d.pop_back();
	if(d.size() == 0) return false;
	if(d[0] >= 6) return true;
	if(d.size() == 1) return false;
	if(d.size() >= 3) return true;
	for(int u = 1; u <= n; ++u) if(deg[u] == 4) {
		if(x == -1) x = u; else y = u;
	}
	int cnt = 0;
	memset(vis, 0, sizeof(vis));
	DFS(x, 0);
	cnt += vis[y];
	memset(vis, 0, sizeof(vis));
	DFS(x, 0);
	cnt += vis[y];
	return cnt == 1;
}

int main() {
	initialize();
	if(solve()) cout << "Yes" << endl;
	else cout << "No" << endl;
	return 0;
}

