const int MAXN=100005;
struct edge{int x,y,next;}a[2*MAXN];int len,last[MAXN];
void ins(int x,int y){len++;a[len].x=x;a[len].y=y;a[len].next=last[x];last[x]=len;}
int du[MAXN],dep[MAXN],mn[MAXN],n,m;
bool vis[MAXN];
int fa[25][MAXN],bin[25];
void dfs(int x)
{
	vis[x]=1;mn[x]=(1<<31-1);
	for(int i=1;bin[i]<=dep[x];i++)fa[i][x]=fa[i-1][fa[i-1][x]];
	for(int k=last[x];k;k=a[k].next)
	{
		int y=a[k].y;
		if(!vis[y])
		{
			fa[0][y]=x;
			dep[y]=dep[x]+1,dfs(y);
			mn[x]=min(mn[x],mn[y]);
		}
		else mn[x]=min(mn[x],dep[y]);
	}
}
int jump(int x,int u)
{
	for(int i=20;i>=0;i--)if(bin[i]<=u)x=fa[i][x],u-=bin[i];
	return x;
}
int cal[MAXN],ln;
int vi[MAXN],tim,sum[MAXN];
int check(int x)
{
	ln=(x!=1);cal[1]=0;tim++;
	for(int k=last[x];k;k=a[k].next)
	{
		int y=a[k].y;
		if(dep[y]<dep[x])cal[1]++;
		else 
		{
			int u=jump(y,dep[y]-dep[x]-1);
			if(vi[u]!=tim)vi[u]=tim,sum[u]=0;
			sum[u]++;
		}
	}
	for(int k=last[x];k;k=a[k].next)if(dep[a[k].y]==dep[x]+1)
	{
		if(mn[a[k].y]>dep[x])cal[1]+=sum[a[k].y];
		else cal[++ln]=sum[a[k].y];
	}
	int ct=0;
	for(int i=1;i<=ln;i++)ct+=(cal[i]&1);
	if(ct&1)return false;
	return ln-ct+ct/2-1;
