#include <bits/stdc++.h>
#define maxn 100010

using namespace std;

int n, m;
int maxd, cnt;
int A, B;
vector<int> G[maxn];
int st[maxn];

void dfs(int u)
{
	st[u] = 1;
	for (int i = 0; i < G[u].size(); i ++ )
	{
		int j = G[u][i];
		if (st[j] == 2) A ? B = u : A = u;
		else if (!st[j]) dfs(j);
	}
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= m; i ++ )
	{
		int u, v;
		scanf("%d%d", &u, &v);
		G[u].push_back(v), G[v].push_back(u);
	}

	for (int i = 1; i <= n; i ++ )
		if (G[i].size() % 2) { puts("No"); return 0; }
		else
		{
			if (G[i].size() > maxd) maxd = G[i].size(), cnt = 1;
			else if (G[i].size() == maxd) cnt ++ ;
		}

	if (maxd >= 6) { puts("Yes"); return 0; }
	else if (maxd == 2 || cnt == 1) { puts("No"); return 0; }
	else if (cnt >= 3) { puts("Yes"); return 0; }
	else
	{
		int cnt = 0;
		for (int i = 1; i <= n; i ++ )	
			if (G[i].size() == 4) st[i] = 2;
		for (int i = 1; i <= n; i ++ )
			if (!st[i])
			{
				A = B = 0;
				dfs(i);
				cnt += (A == B);
			}

		if (cnt) puts("Yes");
		else puts("No");
	}

	return 0;
}

