set<int> cur;

set<int> g[100005];

const int OK = 2000000;
const int NG = -1;

int dfs(int v, int from = -1){
  cur.insert(v);

  for(auto to : g[v]) if(to != from){
    int r = -1;
    if(cur.count(to) == 1) {
      r = to;
    }
    else {
      r = dfs(to, v);
    }
    if(r == OK){ return OK; }
    if(r > -1){
      g[v].erase(to);
      g[to].erase(v);
      if(r == v) return OK;
      else return r;
    }
    if(r == NG) return NG;
  }
  return NG;
}

bool solve(){
  int n,m;
  cin>>n>>m;
  rep(i,m){
    int a,b;
    cin>>a>>b;
    a--;b--;
    g[a].insert(b);
    g[b].insert(a);
  }

  int cnt = 0;
  rep(i,n){
    while(g[i].size() > 0) {
      cur.clear();
      int r = dfs(i);
      if(r == OK) cnt++;
      else {
        assert(r == NG);
        return false;
      }
    }
  }

  return cnt >= 3;
}

int main(){
  cout << (solve() ? "Yes" : "No") << endl;
  return 0;
}

