int main(){
  int N, M;
  cin >> N >> M;
  vector<vector<int>> E(N);
  for (int i = 0; i < M; i++){
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    E[a].push_back(b);
    E[b].push_back(a);
  }
  vector<int> deg(N);
  for (int i = 0; i < N; i++){
    deg[i] = E[i].size();
  }
  sort(deg.begin(), deg.end());
  reverse(deg.begin(), deg.end());
  bool ok = true;
  for (int i = 0; i < N; i++){
    if (deg[i] % 2 == 1){
      ok = false;
    }
  }
  if (!ok){
    cout << "No" << endl;
  } else {
    if (deg[0] == 2){
      cout << "No" << endl;
    } else if (deg[0] >= 6){
      cout << "Yes" << endl;
    } else if (deg[0] == 4){
      if (deg[1] == 2){
        cout << "No" << endl;
      } else {
        assert(false);
        int s = -1;
        for (int i = 0; i < N; i++){
          if (E[i].size() == 4){
            s = i;
          }
        }
        vector<bool> used(N, false);
        int t = 0;
        if (s == t){
          t++;
        }
        used[t] = 0;
        queue<int> Q;
        Q.push(t);
        while (!Q.empty()){
          int v = Q.front();
          Q.pop();
          for (int w : E[v]){
            if (w != s && !used[w]){
              used[w] = true;
              Q.push(w);
            }
          }
        }
        ok = false;
        for (int i = 0; i < N; i++){
          if (!used[i] && i != s){
            ok = true;
          }
        }
        if (ok){
          cout << "Yes" << endl;
        } else {
          cout << "No" << endl;
        }
      }
    }
  }
}

