using namespace std;
using ll = int64_t;

int search(const vector<vector<int>>& g, int i, int j) {
  if (g[j].size() > 2) return j;
  for (int k : g[j]) {
    if (k != i) return search(g, j, k);
  }
  return -1;
}

int main() {
  int n,m;
  cin>>n>>m;
  vector<vector<int>> g(n);
  REP(i,m) {
    int a,b;
    cin>>a>>b;
    --a;--b;
    g[a].push_back(b);
    g[b].push_back(a);
  }
  bool ok = true;
  int k = 0;
  vector<int> idx(n, -1);
  REP(i,n) {
    if (g[i].size() % 2) ok = false;
    if (g[i].size() >= 4) {
      idx[i] = k;
      ++k;
    }
  }
  if (!ok) {
    cout << "No" << endl;
    return 0;
  }
  int cnt = 0;
  vector<vector<int>> h(k);
  ok = false;
  REP(i,n) {
    if (g[i].size() < 4) continue;
    if (g[i].size() >= 6) ok = true;
    for (int j : g[i]) {
      int nx = search(g, i, j);
      if (nx == i) {
        ++cnt;
      } else {
        h[idx[i]].push_back(idx[nx]);
      }
    }
  }
  if (cnt >= 6 || ok) {
    cout << "Yes" << endl;
    return 0;
  } else if (cnt >= 4) {
    if (k >= 2) {
      cout << "Yes" << endl;
      return 0;
    }
  } else if (cnt >= 2) {
    if (k >= 2) {
      cout << "Yes" << endl;
      return 0;
    }
  }
  if (k >= 3) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
  return 0;
}

