int N,M;
vector<int> g[100010];

int countCycles(){
    vector<int> deg(N,0);
    rep(i,N) deg[i]=g[i].size();

    int res=0;
    map<pair<int,int>,int> mp;
    vector<int> used(N,0);
    vector<int> pos(N,0);
    for(int i=0;i<N;i++){
        if(deg[i]==0) continue;

        stack<int> st;
        st.push(i);
        used[i]=1;
        while(1){
            int now=st.top();
            int nex=-1;
            for(;pos[now]<g[now].size();pos[now]++){
                int tar=g[now][pos[now]];
                if(mp.count(mkp(now,tar))) continue;

                nex=tar;
                pos[now]++;
                break;
            }

            if(nex==-1) break;
            if(used[nex]){
                deg[now]--;deg[nex]--;
                mp[mkp(now,nex)]=1;mp[mkp(nex,now)]=1;
                while(st.top()!=nex){
                    int tmp=st.top();
                    st.pop();
                    used[tmp]=0;
                }
                res++;
                continue;
            }else{
                st.push(nex);
                deg[now]--;deg[nex]--;
                used[nex]=1;
                mp[mkp(now,nex)]=1;mp[mkp(nex,now)]=1;
            }
        }
        used[i]=0;
    }
    return res;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin>>N>>M;
  rep(i,M){
      int a,b;
      cin>>a>>b;
      a--;b--;
      g[a].push_back(b);
      g[b].push_back(a);
  }

  rep(i,N){
      if(g[i].size()%2){
          cout<<"No"<<endl;
          return 0;
      }
  }

  int cycles=countCycles();
  if(cycles>=3) cout<<"Yes"<<endl;
  else cout<<"No"<<endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxn = 1e5;
int n, m, deg[maxn + 10], ans, cnt;
struct edge {
	int to, id;
};
vector<edge> g[maxn + 10];
bool vis[maxn + 10];
int cur[maxn + 10];
bool ban[maxn + 10];

int dfs(int p, int fae) {
	vis[p] = 1;	
	for (int &i = cur[p]; i < (int)g[p].size(); ++i) {
		edge e = g[p][i];
		if (e.id != fae && !ban[e.id]) {
			if (vis[e.to]) {
				ban[e.id] = 1; ban[fae] = 1;
				vis[p] = 0; ++i; return e.to;
			} else {
				int w = dfs(e.to, e.id);
				if (w == p) ++ans;
				else {
					vis[p] = 0; ban[fae] = 1; ++i;
					return w;
				}
			}
		}
	}
	assert(!fae);
	vis[p] = 0;
	return 0;
}

int main() {
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= m; ++i) {
		int l, r; scanf("%d%d", &l, &r);
		++deg[l]; ++deg[r];
		g[l].push_back((edge){r, i}); g[r].push_back((edge){l, i});
	}
	for (int i = 1; i <= n; ++i)
		if (deg[i] & 1) {
			printf("No"); return 0;
		}
	for (int i = 1; i <= n; ++i)
		if (deg[i] >= 6) {
			printf("Yes"); return 0;
		} else if (deg[i] == 4) ++cnt;
	if (cnt != 2) {
		printf("%s", cnt >= 3 ? "Yes" : "No");
		return 0;
	}
	for (int i = 1; i <= n; ++i) dfs(i, 0);
	printf("%s", ans >= 3 ? "Yes" : "No");
}

