void dfs(int x, int pa, int s, int t, bool &succ) {
    bool met_pa = false;
    for (int i : edge[x]) {
        if (i == t) continue;
        if (i == pa) {
            if (!met_pa) {
                met_pa = true;
                continue;
            }
        }
        if (i == x) {
            succ = true;
            continue;
        }
        dfs(i, x, s, t, succ);
    }
}

