int main(void)
{
  int n, m;
  cin >> n >> m;
  vec<vec<int>> mp(n, vec<int>(0));
  rep(i, m) {
    int a, b;
    cin >> a >> b;
    a--; b--;
    mp[a].pb(b);
    mp[b].pb(a);
  }

  int flag = 1;
  rep(i, n) if (mp[i].size() % 2) flag = 0;
  if (!flag) {
    cout << "No" << endl;
    return 0;
  }

  //次数が６以上->三分割
  //次数４が３以上->２回踏む閉路があればOK、なければ次数４の３点が分離して2つの閉路に入ってるので各２点間の異なるパスが2つ取れて組み合わせれば閉路完成
  //次数４が２個->２回踏む閉路があればOK、なければダメ
  //次数４が１個以下->muri

  int if6 = 0;
  vec<int> count4(0);
  rep(i, n) {
    if (mp[i].size() >= 6) if6 = 1;
    if (mp[i].size() == 4) count4.pb(i);
  }
  if (if6) cout << "Yes" << endl;
  else if (count4.size() > 2) cout << "Yes" << endl;
  else if (count4.size() < 2) cout << "No" << endl;
  else {
    //次数４の点を片方抜いて閉路ができるか問題
    int start = count4[0];
    int del = count4[1];
    int flag = 0;
    rep(i, mp[start].size()) {
      vec<int> dp(n, 0);
      dp[start] = 1;
      int cur = mp[start][i];
      if (cur == del) continue;
      dp[cur] = 2;
      while(1) {
        int f = 0;
        rep(j, mp[cur].size()) {
          if (mp[cur][j] == del) continue;
          if (mp[cur][j] == start && dp[cur] != 2) {
            flag = 1;
            break;
          }
          if (dp[mp[cur][j]]) continue;
          cur = mp[cur][j];
          dp[cur] = 1;
          f = 1;
        }
        if (flag) break;
        if (!f) break;
      }
    }
    if (flag) cout << "Yes" << endl;
    else cout << "No" << endl;
  }
  return 0;
}

