int n, m;
vector<int> et[100000];
vector<int> rev[100000];
vector<bool> used[100000];
int cnt[100000];

bool make_cycle() {
	static int t[100000];
	int i, j;
	int INF = 11451419;

	for (i = 0; i < n; i++) t[i] = INF;

	int limit = 10000000;
	while (limit > 0) {
		i = xor128() % n;
		if (cnt[i] > 0) break;
		limit--;
	}
	if (limit == 0) return false;
	//cout << "start = " << i << endl;

	int prev = -1;
	int pos = i;
	int nowT = 0;
	vector<int> poses;
	vector<int> ids;
	while (t[pos] == INF) {
		//cout << "pos = " << pos << endl;
		t[pos] = nowT;
		poses.push_back(pos);
		for (j = 0; j < et[pos].size(); j++) {
			if (used[pos][j]) continue;
			if (et[pos][j] == prev) continue;
			break;
		}
		if (j == et[pos].size()) { /*cout << "False" << endl;*/ return false; }
		int nxt = et[pos][j];
		//cout << "nxt = " << nxt << endl;
		prev = pos;
		//cout << "prev = " << pos << endl;
		pos = nxt;
		ids.push_back(j);
		nowT++;
	}
	//cout << "last pos = " << pos << endl;
	poses.push_back(pos);

	for (i = t[pos]; i < poses.size() - 1; i++) {
		int u = poses[i];
		int v = poses[i + 1];
		//cout << "u, v = " << u << ", " << v << endl;
		used[u][ids[i]] = true;
		used[v][rev[u][ids[i]]] = true;
		cnt[u]--;
		cnt[v]--;
	}

	//for (i = 0; i < n; i++) cout << cnt[i] << endl;
	return true;
}

