bool checkTurn(LL v, LL v2, LL v3, vector<vector<LL>>& edge, vector<LL>& memo, LL depth=0){
    if(memo[v]) return false;
    memo[v] = 1;
    for(LL u: edge[v]){
        if(u == v2) continue;
        if(depth > 1 && u == v3) return true;
        if(checkTurn(u, v2, v3, edge, memo, depth+1)) return true;
    }
    return false;
}

bool solve(LL n, LL m, vector<vector<LL>>& edge){
    vector<LL> memo(n), memo2(n);
    LL min_v = 0;
    LL max_v = 0;
    for(LL i = 0; i < n; ++i){
        if(memo[i]) continue;
        vector<LL> v_set;
        searchCC(i, edge, memo, v_set);
        vector<LL> four_v;
        vector<LL> six_v;
        for(LL v: v_set){
            LL en = edge[v].size();
            //cerr << "en=" << en << endl;
            if(en % 2 == 1) return false;
            if(en == 4){
                four_v.push_back(v);
            }
            if(en >= 6){
                six_v.push_back(v);
            }
        }
        //cerr << "cnt=" << cnt << endl;
        min_v += 1;
        if(!six_v.empty()){
            max_v += 3;
        }else{
            if(four_v.size() <= 1){
                max_v += 2;
            }else if(four_v.size() == 2){
                //cerr << "debug!" << endl;
                if(checkTurn(four_v[0], four_v[1], four_v[0], edge, memo2)){
                    max_v += 3;
                }else{
                    max_v += 2;
                }
            }else{
                max_v += 3;
            }
        }
    }
    return (min_v <= 3) && (3 <= max_v);
}

int main(){
    LL n, m;
    cin >> n >> m;
    vector<vector<LL>> edge(n);
    for(LL i = 0; i < m; ++i){
        LL u, v;
        cin >> u >> v;
        --u; --v;
        edge[u].push_back(v);
        edge[v].push_back(u);
    }
    if(solve(n, m, edge)){
        cout << "Yes" << endl;
    }else{
        cout << "No" << endl;
    }
    return 0;
}

