// 20151026
// 二重点連結成分分解 + 間接点列挙
// 橋条件: low[ch] > ord[v]のとき，枝(v, ch)は橋
// 間接点条件: deg(v) >= 2(vが根), 子chが存在してlow[ch] >= ord[v](vが根以外)
// 無向単純グラフのみ
vector<vector<int> > dcc;
vector<int> aps;
int cmp[MAX_V];

static int root = 0;
static int ord[MAX_V];
static int low[MAX_V];  // minimum order of visitable node if we can use backedge once
static bool seen[MAX_V];
static int parent[MAX_V];

void DFSOfArticulationDecomposition(Graph &G, int v) {
    static int time = 0;
    seen[v] = true;
    ord[v] = low[v] = time++;
    bool already = false;
    int numOfChild = 0;
    for (int i = 0; i < (int)G[v].size(); ++i) {
        int ch = G[v][i];
        if (seen[ch]) {
            if (ch != parent[v]) low[v] = min(low[v], ord[ch]);
            continue;
        }
        parent[ch] = v;
        ++numOfChild;
        DFSOfArticulationDecomposition(G, ch);
        low[v] = min(low[v], low[ch]);

        if (v == root) {
            if (numOfChild >= 2)
                aps.push_back(v);
        }
        else {
            if (low[ch] >= ord[v] && !already) {
                aps.push_back(v);
                already = true;
            }
        }
    }
    //cout << v << ": " << ord[v] << ", " << low[v] << endl;
}

static vector<int> comp;
void PostDecomposition(Graph &G, int v, int tempCmp) {
    seen[v] = true;
    cmp[v] = tempCmp;
    for (int i = 0; i < (int)G[v].size(); ++i) {
        int to = G[v][i];
        if (seen[to]) continue;
        if (binary_search(aps.begin(), aps.end(), to)) continue;
        PostDecomposition(G, to, tempCmp);
    }
    comp.push_back(v);
}

void ArticulationDecomposition(Graph &G) {
    for (int i = 0; i < MAX_V; ++i) {
        seen[i] = false;
        parent[i] = -1;
    }
    dcc.clear();
    aps.clear();
    for (int v = 0; v < G.size(); ++v) {
        if (!seen[v]) {
            root = v;
            DFSOfArticulationDecomposition(G, v);
        }
    }
    sort(aps.begin(), aps.end());
    aps.erase(unique(aps.begin(), aps.end()), aps.end());

    for (int i = 0; i < MAX_V; ++i) {
        seen[i] = false;
        cmp[i] = -1;
    }
    int tempCmp = 0;
    for (int v = 0; v < G.size(); ++v) {
        if (seen[v]) continue;
        if (binary_search(aps.begin(), aps.end(), v)) continue;
        comp.clear();
        PostDecomposition(G, v, tempCmp);
        dcc.push_back(comp);
        ++tempCmp;
    }
}


