int dfs(int p, int fae) {
	vis[p] = 1;	
	for (int &i = cur[p]; i < (int)g[p].size(); ++i) {
		edge e = g[p][i];
		if (e.to != fae && !ban[e.id]) {
			if (vis[e.to]) {
				ban[e.id] = 1; ban[fae] = 1;
				vis[p] = 0; return e.to;
			} else {
				int w = dfs(e.to, e.id);
				if (w == p) ++ans;
				else {
					vis[p] = 0; ban[fae] = 1;
					return w;
				}
			}
		}
	}
	assert(!fae);
	vis[p] = 0;
	return 0;
}

