}

void solve() {
  inl(N, M);
  auto g = graph(N, M);
  ll rest = 0;
  each(x, g) {
    if (sz(x) & 1) die("No");
    rest += sz(x) - 2;
  }
  if (rest < 4) die("No");
  if (rest >= 6) die("Yes");

  int u = -1, v = -1;
  rep(i, N) if (sz(g[i]) == 4) {
    if (u == -1)
      u = i;
    else
      v = i;
  }
  if(u == -1) die("Yes");
  trc(u, v);

  int root = u;
  int fake = v;
  // u->v以外のルートがあればよい
  auto dfs = [&](auto rec, int cur, int par = -1) -> int {
    if (cur == fake) return false;
    each(dst, g[cur]) {
      if (dst == par) continue;
      if (dst == root) return true;
      if (rec(rec, dst, cur)) return true;
    }
    return false;
  };
  if (dfs(dfs, root)) die("Yes");
  out("No");
}

