const int MAX = 100100;

multiset<int> g[MAX];
multiset<int> GG[MAX];
VI A[MAX];

int L[MAX];
int F[MAX];

bool no()
{
	cout<<"No"<<endl;
	return 0;
}

bool yes()
{
	cout<<"Yes"<<endl;
	exit(0);
	return true;
}

int n;

bool try_once()
{
	FOR (i, 0, n)
	{
		g[i] = GG[i];
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i]) & 1) return no();
	}

	stack<int> st;
	VI a;

	st.push(0);

	while(SZ(st))
	{
		int x = st.top();
		if (SZ(g[x]) == 0)
		{
			a.PB(x);
			st.pop();
			continue;
		}

		int y;
		{
			int aa = rand() % SZ(A[x]);
			int val = A[x][aa];

			set<int>::iterator it = g[x].lower_bound(val);
			if (it == g[x].end()) it--;
			y = *it;
		}



		g[x].erase(g[x].find(y));
		g[y].erase(g[y].find(x));

		st.push(y);
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i])) throw -1;
	}

	a.pop_back();

//	FOR (i, 0, SZ(a))
//	{
//		cout<<a[i]<<' ';
//	}
//	cout<<endl;

	FOR (i, 0, n)
	{
		L[i] = -1;
	}

	int last = -1;
	int first = INF;

	FOR (i, 0, SZ(a))
	{
		int x = a[i];
		if (L[x] == -1)
		{
			L[x] = i;
			F[x] = i;
			continue;
		}

//		cout<<i<<": "<<x<<' '<<F[x]<<' '<<L[x]<<' '<<first<<' '<<last<<endl;

		if (F[x] <= last) return yes();
		if (L[x] >= first) return yes();

		last = max(last, L[x]);
		first = min(first, i);
		L[x] = i;
	}

	return no();
}

