const int MAX_N=1e6+1;
VI G[MAX_N];
int N,M;

int viz[MAX_N];
void dfs(int u) {
  if(viz[u]) return;
  viz[u]=true;
  FORR(v,G[u]) dfs(v);
}

void nope() {
  println("No");
  exit(0);
}
void yup() {
  println("Yes");
  exit(0);
}
void solve() {
  dfs(0);
  REP(i,N) if(!viz[i]) nope();
  REP(i,N) if(SZ(G[i])%2==1) nope();
  REP(i,N) if(SZ(G[i])>=6) yup();
  int cnt=0;
  REP(i,N) if(SZ(G[i])==4) {
    ++cnt;
  }
  if(cnt>2) yup();
  if(cnt<2) nope();
  REP(i,N) if(SZ(G[i])==4) {
    int e=0;
    REP(u,N)FORR(v,G[u]) if(u!=i&&v!=i) ++e;
    if(e==2*(N-2)) nope();
    else yup();
  }
  assert(false);
}

