#include <bits/stdc++.h>
using namespace std;

int next(int now,int last, vector<pair<int, int>> &node) {
	for (int i = 0; i < node.size(); i++) {
		int tmp;
		if (node[i].first == now) tmp = node[i].second;
		else if (node[i].second == now) tmp = node[i].first;
		else continue;

		if (tmp != last) return tmp;
	}
}

int main()
{
	int N, M;
	cin >> N >> M;
	vector<pair<int, int>> node(M);
	vector<int> count(N + 1, 0);

	for (int i = 0; i < M; i++) {
		cin >> node[i].first >> node[i].second;
		count[node[i].first]++;
		count[node[i].second]++;
	}

	int check = 0;
	int start = -1, end = -1;
	for (int i = 1; i <= N; i++) {
		if (count[i] % 2 == 1) {
			check = 0;
			break;
		}
		if (count[i] >= 6){
			check += 3;
		}
		if (count[i] == 4){
			if (start == -1) start = i;
			else end = i;
			check++;
		}
	}

	if (check >= 3) {
		cout << "Yes" << endl;
	} else if (check <= 1) {
		cout << "No" << endl;
	}
	else {
		int endcount = 0;
		for (int i = 0; i < M; i++) {
			int tmp, now, last;
			if (node[i].first == start) now = node[i].second;
			else if (node[i].second == start) now = node[i].first;
			else continue;

			last = start;
			while (true) {

				if (now == start) break;
				if (now == end) {
					endcount++;
					break;
				}
				tmp = now;
				now = next(now, last, node);
				last = tmp;
			}
		}

		if (endcount == 4) {
			cout << "No" << endl;
		}
		else {
			cout << "Yes" << endl;
		}
	}
}

