int n,m,d[100111],eu[100111],ev[100111],f[100111];
int gf(int x){return x==f[x]?x:f[x]=gf(f[x]);}
int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++)
	{
		scanf("%d%d",eu+i,ev+i);
		d[eu[i]]++;d[ev[i]]++;
	}
