#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll N=1e5+5;
bool vis[N];
vector<ll> adj[N];
bool dfs(ll node,ll pr,ll avoid){
    if(vis[node])return 1;
    vis[node]=1;
    for(auto &u:adj[node])if(u!=pr && u!=avoid && dfs(u,node,avoid))return 1;
    return 0;
}
int main(){
    ios_base:: sync_with_stdio(false);
    cin.tie(NULL); cout.tie(NULL);
    ll n,m;cin>>n>>m;
    for(ll i=0,u,v;i<m;i++)cin>>u>>v,adj[u].push_back(v),adj[v].push_back(u);
    for(ll i=1;i<=n;i++)if(adj[i].size()&1)return cout<<"No" , 0;
    for(ll i=1;i<=n;i++)if(adj[i].size()>=6)return cout<<"Yes" , 0;
    for(ll i=1;i<=n;i++){
        if(adj[i].size()!=4)continue;
        for(auto &v:adj[i]){
            memset(vis,0,sizeof(vis));
            if(dfs(v,0,i))return cout<<"Yes" , 0;
        }
        return cout<<"No" , 0;
    }
    cout<<"No";
}

