#include <bits/stdc++.h>
using namespace std;

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, m;
    static int deg[100000];
    static vector<int> edges[100000];

    cin >> n >> m;
    for(int i=0;i<m;++i){
        int a, b;
        cin >> a >> b;
        --a; --b;
        ++deg[a]; ++deg[b];
    }
    static bool odd, six;
    vector<int> four;
    for(int i=0;i<n;++i){
        if(deg[i] & 1) odd = true;
        if(deg[i] >= 6) six = true;
        if(deg[i] == 4) four.emplace_back(i);
    }
    if(odd) cout << "No" << endl;
    else if(six) cout << "Yes" << endl;
    else if(four.size() >= 3) cout << "Yes" << endl;
    else if(four.size() <= 1) cout << "No" << endl;
    else{
        for(int i=0;i<4;++i){
            queue<pair<int, int>> q;
            q.emplace(edges[four[0]][i], four[0]);
            while(!q.empty()){
                auto t = q.front();
                q.pop();
                if(t.first == four[1]) break;
                if(t.first == four[0]){ cout << "Yes" << endl; return 0; }
                for(int to: edges[t.first]){
                    if(to == t.second) continue;
                    q.emplace(to, t.first);
                }
            }
        }
        cout << "No" << endl;
    }

    return 0;
}

