  os << p.first << ":" << p.second;
  return os;
}

int dfs(int now, int prev, int st, int ed, const vvi &g) {
  int res = 0;
  for(int i=0;i<SZ(g[now]);++i) {
    int nxt = g[now][i];
    if(nxt == prev) continue;
    if(nxt == st) {
      res += 0;
      continue;
    }
    if(nxt == ed) {
      res += 1;
      continue;
    }
    res += dfs(nxt, now, st, ed, g);
  }
  return res;
}

