{
	queue<int> que;
	static int way[MX];
	memset(way, 0, sizeof(way));
	que.push(x);
	way[x] = 1;
	while(!que.empty())
	{
		int a = que.front();
		que.pop();
		if(a == y) continue;
		for(int i=fst[a]; i; i=nxt[i])
