  if(initial == pos) return true;
  vertex_used[pos]++;
  if(bonds[pos].size()==0) return false;
  ll next = bonds[pos][bonds[pos].size()-1];
  bonds[pos].pop_back();
  auto itr = lower_bound(bonds[next].begin(), bonds[next].end(), pos);
  bonds[next].erase(itr);
  return search(initial, next, vertex_used, bonds);
}

