    FOR(i, 1, N+1){
      if(bonds[i].size()>0){
        flag = true;
        vertex_used[i]++;
        ll next = bonds[i][bonds[i].size()-1];
        bonds[i].pop_back();
        auto itr = lower_bound(bonds[next].begin(), bonds[next].end(), i);
        bonds[next].erase(itr);
        //printf("%d %d\n", i, next);
        bool search_flag = search(i, next, vertex_used, bonds);
