const int MAXN = 1e5 + 5;

int N, M;
vector <int> adj[MAXN];
int deg[MAXN], tmp[MAXN];
bool bio[MAXN];
int dad[MAXN];

void no() {
	puts("No");
	exit(0);
}

void yes() {
	puts("Yes");
	exit(0);
}

void dfs(int x, int p) {
	bio[x] = true;
	dad[x] = p;
	for (auto it : adj[x])
		if (!bio[it])
			dfs(it, x);
		else if (it != p) {
			while (1) {
				tmp[x] -= 2;
				if (x == it)
					break;
				x = dad[x];
			}
			for (int i = 1; i <= N; i++)
				if (tmp[i] > 2)
					yes();
			no();
		}
}

int main() {
	scanf("%d%d", &N, &M);
	while (M--) {
		int a, b;
		scanf("%d%d", &a, &b);
		adj[a].push_back(b);
		adj[b].push_back(a);
	}

	if (N == 1)
		no();

	for (int i = 1; i <= N; i++) {
		tmp[i] = deg[i] = adj[i].size();
		if (deg[i] % 2)
			no();
	}

	sort(deg + 1, deg + N + 1, greater <int> ());

	if (deg[1] == 2)
		no();

	if (deg[1] > 4)
		yes();

	if (deg[3] > 2)
		yes();

	dfs(1, 0);

	return 0;
}

