void dfs(vector<int> g[], int u)
{
	euler.pb(u);
	for (auto x : g[u])
	{
		if (mark[{x, u}]) continue;
		mark[{x, u}] = mark[{u, x}] = 1;
		dfs(g, x);
	}
}

void solve()
{
	int n, m; cin >> n >> m;
	vector<int> g[n+1];
	for (int i = 0; i < m; ++i)
	{
		int u, v; cin >> u >> v;
		g[u].pb(v);
		g[v].pb(u);
	}
	bool poss = 1;
	for (int i = 1; i <= n; ++i)
		poss &= (g[i].size()%2 == 0);
	if (!poss)
	{
		cout << "No\n";
		return;
	}

	dfs(g, 1);
	map<int, int> ct;
	euler.pop_back();
	for (auto it : euler)
		++ct[it];
	int ans = 0;
	vector<array<int, 2>> a;
	map<int, int> prev;
	for (auto it : ct)
		if (it.second >= 3)
			ans = 1;
	if (ans) cout << "Yes\n";
	else
	{
		int k = 1;
		for (auto it : euler)
		{
			if (ct[it] == 2 and prev[it] == 0) a.pb({prev[it], k});
			else if (ct[it] == 2) prev[it] = k;
			++k;
		}
		sort(a.begin(), a.end());
