int n, m, deg[N], stk[N], top, ins[N], ban[N], fre[N];
int tot = 1, fir[N], nxt[N << 1], to[N << 1];

inline void addE(int u, int v) {
    nxt[++tot] = fir[u], fir[u] = tot, to[tot] = v;
}

void dfs(int u, int e, int &cnt) {
    if (cnt) return ;
    if (ins[u]) {
        for (int i = top; stk[i + 1] != u; --i)
            deg[stk[i]] -= 2, ++cnt, ban[fre[stk[i]]] = 1;
        return ;
    }
    ins[u] = 1, stk[++top] = u;
    for (int i = fir[u], v; i; i = nxt[i]) {
        if (i / 2 == e) continue;
        v = to[i], fre[v] = i / 2;
        dfs(v, i / 2, cnt);
    }
    stk[top--] = ins[u] = 0;
}

void dfs2(int u, int &cnt) {
    if (ins[u]) return ;
    ins[u] = 1, ++cnt;
    for (int i = fir[u], v; i; i = nxt[i]) {
        v = to[i];
        if (ins[v] || ban[i / 2]) continue;
        dfs2(v, cnt);
    }
}

int main() {
#ifdef isLOCAL
    freopen("work.in", "r", stdin);
    freopen("work.out", "w", stdout);
#endif

    cin >> n >> m;

    for (int i = 1, u, v; i <= m; ++i)
        scanf("%d%d", &u, &v), ++deg[u], ++deg[v],
        addE(u, v), addE(v, u);

    for (int i = 1; i <= n; ++i)
        if (deg[i] & 1) return puts("No"), 0;

    int tmp = 0;
    for (int i = 1; i <= n; ++i)
        if (deg[i] == 4) ++tmp;

    int ok = 0;
    dfs(1, 0, ok);
    if (!ok) return puts("No"), 0;

    int cnt = 0;
    for (int i = 1; i <= n && !cnt; ++i)
        if (deg[i]) dfs2(i, cnt);
    for (int i = 1; i <= n; ++i)
        if (deg[i] == 2) -- cnt;

    if (tmp >= 3) return puts("Yes"), 0;

    puts(cnt ? "Yes" : "No");

    return 0;
}

