int N, M;
vector<int> G[100000];
bool used[100000];

bool rec(int from, int goal) {
	if (from == goal) return true;
	if (used[from]) return false;
	if (G[from].size() != 4) return false;
	used[from] = true;
	for (int to : G[from]) {
		if (rec(to, goal)) return true;
	}
	return false;
}

bool ok(int from) {
	for (int to : G[from]) {
		fill(used, used + N, false);
		if (rec(to, from)) return true;
	}
	return false;
}

bool sub() {
	REP(i, 0, N) {
		if (G[i].size() % 2 == 1) return false;
	}

	REP(i, 0, N) {
		if (G[i].size() >= 6) return true;
	}

	int cnt = 0;
	REP(i, 0, N) {
		if (G[i].size() == 4) {
			++cnt;
		}
	}

	if (cnt <= 1) return false;
	if (cnt >= 3) return true;

	REP(i, 0, N) {
		if (G[i].size() != 4) continue;
		return ok(i);
	}
	throw 1;
}

int main() {
	cin >> N >> M;
	REP(j, 0, M) {
		int a, b;
		cin >> a >> b;
		--a; --b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	YesNo(sub());
	return 0;
}

# include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn(1e5 + 5);

struct Edge {  int u, v, vis;  };

int n, m, d[maxn], vis[maxn];
Edge path[maxn];
multiset <int> edge[maxn];
queue <int> Q;
multiset <int> :: iterator it, ot;

int main() {
	int i, a, b, ret = 0, sum = 0, mx = 0, p1, p2, x, y, p, u, v;
	scanf("%d%d", &n, &m);
	for (i = 1; i <= m; ++i) {
		scanf("%d%d", &a, &b), ++d[a], ++d[b];
		edge[a].insert(i), edge[b].insert(i);
		path[i] = (Edge){a, b, 0};
	}
	for (i = 1; i <= n; ++i) if (d[i] & 1) return puts("No"), 0;
	for (i = 1; i <= n; ++i) if (!d[i]) vis[i] = 1;
	for (i = 1; i <= n; ++i) if (d[i] == 1) Q.push(i);
	while (!Q.empty()) {
		u = Q.front(), Q.pop();
		if (!d[u]) continue;
		vis[u] = 1, p = *edge[u].begin(), path[p].vis = 1;
		v = u == path[p].u ? path[p].v : path[p].u;
		--d[u], edge[u].erase(edge[u].find(p));
		--d[v], edge[v].erase(edge[v].find(p));
		if (d[v] == 1) Q.push(v);
	}
	for (i = 1; i <= n; ++i) if (!vis[i] && d[i] == 2) Q.push(i);
	while (!Q.empty()) {
		u = Q.front(), Q.pop();
		if (!d[u]) continue;
		x = *edge[u].begin(), y = *edge[u].rbegin();
		if (x == y) {  ++sum; continue;  }
		vis[u] = 1;
		p1 = path[x].u == u ? path[x].v : path[x].u;
		p2 = path[y].u == u ? path[y].v : path[y].u;
		path[x].vis = path[y].vis = 1;
		edge[u].erase(edge[u].find(x)), --d[u];
		edge[u].erase(edge[u].find(y)), --d[u];
		edge[p1].erase(edge[p1].find(x)), --d[p1];
		edge[p2].erase(edge[p2].find(y)), --d[p2];
		path[++m] = (Edge){p1, p2, 0};
		edge[p1].insert(m), edge[p2].insert(m), ++d[p1], ++d[p2];
	}
	for (i = 1; i <= n; ++i)
		if (!vis[i]) ++ret, mx = max(mx, (int)edge[i].size());
	sum += mx / 2;
	if (ret >= 3 || sum >= 3) return puts("Yes"), 0;
	return puts("No"), 0;
}

