using namespace std;
using namespace boost;

bool dfs(const vector<vector<pair<int64_t, int64_t>>>& links, vector<bool>& used, int64_t target, int64_t ng, int64_t current) {
  for (auto link : links[current]) {
    if (used[link.second]) {
      continue;
    }

    auto v = link.first;
    if (v == target) {
      return true;
    }

    if (v == ng) {
      return false;
    }

    used[link.second] = true;
    auto tmp = dfs(links, used, target, ng, v);
    if (tmp) {
      return true;
    }
  }

  return false;
}

main() {
  int64_t n, m;
  cin >> n >> m;

  vector<vector<pair<int64_t, int64_t>>> links(n);
  for (auto i : irange(0L, m)) {
    int64_t a, b;
    cin >> a >> b;
    --a;
    --b;
    links[a].emplace_back(b, i);
    links[b].emplace_back(a, i);
  }

  int64_t x = -1, y = -1;
  for (auto i : irange(0L, n)) {
    int64_t k = links[i].size();
    if (k % 2 == 1) {
      cout << "No" << endl;
      return 0;
    }

    if (k >= 6) {
      cout << "Yes" << endl;
      return 0;
    }

    if (k == 4) {
      if (x == -1) {
        x = i;
      } else if (y == -1) {
        y = i;
      } else {
        cout << "Yes" << endl;
        return 0;
      }
    }
  }

  vector<bool> used(m, false);
  auto ret = dfs(links, used, x, y, x);
  if (ret) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
}

