int main(){
  int N,M;
  cin >> N >> M;
  int deg[N];
  bool edge_used[M];
  memset(edge_used,false,sizeof(edge_used));
  memset(deg,0,sizeof(deg));
  vector<pair<int,int>> edge[M];
  map<pair<int,int>, int> p2i;
  for(int i=0; i<M;i++){
     int a,b;
     cin >> a >> b;
     a--;b--;deg[a]++;deg[b]++;
     edge[a].push_back(make_pair(b,i));
     edge[b].push_back(make_pair(a,i));
     p2i[make_pair(a,b)]=i;
     p2i[make_pair(b,a)]=i;
  }
  for(int i=0;i<N;i++){
     if(deg[i]%2==1){
        cout << "No"<<endl;
        return 0;
     }
  }

  for(int i=0;i<3; i++){
     vector<int> route;
     bool arrived[N];
     memset(arrived,false,sizeof(arrived));
     int start = 0;
     while(start<N && deg[start]==0) start++;
     if(start==N){
        cout << "No"<<endl;
        return 0;
     }
     int priv = -1;
     int cur = start;
     while(true){
        route.push_back(cur);
        if( arrived[cur]== true) break;
        arrived[cur]=true;
        for(int ei=0; ei<(int)edge[cur].size(); ei++){
           if(edge_used[edge[cur][ei].second]==false&&edge[cur][ei].first!=priv){
              priv=cur;
              cur=edge[cur][ei].first;
              break;
           }
        }
     }
     reverse(route.begin(),route.end());
     int s = route[0];
     for(int j=0; j+1<(int)route.size(); j++){
        //cout <<route[j] <<"->";
        edge_used[p2i[make_pair(route[j],route[j+1])]]=true;
        deg[route[j]]--;
        deg[route[j+1]]--;
        if(route[j+1]==s) break;
     }
     //cout << endl;
  }
  cout <<"Yes"<<endl;
  return 0;
}

