bool dfs( int cur, int cnt, int goal, const vector<vector<int>>& edge )
{
	for( auto& next : edge[cur] )
	{
		if( next == goal && cnt >= 2 )
			return true;
		if( is[next] )
			continue;
		is[next] = true;
		if( dfs( next, cnt + 1, goal, edge ) )
			return true;
		is[next] = false;
	}
}

