void dlt_edge(int u, int v) {
	assert(g[u].find(v) != g[u].end());
	assert(g[v].find(u) != g[v].end());
	g[u].erase(g[u].find(v));
	g[v].erase(g[v].find(u));
}

void dfs(int u) {
	cnt += vis[u];
	if(!vis[u]) vis[u] = 1;
	while(g[u].size()) {
		int v = *g[u].begin();
		dlt_edge(u, v);
		dfs(v);
	}
}

