template <typename C, typename D>
struct Graph {
  struct Edge {
    int to;
    C cap;
    D cost;
    int rev;
  };
  vector<vector<Edge>> edges;
  int n;
  Graph(int n) : n(n) {
    edges = vector<vector<Edge>>(n);
  }
  void add_edge(int from, int to, C cap = 1, D cost = 0) {
    edges[from].push_back((Edge) { to, cap, cost, (int) edges[to].size() });
    edges[to].push_back((Edge) { from, 0, -cost, (int) edges[from].size() - 1 });
  }
};

template <typename C, typename D>
C max_flow(Graph<C, D> &g, int s, int t) {
  const int n = g.n;
  auto &G = g.edges;

  C flow = 0;
  vector<int> used(n);
  int ui = 0;
  function<C(int, int, C)> dfs = [&](int v, int t, C f) {
    if (v == t) return f;
    used[v] = ui;
    for (int i = 0; i < G[v].size(); i++) {
      auto &e = G[v][i];
      if (used[e.to] == ui || e.cap == 0) continue;
      int d = dfs(e.to, t, min(f, e.cap));
      if (d == 0) continue;
      e.cap -= d;
      G[e.to][e.rev].cap += d;
      return d;
    }
    return 0;
  };
  while (true) {
    ui++;
    int f = dfs(s, t, numeric_limits<C>::max());
    if (f == 0) return flow;
    flow += f;
  }
}

