  int fe = -1, te = -1;
  rep(i, n) {
    if (deg[i] % 2 != 0) no();
    deg[i] == 2 ? to++ : deg[i] == 4 ? fo++ : si++;
    if (deg[i] == 4) {
      if (fe == -1) fe = i;
      else te = i;
    }
  }
  if (si) yes();
  if (!fo || fo == 1) no();
  if (fo >= 3) yes();

  auto graph = Graph<int, int>(n);
  rep(i, n) each(j, es[i]) {
    graph.add_edge(i, j);
  }
  int fa = max_flow(graph, fe, te);
  if (fa == 4) yes(); no();
}

