	int N,M; cin >> N >> M;
	V<V<P<int,int>>> edge(N);
	V<int> node(N,0);
	for(int i = 0; i < M; ++i){
		int a, b; cin >> a >> b;
		a--, b--;
		edge[a].push_back({b,i});
		edge[b].push_back({a,i});
		node[a]++;
		node[b]++;
	}
	for (int i = 0; i < N; ++i) corner(node[i] % 2, "No");
	for (int i = 0; i < N; ++i) corner(node[i] >=6, "Yes");
	V<int> cnt4;
	for (int i = 0; i < N; ++i) if(node[i] == 4) cnt4.push_back(i);
	corner(cnt4.size() < 2, "No");
	corner(cnt4.size() > 2, "Yes");

	int l = cnt4[0], r = cnt4[1], cnt = 0;
	V<int> flg(M, 0),d;
	stack<P<P<int,int>,int>> q;
	q.push({ {l,-1},0 });

	while(q.size()){
		int from = q.top().first.first;
		int ini = q.top().first.second;
		int c = q.top().second;
		if (ini != -1) flg[q.top().second] = 1;
		q.pop();
		if (from == l && ini != -1) {
			d.push_back(c);
			continue;
		}
		if (from == r) c = 1;

		for(auto e:edge[from]){
			if (flg[e.second]) continue;
			q.push({e,c});
		}
	}
	Yn(d[0] == 0 || d[1] == 0);
	return 0;
}

