bool existsCyc = 0;

void fin(string s) {
    ps(s); exit(0);
}

void dfs(int x, int p = -1) {
    vis[x] = 1;
    trav(t,tmp[x]) if (t != p) {
        if (vis[t]) {
            // ps("WHAT",x,t);
            existsCyc = 1;
            return;
        }
        dfs(t,x);
    }
}

bool allThrough(int x) {
    trav(t,tmp[x]) {
        tmp[t].erase(x);
    }
    tmp[x].clear();
    FOR(i,1,N+1) if (!vis[i]) dfs(i);
    return !existsCyc;
}

