bool run(int turn) {
    int start=-1;
    rep(i,N){
        if (turn < 2) {
            if (deg[i] >= 4) { start = i; break; }
        } else {
            if (deg[i] >= 2) { start = i; break; }
        }
    }
    if (start == -1) return false;

    vi route; set<int> visited;
    for (int u=start; ; ) {
        if (found(visited,u)) {
            route.pb(u);
            break;
        }
        route.pb(u);
        visited.insert(u);

        int v = -1;
        for (auto& p: out[u]){
            int tmp = p.first, cnt = p.second;
            if (tmp == u) {
                if (cnt >= 2) {
                    v = tmp;
                    break;
                }
            } else {
                v = tmp;
                break;
            }
        }
        --out[u][v]; --deg[u]; if (out[u][v] == 0) out[u].erase(v);
        --out[v][u]; --deg[v]; if (out[v][u] == 0) out[v].erase(u);
        u = v;
    }
    return true;
}

bool solve() {
    out.resize(N);
    deg.assign(N,0);

    rep(i,M){
        ++out[a[i]][b[i]];
        ++out[b[i]][a[i]];
        ++deg[a[i]];
        ++deg[b[i]];
    }

    rep(i,N){
        if (deg[i] % 2) return false;
    }
    rep(turn,3){
        if (!run(turn)) return false;
    }
    return true;
}

