struct Edge {
	int f, t, cap, flow = 0;
	Edge(int f, int t, int cap) : f(f), t(t), cap(cap) {}
};
const int inf = 1e9;
struct Dinic {
	int n, m, s, t;
	vector<Edge> edges;
	queue<int> q;
	vi ptr, lvl;
	vvi g;
	void init(int n, int s, int t) {
		this->n = n;
		this->m = 0;
		this->s = s;
		this->t = t;
		ptr.resize(n+1);
		lvl.resize(n+1);
		g.resize(n+1);
	}
	void add_edge(int f, int t, int cap) {
		edges.emplace_back(f, t, cap);
		edges.emplace_back(t, f, 0);
		g[f].pb(m);
		g[t].pb(m+1);
		m+=2;
	}
	bool bfs() {
		fill(all(lvl), -1);
		lvl[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int u = q.front();
			q.pop();
			for(auto id : g[u]) {
				if(edges[id].cap-edges[id].flow<1||lvl[edges[id].t]!=-1) continue;
				lvl[edges[id].t]=lvl[u]+1;
				q.push(edges[id].t);
			}
		}
		return lvl[t]==-1;
	}
	ll dfs(int v, int cap) {
		if(cap==0)
			return 0;
		if(v==t)
			return cap;
		for(;ptr[v]<g[v].size();ptr[v]++) {
			int id = g[v][ptr[v]];
			int u = edges[id].t;
			if(lvl[v]+1!=lvl[u]||edges[id].cap-edges[id].flow<1) continue;
			int t = dfs(u, min(cap, edges[id].cap-edges[id].flow));
			if(t==0) continue;
			edges[id].flow+=t;
			edges[id^1].flow-=t;
			return t;
		}
		return 0;
	}
	ll flow() {
		ll ans = 0;
		while(true) {
			if(bfs()) break;
			fill(all(ptr), 0);
			while(ll inc = dfs(s, inf)) ans += inc;
		}
		return ans;
	}
};
