	if(flag) return;
	fa[x]=f;
	for(int i=head[x];i;i=nex[i]){
		if(flag) return;
		if(e[i]==f) continue;
		if(!fa[e[i]]){
			if(flag) return;
			c[e[i]]=(i+1)/2;
			dfs(e[i],x);
		}
		else{
			if(flag) return;
			del[(i+1)/2]=1;
			for(int j=x;j!=e[i];j=fa[j]){
				del[c[j]]=1;
			}
			flag=1;
			return;
		}
	}
}
