template <typename C, typename D>
struct Graph {
  struct Edge {
    int to;
    C cap;
    D cost;
    int rev;
  };
  vector<vector<Edge>> edges;
  int n;
  Graph(int n) : n(n) {
    edges = vector<vector<Edge>>(n);
  }
  void add_edge(int from, int to, C cap = 1, D cost = 0) {
    edges[from].push_back((Edge) { to, cap, cost, (int) edges[to].size() });
    edges[to].push_back((Edge) { from, 0, -cost, (int) edges[from].size() - 1 });
  }
};

template <typename C, typename D>
C max_flow(Graph<C, D> &g, int s, int t) {
  const int n = g.n;
  auto &G = g.edges;

  C flow = 0;
  vector<int> used(n);
  int ui = 0;
  function<C(int, int, C)> dfs = [&](int v, int t, C f) {
    if (v == t) return f;
    used[v] = ui;
    for (int i = 0; i < G[v].size(); i++) {
      auto &e = G[v][i];
      if (used[e.to] == ui || e.cap == 0) continue;
      int d = dfs(e.to, t, min(f, e.cap));
      if (d == 0) continue;
      e.cap -= d;
      G[e.to][e.rev].cap += d;
      return d;
    }
    return 0;
  };
  while (true) {
    ui++;
    int f = dfs(s, t, numeric_limits<C>::max());
    if (f == 0) return flow;
    flow += f;
  }
}

void solve() {
  int n, m; cin >> n >> m;
  vector<vector<int>> es(n);
  vector<int> deg(n);
  rep(i, m) {
    int a, b; cin >> a >> b;
    a--, b--;
    es[a].push_back(b);
    es[b].push_back(a);
    deg[a]++, deg[b]++;
  }
  int to = 0, fo = 0, si = 0;
  int fe = -1, te = -1;
  rep(i, n) {
    if (deg[i] % 2 != 0) no();
    deg[i] == 2 ? to++ : deg[i] == 4 ? fo++ : si++;
    if (deg[i] == 4) {
      if (fe == -1) fe = i;
      else te = i;
    }
  }
  if (si) yes();
  if (!fo || fo == 1) no();
  if (fo >= 3) yes();

  auto graph = Graph<int, int>(n);
  rep(i, n) each(j, es[i]) {
    graph.add_edge(i, j);
  }
  int fa = max_flow(graph, fe, te);
  if (fa == 2) yes(); no();
}

