struct Graph {
    struct Vertex { int n, d, f, c; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1, 0, 0, 0 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        v[i].d++;
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    void dfs(int i, int x, int p) {
        //cout << i << endl;
        v[i].f ^= x;
        v[i].d -= 2;
        v[i].c++;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (o.i == p) continue;
            if (v[o.i].f & x) continue;
            if (x == 2) {
                if (st.count({ i, o.i })) continue;
                if (st.count({ o.i, i })) continue;
            }
            if (x == 1) {
                st.insert({ i, o.i });
            }
            //cout << o.i << endl;
            dfs(o.i, x, i);
            break;
        }
    }
    int solve() {
        int b = 1;
        for (int i = 0; i < n; i++) {
            if (v[i].d % 2 != 0) return 0;
        }
        dfs(0, 1, -1);

        b = 0;
        for (int i = 0; i < n; i++) {
            if (v[i].d > 0) {
                b = 1;
                dfs(i, 2, -1);
                break;
            }
        }
        //for (int i = 0; i < n; i++) {
        //    cout << v[i].d << endl;
        //}
        if (b == 0) return 0;

        b = 0;
        for (int i = 0; i < n; i++) {
            if (v[i].d > 0) {
                b = 1;
                break;
            }
        }
        if (b == 1) return 1;

        b = 0;
        for (int i = 0; i < n; i++) {
            if (v[i].c > 1) {
                b++;
            }
        }
        return b > 2;
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    Graph g(n, m * 2);
    for (int i = 0; i < m; i++) {
        int a, b;
