typedef long long ll;
typedef long double ld;
const int MAXN = 200005;
vector<int> E[MAXN];
vector<int> findCycle(int n) {
	vector<int> vis(n + 1), par(n + 1), cycle;
	function<bool(int)> dfs = [&](int x) {
		vis[x] = 1;
		for (int y : E[x]) {
			if (!vis[y]) {
				par[y] = x;
				if (dfs(y)) return true;
			} else if (vis[y] == 1) {
				// Back-edge.
				for (;;) {
					cycle.push_back(x);
					if (x == y) break;
					x = par[x];
				}
				reverse(cycle.begin(), cycle.end());
				return true;
			}
		}
		vis[x] = 2;
		return false;
	};
	for (int i = 1; i <= n; ++i)
		if (!vis[i] && dfs(i)) break;
	return cycle;
}
set<pair<int, int>> badEdges;
bool used[MAXN];
int cnt;
void dfs(int x) {
	used[x] = true;
	++cnt;
	for (int y : E[x]) {
		if (badEdges.count({x, y})) continue;
		if (used[y]) continue;
		dfs(y);
	}
}
void no() {
	printf("No\n");
	exit(0);
}
int main() {
	int n, m;
	scanf("%d%d", &n, &m);
	vector<int> deg(n + 1);
	for (int i = 0; i < m; ++i) {
		int a, b;
		scanf("%d%d", &a, &b);
		E[a].push_back(b);
		E[b].push_back(a);
		++deg[a];
		++deg[b];
	}
	bool all2 = true;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] & 1) no();
		else if (deg[i] != 2) all2 = false;
	}
	if (all2) no();
	auto cycle = findCycle(n);
	assert(!cycle.empty());
	int x = cycle[0];
	cycle.push_back(x);
	for (int i = 0; i + 1 < cycle.size(); ++i) {
		badEdges.insert({cycle[i], cycle[i + 1]});
		badEdges.insert({cycle[i + 1], cycle[i]});
		--deg[cycle[i]];
		--deg[cycle[i + 1]];
	}
	all2 = true;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] > 0 && deg[i] != 2) all2 = false;
	}
	int comps = 0;
	for (int i = 1; i <= n; ++i) {
		if (used[i]) continue;
		cnt = 0;
		dfs(i);
		if (cnt > 1) ++comps;
	}
