int rev(int i) {return (i&1)?(i+1):(i-1);}
int ask(int x) {return fa[x]==x?x:fa[x]=ask(fa[x]);}

void del(int x,int i)
{
	d[x]--;
	if (i==hd[x]) e[hd[x]=e[i].next].la=0;
	else e[e[i].next].la=e[i].la,e[e[i].la].next=e[i].next;
}

void addedge(int x,int y)
{
	e[++cnt].next=hd[x];
	e[cnt].to=y,e[cnt].la=0;
	e[hd[x]].la=cnt;
	hd[x]=cnt;
}

bool work(int x)
{
	if (bo[x])
	{
		int X=x;
		del(e[rev(la[x])].to,la[x]);
		del(x,rev(la[x])),x=e[rev(la[x])].to;
		while (x!=X) 
		{
			del(e[rev(la[x])].to,la[x]);
			del(x,rev(la[x])),x=e[rev(la[x])].to;
		}
		return 1;
	}
	bo[x]=1;
	for (int i=hd[x]; i; i=e[i].next)
		if (i!=rev(la[x])) 
		{
			la[e[i].to]=i;
			if (work(e[i].to)) return 1;
		}
	return 0;
}

