void solve(){
	vector<int> deg(N,0);
	vector<vector<int> > adj(N);
	REP(i,M)deg[a[i]]++,deg[b[i]]++, adj[a[i]].push_back(b[i]), adj[b[i]].push_back(a[i]);
//	unordered_map<int,int> deg_count;
	vector<int> deg4;
	REP(u,N){
		if(deg[u]%2==1){
			fout<<"No"<<endl;
			return;
		}else if(deg[u]>=6){
			fout<<"Yes"<<endl;
			return;
		}
		if(deg[u]==4){
			deg4.push_back(u);
		}
	}
	if(deg4.size()>=3){
		fout<<"Yes"<<endl;
	}else if(deg4.size()<=1){
		fout<<"No"<<endl;
	}else{
		//deg4_count==2
		int s = deg4[0], t = deg4[1];
		assert(adj[s].size()==4);
		function<int(int,int)> dfs = [&](int u,int p){
			if(adj[u].size()==4){
				return u;
			}
			assert(adj[u].size()==2);
			for(auto &v:adj[u]){
				if(v==p)continue;
				return dfs(v,u);
			}
			assert(false);
			return 0;
		};
		vector<int> dst(4);
		REP(i,4){
			dst[i] = dfs(adj[s][i],s);
		}
		int tc = 0;
		REP(i,4){
			if(dst[i]==t)tc++;
		}
		if(tc==2){
			fout<<"Yes"<<endl;
		}else{
			fout<<"No"<<endl;
		}
	}
}

