//無向グラフがオイラーグラフか判定（オイラー閉路を持つ）
pair<bool, vector<int>> isEulerianGraph(const Graph &udg) {
	//if (!isConnectedGraph(udg))return false;
	int n = udg.size();
	vector<int> degree(n, 0);
	for (auto &es : udg)for (auto &e : es)
		degree[e.d]++, degree[e.s]++;
	bool ok = true;
	for (auto &d : degree) {
		d /= 2;
		if (d % 2)
			ok = false;
	}
	return make_pair(ok, degree);
}

//無向グラフが準オイラーグラフか判定（閉路でないオイラー路を持つ）
bool isSemiEulerianGraph(const Graph &udg) {
	//if (!isConnectedGraph(udg))return false;
	int n = udg.size();
	vector<int> degree(n, 0);
	for (auto &es : udg)for (auto &e : es) degree[e.d]++, degree[e.s]++;
	dump(degree);
	int odd = 0;
	for (auto &d : degree) {
		if ((d / 2) % 2)odd++;
		if (odd > 2)return false;
	}
	return odd == 2;
}

// 単純グラフで閉路があるかどうか
bool hasCycle(const Graph &g, int s = 0) {
	int n = g.size();
	vector<bool> vis(n);
	function<int(int, int)> dfs = [&](int u, int p) {
		bool ret = false;
		vis[u] = true;
		for (auto e : g[u]) {
			if (p == e.d)continue;
			if (vis[e.d])
				return true;
			ret |= dfs(e.d, u);
			if (ret)break;
		}
		return ret;
	};
	return dfs(s, -1);
}

