	for(int i = 1; i <= m; ++i) {
		int x, y; cin >> x >> y;
		vis[i] = false;
		to[i << 1] = y; last[i << 1] = h[x]; h[x] = i << 1;
		to[i << 1 | 1] = x; last[i << 1 | 1] = h[y]; h[y] = i << 1 | 1;
		deg[x]++; deg[y]++;
		st = x;
	}
	for(int u = 1; u <= n; ++u) if(deg[u] & 1) {
		printf("%d!\n", u);
		printf("No\n"); return 0;
	}
	vector<int> d(deg + 1, deg + n + 1);
	std::sort(d.begin(), d.end()); std::reverse(d.begin(), d.end());
	while(d.size() && d.back() == 2) d.pop_back();
	if(d.size() == 0 || (d.size() == 1 && d[0] == 4)) {
		printf("No\n"); return 0;
	} else if(d[0] >= 6 || d.size() >= 3) {
		printf("Yes\n"); return 0;
	}
	DFS(st);
	q.push_back(st);
	for(int i = len; i >= 1; --i) {
		q.push_back(to[stk[i]]);
	}
	for(int x : q) printf("%d ", x);
	printf("%s\n", judge() ? "Yes" : "No");
	return 0;
}

