struct UnionFind {
    vector<int> d;
    UnionFind(int n=0) : d(n, -1){}
    bool unite(int x, int y) {
        if ((x = root(x)) != (y = root(y))){
            if (d[y] < d[x]) swap(x, y);
            d[x] += d[y]; d[y] = x;
        }
        return x != y;
    }
    bool find(int x, int y){return root(x) == root(y);}
    int root(int x){return d[x] < 0 ? x : d[x] = root(d[x]);}
    int size(int x=-1) {return x<0 ? d.size() : -d[root(x)];}
};

int T, n, m;

int solve2(int t, const vector<vi> &g) {
    UnionFind uf(n);
    REP(u, n) {
        for (int v : g[u]) {
            if (u != t && v != t) {
                uf.unite(u, v);
            }
        }
    }
    int c = 0;
    REP(i, n) {
        c += uf.root(i) == i;
    }
    return c == 3;
}

int solve() {
