vi circuit(const Graph &G, int s, vb &ban) {
    vi ret;
    ret.push_back(s);
    int pos = s;
    while (true) {
        int ns = 0;
        for (auto e : G[pos]) {
            if (!ban[e.to]) {
                ns = e.to;
            }
        }
        ban[ns] = true;
        if (ns == pos)
            return ret;
        ret.push_back(ns);
        pos = ns;
    }
}

