bool checkdegree(int N, int M, vector<vector<int>> &edges)
{
    vector<int> degree(N);
    for (auto edge : edges)
    {
        degree[edge.size()]++;
        if (edge.size() % 2 == 1)
            return false;
    }
}
bool solve(int N, int M, vector<vector<int>>& edges)
{
    for (auto edge : edges)
    {
        if (edge.size() % 2 == 1)
            return false;
    }
    for (auto edge : edges)
    {
        if (edge.size() >= 6)
            return true;
    }
    int count=0;
    for (auto edge : edges)
    {
        if (edge.size() == 4)
            count++;
    }
    if(count>=3)return true;
    return false;//uso
}
int main()
{
    int N, M;
    cin >> N >> M;
    vector<vector<int>> edges(N);
    for (int i = 0; i < M; i++)
    {
        int a, b;
        cin >> a >> b;
        edges[a - 1].push_back(b - 1);
        edges[b - 1].push_back(a - 1);
    }
    cout<<solve(N,M,edges)<<endl;
}

