void del_edge(int x, int y)
{
	for (int i=0; i<con[x].size(); i++)
	{
		if (con[x][i]==y)
		{
			swap(con[x][i], con[x].back());
			con[x].pop_back();
			break;
		}
	}
	for (int i=0; i<con[y].size(); i++)
	{
		if (con[y][i]==x)
		{
			swap(con[y][i], con[y].back());
			con[y].pop_back();
		}
	}
}

