int N, M;
vector<int> V[100010];
int parent[100010];
int start = -1;
int goal = -1;

bool dfs(int s)
{
  for (auto x : V[s])
  {
    if (x != parent[s])
    {
      if (x == start)
      {
        return false;
      }
      else if (x == goal)
      {
        return true;
      }
      parent[x] = s;
      if (!dfs(x))
      {
        return false;
      }
    }
  }
  return true;
}

int main()
{
  cin >> N >> M;
  for (auto i = 0; i < M; i++)
  {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    V[a].push_back(b);
    V[b].push_back(a);
  }
  for (auto i = 0; i < N; i++)
  {
    int s = V[i].size();
    if (s % 2 == 1)
    {
      No();
    }
  }
  for (auto i = 0; i < N; i++)
  {
    int s = V[i].size();
    if (s >= 6)
    {
      Yes();
    }
  }
  int four = 0;
  for (auto i = 0; i < N; i++)
  {
    int s = V[i].size();
    if (s == 4)
    {
      four++;
    }
  }
  if (four >= 3)
  {
    Yes();
  }
  if (four <= 1)
  {
    No();
  }
  for (auto i = 0; i < N; i++)
  {
    if ((int)V[i].size() == 4)
    {
      if (start == -1)
      {
        start = i;
      }
      else
      {
        goal = i;
        break;
      }
    }
  }
  fill(parent, parent + N, -1);
  if (!dfs(start))
  {
    Yes();
  }
  else
  {
    No();
  }
}

