int vis[100005];

bool dfs(int x,int par){
    if(vis[x]==1){
        vis[x]=0;
        return true;
    }
    vis[x]=1;
    for(int i=0;i<(int)adj[x].size();i++){
        if(adj[x][i].first==par)continue;
        if(adj[x][i].second.first){
            if(dfs(adj[x][i].first,x)){
                vis[x]=0;
                adj[x][i].second.first=0;
                adj[adj[x][i].first][adj[x][i].second.second].second.first=0;
                return true;
            }
        }
    }
    vis[x]=0;
    return false;
}

