			int cur = x;
			int p = v;
			while(cur != v && cur != w){
				assert(int(edges[cur].size()) == 2);
				p = edges[cur][0] + edges[cur][1] - p;
				swap(p, cur);
			}
			if(cur == w) npaths++;
		}
		if(npaths == 2){
			cout << "Yes" << '\n';
		} else if(npaths == 4){
			cout << "No" << '\n';
		}
	} else if(d4 <= 1){
		cout << "No" << '\n';
		exit(0);
	}
}

