// Eulerian path/circuit in an undirected graph. TODO: Does this handle self-edges?
// NOTE(Brian): This looks like it could theoretically degrade to quadratic time in, say, a graph where we keep going back and forth between two vertices; in this case a lot of time could be wasted searching for an unused edge.
struct EulerianPath {
	int n;
	vector<vector<int> > adj;
	vector<pair<int, int> > edges;
	vector<int> valid;
	vector<int> circuit;

	EulerianPath(int n): n(n), adj(n) {}

	// Call this to construct the graph.
	// Edges are zero-based and undirected (only add each edge once!)
	void add_edge(int x, int y) {
        --x; --y;
		adj[x].push_back(edges.size());
		adj[y].push_back(edges.size());
		edges.push_back(make_pair(x, y));
		valid.push_back(1);
	}

	void find_path(int x){
	  for(int i = 0; i < adj[x].size(); i++){
		int e = adj[x][i];
		if(!valid[e]) continue;
		int v = edges[e].first;
		if(v == x) v = edges[e].second;
		valid[e] = 0;
		find_path(v);
	  }
	  circuit.push_back(x);
	}

	// Call this to find the path/circuit (autodetects)
	// Returns the path/circuit itself in "circuit" variable
	// Initial node is repeated at end if it's a circuit.
	void find_euler_path() {
	  circuit.clear();
	  //supposes graph is connected and has correct degree
	  for(int i = 0; i < n; i++)
		if(adj[i].size()%2){
		  find_path(i);
		  return;
		}
	  find_path(0);
	}
};

const int max_N = 1e5 + 10;
int seen[max_N];

int main() {
    int N, M;
    cin >> N >> M;

    EulerianPath G(N);
    for (int i = 1; i <= M; ++i) {
        int x, y;
        cin >> x >> y;
        G.add_edge(x, y);
    }

    for (int i = 0; i < N; ++i) {
        if (G.adj[i].size() % 2) {
            cout << "No" << endl;
            return 0;
        }
    }

    vector<int> C1, C2;
    G.find_euler_path();
    C1 = G.circuit;

    memset(seen, -1, sizeof(seen));
    bool ok = false;
    for (int i = 0; i < C1.size(); ++i) {
        int v = C1[i];
        if (seen[v] == -1 || (i - seen[v] + 1) == C1.size()) {
            seen[v] = i;
        } else {
            ok = true;
            C2.insert(C2.end(), C1.begin() + seen[v], C1.begin() + i + 1);
            C1.erase(C1.begin() + seen[v], C1.begin() + i);
            break;
        }
    }

    if (!ok) {
        cout << "No" << endl;
        return 0;
    }

    memset(seen, -1, sizeof(seen));
    ok = false;
    for (int i = 0; i < C1.size(); ++i) {
        int v = C1[i];
        if (seen[v] == -1 || (i - seen[v] + 1) == C1.size()) {
            seen[v] = i;
        } else {
            ok = true;
        }
    }

    memset(seen, -1, sizeof(seen));
    for (int i = 0; i < C2.size(); ++i) {
        int v = C2[i];
        if (seen[v] == -1 || (i - seen[v] + 1) == C2.size()) {
            seen[v] = i;
        } else {
            ok = true;
        }
    }

    if (ok) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

