namespace n91 {

	void stop(){}

	bool solve() {
		usize n, m;
		std::cin >> n >> m;
		std::vector<std::multiset<usize>> g(n);
		std::vector<usize> deg(n);
		while (m--) {
			usize a, b;
			std::cin >> a >> b;
			--a;
			--b;
			g[a].emplace(b);
			g[b].emplace(a);
			++deg[a];
			++deg[b];
		}
		for (const auto e : deg) {
			if (e % 2 == 1) {
				return false;
			}
		}
		usize single_cnt = 0;
		for (const auto i : rep(0, n)) {
			if (g[i].size() == 2) {
				const usize a = *g[i].cbegin(), b = *g[i].crbegin();
				if (a == b) {
					++single_cnt;
					g[a].erase(i);
				}
				else {
					g[a].erase(i);
					g[a].emplace(b);
					g[b].erase(i);
					g[b].emplace(a);
				}
				g[i].clear();
			}
		}
		usize edge_cnt = 0;
		for (const auto &e : g) {
			edge_cnt += e.size();
		}
		edge_cnt /= 2;
		return edge_cnt + single_cnt * 2 >= 6;
	}

