        G[b][a] = 1;
        deg[a] += 1;
        deg[b] += 1;
    }
    REP(i, 1, N + 1) {
        if(deg[i] & 1) {
            print("No");
            return 0;
        }
    }
    REP(i, 1, N + 1) {
        if(deg[i] == 2 and SZ(G[i]) > 1) {
            vector<int> vs;
            REP(ii, G[i]) {
                vs.PB(ii->first);
            }
            deg[i] = 0;
            G[i].clear();
            G[vs[0]].erase(i);
            G[vs[1]].erase(i);
            G[vs[0]][vs[1]] += 1;
            G[vs[1]][vs[0]] += 1;
        }
