    //}
    int cnt = 0, Mdeg = 0;
    REP(i, 1, N + 1) {
        if(deg[i] > 0) {
            cnt += 1;
            Mdeg = max(Mdeg, deg[i]);
        }
    }
    if(cnt >= 4) {
