int N, M, A[1 << 18], B[1 << 18], deg[1 << 18], col[1 << 18], col2[1 << 18], cnts, cntv;
vector<int>X[1 << 17], Z[1 << 17], G;

void dfs(int pos) {
	if (col[pos] >= 1) return;
	col[pos] = cnts; G.push_back(pos);
	for (int i = 0; i < X[pos].size(); i++) {
		dfs(X[pos][i]);
	}
}

void dfs2(int pos) {
	if (col2[pos] >= 1) return;
	col2[pos] = cntv;
	for (int i = 0; i < Z[pos].size(); i++) dfs2(Z[pos][i]);
}

pair<int, int> solve(vector<int>I) {
	if (I.size() == 0) return make_pair(0, 0);

	vector<int>T;
	for (int i = 0; i < I.size(); i++) {
		if (deg[I[i]] >= 6) return make_pair(1, 3);
		if (deg[I[i]] == 4) T.push_back(I[i]);
	}

	if (T.size() == 0) return make_pair(1, 1);
	if (T.size() == 1) return make_pair(1, 2);
	if (T.size() >= 6) return make_pair(1, 3);

	for (int i = 0; i < T.size(); i++) {
		for (int j = i + 1; j < T.size(); j++) {
			for (int k : I) { Z[k].clear(); col2[k] = 0; }

			cntv = 0;

			for (int pos1 : I) {
				for (int pos2 : X[pos1]) {
					if (pos1 == T[i] || pos1 == T[j] || pos2 == T[i] || pos2 == T[j]) continue;
					Z[pos1].push_back(pos2);
				}
			}
			for (int k = 0; k < I.size(); k++) {
				if (col2[k] >= 1 || I[k] == T[i] || I[k] == T[j]) continue;
				cntv++; dfs2(I[k]);
			}

			if (cntv < X[T[i]].size() || cntv < X[T[j]].size()) return make_pair(1, 3);
		}
	}
	return make_pair(1, 2);
}

