	cin >> N >> M;
	for (int i = 1; i <= M; i++) {
		cin >> A[i] >> B[i];
		X[A[i]].push_back(B[i]); deg[A[i]]++;
		X[B[i]].push_back(A[i]); deg[B[i]]++;
	}

	for (int i = 1; i <= N; i++) {
		if (deg[i] % 2 == 0) continue;
		cout << "No" << endl;
		return 0;
	}

	int L = 0, R = 0;
	for (int i = 1; i <= N; i++) {
		if (col[i] >= 1) continue;
		G.clear(); cnts++;
		dfs(i);
		pair<int, int> Z = solve(G);
		L += Z.first; R += Z.second;
	}
	if (L <= 3 && 3 <= R) cout << "Yes" << endl;
	else cout << "No" << endl;
	return 0;
}

