using namespace std;

int next(int now,int last, multimap<int, int> &m) {
	auto it = m.lower_bound(now);
	if (it->second == last) it++;
	return it->second;
}

int main()
{
	int N, M;
	cin >> N >> M;
	vector<int> count(N + 1, 0);
	multimap<int, int> m;

	for (int i = 0; i < M; i++) {
		int a, b;
		cin >> a >> b;
		m.emplace(a, b);
		m.emplace(b, a);
		count[a]++;
		count[b]++;
	}

	int check = 0;
	int start = -1, end = -1;
	for (int i = 1; i <= N; i++) {
		if (count[i] % 2 == 1) {
			check = 0;
			break;
		}
		if (count[i] >= 6){
			check += 3;
		}
		if (count[i] == 4){
			if (start == -1) start = i;
			else end = i;
			check++;
		}
	}

	if (check >= 3) {
		cout << "Yes" << endl;
	} else if (check <= 1) {
		cout << "No" << endl;
	}
	else {
		int endcount = 0;
		auto it = m.lower_bound(start);
		for (int i = 0; i < 4; i++) {
			int tmp, now, last;
			now = it->second;

			last = start;
			while (true) {

				if (now == start) break;
				if (now == end) {
					endcount++;
					break;
				}
				tmp = now;
				now = next(now, last, m);
				last = tmp;
			}
			it++;
		}

		if (endcount == 4) {
			cout << "No" << endl;
		}
		else {
			cout << "Yes" << endl;
		}
	}
}

