struct UF {
	vi t;
	int cs;
	UF(int n){
		t.resize(n, -1);
		cs = n;
	}
	int find(int a){
		return t[a]<0 ? a : t[a] = find(t[a]);
	}
	void uni(int a, int b){
		a = find(a), b = find(b);
		if(a == b) return;
		--cs;
		if(t[a] < t[b]) swap(a,b);
		t[b] += t[a];
		t[a] = b;
	}
};

bool solve(){
	int n, m;
	cin >> n >> m;
	if(m < n+2) return false;
	vi a(m), b(m);
	rep(i,0,m) cin >> a[i] >> b[i];
	trav(x, a) --x;
	trav(x, b) --x;
	vi deg(n);
	trav(x, a) ++deg[x];
	trav(x, b) ++deg[x];
	trav(x, deg) if(x%2) return false;
	trav(x, deg) if(x >= 6) return true;
	if(m > n+2) return true;
	int r = -1;
	rep(i,0,n) if(deg[i] == 4) r = i;
	UF uf(n);
	rep(i,0,m) if(a[i] != r && b[i] != r) uf.uni(a[i], b[i]);
	if(uf.cs >= 3) return true;
	return false;
}

