	if (pos == goal && CT >= 2) {
		return true;
	}
	CT++;
	used[pos] = true;
	for (int i = 0; i < edge[pos].size(); i++) {
		if (edge[pos][i] != banned) {
			if (!used[edge[pos][i]] || (used[edge[pos][i]] && edge[pos][i] == goal && CT >= 3)) {
				if (f(edge[pos][i], goal, banned, CT))return true;
			}
		}
	}
	return false;
}

