using Graph = vector<set<int>>;
int dfs(Graph& G, int u, vector<bool>& vis, int& cnt){
  if(vis[u]){
    ++cnt;
    return u;
  }

  vis[u] = true;
  while(!G[u].empty()){
    int to = *begin(G[u]);
    G[u].erase(to);
    G[to].erase(u);
    int r = dfs(G, to, vis, cnt);
    if(r != u){
      vis[u] = false;
      return r;
    }
  }
  vis[u] = false;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N, M;
  cin >> N >> M;
  Graph G(N);

  REP(i,M){
    int u, v;
    cin >> u >> v;
    --u;
    --v;
    G[u].insert(v);
    G[v].insert(u);
  }

  REP(i,N){
    if(SZ(G[i]) % 2){
      cout << "No" << endl;
      return 0;
    }
  }

  int cnt = 0;
  vector<bool> vis(N);
  REP(i,N){
    while(!G[i].empty()){
      dfs(G, i, vis, cnt);
    }
  }

  cout << (cnt >= 3 ? "Yes" : "No") << endl;

  return 0;
}

