	EulerianPath P(n);
	For(i,0,m){
		ll x,y;cin>>x>>y;x--;y--;
		adj[x].pb(y);
		adj[y].pb(x);
		P.add_edge(x,y);
	}
	ll count=0;
	For(i,0,n) if(adj[i].size()%2!=0){
		cout<<"No"<<endl;return 0;
	}else if(adj[i].size()>=6){
		cout<<"Yes"<<endl;return 0;
	}else if(adj[i].size()==4){
		count++;
	}
	if(count>=3){
		cout<<"Yes"<<endl;return 0;
	}else if(count==2){
		ll a=-1,b=-1;
		For(i,0,n){
			if(a==-1 && adj[i].size()==4) a=i;
			else if(adj[i].size()==4) b=i;
		}
		P.find_euler_path(a);
		vector<int> C = P.circuit;
		ll times=0;
		for(ll x:C) if(x==b) times++;
		if(times%2){
