#include <iostream>
#include <cstdio>
#include <vector>
using namespace std;

const int N = 1e5;

struct Edge
{
    int x, y;
    bool us;

    Edge() {};
    Edge(int _x, int _y, bool _us): x(_x), y(_y), us(_us) {};
};

vector<int> g[N];
bool used[N];
Edge e[N];
int p[N];

int getOther(int u, int i)
{
    return (e[i].x) ^ (e[i].y) ^ u;
}

bool dfs(int v)
{
    //printf("%d:\n", v + 1);

    used[v] = true;
    for (int i : g[v])
    {
        static int u;
        u = getOther(v, i);
        if (!e[i].us || p[v] == i) continue;

        if (!used[u])
        {
            p[u] = i;
            if (dfs(u))
                return true;
        }
        else
        {
            e[i].us = false;
            for (; v != u; v = getOther(v, p[v]))
            {
                e[p[v]].us = false;
                //printf("%d ", v + 1);
            }
            //printf("%d\n", u + 1);

            return true;
        }
    }
    return false;
}

bool Try(int n)
{
    for (int v = 0; v < n; ++v)
    {
        p[v] = -1;
        used[v] = false;
    }
    for (int v = 0; v < n; ++v)
    {
        if (!used[v] && dfs(v))
            return true;
    }
    return false;
}

int main()
{
    int n, m;
    scanf("%d%d", &n, &m);

    for (int i = 0; i < m; ++i)
    {
        static int u, v;
        scanf("%d%d", &u, &v);
        --u; --v;
        e[i] = Edge(u, v, true);
        g[u].push_back(i);
        g[v].push_back(i);
    }

    for (int v = 0; v < n; ++v)
    {
        if ((int)g[v].size() & 1)
        {
            printf("No");
            return 0;
        }
    }

    for (int i = 0; i < 3; ++i)
    {
        if (!Try(n))
        {
            printf("No");
            return 0;
        }
    }

    printf("Yes");
}

