using namespace std;

int dfs_cnt = 0;
void dfs_bridge(int u, const vector<vector<int>> &g, int &cnt,
                    vector<int> &low, vector<int> &num, vector<int> &par)
{
    low[u] = num[u] = ++dfs_cnt;
    for (int v : g[u]) {
        if (!num[v]) {
            par[v] = u;
            dfs_bridge(v, g, cnt, low, num, par);
            if (low[v] > num[u]) {
                ++cnt;
            }
            low[u] = min(low[u], low[v]);
        } else if (v != par[u]) {
            low[u] = min(low[u], low[v]);
        }
    }
}

