    V<int> a(m), b(m);
    V<int> deg(n);
    for (int i = 0; i < m; i++) {
        cin >> a[i] >> b[i]; a[i]--; b[i]--;
        deg[a[i]]++; deg[b[i]]++;
    }

    for (int i = 0; i < n; i++) {
        if (deg[i] % 2) fack();
    }

    if (m > n + 2) good();
    if (n + 2 > m) fack();

    int s = -1;
    for (int i = 0; i < n; i++) {
        if (deg[i] == 6) good();
        if (deg[i] == 4) s = i;
    }

    auto uf = UnionFind(n);
    for (int i = 0; i < m; i++) {
        if (a[i] == s || b[i] == s) continue;
        uf.merge(a[i], b[i]);
    }

    if (uf.gn == 2) fack();
    else good();

    return 0;
}

