template<typename T>
class fixed_point : T {
  public:
    explicit constexpr fixed_point (T&& t) noexcept
      : T(std::forward<T>(t)) {}
    template<typename... Args>
    constexpr decltype(auto) operator()(Args&&... args) const
      {return T::operator()(*this, std::forward<Args>(args)...);}
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{std::forward<T>(t)};
}
int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  size_t n, m; std::cin >> n >> m;
  std::vector<std::vector<size_t>> graph(n);
  for (size_t _ = 0; _ < m; _++) {
    size_t a, b; std::cin >> a >> b;
    a--, b--;
    graph.at(a).push_back(b);
    graph.at(b).push_back(a);
  }
  auto yes = [&] {
    std::cout << "Yes" << std::endl;
    exit(0);
  };
  auto no = [&] {
    std::cout << "No" << std::endl;
    exit(0);
  };
  std::for_each(graph.begin(), graph.end(), [&](auto& v){
    if (v.size() % 2 != 0) no();
  });
  std::for_each(graph.begin(), graph.end(), [&](auto& v){
    if (v.size() >= 6) yes();
  });
  std::vector<size_t> fours;
  for (size_t i = 0; i < n; i++) {
    if (graph.at(i).size() == 4) fours.push_back(i);
  }
  if (fours.size() >= 3) yes();
  if (fours.size() <= 1) no();
  auto check = [&] (size_t x) {
    std::vector<int> ckd(n, false);
    ckd.at(x) = true;
    size_t root = (x == 0);
    fix ([&](auto dfs, int crr) -> void {
      ckd.at(crr) = true;
      for (auto const& nxt : graph.at(crr)) {
        if (ckd.at(nxt)) continue;
        dfs(nxt);
      }
    })(root);
    std::for_each(ckd.begin(), ckd.end(), [&](auto x){if (!x) yes();});
  };
  std::for_each(fours.begin(), fours.end(), check);
  std::cout << "No" << std::endl;
  return 0;
}

