using namespace std;

typedef long long ll;

const int MAX_N = 1e5 + 10;

int n, m;
bool inCycle[MAX_N];
vector <int> G[MAX_N];
int vis[MAX_N];
int path[MAX_N];
int nCycles = 0;
int H[MAX_N];
set <pair <int, int>> taken;

void dfs_buid (int u, int v, int h) {
  vector <int> pib;
  for (int v: G[u]) {
    if (H[v] == 0) {
      pib.push_back(v);
      H[v] = h + 1;
    }
  }
  for (int v: pib) dfs_buid(v, u, h + 1);
}

void dfs (int u, int p) {
  vis[u] = 1;
  for (int v: G[u]) {
    if (vis[v] == 2 or v == p) continue;
    if (vis[v] == 0) {
      path[v] = u;
      dfs(v, u);
    } else {
      nCycles++;
      int p = u;
      while (true) {
        inCycle[p] = true;
        if (p == v) break;
        pair <int, int> pp(p, path[p]);
        if (pp.first < pp.second) swap(pp.first, pp.second);
        if (taken.count(pp)) break;
        taken.insert(pp);
        p = path[p];
      }
    }
  }
  vis[u] = 2;
}

