    G[u].push_back(v);
    G[v].push_back(u);
  }
  H[1] = 1;
  dfs_buid(1, -1, 1);
  for (int u = 1; u <= n; u++) sort(all(G[u]), [&] (int u, int v) { return H[u] < H[v]; });
  dfs(1, -1);
  bool ok = true;
  for (int u = 1; u <= n; u++) ok &= inCycle[u];
  if (ok and nCycles >= 3) cout << "Yes" << endl;
  else cout << "No" << endl;
  return (0);
}

