  rep(i, n) if (mp[i].size() % 2) flag = 0;
  if (!flag) {
    cout << "No" << endl;
    return 0;
  }

  //次数が６以上->三分割
  //次数４が３以上->２回踏む閉路があればOK、なければ次数４の３点が分離して2つの閉路に入ってるので各２点間の異なるパスが2つ取れて組み合わせれば閉路完成
  //次数４が２個->２回踏む閉路があればOK、なければダメ
  //次数４が１個以下->muri

  int if6 = 0;
  vec<int> count4(0);
  rep(i, n) {
    if (mp[i].size() >= 6) if6 = 1;
    if (mp[i].size() == 4) count4.pb(i);
  }
