        rep(j, mp[cur].size()) {
          if (mp[cur][j] == start && dp[cur] != 2) {
            flag = 1;
            break;
          }
          if (dp[mp[cur][j]]) continue;
          cur = mp[cur][j];
          dp[cur] = 1;
          f = 1;
        }
