template<class E>
struct Articulation{
	using P = pair<int,E>;
	using VP = vector<P>;

	//in
	vector<vector<E>> G;

	//out
	vector<int> arts;
	vector<VP> biedges;

	//out(ConstructGraphAB)
	vector<vector<int>> GraphAB;


	//tmp
	vector<int> ord,low;
	int I;
	stack<P> st;

	Articulation(const vector<vector<E>>& G):G(G){	//calc arts,biedges
		int N = G.size();
		ord.assign(N,0);
		low.assign(N,0);
		I = 0;

		rep(i,N) if(ord[i]==0){
			while(!st.empty()) st.pop();
			dfs(i);
		}
	}

	void ConstructGraphAB(){
		int A = arts.size();		//[0,A)
		int B = biedges.size();		//[A,A+B)
		GraphAB.resize(A+B);

		int N = G.size();
		vector<int> a2id(N,-1);
		rep(i,A){
			a2id[arts[i]] = i;
		}

		rep(b,B){
			vector<int> vc;
			for(P p:biedges[b]){
				int from = p.fs;
				int to = p.sc.to;
				if(a2id[from]!=-1){
					vc.pb(a2id[from]);
				}
				if(a2id[to]!=-1){
					vc.pb(a2id[to]);
				}
			}
			sort(all(vc));
			vc.erase(unique(vc.begin(),vc.end()),vc.end());
			for(int v:vc){
				GraphAB[A+b].pb(v);
				GraphAB[v].pb(A+b);
			}
		}
	}

	void dfs(int v,int p = -1){
		ord[v]=++I;
		low[v]=ord[v];
		int c=0;
		bool isart=0;
		for(auto& e:G[v]) if(e.to!=p){
			int u = e.to;
			if(ord[u]<ord[v]) st.push(P(v,e));
			if(ord[u]) chmin(low[v],ord[u]);	//back edge
			else{
				dfs(u,v);
				c++;
				chmin(low[v],low[u]);
				if(low[u]>=ord[v]){
					isart = 1;
					vector<P> vp;
					while(true){
						P p=st.top();st.pop();
						vp.pb(p);
						if(p.fs==v && p.sc.to==u) break;
					}
					biedges.pb(vp);
				}
			}
		}
		if(p<0) isart=(c>1);
		if(isart) arts.pb(v);
	}

};
