	friend ostream& operator<<(ostream& o,const Edge& e){return o<<e.to;}
};


void Answer(bool b){
	if(b) cout << "Yes" << endl;
	else cout << "No" << endl;
	exit(0);
	return;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);		//DON'T USE scanf/printf/puts !!
	cout << fixed << setprecision(20);

	int N,M;
	cin >> N >> M;
	VV<Edge> G(N);
	rep(i,M){
		int x,y;
		cin >> x >> y;
		x--,y--;
		G[x].pb({y});
		G[y].pb({x});
	}
	rep(i,N){
		if(G[i].size()%2 == 1){
			Answer(false);
		}
	}

	int cnt = 0;
	int mx = 0;
	rep(i,N){
		if(G[i].size() > 2) cnt++;
		chmax(mx,(int)G[i].size());
	}
	if(cnt > 2){
		Answer(true);
	}
	if(cnt == 0) Answer(false);
	if(cnt == 1){
		if(mx>=6) Answer(true);
		Answer(false);
	}

	Articulation<Edge> art(G);
	if(art.arts.empty()) Answer(false);
	Answer(true);

}

