        g[u].insert(v);
        g[v].insert(u);
    }
    for (int v = 1; v <= n; ++v) {
        if (g[v].size() & 1) {
            cout << "No";
            return;
        }
        deg_v.insert({g[v].size(), v});
    }

    for (int v = 1; v <= n; ++v) {
        if (g[v].size() >= 6) {
            cout << "Yes";
            return;
        }
    }

    while (deg_v.size() > 1 && (*deg_v.begin()).first == 2) {
        int v = (*deg_v.begin()).second;
        deg_v.erase({g[v].size(), v});
        int a = *g[v].begin(), b = *g[v].rbegin();
        g[v].clear();
        deg_v.erase({g[a].size(), a});
        deg_v.erase({g[b].size(), b});
        g[a].erase(v);
        g[b].erase(v);
        g[a].insert(b);
        g[b].insert(a);
        deg_v.insert({g[a].size(), a});
        deg_v.insert({g[b].size(), b});
    }

    int cnt = 0;
    for (auto x : deg_v) {
        cnt += x.first;
    }
    cnt /= 2;

    for (int v = 1; v <= n; ++v) {
        cnt += g[v].count(v) / 2;
    }

    if (cnt >= 6) {
        cout << "Yes";
    } else {
        cout << "No";
    }

}

