typedef struct edge{
  int node, ck, rev;
  edge(int node, int ck, int rev) : node(node), ck(ck), rev(rev) {}
}edge;

int N, M;
vector<edge> adj[MAXN];

void add_edge(int node1, int node2){
  adj[node1].push_back({node2, 0, (int)adj[node2].size()});
  adj[node2].push_back({node1, 0, (int)adj[node1].size() - 1});
}

int dfs(int here){
  int ret = here;
  for(edge &val : adj[here]){
    if(val.ck == 0){
      val.ck = 1; adj[val.node][val.rev].ck = 1;
      return dfs(val.node);
    }
  }
  return ret;
}
int main(void){
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr), cout.tie(nullptr);

  cin >> N >> M;
  for(int x, y, i = 1 ; i <= M ; i++) {
