    add_edge(x, y);
  }

  int pos = 0;
  for(int i = 1 ; i <= N ; i++) if(adj[i].size() == 6) pos = i;

  int ans = 1;
  if(pos) {
    int end_pos = dfs(pos);
    for(int i = 1 ; i <= N ; i++) for(edge val : adj[i]) if(val.ck == 0) ans = 0;
    if(end_pos != pos) ans = 0;
  }
  else ans = 0;

  if(ans) cout << "Yes\n";
  else cout << "No\n";
  return 0;
}

