const int N = 100005;
int n, m, deg[N], tot = 1, nxt[4 * N], fst[N], to[4 * N], f[4 * N], cur[N], dis[N], S, T;

void addedge(int u, int v, int w) {
	nxt[++tot] = fst[u]; fst[u] = tot; to[tot] = v; f[tot] = w;
	nxt[++tot] = fst[v]; fst[v] = tot; to[tot] = u; f[tot] = 0;
}
bool bfs() {
	static int q[N];
	int st = 0, ed = 0;
	for (int i = 1; i <= n; ++i)
		dis[i] = -1, cur[i] = fst[i];
	q[ed++] = S;
	dis[S] = 0;
	while (st < ed) {
		int u = q[st++];
		for (int i = fst[u]; i; i = nxt[i])
			if (dis[to[i]] == -1 && f[i] > 0) {
				dis[to[i]] = dis[u] + 1;
				if (to[i] == T) return true;
				q[ed++] = to[i];
			}
	}
	return false;
}
int dfs(int u, int fl) {
	if (u == T || !fl) return fl;
	int used = 0;
	for (int &i = cur[u]; i; i = nxt[i])
		if (dis[to[i]] == dis[u] + 1) {
			int t = dfs(to[i], min(fl - used, f[i]));
			f[i] -= t, f[i ^ 1] += t, used += t;
			if (used == fl) break;
		}
	return used;
}

