const int maxn = 1e5 + 7;
int n, m, cnt[7];

int d[maxn];
int fir[maxn], nxt[2 * maxn], to[2 * maxn], e = 1;
bool usd[2 * maxn];
void add(int x, int y) {
	to[++e] = y; nxt[e] = fir[x]; fir[x] = e;
	to[++e] = x; nxt[e] = fir[y]; fir[y] = e;
}

bool inz[maxn];
int zz[maxn], t;
void dfs(int pos, int f) {
	int y, z;
	if(inz[pos]) {
		do{
			usd[zz[t]] = usd[zz[t] ^ 1] = 1;
			//printf("%d, %d\n", to[zz[t]], to[zz[t] ^ 1]);
			--d[to[zz[t]]]; --d[to[zz[t] ^ 1]];
		}while(to[zz[t--] ^ 1] != pos);
		return;
	}
	inz[pos] = 1;
	for (y = fir[pos]; y; y = nxt[y]) {
		if(usd[y]) continue;
		if((z = to[y]) == f) continue;
		zz[++t] = y; dfs(z, pos); 
		return;
	}
}

