int main() {
	fast_cin();
	int n, m;
	cin >> n >> m;
	if (n == 1) {
		cout << "No\n";
		return 0;
	}
	for (int i = 1; i <= m; ++i) {
		int u, v;
		cin >> u >> v;
		++deg[u]; ++deg[v];
		g[u].pb(v);
		g[v].pb(u);
	}
	vector<int> deg4;
	for (int i = 1; i <= n; ++i) {
		if (deg[i] % 2) {
			cout << "No\n";
			return 0;
		} else if (deg[i] >= 6) {
			cout << "Yes\n";
			return 0;
		} else if (deg[i] >= 4) {
			deg4.pb(i);
		}
	}
	if (deg4.size() >= 3) {
		cout << "Yes\n";
	} else if (deg4.size() <= 1) {
		cout << "No\n";
	} else if (cycle(deg4[0], deg4[1], 0)) {
		cout << "Yes\n";
	} else {
		cout << "No\n";
	}
}

bool cycle(int u, int v, int p) {
	seen[u] = true;
	for (auto &i : g[u]) {
		if (i == v or i == p) {
			continue;
		} else if (seen[i]) {
			return true;
		} else if (cycle(i, v, u)) {
			return true;
		}
	}
	return false;
}

