void dfs(int now, string path){
	if(cir.size() > 2)return;
	for(int i = 0;i < v[now].size();++i){
		string tmp = path;
		tmp.push_back(' ');
		tmp += to_string(v[now][i]);
		if(visited[v[now][i]]){
			cir.insert(tmp);
		}
		else{
			visited[v[now][i]] = true;
			dfs(v[now][i], tmp);
			visited[v[now][i]] = false;
		}
		if(cir.size() > 2)return;
	}
}
