void YES() {
	OUT("Yes")BR;
	exit(0);
}
void NO() {
	OUT("No")BR;
	exit(0);
}

signed main() {
	INIT;

	VAR(int, n, m);
	VEC_ROW(int, m, a, b);

	V<std::set<int>> g(n);

	REP(i, m) {
		--a[i]; --b[i];
		g[a[i]].emplace(b[i]);
		g[b[i]].emplace(a[i]);
	}

	int cnt4 = 0, cnt6 = 0;
	REP(i, n) {
		if (g[i].size() % 2 == 1) {
			OUT("No")BR;
			return 0;
		}
		cnt4 += g[i].size() == 4;
		cnt6 += g[i].size() >= 6;
	}
	if (cnt6 || cnt4 >= 3) YES();

	int cnt = 0;
	int start = 0;
	while (true) {
		while (start < n && g[start].empty()) ++start;
		if (start == n) break;

		std::set<int> set({ start });
		std::stack<int> st({ start });

		int now = start;
		int pre = -1;

		while (true) {

			[&] {
				while (true) {
					for (int to : g[now]) if (pre != to) {
						if (set.count(to)) {
							st.emplace(to);
							return;
						}
						else {
							pre = now;
							now = to;
							set.emplace(now);
							st.emplace(to);
							break;
						}
					}
				}
			}();

			int top = st.top(); st.pop();
			pre = top;
			now = st.top(); st.pop();
			while (now != top) {
				g[pre].erase(now);
				g[now].erase(pre);
				set.erase(now);
				pre = now;
				now = st.top(); st.pop();
			}
			g[pre].erase(now);
			g[now].erase(pre);
			++cnt;

			if (st.empty()) break;
			pre = st.top();
			st.emplace(now);
		}
	}
	if (cnt >= 3) YES();
	else NO();

	return 0;
}

