bool dfs( int cur, int prev, int goal, int ban,  const vector<vector<int>>& edge )
{
	for( auto& next : edge[cur] )
	{
		if( next == ban ) continue;
		if( next == prev ) continue;
		if( next == goal )
			return true;
		if( dfs( next, cur, goal, ban, edge ) )
			return true;
	}
	return false;
}

bool reach( int n, int a, int b, const vector<vector<int>>& edge )
{
	return dfs( a, a, a, b, edge );
}

