using namespace std;

int dfs_cnt = 0;
void dfs_bridge(int u, const vector<vector<int>> &g, int &cnt,
                    vector<int> &low, vector<int> &num, vector<int> &par)
{
    low[u] = num[u] = ++dfs_cnt;
    for (int v : g[u]) {
        if (!num[v]) {
            par[v] = u;
            dfs_bridge(v, g, cnt, low, num, par);
            if (low[v] > num[u]) {
                ++cnt;
            }
            low[u] = min(low[u], low[v]);
        } else if (v != par[u]) {
            low[u] = min(low[u], low[v]);
        }
    }
}

bool dfs(int u, vector<set<int>> &g, vector<int> &vis,
         set<int> &cur, vector<int> &st)
{
    vis[u] = 1;
    cur.insert(u);
    st.push_back(u);
    for (int v : g[u]) {
        if (!vis[v]) {
            if (dfs(v, g, vis, cur, st)) {
                return true;
            }
        } else if (cur.count(v) && v != st[st.size() - 2U]) {
            vector<int> er;
            while (st.back() != v) {
                er.push_back(st.back());
                st.pop_back();
            }
            er.push_back(st.back());
            st.pop_back();
            for (int i = 0; i + 1 < (int)er.size(); ++i) {
                int a = er[i], b = er[i + 1];
                g[a].erase(b);
                g[b].erase(a);
            }
            return true;
        }
    }
    cur.erase(u);
    st.pop_back();
    return false;
}

