const int N = 1e5;
std::vector<std::vector<int>> g, G;
int n, m;

int used[N];
int ans = 0;
int c = 1;
set<pair<int, int>> rem;
int ok = 0;

void dfs(int i, int f, int p = 0) {
  if(ok) return;
  if(i == f && p) {
    ok = 1;
    return;
  }
  dump(i);
  used[i] = c;
  auto ng = g[i];
  ng.clear();
  for(int j : g[i]) {
    if(ok || used[j] == c) {
      ng.push_back(j);
    } else {
      rem.insert(make_pair(i, j));
      rem.insert(make_pair(j, i));
      dfs(j, f, 1);
    }
  }
  g[i] = ng;
}

bool solve() {
  for(int i = 0; i < n; i++) if(g[i].size() % 2) return 0;
  for(int i = 0; i < 3; i++) {
    dump(i);
    c++;
    int v = -1;
    for(int k = 0; k < n; k++) if(g[k].size()) v = k;
    if(v == -1) return 0;
    dump(v);
    ok = 0;
    dfs(v, v);
    for(int k = 0; k < n; k++) {
      auto ng = g[k];
      ng.clear();
      for(int j : g[k]) {
        if(!rem.count(make_pair(k, j))) {
          ng.push_back(j);
        }
      }
      g[k] = ng;
    }
  }
  return 1;
}

int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  cin >> n >> m;
  g.resize(n);
  for(int i = 0; i < m; i++) {
    int a, b; std::cin >> a >> b;
    a--; b--;
    g[a].emplace_back(b);
    g[b].emplace_back(a);
  }
  G = g;
  cout << (solve() ? "Yes" : "No") << endl;
  return 0;
}

