#define N 200000 + 5

int n, m, sz, T[N], Deg[N], R[N], Last[N], Head[N];
bool ok = true, Vis[N];

struct Edge
{
	int next, node;
}h[N << 1];

inline void addedge(int u, int v)
{
	static int tot = 1;
	h[++ tot].next = Head[u], Head[u] = tot;
	h[tot].node = v;
}

void dfs(int z)
{
	while (Head[z])
	{
		int i = Head[z];
		int d = h[i].node;
		Head[z] = h[i].next;
		if (Vis[i >> 1]) continue ;
		Vis[i >> 1] = 1;
		dfs(d);
	}
	T[++ sz] = z;
}

