inline int read()
{
    int x=0,f=1;char ch=getchar();
    for (;ch<'0'||ch>'9';ch=getchar()) if (ch=='-') f=-1;
    for (;ch>='0'&&ch<='9';ch=getchar()) x=(x<<1)+(x<<3)+ch-'0';
    return x*f;
}

int main()
{
	int n=read(), m=read();
	for (int i=1; i<=m; i++) 
	{
		int u=read(), v=read();
		deg[u]++; deg[v]++;
		G[u].push_back(v); G[v].push_back(u);
	}
	for (int i=1; i<=m; i++) if (deg[i]&1) {puts("No"); return 0;}
	int deg_4=0;
	for (int i=1; i<=m; i++)
	{
		if (deg[i]>=6) {puts("Yes"); return 0;}
		if (deg[i]>=4) deg_4++;
	}
		if (deg_4>=3) puts("Yes");
	if (deg_4==2)
	{
		int u=0, v=0, path=0;
		for (int i=1; i<=n; i++) if (deg[i]==4) 
			{if (u) v=i; else u=i;}
		for (int w: G[u])
		{
			int cur=w, pre=u;
			while (cur^u && cur^v) 
				pre=G[cur][0]-G[cur][1]-pre, swap(cur, pre);
			if (cur==v) path++;
		}
		if (path==2) {puts("Yes"); return 0;}
	}
	puts("No");
	return 0;
}

