using namespace std;
const int N=400010;
struct A{
	int x,y;
}a[N];
int e[N],nex[N],head[N],ed=0;
int del[N],c[N],fa[N],d[N];
void adde(int x,int y){e[++ed]=y;nex[ed]=head[x];head[x]=ed;}
int flag;
void dfs(int x,int f){
	if(flag) return;
	fa[x]=f;
	for(int i=head[x];i;i=nex[i]){
		if(flag) return;
		if(e[i]==f) continue;
		if(!fa[e[i]]){
			if(flag) return;
			c[e[i]]=(i+1)/2;
			dfs(e[i],x);
		}
		else{
			if(flag) return;
			del[(i+1)/2]=1;
			for(int j=x;j!=e[i];j=fa[j]){
				del[c[j]]=1;
			}
			flag=1;
			return;
		}
	}
}
int n,m;
void solve(){
	int i,m0=0;
	memset(head,0,sizeof(head));ed=0;
	memset(d,0,sizeof(d));flag=0;
	memset(fa,0,sizeof(fa));
	memset(del,0,sizeof(del));
	for(i=1;i<=m;i++){
		adde(a[i].x,a[i].y);
		adde(a[i].y,a[i].x);
		d[a[i].x]++;d[a[i].y]++;
	}
	for(i=1;i<=n;i++)
		if(d[i]){
			dfs(i,-1);
			break;
		}
	for(i=1;i<=m;i++)
		if(!del[i]) a[++m0]=a[i];
	m=m0;
}
int main(){
	int i;
	scanf("%d %d",&n,&m);
	for(i=1;i<=m;i++){
		scanf("%d %d",&a[i].x,&a[i].y);
		d[a[i].x]++;d[a[i].y]++;
	}
	for(i=1;i<=n;i++)
		if(d[i]%2==1) break;
	if(i<=n){printf("No\n");return 0;}
	for(i=1;i<=3;i++){
		solve();
		if(m==0) break;
	}
	if(i>=3) printf("Yes\n");
	else printf("No\n");
	return 0;
}

