using namespace std;
const int MAXN = 4e5+5;
set<pair<int,int>> v1[MAXN];
stack<int> q1;
int q,w;
vector<int> res;
vector<int> ans;
int main(){
    int n,m;
    cin>>n>>m;
    for(int i=1;i<=m;i++){
        int x,y;
        cin>>x>>y;
        v1[x].insert(make_pair(y,i));
        v1[y].insert(make_pair(x,i));

    }
    int mxdeg = 0;
    int cnt4 =0;
    for(int i=1;i<=n;i++){
        if(v1[i].size()%2 == 1){
            cout<<"No"<<endl;
            return 0;
        }
        if(v1[i].size() ==4){
            cnt4++;
        }
        mxdeg = max(mxdeg,(int)v1[i].size());
    }
    if(mxdeg>=6){
        cout<<"Yes"<<endl;
        return 0;
    }
    if(mxdeg<=2){
        cout<<"No"<<endl;
        return 0;
    }
    if(cnt4>=3){
        cout<<"Yes"<<endl;
        return 0;
    }
    if(cnt4<=1){
        cout<<"No"<<endl;
        return 0;
    }
    for(int i=1;i<=n;i++){
        if(v1[i].size() == 4){
            if(!q1.size()){
                q1.push(i);
                q = i;
            }else{
                w = i;
            }

        }
    }
    while(!q1.empty()){
        int curr = q1.top();
        res.push_back(curr);

        if(v1[curr].size() == 0){

            q1.pop();
        }
        for(auto x:v1[curr]){
            //cout<<curr<<" "<<x.first<<" "<<x.second<<endl;
            int val = x.first;
            int ind = x.second;
            q1.push(val);
            v1[val].erase(v1[val].find(make_pair(curr,ind)));
            v1[curr].erase(v1[curr].find(make_pair(val,ind)));
            break;

        }
    }
    for(int x:res){
        if(x==q||x==w){
            ans.push_back(x);

        }
    }
    for(int i=0;i<ans.size()-1;i++){
        if(ans[i]==ans[i+1]){

            cout<<"Yes"<<endl;
            return 0;
        }
    }
    cout<<"No"<<endl;
}

