#include <bits/stdc++.h>
using namespace std;
constexpr int N = 1E5;
int n, m;
vector<int> e[N];
int pre[N], to[2 * N];
bool used[2 * N];
void yes() {
    cout << "Yes" << endl;
    exit(0);
}
void no() {
    cout << "No" << endl;
    exit(0);
}
void bfs(int s) {
    memset(pre, -1, n * sizeof(int));
    queue<int> que;
    pre[s] = -2;
    que.push(s);
    while (!que.empty()) {
        int u = que.front();
        que.pop();
        for (int i : e[u]) {
            if (used[i])
                continue;
            int v = to[i];
            if (pre[v] == -1) {
                pre[v] = i;
                que.push(v);
            }
        }
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        to[2 * i] = --v;
        to[2 * i + 1] = --u;
        e[u].push_back(2 * i);
        e[v].push_back(2 * i + 1);
    }
    vector<int> d4;
    for (int i = 0; i < n; ++i)
        if ((int)e[i].size() % 2 == 1)
            no();
    for (int i = 0; i < n; ++i) {
        if ((int)e[i].size() >= 6)
            yes();
        if ((int)e[i].size() == 4)
            d4.push_back(i);
    }
    if ((int)d4.size() >= 3)
        yes();
    if ((int)d4.size() <= 1)
        no();
    for (int i = 0; i < 3; ++i) {
        bfs(d4[0]);
        if (i == 2)
            break;
        int u = d4[1];
        while (u != d4[0]) {
            used[pre[u]] = true;
            u = to[pre[u] ^ 1];
        }
    }
    if (pre[d4[1]] != -1)
        no();
    yes();
    return 0;
}

//頂点の次数が全て偶数じゃなきゃダメ。そうでないなら貪欲に閉路を作って、3つ作れたらOK. 作れなければダメ。
