ll cnt[200005]={0};
bool dfs(ll pos,ll st,bool f){
  if(f&&pos==st) return true;
  for(int i=0;i<node[pos].size();i++){
    int to=node[pos][i].first,idx=node[pos][i].second;
    if(!used2[to]&&!used[idx]){
      used[idx]=true;
      used2[to]=true;
      if(dfs(to,st,true)) {
        used[idx]=true;
        return true;
      }
      else{
        used[idx]=false;
      }
    }
  }
  return false;
}
bool dfs2(ll pos,ll st,bool f){
  //cout<<pos<<" "<<st<<" "<<(f?"O":"X")<<endl;
  if(f&&pos==st) return true;
  for(int i=0;i<node[pos].size();i++){
    int to=node[pos][i].first,idx=node[pos][i].second;
    if(!used2[to]&&!used3[idx]&&!used[idx]){
      used3[idx]=true;
      used2[to]=true;
      if(dfs2(to,st,true)) {
        used3[idx]=true;
        return true;
      }
      else{
        if(!used[idx]) used3[idx]=false;
      }
    }
  }
  return false;
}
int main(){
  ll n,m;
  cin>>n>>m;
  for(int i=0;i<=max(n,m);i++){
    used[i]=false;
    used2[i]=false;
    used3[i]=false;
  }
  vector<P> qr;
  qr.push_back(P(0,0));
  for(int i=1;i<=m;i++){
    ll a,b;
    cin>>a>>b;
    qr.push_back(P(a,b));
    node[a].push_back(P(b,i));
    node[b].push_back(P(a,i));
  }
  if(!dfs(1,1,false)){
    cout<<"No"<<endl;
    return 0;
  }

  for(int i=0;i<=max(n,m);i++) {
    used2[i]=false;
    used3[i]=used[i];
  }
  for(int i=1;i<=m;i++){
    if(!used3[i]){
      if(!dfs2(qr[i].first,qr[i].first,false)){
        cout<<"No"<<endl;
        return 0;
      }
      break;
    }
    if(i==m){
      cout<<"No"<<endl;
      return 0;
    }
