int n,m;

bool triangle() {
	for(int i = 0;i < n;i++) {
		for(auto itr1 = nodes[i].path.begin();itr1 != nodes[i].path.end();itr1++) {
			for(auto itr2 = nodes[i].path.begin();itr2 != itr1;itr2++) {
				if(nodes[(*itr1)-1].path.find(*itr2) != nodes[(*itr1)-1].path.end()) {
					int a[3] = {*itr1-1,*itr2-1,i};
					for(int j = 0;j < 3;j++) {
						nodes[a[j]].path.erase(a[(j+1)%3]);
						nodes[a[j]].path.erase(a[(j+2)%3]);
					}
					return true;
				}
			}
		}
	}
	return false;
}

