int main()
{
//	freopen("in.txt", "r", stdin);
	//ios::sync_with_stdio(false); cin.tie(0);

	int n, m;
	scanf("%d%d", &n, &m);
	FOR (i, 0, m)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		x--;
		y--;
		g[x].insert(y);
		g[y].insert(x);
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i]) & 1) no();
	}

	stack<int> st;
	VI a;

	st.push(0);

	while(SZ(st))
	{
		int x = st.top();
		if (SZ(g[x]) == 0)
		{
			a.PB(x);
			st.pop();
			continue;
		}

		int y = *g[x].begin();

		g[x].erase(g[x].find(y));
		g[y].erase(g[y].find(x));

		st.push(y);
	}

	FOR (i, 0, n)
	{
		if (SZ(g[i])) throw -1;
	}

	a.pop_back();

//	FOR (i, 0, SZ(a))
//	{
//		cout<<a[i]<<' ';
//	}
//	cout<<endl;

	FOR (i, 0, n)
	{
		L[i] = -1;
	}

	int last = -1;
	int first = INF;

	FOR (i, 0, SZ(a))
	{
		int x = a[i];
		if (L[x] == -1)
		{
			L[x] = i;
			F[x] = i;
			continue;
		}

		first = min(first, i);

//		cout<<i<<": "<<x<<' '<<F[x]<<' '<<L[x]<<' '<<first<<' '<<last<<endl;

		if (F[x] < last) yes();
		if (L[x] >= first) yes();

		last = max(last, L[x]);
		L[x] = i;
	}

	no();

}

