const int MX = 100005;
int n, m, u, v, c, to[2*MX], vis[MX], d[MX], p[MX];
vi adj[MX];
bitset<2*MX> ex, in;
set<int> st[MX];

void cyc (int u) {
	int v = u, nd = 0;
	do {
		nd += int(in[u]);
		in[u] = 1;

		st[u].insert(p[u]);
		st[p[u]].insert(u);

		d[u]--;
		d[p[u]]--;
		u = p[u];
	} while (v != u && p[u]);
	c += max(1, nd);
}

void dfs (int u, int par) {
	vis[u] = 1;
	for (int i : adj[u]) {
		int v = to[i];
		if (v == par || st[u].count(v)) continue;

		if (vis[v]) {
			p[v] = u;
			cyc(u);
		} else {
			p[v] = u;
			dfs(v, u);
		}

		return;
	}
}

int main () {
	ios_base::sync_with_stdio(0); cin.tie(0);

	ex.set();

	cin >> n >> m;
	for (int i = 0; i < m; i++) {
		cin >> u >> v;
		to[2*i] = v;
		to[2*i+1] = u;
		adj[u].pb(i*2);
		adj[v].pb(i*2+1);
		d[u]++, d[v]++;
	}

	for (int i = 1; i <= n; i++)
		if (d[i] & 1)
			no();

	for (int i = 0; i < 3; i++) {
		for (int i = 1; i <= n; i++)
			if (d[i]) {
				memset(vis, 0, sizeof(vis));
				dfs(i, -1);
				if (c >= 3)
					yes();
			}
	}

	no();

	return 0;
}

