// Union-Find
struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};






int main(){
    int N,M;
    cin >> N >> M;
    vector<int>a(M);
    vector<int>b(M);
    for(int i=0; i<M; i++){
        cin >> a[i] >> b[i];
    }

    vector<int>ver(N,0);
    for(int i=0; i<M; i++){
        ver[a[i]-1]++;
        ver[b[i]-1]++;
    }

    int intersection4 = 0; // 4つ以上の頂点と隣接する頂点の数
    int intersection6 = 0; // 6
    bool ans = true;
    for(int i=0; i<N; i++){
        if(ver[i] % 2 != 0){
            ans = false;
        }
        if(ver[i] >= 4){
            intersection4++;
        }
        if(ver[i] >= 6){
            intersection6++;
        }
    }
    if(intersection4 < 2 && intersection6 == 0){
        ans = false;
    }



    // 以下乱雑コード
    if(intersection4 == 2 && intersection6 == 0){
        int p; // intersectionの番号
        auto itr = ver.begin();
        itr = find(itr, ver.end(), 4);
        p = itr - ver.begin() + 1;

