const int mod=1000000007,MAX=100003,INF=1<<30;
vector<int> S[MAX];
map<pair<int,int>,int> M;

int DFS(int u,int v){
    int ans=0;
    stack<pair<int,int>> ST;
    for(int i=0;i<S[u].size();i++){
        int a=S[u][i];
        ST.push(make_pair(u,a));
        M[make_pair(u,a)]++;
    }

    while(!ST.empty()){
        int a=ST.top().first;
        int b=ST.top().second;
        ST.pop();
        if(b==v){
            ans++;
            continue;
        }
        for(int i=0;i<S[b].size();i++){
            int c=S[b][i];
            if(M[make_pair(b,c)]) continue;
            ST.push(make_pair(b,c));
            M[make_pair(b,c)]++;
        }
    }

    return ans;
}

