#include "bits/stdc++.h"
using namespace std;

const int MAX_N = 100010;
int par[MAX_N];
int rnk[MAX_N];

void init(int n) {
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rnk[i] = 0;
    }
}

int find(int x) {
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rnk[x] < rnk[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rnk[x] == rnk[y]) rnk[x]++;
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

void solve() {
    int N, M;
    cin >> N >> M;
    vector<vector<int>> edge(M, vector<int>(2));
    vector<int> g(N);
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edge.at(i).at(j);
            edge.at(i).at(j)--;
            g.at(edge.at(i).at(j))++;
        }
    }
    int ans = 0;
    for (int i = 0; i < N; i++) {
        if (g.at(i) % 2) {
            cout << "No" << endl;
            return;
        }
        ans += g.at(i) / 2 - 1;
    }
    init(N);
    for (int i = 0; i < M; i++) {
        unite(edge.at(i).at(0), edge.at(i).at(1));
    }
    int compo = 0;
    for (int i = 0; i < N; i++) {
        if (find(i) == i) compo++;
    }
    if (ans + compo > 2) cout << "Yes" << endl;
    else cout << "No" << endl;
    return;
}

int main() {
    solve();
}

