const int N = 1e5+10, M = 1e5+10;
vector<pair<int, int> > g[N];
int cur[N], d[N], lasts[N], n, m;
bool used[M];
vector<int> tour;

void dfs(int s) {
	while(cur[s] != g[s].size()) {
		if (used[g[s][cur[s]].second]) {
			++cur[s];
			continue;
		}
		auto p = g[s][cur[s]++];
		used[p.second] = true;
		dfs(p.first);
	}
	tour.push_back(s);
}

