int main(void){

	int v, e; scanf("%d %d", &v, &e);
	std::vector<std::vector<int>> edges(v+1);
	for(int i=0; i<e; i++){
		int v1, v2; scanf("%d %d", &v1, &v2);
		edges[v1].push_back(v2);
		edges[v2].push_back(v1);
	}

	// Odd vertex -> NO
	for(int i=1; i<=v; i++){
		if(edges[i].size() % 2 != 0){
			printf("NO");
			return 0;
		}
	}

	std::vector<bool> searched(v+1, false);
	int simplestgroup = 0, minigroup = 0, complexgroup = 0;
	for(int i=1; i<=v; i++){
		if(!searched[i]){ // isolated vertex
			if(edges[i].size() == 0){
				searched[i] = true;
				continue;
			}
			else{ // Non-isolated vertex; find group
				std::vector<int> stack = {i}; searched[i] = true;
				int v2 = 0, v4 = 0, v6p = 0;
				while(!stack.empty()){
					int now = stack.back(); stack.pop_back();
					if(edges[now].size() == 2) v2++;//v2.push_back(now);
					else if(edges[now].size() == 4) v4++;//v4.push_back(now);
					else v6p++;//v6.push_back(now);
					for(auto next: edges[now]){
						if(!searched[next]){
							searched[next] = true;
							stack.push_back(next);
						}
					}
				}
				if(v6p > 0 || v4 > 1) complexgroup++;
				else if(v2 == 3) simplestgroup++;
				else minigroup++; 
			}
		}
	}

	//printf("Complex %d, Simplest %d, Mini %d\n", complexgroup, simplestgroup, minigroup);
	if(complexgroup > 0 || simplestgroup + minigroup * 2 >= 3) printf("YES");
	else printf("NO");

	return 0;
}

