using namespace std;

int n, m;
vector<int> et[100000];
vector<int> rev[100000];
vector<bool> used[100000];
int cnt[100000];

bool make_cycle() {
	static int t[100000];
	int i, j;
	int INF = 11451419;

	for (i = 0; i < n; i++) t[i] = INF;
	for (i = 0; i < n; i++) if (cnt[i] > 0) break;
	//cout << "start = " << i << endl;

	int prev = -1;
	int pos = i;
	int nowT = 0;
	vector<int> poses;
	vector<int> ids;
	while (t[pos] == INF) {
		//cout << "pos = " << pos << endl;
		t[pos] = nowT;
		poses.push_back(pos);
		for (j = 0; j < et[pos].size(); j++) {
			if (used[pos][j]) continue;
			if (et[pos][j] == prev) continue;
			break;
		}
		if (j == et[pos].size()) { /*cout << "False" << endl;*/ return false; }
		int nxt = et[pos][j];
		//cout << "nxt = " << nxt << endl;
		prev = pos;
		//cout << "prev = " << pos << endl;
		pos = nxt;
		ids.push_back(j);
		nowT++;
	}
	poses.push_back(pos);

	for (i = t[pos]; i < poses.size() - 1; i++) {
		int u = poses[i];
		int v = poses[i + 1];
		//cout << "u, v = " << u << ", " << v << endl;
		used[u][ids[i]] = true;
		used[v][rev[u][ids[i]]] = true;
	}
	return true;
}

signed main() {
	int i, j;

	cin >> n >> m;
	rep(i, m) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		et[a].push_back(b); rev[a].push_back(et[b].size());
		et[b].push_back(a); rev[b].push_back(et[a].size() - 1);
	}

	rep(i, n) {
		used[i].resize(et[i].size());
		rep(j, used[i].size()) used[i][j] = false;
		cnt[i] = et[i].size();
	}

	rep(i, n) {
		if (et[i].size() % 2 == 1) { cout << "No" << endl; return 0; }
	}

	rep(i, 3) {
		bool res = make_cycle();
		if (!res) { cout << "No" << endl; return 0; }
	}

	cout << "Yes" << endl;
	return 0;
}

