bool solve() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n+1);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    for (int i = 1; i <= n; ++i) {
        if (g[i].size() % 2 == 1) return false;
    }

    vector<int> qv;
    for (int i = 1; i <= n; ++i) {
        if (g[i].size() >= 6) return true;
        if (g[i].size() == 4) {
            qv.push_back(i);
            if (qv.size() >= 3) return true;
        }
    }
    if (qv.size() < 2) return false;

    for (auto &e: g[qv[0]]) {
        int v = e;
        int p = qv[0];
        while (v != qv[0] && v != qv[1]) {
            if (g[v][0] == p) swap(g[v][0], g[v][1]);
            p = v;
            v = g[v][0];
        }
        if (v == qv[0]) return true;
    }

    return false;
}

int main() {
    if (solve()) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MX = 100000;

multiset<int> G[MX];
int loops = 0;

void remove(int v) {
	int a = *G[v].begin();
	int b = *G[v].rbegin();

	G[v].clear();

	G[a].erase(v);
	G[b].erase(v);

	if (a == b) {
		loops++;

		if (G[a].size() == 2) remove(a);
		if (G[b].size() == 2) remove(b);
	}
	else {
		G[a].insert(b);
		G[b].insert(a);
	}
}

int main() {
	int n, m;
	ignore = scanf("%d %d", &n, &m);
	for (int i = 0, u, v; i < m; i++) {
		ignore = scanf("%d %d", &u, &v);
		u--;
		v--;
		G[u].insert(v);
		G[v].insert(u);
	}

	bool bad = false;
	for (int v = 0; v < n; v++) {
		if (G[v].size() == 2) remove(v);
		if (G[v].size() % 2 == 1) bad = true;
	}

	int V = 0, E = 0;
	for (int v = 0; v < n; v++) {
		if (G[v].empty() == false) V++;
		E += G[v].size() / 2;
	}

	bool ok = (E / 2 + loops >= 3);

	printf("%s\n", ok && (bad == false) ? "Yes" : "No");

	return 0;
}

