#include <bits/stdc++.h>
using namespace std;
const int N = 2e5+5;
vector<int> graph[N];

int a[N],b[N];

int dfn[N],low[N];
int piv = 1,par[N];
void dfs(int x, int p){
    dfn[x] = low[x] = ++piv;
    par[x] = p;
    for(int i=0; i<graph[x].size(); i++){
        int id = graph[x][i];

        int w= a[id]^b[id]^x;
        if(w == p) continue;
        if(!dfn[w]){
            dfs(w, x);
            low[x] = min(low[x], low[w]);
        }
        else{
            low[x] = min(low[x], dfn[w]);
        }
    }
}

bool vis[N];
int cpiv = 1;
vector<int> Edge[N];

int sz[N],height[N];
void color(int x, int c){
    vis[x] = 1;
    if(c>0)
        ++sz[c];

    for(int i=0; i<graph[x].size(); i++){
        int id = graph[x][i];
        int w= a[id]^b[id]^x;
        if(vis[w]){
            if(height[w]<height[x]-1){
                Edge[c].push_back(id);
            }
            continue;
        }
        height[w]= height[x]+1;
        if(dfn[x] <= low[w]){
            ++cpiv;
            ++sz[cpiv];
            Edge[cpiv].push_back(id);
            color(w, cpiv);
        }
        else{
            Edge[c].push_back(id);
            color(w, c);
        }
    }
}

vector<int> adj[N];

int dp[N];
//자자 중대장은 너희에게 실망했다.
int pos;

int num[N];

vector<pair<int,int> > edgeList;

void dfs2(int node,int p) {
   num[node] = pos++;
   for(int i=0;i<adj[node].size();++i) {
      int ch = adj[node][i];
      if(ch==p) {
         continue;
      }
      if(num[ch]==0) {
         dfs2(ch,node);
      } else if(num[ch]<num[node]) {
         edgeList.push_back(make_pair(num[ch],num[node]));
      }
   }
}

int solveDp(int node,int n) {
   if(node>n) {
      return 0;
   }
   int &ret = dp[node];
   if(ret!=-1) {
      return ret;
   }
   ret = 0;
   int pos = lower_bound(edgeList.begin(),edgeList.end(), (make_pair(node,0)) ) - edgeList.begin();
   if(pos== edgeList.size()) {
      return 0;
   }
   if(edgeList[pos].first != node) {
      return solveDp(node+1,n);
   }
   int add = 1;
   ret = max(ret, 1 + solveDp(edgeList[pos].second,n));
   for(int x = 1;x<=2 && pos + x*2< edgeList.size() && edgeList[pos+x*2].first == node;++x) {
      int g = edgeList[pos+x*2].second;
      ret = max(ret, 1 + x + solveDp(g,n));
   }
   return ret;
}
void solve() {
   int n,m;
   scanf("%d%d",&n,&m);
   for(int i=0;i<m;++i) {
      scanf("%d%d",&a[i],&b[i]);
      graph[a[i]].push_back(i);
      graph[b[i]].push_back(i);
   }
   for(int i=1;i<=n;++i) {
      if(dfn[i]==0) {
         dfs(i,0);
      }
   }
   for(int i=1;i<=n;++i) {
      if(!vis[i]) {
         color(i,0);
      }
   }
   int ret = 0;
   for(int c= 1;c<=cpiv;++c) {
      if(sz[c]<3) {
         continue;
      }
      for(int j = 0;j<=sz[c] + 15;++j) {
         dp[j] = -1;
      }
      int root = -1;
      pos = 1;
      for(int j = 0;j<Edge[c].size();++j) {
         int id = Edge[c][j];
         root = a[id];
         num[a[id]] = num[b[id]] = 0;
         adj[a[id]].push_back(b[id]);
         adj[b[id]].push_back(a[id]);
      }

      dfs2(root,0);
      sort(edgeList.begin(),edgeList.end());
      ret += solveDp(1,sz[c]);
      if(ret>=3) {
         printf("Yes\n");
         return;
      }
      for(int j = 0;j<Edge[c].size();++j) {
         int id = Edge[c][j];
         adj[a[id]].clear();
         adj[b[id]].clear();
      }
      edgeList.clear();
   }
   printf("No\n");
}
int main()
{
    //freopen("input.txt","r",stdin);
    solve();
}

