    if(u == s) return -1;
    if(u == t) return 1;
    for(auto i=g[u].begin(); i!=g[u].end(); i=g[u].erase(i)) {
        if(*i == p) continue;
        int d = dfs(*i, u, s, t);
        if(d) return d;
    } return 0;
}

