typedef long long ll;

const int n = 1e5 + 10;

int N, M;
vector<int> G[n];

bool vis[n];
stack<int> S;
int res;

void dfs(int cur){
  //cout << cur << endl;
  if(vis[cur]){
    int x;
    do{
      x = S.top();
      S.pop();
      vis[x] = false;
    } while(x != cur);
    res++;
  }
  vis[cur] = true;
  S.push(cur);
  while(!G[cur].empty()){
    int x = G[cur].back();
    G[cur].pop_back();
    dfs(x);
  }
}

int main(){
  cin >> N >> M;
  for(int i=0; i<M; i++){
    int a, b;
    cin >> a >> b;
    a--; b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  bool flag = true;
  int cnt = 1;
  for(int i=0; i<N; i++){
    int g = G[i].size();
    if(g%2){
      flag = false;
    }
    cnt += (g-2)/2;
  }

  if(!flag || cnt < 3){
    cout << "No" << endl;
    return 0;
  }
  dfs(0);
  if(res >= 3){
    cout << "Yes" << endl;
  }
  else{
    cout << "No" << endl;
  }

  return 0;
}

