const int N = 1e5;
struct Edge
{
	int v,nxt;
} e[(N<<1)+3];
int fe[N+3];
int du[N+3];
int n,m,en;

void addedge(int u,int v)
{
	du[u]++;
	en++; e[en].v = v;
	e[en].nxt = fe[u]; fe[u] = en;
}

int dfs(int u,int prv,int s)
{
	if(du[u]==4) {return u==s;}
	for(int i=fe[u]; i; i=e[i].nxt)
	{
		int v = e[i].v; if(v==prv) continue;
		return dfs(v,u,s);
	}
}

int main()
{
	scanf("%d%d",&n,&m); en = 1;
	for(int i=1; i<=m; i++)
	{
		int u,v; scanf("%d%d",&u,&v); assert(u!=v);
		addedge(u,v); addedge(v,u);
	}
	int cnt6 = 0,cnt4 = 0,cntodd = 0;
	for(int i=1; i<=n; i++) {if(du[i]>=6) cnt6++; else if(du[i]==4) cnt4++; else if(du[i]&1) cntodd++;}
	if(cntodd) {puts("No"); return 0;}
	else if(cnt6) {puts("Yes"); return 0;}
	else if(cnt4>=3) {puts("Yes"); return 0;}
	else if(cnt4<=1) {puts("No"); return 0;}
	int u = 0,v = 0;
	for(int i=1; i<=n; i++) if(du[i]==4) {u?v=i:u=i;}
	int ans = 0;
	for(int i=fe[u]; i; i=e[i].nxt)
	{
		ans |= dfs(e[i].v,u,u);
	}
	if(ans) puts("Yes"); else puts("No");
	return 0;
}

