                    circuit_found++;
                    break;
                }
                list.push_back(this_i + to_string(j));
            }
            if(list.size() == 0)
                break; // no loop found
        }
        // remove found circuit
        if(looped){
        string this_circuit = list.back();
        for(size_t i = 0; i < this_circuit.length()-1; i++)
