bool return_start(int v, int start, int goal, vector<int> *es) {
    int prev = start;
    while (v != start && v != goal) {
        for (int n: es[v]) {
            if (n != prev) {
                prev = v;
                v = n;
                break;
            }
        }
    }
    return (v == start);
}

bool has_three(vector<int> four_neighber, vector<int> *es) {
