    int N,M;
    cin >> N >> M;
    vector<int>a(M);
    vector<int>b(M);
    for(int i=0; i<M; i++){
        cin >> a[i] >> b[i];
    }

    vector<int>ver(N,0);
    for(int i=0; i<M; i++){
        ver[a[i]-1]++;
        ver[b[i]-1]++;
    }

    int intersection4 = 0; // 4つ以上の頂点と隣接する頂点の数
    int intersection6 = 0; // 6
    bool ans = true;
    for(int i=0; i<N; i++){
        if(ver[i] % 2 != 0){
            ans = false;
        }
        if(ver[i] >= 4){
            intersection4++;
        }
        if(ver[i] >= 6){
            intersection6++;
        }
    }
    if(intersection4 < 2 && intersection6 == 0){
        ans = false;
    }



    // 以下乱雑コード
    if(intersection4 == 2 && intersection6 == 0){
        int p; // intersectionの位置
        auto itr = ver.begin();
        itr = find(itr, ver.end(), 4);
        p = itr - ver.begin();

        UnionFind tree(N);
        for(int i=0; i<M; i++){
            if(a[i]!=p && b[i]!=p){
                tree.unite(a[i]-1, b[i]-1);
            }
        }

        int cnt=0;
        for(int i=0;i<N;i++){
            if(!tree.same(0,i)){
                tree.unite(0, i);
                cnt++;
            }
        }
        if(cnt == 2){
            ans = false;
        }
    }




    if(ans){
        cout << "Yes";
    }else{
        cout << "No";
    }
    return 0;
}

