int a, b;

bool cmp(int a, int b) {
    return graph[a].size() > graph[b].size();
}

void dfs(int u) {
    vis[u] = true;
    vector < int > aux;
    for (int v : graph[u])
        aux.push_back(v);
    sort(aux.begin(), aux.end(), cmp);

    for (int v : aux) {
        if (!vis[v]) {
            prv[v] = u;
            dfs(v);
        }
        else if (v != prv[u]) {
            if (!cyc) {
                cyc = true;
                a = u; b = v;
            }
        }
    }
}

