bool is[100010];

bool dfs( int cur, int cnt, int goal, const vector<vector<int>>& edge )
{
	is[cur] = true;
	for( auto& next : edge[cur] )
	{
		if( next == goal && cnt >= 2 )
			return true;
		if( is[next] )
			continue;
		if( dfs( next, cnt + 1, goal, edge ) )
			return true;
	}
	return false;
}

bool reach( int n, int a, int b, const vector<vector<int>>& edge )
{
	memset( is, 0, sizeof(is) );
	is[b] = true;
	return dfs( a, 0, a, edge );
}

