//end of templates

VVPII G; // {to, edge id}
VI euler;
VI vis, edge_taken;

void euler_DFS(int v = 0) {
    vis[v] = 1;

    while(SZ(G[v])) {
        int u, e;
        tie(u, e) = G[v].back();
        G[v].pop_back();
        if(!edge_taken[e]) {
            edge_taken[e] = 1;
            euler_DFS(u);
            euler.EB(v);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    G.RS(n);
    int edges = 0;
    while(m --> 0) {
        int a, b;
        cin >> a >> b;
		G[--a].EB(--b, edges);
		G[b].EB(a, edges++);
    }
    D << I(n) << I(G);

    REP(v, n)
        if(SZ(G[v]) & 1)
            return cout << "No\n", 0;

    vis.RS(n);
    edge_taken.RS(edges);
    REP(v, n)
        if(!vis[v]) {
            euler.EB(v);
            euler_DFS(v);
        }
    D << I(euler);

    VI was_seen(n), stack;
    VVI cycles;

    REP(i, SZ(euler)) {
        if(was_seen[euler[i]]) {

            VI simple_cycle = { euler[i] };

            while(SZ(stack)) {
                int v = stack.back();

                was_seen[v] = 0;
                simple_cycle.EB(v);
                stack.pop_back();

                if(v == euler[i])
                    break;
            }

            cycles.EB(simple_cycle);
        }
        was_seen[euler[i]] = 1;
        stack.EB(euler[i]);
    }
	D << I(cycles);

	if(SZ(cycles) >= 2)
		cout << "Yes\n";
	else
		cout << "No\n";
}

