    {
        if(v==par) continue ;
        if( vis[v] )
        {
            int Next = v ;
            while( 1 )
            {
                g[ st.top() ].erase( g[ st.top() ].find( Next ) ) ;
                g[ Next ].erase( g[Next].find( st.top() ) ) ;
                Next = st.top() ;
                st.pop() ;
                if( Next==v ) break ;
            }
            fl = 1 ;
        }
        else dfs(v,u) ;
        if(fl) return ;
    }
 //   printf("fl %d\n",fl) ;
