    g[x].push_back(y);
    g[y].push_back(x);
  }
  vector<int> deg(n);
  for (int i = 0; i < n; i++) {
    deg[i] = (int) g[i].size();
  }
  for (int i = 0; i < n; i++) {
    if (deg[i] % 2 != 0) {
      cout << "No" << '\n';
      return 0;
    }
  }
  for (int i = 0; i < n; i++) {
    if (deg[i] >= 6) {
