struct euler_tour {
	ll n;
	vvl adj;
	vl pos, indeg, path;

	euler_tour(vvl adj): n(sz(adj)), adj(adj), pos(n), indeg(n) {
		FOR(i,0,n) for (ll j: adj[i]) indeg[j]++;
	}

	void rec(ll i) {
		while (pos[i] < sz(adj[i])) rec(adj[i][ pos[i]++ ]);
		path.pb(i);
	}

	bool construct() {
		ll s = -1, t = -1;
		FOR(i,0,n) {
			ll in = indeg[i], out = sz(adj[i]);
			if (abs(in-out) > 1) return false;
			if (in < out) { if (s < 0) s = i; else return false; }
			if (in > out) { if (t < 0) t = i; else return false; }
		}
		if ((s < 0) != (t < 0)) return false;
		if (s < 0) FOR(i,0,n) if (sz(adj[i])) s = i;
		if (s < 0) return true;
		rec(s);
		reverse(all(path));
		return sz(path) == accumulate(all(indeg),0) + 1;
	}
};

