		adj[b].pb(a);
	}

	euler_tour E(adj);
	if (!E.construct()) return false;
	if (E.path[0] != E.path.back()) return false;

	map<ll,ll> deg_cnt;
	FOR(i,0,n) deg_cnt[min(6LL,sz(adj[i]))]++;

	if (deg_cnt[6] >= 1) return true;
	if (deg_cnt[4] <= 1) return false;
	if (deg_cnt[4] >= 3) return false;

	ll i = 0;
	while (sz(adj[i]) == 2) i++;

	for (ll j: adj[i]) {
		ll a = i, b = j;
		while (sz(adj[b]) == 2) {
			a ^= adj[b][0] ^ adj[b][1];
			swap(a,b);
		}
		if (b == i) return true;
	}
	return false;
}

