		deg[x]++;
		deg[y]++;
	}
	g.vcnt=n;
	g.ecnt=2*m;
	qsort(g.e,g.ecnt,sizeof(E),esort);

	int p=0;
	rep(i,0,g.vcnt){
		while(p<g.ecnt&&g.e[p].s<i)p++;
		g.id[i]=p;
	}
	g.id[g.vcnt]=g.ecnt;//番兵
}

int f(int v1,int v2){
	int cnt=0;//結合の数
	rep(i,0,4){
		int pre=v1;
		int t=g.e[g.id[v1]+i].g;
		while(t!=v1&&t!=v2){
			if(g.e[g.id[t]].g!=pre){
				pre=t;
				t=g.e[g.id[t]].g;
			}else{
				pre=t;
				t=g.e[g.id[t]+1].g;
			}
		}
		if(t==v2)cnt++;
	}
	return cnt==2;
}

