void QSort(int left,int right)
{
  int i,j;
  int a_center;
  int temp;

  i=left;
  j=right;
  a_center=a[(left+right)/2];
  while(1){
      while(a[i]<a_center){i++;}
      while(a_center<a[j]){j--;}
      if(i>=j){break;}
      temp=a[i];
      a[i]=a[j];
      a[j]=temp;
      temp=b[i];
      b[i]=b[j];
      b[j]=temp;
      i++;
      j--;
  }
  if (left<i-1){QSort(left,i-1);} 
  if (j+1<right){QSort(j+1,right);}
}

