void QSort(int left,int right)
{
  int i,j,a_center,temp;
  i=left;
  j=right;
  a_center=edge[(left+right)/2];
  while(1){
      while(edge[i]<a_center){i++;}
      while(a_center<edge[j]){j--;}
      if(i>=j){break;}
      temp=edge[i];
      edge[i]=edge[j];
      edge[j]=temp;
      i++;
      j--;
  }
  if (left<i-1){QSort(left,i-1);} 
  if (j+1<right){QSort(j+1,right);}
}

