						mid.add(sides.get(i).get(0));
						mid.add(sides.get(i).get(3));
					}						
					else if(uf.same(sides.get(i).get(1), sides.get(i).get(3))) {
						mid.add(sides.get(i).get(0));
						mid.add(sides.get(i).get(2));
					}
					else if(uf.same(sides.get(i).get(2), sides.get(i).get(3))) {
						mid.add(sides.get(i).get(0));
