public class Main {
    private static InputStream is;
    private static PrintWriter out;
    private static String INPUT = "";

    int N, M;
    int ec[];
    List<Integer> edge[];
    Set<Long> used = new HashSet<>();

    void add(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        used.add((a << 32) | b);
    }

    boolean contain(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        return used.contains((a << 32) | b);
    }

    void solve() {
        N = ni();
        M = ni();
        edge = new List[N];
        for (int i = 0; i < N; ++i) {
            edge[i] = new ArrayList<>();
        }
        ec = new int[N];
        for (int i = 0; i < M; ++i) {
            int a = ni() - 1, b = ni() - 1;
            edge[a].add(b);
            edge[b].add(a);
            ec[a]++;
            ec[b]++;
        }
        int c = 0;
        for (int i = 0; i < N; ++i) {
            if (ec[i] % 2 == 1) {
                out.println("No");
                return;
            }
            if (ec[i] > 0) c += (ec[i] - 2) / 2;
        }
        if (c < 2) {
            out.println("No");
            return;
        }
        for (int i = 0; i < N; ++i) {
            while (ec[i] > 0) {
                if (!dfs(i, i, 0)) {
                    out.println("No");
                    return;
                }
            }
        }
        out.println("Yes");
    }

    boolean dfs(int s, int i, int c) {
        if (c > 0 && s == i) return true;
        c++;
        for (Integer j : edge[i]) {
            if (contain(i, j)) continue;
            add(i, j);
            ec[i]--;
            ec[j]--;
            return dfs(s, j, c);
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        new Main().solve();
        out.flush();
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

