        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        CThreeCircuits solver = new CThreeCircuits();
        solver.solve(1, in, out);
        out.close();
    }

    static class CThreeCircuits {
        private static final String YES = "Yes";
        private static final String NO = "No";

        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints(), m = in.ints();
            int[] cnt = new int[n];
            List<List<Integer>> neg = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                neg.add(new ArrayList<>());
            }
            for (int i = 0; i < m; i++) {
                int a = in.ints() - 1, b = in.ints() - 1;
                cnt[a]++;
                neg.get(a).add(b);
                cnt[b]++;
                neg.get(b).add(a);
            }

            int cr = 0;
            boolean[] isCr = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (cnt[i] % 2 == 1) {
                    out.ansln(NO);
                    return;
                } else if (cnt[i] >= 6) {
                    out.ansln(YES);
                    return;
                    // throw new RuntimeException();
                } else if (cnt[i] == 4) {
                    cr++;
                    isCr[i] = true;
                }
            }
            if (cr >= 3) {
                out.ansln(YES);
                return;
                //throw new RuntimeException();
            }

            boolean[] visited = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (!isCr[i]) {
                    continue;
                }
                Stack<CThreeCircuits.Visit> st = new Stack<>();
                st.add(new CThreeCircuits.Visit(i, 0));
                while (!st.isEmpty()) {
                    CThreeCircuits.Visit p = st.pop();
                    visited[p.dest] = true;
                    for (Integer b : neg.get(p.dest)) {
                        if (b == i && p.depth > 1) {
                            out.ansln(YES);
                            //return;
                            throw new RuntimeException();
                        } else if (isCr[b] || visited[b]) {
                            continue;
                        }
                        st.push(new CThreeCircuits.Visit(b, p.depth + 1));
                    }
                }
            }
            out.ansln(NO);
        }

        private static class Visit {
            int dest;
            int depth;

            public Visit(int dest, int depth) {
                this.dest = dest;
                this.depth = depth;
            }

        }

    }

