	{
		int n = ni(), m = ni();
		int[] from = new int[m];
		int[] to = new int[m];
		for (int i = 0; i < m; i++) {
			from[i] = ni() - 1;
			to[i] = ni() - 1;
		}
		int[][] g = packU(n, from, to);
		for(int i = 0;i < n;i++){
			if(g[i].length % 2 != 0){
				out.println("No");
				return;
			}
		}

		int[] four = new int[n];
		int p = 0;
		for(int i = 0;i < n;i++){
			if(g[i].length >= 6){
				out.println("Yes");
				return;
			}
			if(g[i].length == 4){
				four[p++] = i;
			}
		}
		if(p <= 1){
			out.println("No");
			return;
		}
		if(p >= 3){
			out.println("Yes");
			return;
		}
		for(int ne : g[four[0]]){
			int cur = ne;
			int pre = four[0];
			inner:
			for(;g[cur].length != 4;){
				for(int e : g[cur]){
					if(pre == e)continue;
					pre = cur;
					cur = e;
					continue inner;
				}
				out.println("Yes");
				return;
			}
			if(cur == four[0]){
				out.println("Yes");
				return;
			}
		}
		out.println("No");
