    void add(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        used.add((a << 32) | b);
    }

    boolean contain(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        return used.contains((a << 32) | b);
    }

    void solve() {
        N = ni();
        M = ni();
        edge = new List[N];
        for (int i = 0; i < N; ++i) {
            edge[i] = new ArrayList<>();
        }
        ec = new int[N];
        for (int i = 0; i < M; ++i) {
            int a = ni() - 1, b = ni() - 1;
            edge[a].add(b);
            edge[b].add(b);
            ec[a]++;
            ec[b]++;
        }
        int c = 0;
        for (int i = 0; i < N; ++i) {
            if (ec[i] % 2 == 1) {
                out.println("No");
