class Solver {
  final int n, m;
  final int[][] abs;
  List<List<Integer>> graph;

  Solver(int n, int m, int[][] abs) {
    this.n = n;
    this.m = m;
    this.abs = abs;
  }

  public boolean solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }
    int extra = 0;
    for (int i = 1; i <= n; i++) {
      int size = graph.get(i).size();
      if (size % 2 == 1) {
        return false;
      }
      extra += (size / 2) - 1;
    }
    return extra >= 2;
  }
}

