    }

    int[][] g = packU(n, from, to);

    // {2,4,6}
    for (int i = 0; i < n; i++) {
      if (g[i].length % 2 == 1) {
        System.out.println("No");
        return;
      }
    }

    int ptr = 0;
    int[] four = new int[n];
    for (int i = 0; i < n; i++) {
      if (g[i].length >= 6) {
        System.out.println("Yes");
        return;
      }
      if (g[i].length == 4) {
        four[ptr++] = i;
      }
    }

    if (ptr >= 3) {
      System.out.println("Yes");
      return;
    } else if (ptr <= 1) {
      System.out.println("No");
      return;
    }

    int x = 0;
    for (int i = 0; i < 4; i++) {
      if (dfs(four[0], -1, four[0], four[1], g)) {
        x++;
      }
    }

    if (x == 2) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }


  private static boolean dfs(int now, int pre, int s, int t, int[][] g) {


    for (int v : g[now]) {
      if (v == pre)
        continue;

      if (v == s)
        return false;
      else if (v == t)
        return true;

      return dfs(v, now, s, t, g);
    }
    return false;
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

