public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CThreeCircuits solver = new CThreeCircuits();
        solver.solve(1, in, out);
        out.close();
    }

    static class CThreeCircuits {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int[] deg = new int[n];
            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                deg[a]++;
                deg[b]++;
            }
            int cnt4 = 0;
            for (int i = 0; i < n; i++) {
                if (deg[i] % 2 != 0) {
                    out.println("No");
                    return;
                }
                if (deg[i] == 2) continue;
                if (deg[i] == 4) cnt4++;
                if (deg[i] > 4) cnt4 += 3;
            }
            out.println(cnt4 >= 2 ? "Yes" : "No");
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.*;

public class Main {
	static class MaxFlow {
		//dinic
		public class Edge {
			int to, rev;
			double cap;

			public Edge(int to, double cap, int rev) {
				this.to = to;
				this.cap = cap;
				this.rev = rev;
			}
		}
		double delta = 1e-15;

		int V;
		ArrayList<ArrayList<Edge>> G;
		int[] level;
		int[] iter;
		public final int INF = 1000000000;

		public MaxFlow(int V) {
			this.V = V;
			G = new ArrayList<ArrayList<Edge>>();
			for(int i=0; i<V; i++)
				G.add(new ArrayList<Edge>());
			level = new int[V];
			iter = new int[V];
		}

		public void addEdge(int from, int to, double cap) {
			G.get(from).add(new Edge(to, cap, G.get(to).size()));
			G.get(to).add(new Edge(from, 0, G.get(from).size()-1));
		}

		void bfs(int s) {
			Arrays.fill(level, -1);
			Queue<Integer> que = new LinkedList<Integer>();
			level[s] = 0;
			que.add(s);
			while(!que.isEmpty()) {
				int v = que.remove();
				for(int i=0; i<G.get(v).size(); i++) {
					Edge e = G.get(v).get(i);
					if(e.cap>0 && level[e.to]<0) {
						level[e.to] = level[v] + 1;
						que.add(e.to);
					}
				}
			}
		}

		double dfs(int v, int t, double f) {
			if(v==t) return f;
			for(; iter[v]<G.get(v).size(); iter[v]++) {
				Edge e = G.get(v).get(iter[v]);
				if(e.cap>0 && level[v] < level[e.to]) {
					double d = dfs(e.to, t, Math.min(f, e.cap));
					if(d>delta) {
						e.cap -= d;
						G.get(e.to).get(e.rev).cap += d;
						return d;
					}
				}
			}
			return 0;
		}

		double getMaxFlow(int s, int t) {
			double flow = 0;
			while(true) {
				bfs(s);
				if(level[t]<0)
					return flow;

				Arrays.fill(iter, 0);
				double f;
				while((f = dfs(s, t, INF)) > delta) {
					flow += f;
				}
			}
		}
	}

	static class Counter{
		int index;
		int count;
		public Counter(int index, int count) {
			this.index = index;
			this.count = count;
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();

		MaxFlow mf = new MaxFlow(N);

		for(int i=0; i<M; i++) {
			mf.addEdge(sc.nextInt()-1, sc.nextInt()-1, 1);
		}

		System.out.println(couldCreateThreeCircuits(mf) ? "Yes" : "No");
		sc.close();
	}

	static boolean couldCreateThreeCircuits(MaxFlow mf) {
		int N = mf.V;
		Counter[] c = new Counter[N];
		for(int i=0; i<N; i++) {
			c[i] = new Counter(i, mf.G.get(i).size());
		}

		Arrays.sort(c, new Comparator<Counter>() {
			public int compare(Counter c1, Counter c2) {
				return - (c1.count - c2.count);
			}
		});

		for(int i=0; i<N; i++)
			if(c[i].count%2!=0)
				return false;

		if(c[0].count>=6)
			return true;
		if(N>=3 && c[2].count>=4)
			return true;
		if(N>=2 && c[1].count>=4)
			return mf.getMaxFlow(c[0].index, c[1].index)==2;
		return false;
	}
}

