            a = b;
            b = t;
        }
        return used.contains((a << 32) | b);
    }

    void solve() {
        N = ni();
        M = ni();
        edge = new List[N];
        for (int i = 0; i < N; ++i) {
            edge[i] = new ArrayList<>();
        }
        ec = new int[N];
        for (int i = 0; i < M; ++i) {
            int a = ni() - 1, b = ni() - 1;
            edge[a].add(b);
            edge[b].add(b);
            ec[a]++;
            ec[b]++;
        }
        int c = 0;
        for (int i = 0; i < N; ++i) {
            if (edge[i].isEmpty() || edge[i].size() % 2 == 1) {
                out.println("No");
                return;
            }
            c += (edge[i].size() - 2) / 2;
        }
        if (c < 2) {
            out.println("No");
            return;
        }
        for (int i = 0; i < N; ++i) {
            if (ec[i] > 0 && !dfs(i, i)) {
                out.println("No");
                return;
            }
        }
        out.println("Yes");
    }

    boolean dfs(int s, int i) {
        if (s == i) return true;
        for (Integer j : edge[i]) {
            if (contain(i, j)) continue;
            add(i, j);
            ec[i]--;
            ec[j]--;
            return dfs(s, j);
        }
        return false;
    }

