			branch += count[i]-2;
		}
		if(branch >= 6) six = true;

		if(even && !six && branch == 4) {
			UnionFind uf = new UnionFind(n);
			for(int i=0; i<n; i++) {
				if(sides.get(i).size() == 2 && sides.get(sides.get(i).get(0)).size() == 2 && 
				                    	       sides.get(sides.get(i).get(1)).size() == 2) {
					uf.unite(i, sides.get(i).get(0));
					uf.unite(i, sides.get(i).get(1));
				}
			}

			ArrayList<Integer> mid = new ArrayList<Integer>();
			for(int i=0; i<n; i++) {
				if(sides.get(i).size() == 4) {
					Collections.sort(sides.get(i));
					if(sides.get(i).get(0) == sides.get(i).get(1)) {
						mid.add(sides.get(i).get(2));
						mid.add(sides.get(i).get(3));
					}
					else if(sides.get(i).get(1) == sides.get(i).get(2)) {
						mid.add(sides.get(i).get(0));
						mid.add(sides.get(i).get(3));
					}						
					else if(sides.get(i).get(2) == sides.get(i).get(3)) {
						mid.add(sides.get(i).get(0));
						mid.add(sides.get(i).get(1));
					}						
				}	
			}
			if(mid.size() == 4 && (
			   mid.get(0) == mid.get(2) && mid.get(1) == mid.get(3) || 
			   mid.get(0) == mid.get(3) && mid.get(1) == mid.get(2))) six = true;
		}

		out.println(even && six ? "Yes": "No");
    }
}

