import java.util.function.LongUnaryOperator;



public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
        }
        for (int i = 0; i < n; i++) {
            if (g[i].size() % 2 == 1) {
                out.writeln("No");
                return;
            }
        }
        for (int i = 0; i < n; i++) {
            if (g[i].size() >= 6) {
                out.writeln("Yes");
                return;
            }
        }
        for (int i = 0; i < n; i++) {
            if (g[i].size() == 4) {
                for (var it = g[i].iterator(); it.hasNext();) {
                    int u = i;
                    int v = it.nextInt();
                    while (g[v].size() == 2) {
                        if (g[v].get(0) == u) {
                            v = g[v].get(1);
                        } else {
                            v = g[v].get(0);
                        }
                        u = v;
                    }
                    if (v == i) {
                        out.writeln("Yes");
                        return;
                    }
                }
            }
        }
        out.writeln("No");
    }
}


