public class Main {
  private static void solve() {
    int n = ni();
    int m = ni();

    int[] from = new int[m];
    int[] to = new int[m];
    int[] w = new int[m];

    int[] deg = new int[n];
    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;

      deg[from[i]]++;
      deg[to[i]]++;
    }

    // {2,4,6}
    int[] cnt = new int[3];
    for (int i = 0; i < n; i++) {
      if (deg[i] % 2 == 1) {
        System.out.println("No");
        return;
      } else {
        cnt[Math.min(deg[i] / 2 - 1, 2)]++;
      }
    }

    if (cnt[1] >= 3 || cnt[2] >= 1) {
      System.out.println("Yes");
      return;
    } else if (cnt[1] == 1) {
      System.out.println("No");
      return;
    }

    int ptr = 0;
    int[] four = new int[2];
    for (int i = 0; i < n; i++) {
      if (deg[i] == 4) {
        four[ptr++] = i;
      }
    }
    int[][][] g = packWU(n, from, to, w);

    int x = 0;
    for (int i = 0; i < 4; i++) {
      if (dfs(four[0], four[0], four[1], g)) {
        x++;
      }
    }

    if (x == 2) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }


  private static boolean dfs(int now, int s, int t, int[][][] g) {


    for (int[] v : g[now]) {
      if (v[1] == 1)
        continue;

      v[1] = 1;

      if (v[0] == s)
        return false;
      else if (v[0] == t)
        return true;

      return dfs(v[0], s, t, g);
    }
    return false;
  }

  public static int[][][] packWU(int n, int[] from, int[] to, int[] w) {
    return packWU(n, from, to, w, from.length);
  }

  public static int[][][] packWU(int n, int[] from, int[] to, int[] w, int sup) {
    int[][][] g = new int[n][][];
    int[] p = new int[n];
    for (int i = 0; i < sup; i++)
      p[from[i]]++;
    for (int i = 0; i < sup; i++)
      p[to[i]]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]][2];
    for (int i = 0; i < sup; i++) {
      --p[from[i]];
      g[from[i]][p[from[i]]][0] = to[i];
      g[from[i]][p[from[i]]][1] = w[i];
      --p[to[i]];
      g[to[i]][p[to[i]]][0] = from[i];
      g[to[i]][p[to[i]]][1] = w[i];
    }
    return g;
  }

