public class Main {
    private static InputStream is;
    private static PrintWriter out;
    private static String INPUT = "";

    int N, M;
    int ec[];
    List<Integer> edge[];
    Set<Long> used = new HashSet<>();

    void add(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        used.add((a << 20) | b);
    }

    boolean contain(long a, long b) {
        if (a > b) {
            long t = a;
            a = b;
            b = t;
        }
        return used.contains((a << 20) | b);
    }

    void solve() {
        N = ni();
        M = ni();
        edge = new List[N];
        for (int i = 0; i < N; ++i) {
            edge[i] = new ArrayList<>();
        }
        ec = new int[N];
        for (int i = 0; i < M; ++i) {
            int a = ni() - 1, b = ni() - 1;
            edge[a].add(b);
            edge[b].add(a);
            ec[a]++;
            ec[b]++;
        }
        int c = 0;
        for (int i = 0; i < N; ++i) {
            if (ec[i] % 2 == 1) {
                out.println("No");
                return;
            }
            if (ec[i] > 0) c += (ec[i] - 2) / 2;
        }
        if (c < 2) {
            out.println("No");
            return;
        }
        for (int i = 0; i < N; ++i) {
            while (ec[i] > 0) {
                if (!dfs(i, i)) {
                    out.println("No");
                    return;
                }
            }
        }
        out.println("Yes");
    }

    boolean dfs(int s, int i) {
        for (Integer j : edge[i]) {
            if (contain(i, j)) continue;
            add(i, j);
            ec[i]--;
            ec[j]--;
            if (s == j) return true;
            return dfs(s, j);
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        new Main().solve();
        out.flush();
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

