        public class Edge {
            int a;
            int b;
            boolean inCycle;

            public Edge(int a, int b) {
                this.a = a;
                this.b = b;
            }

            public int get(int yt) {
                if (a == yt) return b;
                return a;
            }
        }
        List<Edge>[] edges;

        public int labelOneCycle(int u, int[] state) {
            state[u] = 1;
            for (Edge e: edges[u]) {
                if (e.inCycle) continue;
                if (state[e.get(u)] == 2) continue;
                if (state[e.get(u)] == 1) {
                    e.inCycle = true;
                    return e.get(u);
                } else {
                    int end = labelOneCycle(e.get(u), state);
                    if (end >= 0) {
                        e.inCycle = true;
                        if (u == end) return -2;
                        return end;
                    }
                    if (end == -2) return -2;
                }
            }
            state[u] = 2;
            return -1;
        }

        public boolean existEdge() {
            for (List<Edge> edge : edges) {
                for (Edge e : edge) {
                    if (!e.inCycle) return true;
                }
            }
            return false;
        }

        public boolean isVertexIn(int u) {
            for (Edge e: edges[u]) {
                if (!e.inCycle) return true;
            }
            return false;
        }

        public boolean isTwoCycle() {
            int[] state = new int[edges.length];
            labelOneCycle(0, state);
            if (!existEdge()) {
                throw new RuntimeException();
            }
            Arrays.fill(state, 0);
            for (int i = 0; i < edges.length; i++) {
                if (isVertexIn(i)) {
                    labelOneCycle(0, state);
                    return !existEdge();
                }
            }
            throw new RuntimeException();
        }

