    static class CThreeCircuits {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int[] a = new int[m];
            int[] b = new int[m];
            in.readIntArrays(a, b);
            MiscUtils.decreaseByOne(a, b);
            int[] degree = new int[n];
            for (int i : a) {
                degree[i]++;
            }
            for (int i : b) {
                degree[i]++;
            }
            int[] orDegree = degree.clone();
            ArrayUtils.sort(degree);
            for (int i = 0; i < n; i++) {
                if (degree[i] % 2 != 0) {
                    out.printLine("No");
                    return;
                }
            }
            if (degree[n - 1] >= 6) {
                out.printLine("Yes");
                return;
            }
            if (n >= 3 && degree[n - 3] >= 4) {
                out.printLine("Yes");
                return;
            }
            if (n >= 2 && degree[n - 2] >= 4) {
                Graph graph = BidirectionalGraph.createGraph(n, a, b);
                int x = ArrayUtils.find(orDegree, 4);
                orDegree[x] = -1;
                int y = ArrayUtils.find(orDegree, 4);
                for (int i = graph.firstOutbound(x); i != -1; i = graph.nextOutbound(i)) {
                    int last = x;
                    int current = graph.destination(i);
                    while (true) {
                        int next = -1;
                        for (int j = graph.firstOutbound(current); j != -1; j = graph.nextOutbound(j)) {
                            int cand = graph.destination(j);
                            if (cand != last) {
                                next = cand;
                                break;
                            }
                        }
                        last = current;
                        current = next;
                        if (current == x || current == y) {
                            break;
                        }
                    }
                    if (current == x) {
                        out.printLine("Yes");
                        return;
                    }
                }
            }
            out.printLine("No");
        }

    }

    static interface IntList extends IntReversableCollection {
        public abstract int get(int index);

        public abstract void set(int index, int value);

        public abstract void addAt(int index, int value);

        public abstract void removeAt(int index);

        default public void swap(int first, int second) {
            if (first == second) {
                return;
            }
            int temp = get(first);
            set(first, get(second));
            set(second, temp);
        }

        default public IntIterator intIterator() {
            return new IntIterator() {
                private int at;
                private boolean removed;

                public int value() {
                    if (removed) {
                        throw new IllegalStateException();
                    }
                    return get(at);
                }

                public boolean advance() {
                    at++;
                    removed = false;
                    return isValid();
                }

                public boolean isValid() {
                    return !removed && at < size();
                }

                public void remove() {
                    removeAt(at);
                    at--;
                    removed = true;
                }
            };
        }

        default public void add(int value) {
            addAt(size(), value);
        }

        default public IntList sort(IntComparator comparator) {
            Sorter.sort(this, comparator);
            return this;
        }

        default public int find(int value) {
            int size = size();
            for (int i = 0; i < size; i++) {
                if (get(i) == value) {
                    return i;
                }
            }
            return -1;
        }

        default public IntList subList(final int from, final int to) {
            return new IntList() {
                private final int shift;
                private final int size;

                {
                    if (from < 0 || from > to || to > IntList.this.size()) {
                        throw new IndexOutOfBoundsException("from = " + from + ", to = " + to + ", size = " + size());
                    }
                    shift = from;
                    size = to - from;
                }

                public int size() {
                    return size;
                }

                public int get(int at) {
                    if (at < 0 || at >= size) {
                        throw new IndexOutOfBoundsException("at = " + at + ", size = " + size());
                    }
                    return IntList.this.get(at + shift);
                }

                public void addAt(int index, int value) {
                    throw new UnsupportedOperationException();
                }

                public void removeAt(int index) {
                    throw new UnsupportedOperationException();
                }

                public void set(int at, int value) {
                    if (at < 0 || at >= size) {
                        throw new IndexOutOfBoundsException("at = " + at + ", size = " + size());
                    }
                    IntList.this.set(at + shift, value);
                }

                public IntList compute() {
                    return new IntArrayList(this);
                }
            };
        }

    }

