class UnionFind {
    int[] par;
    int[] num;

    UnionFind(int n) { 
    	par = new int[n];
    	num = new int[n];
        for(int i = 0; i < n; i++) {
        	par[i] = i;
        	num[i] = 1;
        }
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x); 
        int ry = root(y);
        if (rx == ry) return; 

        par[rx] = ry;
        num[ry] += num[rx];
    }

    boolean same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int getNum(int n) {
    	return num[root(n)];
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(in);

        int n = sc.nextInt();
		int m = sc.nextInt();

		int[] count = new int[n];
		ArrayList<ArrayList<Integer>> sides = new ArrayList<ArrayList<Integer>>();
		for(int i=0; i<n; i++) sides.add(new ArrayList<Integer>());
		for(int i=0; i<m; i++) {
			int a = sc.nextInt()-1;
			int b = sc.nextInt()-1;

			count[a]++;
			count[b]++;
			sides.get(a).add(b);			
		}

		boolean even = true;
		boolean six = false;
		int branch = 0;
		for(int i=0; i<n; i++) {
			even &= ((count[i]%2)==0);
			six |= count[i] >= 6;
			branch += count[i]-2;
		}
		if(branch >= 6) six = true;

		if(even && !six && branch == 4) {
			UnionFind uf = new UnionFind(n);
			for(int i=0; i<n; i++) {
				if(sides.get(i).size() == 2 && sides.get(sides.get(i).get(0)).size() == 2 && 
				                    	       sides.get(sides.get(i).get(1)).size() == 2) {
