        static public void Solve()
        {
            var N = NN;
            var M = NN;
            var ab = Repeat(0, M).Select(_ => new { a = NN - 1, b = NN - 1 }).ToArray();
            var path = Repeat(0, N).Select(_ => new List<long>()).ToArray();
            foreach (var item in ab)
            {
                path[item.a].Add(item.b);
                path[item.b].Add(item.a);
            }

            var treepath = Repeat(0, N).Select(_ => new List<long>()).ToArray();
            var heiroPair = new List<Tuple<long, long>>();
            var parent = new long[N];
            {
                var done = new bool[N];
                var q = new Queue<long>();
                done[0] = true;
                parent[0] = 0;
                q.Enqueue(0);
                while (q.Count > 0)
                {
                    var v = q.Dequeue();
                    foreach (var item in path[v])
                    {
                        if (done[item])
                        {
                            heiroPair.Add(Tuple.Create(v, item));
                            continue;
                        }
                        parent[item] = v;
                        treepath[v].Add(item);
                        treepath[item].Add(v);
                        done[item] = true;
                        q.Enqueue(item);
                    }
                }
            }
            var tree = new Tree(treepath, 0);
            var heiroKouho = new List<List<long>>();
            foreach (var item in heiroPair)
            {
                var z = tree.LCA(item.Item1, item.Item2);
                var nextVtx = item.Item1;
                var heiro = new List<long>();
                while (nextVtx != z)
                {
                    heiro.Add(nextVtx);
                    nextVtx = parent[nextVtx];
                }
                heiro.Add(nextVtx);
                heiro.Reverse();
                nextVtx = item.Item2;
                while (nextVtx != z)
                {
                    heiro.Add(nextVtx);
                    nextVtx = parent[nextVtx];
                }
                heiroKouho.Add(heiro);
            }
            var heiroCount = 0;
            var donePath = Repeat(0, N).Select(_ => new bool[N]).ToArray();
            foreach (var item in heiroKouho)
            {
                var ok = true;
                foreach (var item2 in item.Zip(item.Skip(1), (x, y) => new { x, y }))
                {
                    var used = donePath[item2.x][item2.y];
                    if (used)
                    {
                        ok = false;
                        break;
                    }
                    donePath[item2.x][item2.y] = true;
                    donePath[item2.y][item2.x] = true;
                }
                if (ok) ++heiroCount;
                if (heiroCount >= 3)
                {
                    Console.WriteLine("Yes");
                    return;
                }
            }
            Console.WriteLine("No");

        }

