class Solver
{
    public SC sc = new SC();
    public void Solve()
    {
        int N, M;
        sc.Make(out N, out M);
        var deg = new int[N];
        var G = Create(N, () => new List<(int to,int idx)>());
        for (int i = 0; i < M; i++)
        {
            int a, b;
            sc.Make(out a, out b);a--;b--;
            deg[a]++;deg[b]++;
            G[a].Add((b,i));
            G[b].Add((a,i));
        }
        {
            if (deg.Count(v => v % 2 == 1) != 0) Fail("No");
            var max = deg.Max();
            if (max > 4) Fail("Yes");
            if (max < 4) Fail("No");
            var ct = deg.Count(v => v == 4);
            if (ct >= 3) Fail("Yes");
            if (ct <= 1) Fail("No");
        }
        int f = -1, s = -1;
        for (int i = 0; i < N; i++)
        {
            if (deg[i] == 4)
            {
                if (f == -1) f = i;
                else s = i;
            }
        }
        var use = new bool[M];
        var ok = false;
        void dfs(int i)
        {
            ok |= i == s;
            var fi = false;
            foreach (var (to, idx) in G[i])
            {
                if (use[idx]) continue;
                if (fi) continue;
                fi |= i == f;
                use[idx] = true;
                if (to == f) continue;
                dfs(to);
            }
        }
        var res = 0;
        dfs(f);
        if (!ok) Fail("Yes");
        if (use.All(v => v)) Fail("No");
        Console.WriteLine("Yes");
    }
}

