	public void Solve(){

		if(!chk1()){
			Console.WriteLine("No");
			return;
		}

		List<int>[] E = new List<int>[N];
		for(int i=0;i<N;i++) E[i] = new List<int>();
		for(int i=0;i<M;i++){
			E[A[i]].Add(i);
			E[B[i]].Add(i);
		}

		int[] dep = new int[N];
		int[] pe = new int[N];
		var o1 = new List<int>();
		for(int i=0;i<N;i++) dep[i] = -1;
		for(int i=0;i<N;i++) pe[i] = -1;
		dep[0] = 0;
		var q = new Queue<int>();
		q.Enqueue(0);
		bool found = false;
		while(q.Count > 0){
			if(found) break;
			var now = q.Dequeue();
			foreach(var e in E[now]){
				int nxt = A[e] == now ? B[e] : A[e];
				if(e == pe[now]) continue;
				if(dep[nxt] == -1){
					dep[nxt] = dep[now] + 1;
					pe[nxt] = e;
					q.Enqueue(nxt);
					continue;
				}
				found = true;
				o1.Add(e);
				int v = now;
				while(pe[v] != -1){
					int nv = A[pe[v]] == v ? B[pe[v]] : A[pe[v]];
					o1.Add(pe[v]);
					v = nv;
				}
				v = nxt;
				while(pe[v] != -1){
					int nv = A[pe[v]] == v ? B[pe[v]] : A[pe[v]];
					o1.Add(pe[v]);
					v = nv;
				}
			}
			break;
		}

		bool[] used = new bool[M];
		foreach(var e in o1){
			used[e] = true;
		}

		if(chk2(used)){
