			if(used[i]) continue;
			ec++;
			E[A[i]].Add(i);
			E[B[i]].Add(i);
		}

		if(ec == 0){
			Console.WriteLine("No");
			return;
		}
		dep = new int[N];
		pe = new int[N];
		var o2 = new List<int>();
		for(int i=0;i<N;i++) dep[i] = -1;
		for(int i=0;i<N;i++) pe[i] = -1;
		int root = -1;
		for(int i=0;i<N;i++){
			if(E[i].Count > 0){
				root = i;
				break;
			}
		}
		if(root == -1){
			Console.WriteLine("No");
			return;
		}
		dep[root] = 0;
		q = new Queue<int>();
		q.Enqueue(root);
		found = false;
		while(q.Count > 0){
			if(found) break;
			var now = q.Dequeue();
			foreach(var e in E[now]){
				int nxt = A[e] == now ? B[e] : A[e];
				if(e == pe[now]) continue;
				if(dep[nxt] == -1){
					dep[nxt] = dep[now] + 1;
					pe[nxt] = e;
					q.Enqueue(nxt);
					continue;
				}
				found = true;
				o2.Add(e);
				int v = now;
				while(pe[v] != -1){
					int nv = A[pe[v]] == v ? B[pe[v]] : A[pe[v]];
					o2.Add(pe[v]);
					v = nv;
				}
				v = nxt;
				while(pe[v] != -1){
					int nv = A[pe[v]] == v ? B[pe[v]] : A[pe[v]];
					o2.Add(pe[v]);
					v = nv;
				}
			}
			break;
		}

		foreach(var e in o2){
			used[e] = true;
		}

		for(int i=0;i<M;i++){
			if(!used[i]){
