	bool chk1(){
		int[] deg = new int[N];
		for(int i=0;i<M;i++){
			deg[A[i]]++;
			deg[B[i]]++;
		}
		for(int i=0;i<N;i++){
			if(deg[i] == 0 || deg[i] % 2 == 1){
				return false;
			}
		}
		return true;
	}

	bool chk2(bool[] used){
		var UF = new UnionFind(N);
		for(int i=0;i<M;i++){
			if(used[i]) continue;
			UF.Unite(A[i], B[i]);
		}
		int cnt = 0;
		var hs = new HashSet<int>();
		for(int i=0;i<N;i++){
			if(UF.MemCnt(i) == 1) continue;
			hs.Add(UF.MemCnt(i));
			cnt++;
		}
		if(hs.Count == 1){
			var num = hs.ToList()[0];
			if(num == cnt) return false;
		}
		return true;

	}



