        static public void Solve()
        {
            var N = NN;
            var M = NN;
            var ab = Repeat(0, M).Select(_ => new { a = NN - 1, b = NN - 1 }).ToArray();
            var path = Repeat(0, N).Select(_ => new List<long>()).ToArray();
            var pathIdx = 0;
            var pathIdxList = Repeat(0, N).Select(_ => new long[N]).ToArray();
            foreach (var item in ab)
            {
                path[item.a].Add(item.b);
                path[item.b].Add(item.a);
                pathIdxList[item.a][item.b] = pathIdx;
                pathIdxList[item.b][item.a] = pathIdx;
                ++pathIdx;
            }
            var doneVtx = new bool[N];
            var donePath = new bool[M];
            var vtx = 0L;
            var donePathCount = 0L;
            var heiroCount = 1L;
            while (donePathCount < M)
            {
                if (doneVtx[vtx]) ++heiroCount;
                doneVtx[vtx] = true;
                foreach (var item in path[vtx])
                {
                    var pIdx = pathIdxList[vtx][item];
                    if (donePath[pIdx]) continue;
                    donePath[pIdx] = true;
                    ++donePathCount;
                    vtx = item;
                    break;
                }
            }
            if (heiroCount >= 3)
            {
                Console.WriteLine("Yes");

            }
            else
            {
                Console.WriteLine("No");

            }
        }

