            var ab = Repeat(0, M).Select(_ => new { a = NN - 1, b = NN - 1 }).ToArray();
            var path = Repeat(0, N).Select(_ => new List<long>()).ToArray();
            foreach (var item in ab)
            {
                path[item.a].Add(item.b);
                path[item.b].Add(item.a);
            }
            var dim = new long[N];
            for (var i = 0; i < N; i++)
            {
                dim[i] = path[i].Count;
                if (dim[i] % 2 == 1)
                {
                    Console.WriteLine("No");
                    return;
                }
            }
            if (dim.Any(e => e >= 6))
            {
                Console.WriteLine("Yes");
                return;
            }
            var dim4 = path.Select((x, i) => new { x, i }).Where(e => e.x.Count >= 4).ToArray();
            if (dim4.Length >= 3)
            {
                Console.WriteLine("Yes");
                return;
            }
            if (dim4.Length < 2)
            {
                Console.WriteLine("No");
                return;
            }
            var a = dim4.First().i;
            var b = dim4.Last().i;
            var pathCount = 0;
            {
                var done = new bool[N];
                var q = new Queue<long>();
                done[a] = true;
                done[b] = true;
                q.Enqueue(a);
                while (q.Count > 0)
                {
                    var v = q.Dequeue();
                    foreach (var item in path[v])
                    {
                        if (item == b) ++pathCount;
                        if (done[item]) continue;
                        done[item] = true;
                        q.Enqueue(item);
                    }
                }
            }
            if (pathCount == 2)
            {
                Console.WriteLine("Yes");

            }
            else
            {
                Console.WriteLine("No");

            }
        }

