namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			int[] nm = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nm[0];
			int m = nm[1];
			List<int>[] to = new List<int>[n];
			for (int i = 0; i < n; i++) {
				to[i] = new List<int>();
			}
			for (int i = 0; i < m; i++) {
				int[] ab = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
				to[ab[0] - 1].Add(ab[1] - 1);
				to[ab[1] - 1].Add(ab[0] - 1);
			}

			int cross6 = 0;
			List<int> cross = new List<int>();
			for (int i = 0; i < n; i++) {
				if (to[i].Count % 2 == 1) {
					Console.WriteLine("No");
					return;
				}

				if (to[i].Count != 2) {
					cross.Add(i);
					if (to[i].Count >= 6) {
						++cross6;
					}
				}
			}

			if (cross.Count >= 2 || cross6 > 0) {
				if (cross.Count == 2 && cross6 == 0) {
					int same = 0;
					int a = cross[0];
					int b = cross[1];
					foreach (int v in to[a]) {
						int last = a;
						int w = v;
						while (w != a || w != b) {
							if (to[w][0] != last) {
								last = w;
								w = to[w][0];
							} else {
								last = w;
								w = to[w][1];
							}
						}

						if (w == b) {
							same++;
						}
					}

					if (same > 2) {
						Console.WriteLine("No");
					} else {
						Console.WriteLine("Yes");
					}
				} else {
					Console.WriteLine("Yes");
				}
			} else {
				Console.WriteLine("No");
			}
		}
	}
}

