function dfsStart(s, t, adj, N) {
  var count = 0;
  var colors = Array(N + 1).fill("white");
  colors[s] = "black";

  var cur = s;
  while (count < 3) {
    cur = s;
    var prev;
    while (cur !== t) {
      prev = cur;
      cur = adj[cur].filter(x => colors[x] === "white")[0];
      if (!cur) {
        if (adj[prev].indexOf(t) === -1) {
          return true;
        } else {
          cur = t;
        }
      } 
      colors[cur] = "black";
    }
    count += 1;
  }

  return false;
}


