func min(n,m int) int {
  if n < m { return n }
  return m
}

type Edge struct { to,capa,rev int }
type Graph [][]Edge
func NewGraph(n int) Graph { return make([][]Edge,n) }
func(g Graph) AddEdge(fm int,e Edge) { g[fm] = append(g[fm],e) }
func(g Graph) Add(fm,to,capa int) {
  g.AddEdge(fm,Edge{to,capa,len(g[to])})
  g.AddEdge(to,Edge{fm,0,len(g[fm])-1})
}
func(g Graph) FordFulkerson(s,t int) int {
  used := make([]bool,len(g))
  var dfs func(int,int,int) int
  dfs = func(v,t,f int) int {
    if v == t { return f }
    used[v] = true
    for i,e := range g[v] {
      if used[e.to] || e.capa <= 0 { continue }
      d := dfs(e.to,t,min(f,e.capa))
      if d > 0 {
        g[v][i].capa -= d
        g[e.to][e.rev].capa += d
        return d
      }
    }
    return 0
  }
  for flow:=0;; {
    for i:=0;i<len(used);i++ { used[i] = false }
    f := dfs(s,t,INF)
    if f == 0 { return flow }
    flow += f
  }
}

