class Node{
	long _b, _w;
	int id;
	Node[] nodes;
	Node[] kids;
	Node parent;
	bool isVisited;
	this(int id){
		this.id = id;
	}
	int search4(){
		print!1("(", this.id + 1, ")");
		if(this.nodes.length == 4) return this.id;
		this.isVisited = 1;
		if(! this.nodes[0].isVisited) return this.nodes[0].search4();
		else return this.nodes[1].search4();
	}

	override string toString(){
		return "id:" ~ id.to!string ~ " b:" ~ _b.to!string ~ " w:" ~ _w.to!string ~ " kids:" ~ kids.map!(x => x.id).to!string;
	}
}

