            return xo
        j -= 1
    raise newException(IndexError, "Out of bounds: " & $i & " >= " & $(S.len))

proc head[T](L: seq[T]):T =
    return L[0]

proc tail[T](L: seq[T]):T =
    return L[L.len-1]

proc neighbours_v_es(vl: int, es: seq[Edge]): seq[IntSet] =
    var neighbours_v = newSeqWith(vl, initIntSet())
    for e in es:
        var va = e.v1
        var vb = e.v2
        neighbours_v[va].incl(vb)
        neighbours_v[vb].incl(va)
    return neighbours_v

proc isConnected_neighbours_v(neighbours_v: seq[IntSet]) :bool =
    let vl = neighbours_v.len
    var wringingVs = initIntSet()
    var notConnectedVs = initIntSet()
    wringingVs.incl(0)
    for v in 1..<vl:
        notConnectedVs.incl(v)
    while wringingVs.len != 0:
        var va = wringingVs.pop()
        for vb in neighbours_v[va]:
            if vb in notConnectedVs:
                notConnectedVs.excl(vb)
                wringingVs.incl(vb)
    return notConnectedVs.len == 0

proc eulerEndPoints_neighbours_v(neighbours_v: seq[IntSet]): (int,int)=
    let vl = neighbours_v.len
    if not isConnected_neighbours_v(neighbours_v):
        return (-1,-1)
    var oddDegreesVs = newSeq[int](0)
    for v in 0..<vl:
        if neighbours_v[v].len mod 2 == 1:
            oddDegreesVs.add(v)
    if oddDegreesVs.len == 0:
        return (0,0)
    elif oddDegreesVs.len == 2:
        return (oddDegreesVs[0], oddDegreesVs[1])
    else:
        return (-1,-1)





