loop_count = 0

def dfs(graph, path, ps):
    global loop_count
    a = path[-1]
    nexts = list(graph[path[-1]])
    for nex in nexts:
        try:
            graph[a].remove(nex)
            graph[nex].remove(a)
        except KeyError:
            continue
        if nex in ps:
            loop_count += 1
            path.pop()
            return nex
        else:
            path.append(nex)
            ps.add(nex)
            ret = dfs(graph, path, ps)
            if ret is None:
                return
            if ret != a:
                path.pop()
                ps.remove(nex)
                return ret


