class Graph:
    def __init__(self, V: int):
        self.__V = V
        self.__g = [[] for _ in range(V)]
        self.__used = [False] * V

    def add_edge(self, u: int, v: int, cap: int):
        self.__g[u].append((v, cap, len(self.__g[v])))
        self.__g[v].append((u, 0, len(self.__g[u])-1))

    def ford_fulkerson(self, s: int, t: int)->int:
        flow = 0
        while True:
            self.__used = [False] * self.__V
            f = self.__dfs(s, t, float('inf'))
            if f == 0:
                break
            flow += f
        return flow

    def __dfs(self, v: int, t: int, f: int)->int:
        if v == t:
            return f
        self.__used[v] = True

        for i, (to, cap, rev) in enumerate(self.__g[v]):
            if (not self.__used[v]) and cap > 0:
                d = self.__dfs(to, t, min(f, cap))

                if d > 0:
                    self.__g[v][i] = (to, cap-d, rev)
                    self.__g[to][rev][1] += d
                    return d
        return 0


def three_circuits(N: int, M: int, edges: list)->bool:
    d = [0] * N

    for u, v in edges:
        d[u-1] += 1
        d[v-1] += 1

    if any(v & 1 == 1 for v in d):
        # euler 閉路でないなら NG
        return False
    if any(v >= 6 for v in d):
        # 次数が 6 以上のものがあれば OK
        return True

    c4 = d.count(4)
    if c4 >= 3:
        # 次数が 4 のものが 3 つ以上存在すれば OK
        return True
    if c4 < 2:
        # 次数が 4 のものが 1 つ以下なら NG
        return False

    # 次数が 4 のものが 2 つならその二つの頂点間にパスが二つ
    # の時のみ OK
    graph = Graph(N)
    for u, v in edges:
        graph.add_edge(u, v, 1)

    u = d.index(4)
    v = d.index(4, start=u+1)

    return graph.ford_fulkerson(u, v) == 2


