use std::collections::{HashSet, VecDeque};

fn main() {
    input!{
        n: usize,
        m: usize,
        v: [(usize1, usize1); m]
    }
    let mut g: Vec<HashSet<usize>> = vec![HashSet::new(); n];
    for &(a, b) in v.iter() {
        g[a].insert(b);
        g[b].insert(a);
    }
    for i in 0..n {
        if g[i].len() % 2 != 0 {
            println!("No");
            return;
        }
    }
    let ans = bfs(&g, &(0..n).collect::<HashSet<usize>>(), &HashSet::new(), 0);
    println!("{}", if ans {"Yes"} else {"No"});
}

fn bfs(g: &Vec<HashSet<usize>>, setv: &HashSet<usize>, sete: &HashSet<(usize, usize)>, k: usize) -> bool {
    if k >= 3 {
        return true;
    }
    if setv.len() == 0 {
        return false;
    }
    let mut q: VecDeque<(usize, HashSet<usize>, HashSet<(usize, usize)>)> = VecDeque::new();
    let mut setv2 = setv.clone();
    let mut n0 = 0;
    while !setv2.contains(&n0) {
        n0 += 1;
    }
    setv2.remove(&n0);
    q.push_back((n0, setv2, sete.clone()));
    while q.len() > 0 {
        let (n, mut sv, mut se) = q.pop_front().unwrap();
        for &c in g[n].iter() {
            if se.contains(&(n, c)) || se.contains(&(c, n)) {
                continue;
            }
            se.insert((n, c));
            if !sv.contains(&c) {
                return bfs(g, &sv, &se, k + 1);
            }
            sv.remove(&c);
            q.push_back((c, sv.clone(), se.clone()));
        }
    }
    return false;
}

