fn dfs(g: &Vec<HashSet<usize>>, s: usize, t: usize, ps: &mut HashSet<usize>) -> bool {
    if s == t {
        return true;
    }
    for &c in g[s].iter() {
        if !ps.insert(c) {
            continue;
        }
        if dfs(g, c, t, ps) {
            return true;
        }
        ps.remove(&s);
    }
    return false;
}

