#[derive(Clone)]
pub struct BiEdge<T: Eq> {
    vs: (T, T),
}
impl<T: Eq> BiEdge<T> {
    pub fn new(v1: T, v2: T) -> BiEdge<T> {
        BiEdge { vs: (v1, v2) }
    }
    pub fn from(&self, v: &T) -> Option<&T> {
        if self.vs.0 == *v {
            Some(&self.vs.1)
        } else if self.vs.1 == *v {
            Some(&self.vs.0)
        } else {
            None
        }
    }
}
impl<T: Eq> PartialEq for BiEdge<T> {
    fn eq(&self, other: &BiEdge<T>) -> bool {
        self.vs == other.vs || self.vs.0 == other.vs.1 && self.vs.1 == other.vs.0
    }
}
impl<T: Eq> Eq for BiEdge<T> {}
impl<T: Eq + std::hash::Hash> std::hash::Hash for BiEdge<T> {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        use std::default::Default;
        use std::hash::Hasher;
        let mut hash0 = FnvHasher::default();
        self.vs.0.hash(&mut hash0);
        let mut hash1 = FnvHasher::default();
        self.vs.1.hash(&mut hash1);
        if hash1.finish() >= hash1.finish() {
            self.vs.hash(state);
        } else {
            self.vs.1.hash(state);
            self.vs.0.hash(state);
        }
    }
}
impl<T: Eq + std::fmt::Debug> std::fmt::Debug for BiEdge<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        use std::hash::{Hash, Hasher};
        let s0 = format!("{:?}", self.vs.0);
        let mut hash0 = FnvHasher::default();
        s0.hash(&mut hash0);
        let s1 = format!("{:?}", self.vs.1);
        let mut hash1 = FnvHasher::default();
        s1.hash(&mut hash1);
        let pair = if hash0.finish() >= hash1.finish() {
            (s0, s1)
        } else {
            (s1, s0)
        };
        write!(f, "{{{}, {}}}", pair.0, pair.1)
    }
}
pub struct HashGraph<T: Eq + Clone + std::hash::Hash> {
    adjacency: std::collections::HashMap<T, std::collections::HashMap<T, BiEdge<T>>>,
}
impl<T: Eq + Clone + std::hash::Hash> HashGraph<T> {
    pub fn from_pairs<V, VIter, E, EIter>(vertises: V, edges: E) -> HashGraph<T>
    where
        V: IntoIterator<Item = T, IntoIter = VIter>,
        VIter: Iterator<Item = T>,
        E: IntoIterator<Item = (T, T), IntoIter = EIter>,
        EIter: Iterator<Item = (T, T)>,
    {
        let mut adjacency = std::collections::HashMap::new();
        for v in vertises {
            adjacency.insert(v, std::collections::HashMap::new());
        }
        for (v1, v2) in edges {
            adjacency
                .get_mut(&v1)
                .unwrap()
                .insert(v2.clone(), BiEdge::new(v1.clone(), v2.clone()));
            adjacency
                .get_mut(&v2)
                .unwrap()
                .insert(v1.clone(), BiEdge::new(v1, v2));
        }
        HashGraph {
            adjacency: adjacency,
        }
    }
    pub fn connected(&self, v1: &T, v2: &T) -> Result<bool, ()> {
        self.edge(v1, v2).map(|e| e.is_some())
    }
    pub fn edge(&self, v1: &T, v2: &T) -> Result<Option<&BiEdge<T>>, ()> {
        if !self.adjacency.contains_key(v1) || !self.adjacency.contains_key(v2) {
            Err(())
        } else {
            Ok(self.adjacency.get(v1).unwrap().get(v2))
        }
    }
    pub fn edges(&self, v1: &T) -> Result<std::collections::hash_map::Values<T, BiEdge<T>>, ()> {
        self.adjacency
            .get(v1)
            .ok_or(())
            .map(|edges_map| edges_map.values())
    }
}

