use std::collections::HashSet;

type E = BiEdge<u32>;
type G = HashGraph<u32>;

fn dfs(v: u32, start: u32, goal: u32,
       g: &G, visited: &mut HashSet<E>, is_start_visited: bool) -> bool {
    if v == goal {
        true
    } else if is_start_visited && v == start {
        false
    } else {
        for e in g.edges(&v).unwrap() {
            if !visited.contains(e) {
                visited.insert(e.clone());
                if dfs(*e.from(&v).unwrap(), start, goal, g, visited, true) {
                    return true;
                }
            }
        }
        false
    }
}

