struct UnionFind {
    par: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            par: (0..n).collect(),
        }
    }

    fn root(&mut self, x: usize) -> usize {
        let p = self.par[x];
        if p == x {
            x
        } else {
            let r = self.root(p);
            self.par[x] = r;
            r
        }
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }

    fn unite(&mut self, x: usize, y: usize) {
        let rootx = self.root(x);
        let rooty = self.root(y);
        if rootx == rooty {
            ;
        } else {
            self.par[rootx] = rooty;
        }
    }
}

fn solv(nodes: Vec<Vec<usize>>, mut uf: UnionFind) -> bool {
    let mut deg4nodes = Vec::new();

    for i in 0..nodes.len() {
        let ref n = nodes[i];

        if n.len() % 2 == 1 {
            return false;
        } else if n.len() >= 6 {
            return true;
        } else if n.len() == 4 {
            deg4nodes.push(i);
        } else {
            uf.unite(n[0], n[1]);
        }
    }

    if deg4nodes.len() > 2 { return true; }
    if deg4nodes.len() < 2 { return false; }

    let n = deg4nodes[0];

    return
        uf.same(nodes[n][0], nodes[n][1]) ||
        uf.same(nodes[n][0], nodes[n][2]) ||
        uf.same(nodes[n][0], nodes[n][3]) ||
        uf.same(nodes[n][1], nodes[n][2]) ||
        uf.same(nodes[n][1], nodes[n][3]) ||
        uf.same(nodes[n][2], nodes[n][3]);
}

