macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

use std::collections::HashSet;

fn main() {
    input!{
        n: usize,
        m: usize,
        v: [(usize1, usize1); m]
    }
    let mut g: Vec<HashSet<usize>> = vec![HashSet::new(); n];
    for &(a, b) in v.iter() {
        g[a].insert(b);
        g[b].insert(a);
    }
    let mut d4: Vec<usize> = Vec::new();
    for i in 0..n {
        let d = g[i].len();
        if d % 2 != 0 {
            println!("No");
            return;
        } else if d >= 6 {
            println!("Yes");
            return;
        } else if d == 4 {
            d4.push(i);
        }
    }
    if d4.len() > 2 {
        println!("Yes");
        return;
    } else if d4.len() < 2 {
        println!("No");
        return;
    }
    let ans = flow(&g, d4[0], d4[1]);
    println!("{}", if ans == 2 {"Yes"} else {"No"});
}

fn flow(g: &Vec<HashSet<usize>>, s: usize, t: usize) -> usize {
    let mut h = g.clone();
    let mut ret = 0;
    loop {
        let mut p: Vec<usize> = Vec::new();
        if dfs(&h, s, t, &mut HashSet::new(), &mut p) {
            for w in p.windows(2) {
                h[w[0]].remove(&w[1]);
                h[w[1]].remove(&w[0]);
            }
            ret += 1;
        } else {
            break;
        }
    }
    ret
}

fn dfs(g: &Vec<HashSet<usize>>, s: usize, t: usize, ps: &mut HashSet<usize>, p: &mut Vec<usize>) -> bool {
    ps.insert(s);
    p.push(s);
    if s == t {
        return true;
    }
    for &c in g[s].iter() {
        if ps.contains(&c) {
            continue;
        }
        if dfs(g, c, t, ps, p) {
            return true;
        }
    }
    ps.remove(&s);
    p.pop();
    return false;
}

pub trait IterScan: Sized {
    type Output;
    fn scan<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> Option<Self::Output>;
}
pub trait MarkedIterScan: Sized {
    type Output;
    fn mscan<'a, I: Iterator<Item = &'a str>>(self, iter: &mut I) -> Option<Self::Output>;
}
#[derive(Debug)]
pub struct Scanner<'a> {
    iter: std::str::SplitAsciiWhitespace<'a>,
}
impl<'a> Scanner<'a> {
    #[inline]
    pub fn new(s: &'a str) -> Self {
        let iter = s.split_ascii_whitespace();
        Self { iter }
    }
    #[inline]
    pub fn scan<T: IterScan>(&mut self) -> <T as IterScan>::Output {
        T::scan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn mscan<T: MarkedIterScan>(&mut self, marker: T) -> <T as MarkedIterScan>::Output {
        marker.mscan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn scan_vec<T: IterScan>(&mut self, size: usize) -> Vec<<T as IterScan>::Output> {
        (0..size)
            .map(|_| T::scan(&mut self.iter).unwrap())
            .collect()
    }
    #[inline]
    pub fn scan_chars(&mut self) -> Vec<char> {
        self.iter.next().unwrap().chars().collect::<Vec<char>>()
    }
}
