// return (find_loop, last_node, is_loop)
fn dfs(
    g: &Graph,
    from: usize,
    parent: usize,
    visit: &mut Vec<bool>,
    bans: &mut Vec<bool>,
) -> (bool, usize, bool) {
    if visit[from] {
        return (true, from, true);
    }
    visit[from] = true;
    for e in g[from].iter() {
        if bans[e.index] || e.dest == parent {
            continue;
        }
        let nret = dfs(g, e.dest, from, visit, bans);
        if nret.0 {
            if nret.2 {
                bans[e.index] = true;
            }
            return (true, nret.1, nret.2 && from != nret.1);
        }
    }
    return (false, 0, false);
}

fn main() {
    let n = read::<usize>();
    let m = read::<usize>();
    let mut g = graph_new(n);
    let mut index = 0;
    for _i in 0..m {
        let f = read::<usize>() - 1;
        let t = read::<usize>() - 1;
        add_bi_edge(&mut g, &mut index, f, t, 0);
    }
    for i in 0..n {
        if g[i].len() % 2 != 0 {
            println!("No");
            return;
        }
    }
    let mut rnd = XorShift::new();
    'random_loop: for _r in 0..20 {
        let mut bans = vec![false; m];
        for _iter in 0..3 {
            let mut ok = false;
            let mut visit = vec![false; n];
            for i in 0..n {
                if dfs(&g, i, i, &mut visit, &mut bans).0 {
                    // println!("{:?}", bans);
                    ok = true;
                    break;
                }
            }
            if !ok {
                for i in 0..n {
                    for j in 0..g[i].len() {
                        g[i].swap(j, rnd.next_i32(j as i32 + 1) as usize);
                    }
                }
                continue 'random_loop;
            }
        }
        println!("Yes");
        return;
    }
    println!("No");
}

