use std::collections::HashSet;

fn check(v: usize, src: usize, block: usize, is_src_visited: bool, adj: &mut [HashSet<usize>]) -> bool {
    if v == src && is_src_visited {
        return true;
    } else if v == block {
        return false;
    }

    let drained: Vec<usize> = adj[v].drain().collect();
    for next in drained {
        adj[next].remove(&v);
        if check(next, src, block, true, adj) {
            return true;
        }
    }

    false
}

fn main() {
    read!(n = usize, _ = ());
    let mut degs = vec![0; n];
    let mut adj = vec![HashSet::new(); n];
    readx_loop!(|a = usize_, b = usize_| {
        degs[a] += 1;
        adj[a].insert(b);
        degs[b] += 1;
        adj[b].insert(a);
    });

    yn(degs.iter().all(|&n| n % 2 == 0) &&
       (degs.iter().find(|&&n| n >= 6).is_some() ||
        {
            let fours: Vec<usize> =
                degs.iter().enumerate().filter(|&(_, &n)| n == 4).map(|(i, _)| i).collect();
            fours.len() >= 3 || (fours.len() == 2 &&
                                 check(fours[0], fours[0], fours[1], false, &mut adj))
        }
       ));
}

