fn dfs(v: usize, goal: usize, fb: usize,
       par: usize,
       g: &[Vec<usize>], vis: &mut [bool]) -> bool {
    if vis[v] {
        if v == goal {
            return true;
        }
    } else {
        if v == fb {
            return false;
        }
    }
    // eprintln!("v = {}, goal = {}, fb = {}", v, goal, fb);
    vis[v] = true;
    for &w in &g[v] {
        if w == par { continue; }
        if dfs(w, goal, fb, v, g, vis) {
            return true;
        }
    }
    false
}

fn calc(g: &[Vec<usize>]) -> bool {
    let n = g.len();
    for i in 0..n {
        if g[i].len() % 2 == 1 {
            return false;
        }
    }
    let mut four = 0;
    let mut fv = vec![];
    for i in 0..n {
        if g[i].len() >= 6 {
            return true;
        }
        if g[i].len() == 4 {
            four += 1;
            fv.push(i);
        }
    }
    if four >= 3 {
        return true;
    }
    if four <= 1 {
        return false;
    }
    assert_eq!(four, 2);
    let mut vis = vec![false; n];
    dfs(fv[0], fv[0], fv[1], n, &g, &mut vis)
}

