    for i in 0..n {
        let d = g[i].len();
        if d % 2 != 0 {
            println!("No");
            return;
        } else if d >= 6 {
            println!("Yes");
            return;
        } else if d == 4 {
            d4.push(i);
        }
    }
    if d4.len() > 2 {
        println!("Yes");
        return;
    } else if d4.len() < 2 {
        println!("No");
        return;
    }
    let ans = flow(&g, d4[0], d4[1]);
    println!("{}", if ans {"Yes"} else {"No"});
}

fn flow(g: &Vec<HashSet<usize>>, s: usize, t: usize) -> bool {
    let mut h = g.clone();
    for &v in g[s].iter() {
        let mut p: Vec<usize> = vec![s];
        let mut ps: HashSet<usize> = p.iter().cloned().collect();
        if dfs(&h, v, t, &mut ps, &mut p) {
            for w in p.windows(2) {
                h[w[0]].remove(&w[1]);
                h[w[1]].remove(&w[0]);
            }
        } else {
            return true;
        }
    }
    false
}

fn dfs(g: &Vec<HashSet<usize>>, s: usize, t: usize, ps: &mut HashSet<usize>, p: &mut Vec<usize>) -> bool {
    ps.insert(s);
    p.push(s);
    if s == t {
        return true;
    }
    for &c in g[s].iter() {
        if ps.contains(&c) {
            continue;
        }
        if dfs(g, c, t, ps, p) {
            return true;
        }
    }
    ps.remove(&s);
    p.pop();
    return false;
}

