fn bfs(g: &Vec<HashSet<usize>>, setv: &HashSet<usize>, sete: &HashSet<(usize, usize)>) -> usize {
    if setv.len() == 0 {
        return 0;
    }
    let mut q: VecDeque<(usize, HashSet<usize>, HashSet<(usize, usize)>)> = VecDeque::new();
    let mut setv2 = setv.clone();
    let mut n0 = 0;
    while !setv2.contains(&n0) {
        n0 += 1;
    }
    setv2.remove(&n0);
    q.push_back((n0, setv2, sete.clone()));
    while q.len() > 0 {
        let (n, mut sv, mut se) = q.pop_front().unwrap();
        for &c in g[n].iter() {
            if se.contains(&(n, c)) || se.contains(&(c, n)) {
                continue;
            }
