fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for i in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push((b, i));
        graph[b].push((a, i));
    }

    let ge_six = graph.iter().filter(|g| g.len() >= 6).count();

    let all_even = graph.iter().all(|g| g.len() % 2 == 0);
    if !all_even {
        println!("No");
    } else if ge_six > 0 {
        println!("Yes");
    } else if graph.iter().filter(|g| g.len() == 4).count() >= 3 {
        println!("Yes");
    } else if graph.iter().filter(|g| g.len() == 4).count() <= 1 {
        println!("No");
    } else {
        let four2 = (0..n).filter(|&i| graph[i].len() == 4).collect::<Vec<_>>();

        let f1 = four2[0];
        let f2 = four2[1];

        let mut reach_f1 = 0;

        let mut used = vec![false; m];
        for i in 0..4 {
            assert!(!used[graph[f1][i].1]);
            used[graph[f1][i].1] = true;
            let mut cur = graph[f1][i].0;
            while cur != f1 && cur != f2 {
                assert_eq!(graph[cur].len(), 2);
                let next = &graph[cur];
                let i = if used[next[0].1] { 1 } else { 0 };
                assert!(!used[next[i].1]);
                used[next[i].1] = true;
                cur = next[i].0;
            }
            if cur == f1 {
                reach_f1 += 1;
            }
        }

        if reach_f1 == 2 {
