// return (find_loop, last_node, is_loop)
fn dfs(
    g: &Graph,
    from: usize,
    parent: usize,
    visit: &mut Vec<bool>,
    bans: &mut Vec<bool>,
) -> (bool, usize, bool) {
    if visit[from] {
        return (true, from, true);
    }
    visit[from] = true;
    for e in g[from].iter() {
        if bans[e.index] || e.dest == parent {
            continue;
        }
        let nret = dfs(g, e.dest, from, visit, bans);
        if nret.0 {
            if nret.2 {
                bans[e.index] = true;
            }
            return (true, nret.1, nret.2 && from != nret.1);
        }
    }
    return (false, 0, false);
}

