    for &(a, b) in v.iter() {
        g[a].insert(b);
        g[b].insert(a);
    }
    let mut d4: Vec<usize> = Vec::new();
    let mut f6 = false;
    for i in 0..n {
        let d = g[i].len();
        if d % 2 != 0 {
            println!("No");
            return;
        } else if d >= 6 {
            f6 = true;
        } else if d == 4 {
            d4.push(i);
        }
    }
    if f6 {
        println!("Yes");
        return;
    }
    if d4.len() > 2 {
        println!("Yes");
        return;
    } else if d4.len() < 2 {
