fn check(v: usize, src: usize, dest: usize, visited: &mut [bool], adj: &[Vec<usize>]) -> bool {
    if visited[v] {
        false
    } else {
        visited[v] = true;
        v == dest || adj[v].iter().any(|&next| check(next, src, dest, visited, adj))
    }
}

